--
-- Table structure for table `msds章节`
--

DROP TABLE IF EXISTS `msds章节`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `msds章节` (
  `编号` bigint NOT NULL AUTO_INCREMENT COMMENT 'MSDS章节ID',
  `文档编号` bigint NOT NULL COMMENT 'MSDS文档ID',
  `章节序号` tinyint NOT NULL COMMENT '章节号（1-16）',
  `章节标题` varchar(256) NOT NULL COMMENT '章节标题',
  `内容` longtext COMMENT '章节内容（纯文本）',
  `图片JSON` json DEFAULT NULL COMMENT '章节图片列表，格式：[{"url": "images/xxx.png", "alt": "GHS象形图", "type": "ghs"}]',
  `创建时间` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `更新时间` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`编号`),
  UNIQUE KEY `唯一键_文档章节` (`文档编号`,`章节序号`),
  KEY `索引_章节序号` (`章节序号`),
  FULLTEXT KEY `全文索引_内容` (`章节标题`,`内容`) COMMENT '内容全文索引',
  CONSTRAINT `外键_章节_文档` FOREIGN KEY (`文档编号`) REFERENCES `msds文档` (`编号`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='MSDS章节表（16个部分）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `msds章节`
--

LOCK TABLES `msds章节` WRITE;
/*!40000 ALTER TABLE `msds章节` DISABLE KEYS */;
INSERT INTO `msds章节` VALUES (353,15,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,1-二氯乙烯\n\n产品英文名称\n1,1-dichloroethylene|vinylidene chloride\n\n别名\n偏二氯乙烯|乙烯叉二氯\n\nCAS NO.\n75-35-4\n\nEC NO.\n200-864-0\n\n分子式\nC2H2Cl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(354,15,2,'危险性概述','紧急情况概述\n\n液体。极端易燃，有爆炸危险。\n\nGHS危险性类别\n\n易燃液体\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH224\n极易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃液体，有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，神志不清。\n\n食入\n腹部疼痛，咽喉疼痛（另见吸入）\n\n皮肤接触\n发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:10','2025-10-21 07:50:10'),(355,15,3,'成分/组成信息','1,1-二氯乙烯\n\nCas No.\n75-35-4\n\nEC No.\n200-864-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(356,15,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，不要催吐，大量饮水，休息\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(357,15,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(358,15,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(359,15,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(360,15,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(361,15,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-122\n\n初沸点和沸程(℃)\n32\n\n闪点(闭杯，℃)\n-25\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：16；下限：5.6\n\n蒸气压\n66.5kPa（20℃）\n\n蒸气密度(空气=1)\n3.3\n\n相对密度(水=1)\n1.2\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.32\n\n自燃温度(℃)\n570\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(362,15,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(363,15,11,'毒理学信息','急性毒性\n\n1,1-二氯乙烯\n75-35-4\n\nLD\n50\n(经口)\n200mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n200mg/kg(大鼠)\n\n致癌性\n\n1,1-二氯乙烯\n75-35-4\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,1-二氯乙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(364,15,12,'生态学信息','急性水生毒性\n\n1,1-二氯乙烯\n75-35-4\n\n鱼类\nLC\n50\n：45mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：16mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：410mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(365,15,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(366,15,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1303\n\n联合国正确运输名称\n乙烯叉二氯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:10','2025-10-21 07:50:10'),(367,15,15,'法规信息','国际化学品名录\n\n1,1-二氯乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,1-二氯乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(368,15,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(369,16,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,2-苯二胺\n\n产品英文名称\n1,2-phenylene diamine|o-phenylenediamine|1,2-diaminobenzene\n\n别名\n邻苯二胺|1,2-二氨基苯\n\nCAS NO.\n95-54-5\n\nEC NO.\n202-430-6\n\n分子式\nC6H8N2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(370,16,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。可能有发生不可逆性作用的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖细胞致突变性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n（另见吸入）。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:10','2025-10-21 07:50:10'),(371,16,3,'成分/组成信息','1,2-苯二胺\n\nCas No.\n95-54-5\n\nEC No.\n202-430-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(372,16,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。用水冲服活性炭浆。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(373,16,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(374,16,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(375,16,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(376,16,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(377,16,9,'理化特性','外观与性状\n无色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n8.7\n\n熔点/凝固点(℃)\n103~104\n\n初沸点和沸程(℃)\n256~258\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：1.5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.03（160℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.15\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(378,16,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(379,16,11,'毒理学信息','急性毒性\n\n1,2-苯二胺\n95-54-5\n\nLD\n50\n(经口)\n510mg/kg(大鼠)\n\nLD\n50\n(经皮)\n510mg/kg(大鼠)\n\nLD\n50\n(吸入)\n510mg/kg(大鼠)\n\n致癌性\n\n1,2-苯二胺\n95-54-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,2-苯二胺\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(380,16,12,'生态学信息','急性水生毒性\n\n1,2-苯二胺\n95-54-5\n\n鱼类\nLC\n50\n：4.6mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.4mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：0.82mg/L (72h)()\n\n慢性水生毒性\n\n1,2-苯二胺\n95-54-5\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.083mg/L()\n\n藻类/水生植物\nNOEC：0.37mg/L()\n\n其他信息\n\n持久性和降解性\n1,2-苯二胺：水/土壤-高 空气-高\n\n生物富集或生物积累性\n1,2-苯二胺：生物富集性-低（LogKOW=0.15）\n\n土壤中的迁移性\n1,2-苯二胺：土壤迁移性-低（koc=74.04）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(381,16,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(382,16,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1673\n\n联合国正确运输名称\n苯二胺(邻)\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:10','2025-10-21 07:50:10'),(383,16,15,'法规信息','国际化学品名录\n\n1,2-苯二胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,2-苯二胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(384,16,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:10','2025-10-21 07:50:10'),(385,17,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,2-二氯乙烷\n\n产品英文名称\n1,2-dichloroethane|ethylene dichloride|ethylidene chloride\n\n别名\n乙撑二氯|亚乙基二氯|1,2-二氯化乙烯\n\nCAS NO.\n107-06-2\n\nEC NO.\n203-458-1\n\n分子式\nC2H4Cl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(386,17,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。有轻微致癌性风险。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n致癌性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH351\n怀疑致癌\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n腹痛,咳嗽,头晕,头痛,恶心,咽喉痛,神志不清,呕吐,症状可能推迟显现。\n\n食入\n胃痉挛，腹泻。（另见吸入）。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(387,17,3,'成分/组成信息','1,2-二氯乙烷\n\nCas No.\n107-06-2\n\nEC No.\n203-458-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(388,17,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗数分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗，然后用水和肥皂冲洗皮肤，并给予医疗护理。\n\n食入\n不要饮用任何东西，给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(389,17,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(390,17,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(391,17,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(392,17,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,2-二氯乙烷\nGBZ 2.1-2007\n\nPC-TWA\n7 mg/m3\n\nPC-STEL\n15 mg/m3\n\n备注\nG2B\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(393,17,9,'理化特性','外观与性状\n无色油性液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-35.7\n\n初沸点和沸程(℃)\n83.5\n\n闪点(闭杯，℃)\n13\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：16；下限：6.2\n\n蒸气压\n8.7kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.42\n\n相对密度(水=1)\n1.235\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n1.48\n\n自燃温度(℃)\n413\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(394,17,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(395,17,11,'毒理学信息','急性毒性\n\n1,2-二氯乙烷\n107-06-2\n\nLD\n50\n(经口)\n670mg/kg(大鼠)\n\nLD\n50\n(经皮)\n670mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,2-二氯乙烷\n107-06-2\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,2-二氯乙烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(396,17,12,'生态学信息','急性水生毒性\n\n1,2-二氯乙烷\n107-06-2\n\n鱼类\nLC\n50\n：136mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：99mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：230mg/L (72h)(藻类)\n\n慢性水生毒性\n\n1,2-二氯乙烷\n107-06-2\n\n鱼类\nNOEC：41mg/L(鱼)\n\n甲壳纲动物\nNOEC：1.0mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：55mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(397,17,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(398,17,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1184\n\n联合国正确运输名称\n二氯化乙烯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n6.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(399,17,15,'法规信息','国际化学品名录\n\n1,2-二氯乙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,2-二氯乙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(400,17,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(401,18,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,2-乙二胺\n\n产品英文名称\n1,2-ethylenediamine|1,2-diaminoethane|ethylene diamine\n\n别名\n1,2-二氨基乙烷|乙撑二胺\n\nCAS NO.\n107-15-3\n\nEC NO.\n203-468-6\n\n分子式\nC2H8N2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(402,18,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。有引起过敏、哮喘病症状或呼吸困难的风险。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n呼吸道致敏物\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咳嗽。气促。咽喉痛。喘息。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(403,18,3,'成分/组成信息','1,2-乙二胺\n\nCas No.\n107-15-3\n\nEC No.\n203-468-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(404,18,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。不要催吐。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(405,18,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(406,18,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(407,18,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(408,18,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,2-乙二胺\nGBZ 2.1-2007\n\nPC-TWA\n4 mg/m3\n\nPC-STEL\n10 mg/m3\n\n备注\n皮；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(409,18,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n12.2（25℃，100g/L）\n\n熔点/凝固点(℃)\n8.5\n\n初沸点和沸程(℃)\n117\n\n闪点(闭杯，℃)\n34\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：16.6；下限：2.5\n\n蒸气压\n1.4kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.1\n\n相对密度(水=1)\n0.9\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-1.2\n\n自燃温度(℃)\n385\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(410,18,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(411,18,11,'毒理学信息','急性毒性\n\n1,2-乙二胺\n107-15-3\n\nLD\n50\n(经口)\n1200mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,2-乙二胺\n107-15-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,2-乙二胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(412,18,12,'生态学信息','急性水生毒性\n\n1,2-乙二胺\n107-15-3\n\n鱼类\nLC\n50\n：248mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：126mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(413,18,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(414,18,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1604\n\n联合国正确运输名称\n1,2-乙二胺(乙撑二胺)\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(415,18,15,'法规信息','国际化学品名录\n\n1,2-乙二胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,2-乙二胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(416,18,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(417,19,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,3,5-三甲基苯\n\n产品英文名称\n1,3,5-trimethylbenzene|sym-trimethylbenzene|mesitylene\n\n别名\n均三甲苯\n\nCAS NO.\n108-67-8\n\nEC NO.\n203-604-4\n\n分子式\nC9H12\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(418,19,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对呼吸道有刺激作用。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n意识模糊，咳嗽，头晕，倦睡，头痛，咽喉痛，呕吐。\n\n食入\n见吸入。\n\n皮肤接触\n发红，皮肤干燥。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(419,19,3,'成分/组成信息','1,3,5-三甲基苯\n\nCas No.\n108-67-8\n\nEC No.\n203-604-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(420,19,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(421,19,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(422,19,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(423,19,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(424,19,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(425,19,9,'理化特性','外观与性状\n无色油状液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-45\n\n初沸点和沸程(℃)\n165\n\n闪点(闭杯，℃)\n50\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.3；下限：0.96\n\n蒸气压\n0.25kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.1\n\n相对密度(水=1)\n0.865（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.42\n\n自燃温度(℃)\n550\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(426,19,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(427,19,11,'毒理学信息','急性毒性\n\n1,3,5-三甲基苯\n108-67-8\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n1,3,5-三甲基苯\n108-67-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,3,5-三甲基苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(428,19,12,'生态学信息','急性水生毒性\n\n1,3,5-三甲基苯\n108-67-8\n\n鱼类\nLC\n50\n：12.5mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(429,19,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(430,19,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2325\n\n联合国正确运输名称\n1,3,5-三甲基苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(431,19,15,'法规信息','国际化学品名录\n\n1,3,5-三甲基苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,3,5-三甲基苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(432,19,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(433,20,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,3-苯二酚\n\n产品英文名称\n1,3-benzenediol|m-benzenediol|resorcinol\n\n别名\n间苯二酚|雷琐酚\n\nCAS NO.\n108-46-3\n\nEC NO.\n203-585-2\n\n分子式\nC6H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(434,20,2,'危险性概述','紧急情况概述\n\n固体。对皮肤有刺激性。对眼睛有严重刺激性。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腹部疼痛。嘴唇发青或指甲发青。皮肤发青。意识模糊。惊厥。咳嗽。头晕。头痛。恶心。咽喉痛。神志不清。\n\n食入\n（另见吸入）。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(435,20,3,'成分/组成信息','1,3-苯二酚\n\nCas No.\n108-46-3\n\nEC No.\n203-585-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(436,20,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n漱口,催吐(仅对清醒病人!)。用水冲服活性炭浆。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(437,20,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(438,20,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(439,20,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(440,20,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,3-苯二酚\nGBZ 2.1-2007\n\nPC-TWA\n20 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(441,20,9,'理化特性','外观与性状\n白色晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n5.2\n\n熔点/凝固点(℃)\n110\n\n初沸点和沸程(℃)\n280\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：1.4\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.28\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.79~0.93\n\n自燃温度(℃)\n607\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(442,20,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与三氯化铝/硝基化合物的混合物接触，发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n三氯化铝、强氧化剂、硝酸盐、亚硝酸盐和卤素含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(443,20,11,'毒理学信息','急性毒性\n\n1,3-苯二酚\n108-46-3\n\nLD\n50\n(经口)\n301mg/kg(大鼠)\n\nLD\n50\n(经皮)\n301mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,3-苯二酚\n108-46-3\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,3-苯二酚\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(444,20,12,'生态学信息','急性水生毒性\n\n1,3-苯二酚\n108-46-3\n\n鱼类\nLC\n50\n：58.2mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n1,3-苯二酚：水/土壤-低 空气-低\n\n生物富集或生物积累性\n1,3-苯二酚：生物富集性-低（BCF=2.4）\n\n土壤中的迁移性\n1,3-苯二酚：土壤迁移性-低（koc=434）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(445,20,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(446,20,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2876\n\n联合国正确运输名称\n间苯二酚\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(447,20,15,'法规信息','国际化学品名录\n\n1,3-苯二酚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,3-苯二酚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(448,20,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(449,21,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,3-丁二烯[稳定的]\n\n产品英文名称\n1,3-butadiene,stabilized|buta-1,3-diene|biethylene\n\n别名\n联乙烯\n\nCAS NO.\n106-99-0\n\nEC NO.\n203-450-8\n\n分子式\nC4H6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(450,21,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,头晕,头痛,倦睡,出汗,恶心，神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n发红,疼痛，视力模糊（另见皮肤）。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(451,21,3,'成分/组成信息','1,3-丁二烯\n\nCas No.\n106-99-0\n\nEC No.\n203-450-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(452,21,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(453,21,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(454,21,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(455,21,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(456,21,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,3-丁二烯\nGBZ 2.1-2007\n\nPC-TWA\n5 mg/m3\n\nPC-STEL\n-\n\n备注\nG1\n\n控制参数->生物限值\n\n1,3-丁二烯\nGBZ 2.1-2019\n\n生物检测指标\n尿中 1,2-双羟基-4-（N-乙酰半胱胺酸）丁烷\n\n生物限值\n2.9 mg/g Cr\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(457,21,9,'理化特性','外观与性状\n无色气体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-109\n\n初沸点和沸程(℃)\n-4\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：16.3；下限：1.1\n\n蒸气压\n不适用（20℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用（-6℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n414\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(458,21,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与二氧化氮、氧化氮、氨反应形成氮氧化物的加成产物易发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n二氧化氮、氧化氮、氨、氧化剂、卤代烃和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(459,21,11,'毒理学信息','急性毒性\n\n1,3-丁二烯\n106-99-0\n\nLD\n50\n(经口)\n5480mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n5480mg/kg(大鼠)\n\n致癌性\n\n1,3-丁二烯\n106-99-0\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,3-丁二烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(460,21,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n1,3-丁二烯：水/土壤-低(半衰期=56天) 空气-低(半衰期=0.33天)\n\n生物富集或生物积累性\n1,3-丁二烯：生物富集性-低（BCF=19.1）\n\n土壤中的迁移性\n1,3-丁二烯：土壤迁移性-低（koc=43.79）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(461,21,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(462,21,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1010\n\n联合国正确运输名称\n丁二烯，稳定的\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(463,21,15,'法规信息','国际化学品名录\n\n1,3-丁二烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,3-丁二烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(464,21,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(465,22,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,3-二甲苯\n\n产品英文名称\n1,3-xylene|m-xylene\n\n别名\n间二甲苯\n\nCAS NO.\n108-38-3\n\nEC NO.\n203-576-3\n\n分子式\nC8H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(466,22,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，头痛，恶心。\n\n食入\n灼烧感，腹部疼痛。另见吸入。\n\n皮肤接触\n皮肤干燥，发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:11','2025-10-21 07:50:11'),(467,22,3,'成分/组成信息','1,3-二甲苯\n\nCas No.\n108-38-3\n\nEC No.\n203-576-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(468,22,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(469,22,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(470,22,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:11','2025-10-21 07:50:11'),(471,22,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(472,22,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,3-二甲苯\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n100 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n1,3-二甲苯\nGBZ 2.1-2019\n\n生物检测指标\n尿中甲基马尿酸\n\n生物限值\n0.3 g/g Cr 或 0.4 g/L\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(473,22,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-48\n\n初沸点和沸程(℃)\n139\n\n闪点(闭杯，℃)\n27\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7；下限：1.1\n\n蒸气压\n0.8kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.7\n\n相对密度(水=1)\n0.87（15℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.20\n\n自燃温度(℃)\n527\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(474,22,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(475,22,11,'毒理学信息','急性毒性\n\n1,3-二甲苯\n108-38-3\n\nLD\n50\n(经口)\n5000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,3-二甲苯\n108-38-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,3-二甲苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(476,22,12,'生态学信息','急性水生毒性\n\n1,3-二甲苯\n108-38-3\n\n鱼类\nLC\n50\n：10.6mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：2.4mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：8.9mg/L (72h)(藻类)\n\n慢性水生毒性\n\n1,3-二甲苯\n108-38-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.41mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：5.3mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n1,3-二甲苯：水/土壤-高(半衰期=360天) 空气-低(半衰期=1.08天)\n\n生物富集或生物积累性\n1,3-二甲苯：生物富集性-低（BCF=1.37）\n\n土壤中的迁移性\n1,3-二甲苯：土壤迁移性-低（koc=434）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(477,22,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(478,22,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1307\n\n联合国正确运输名称\n二甲苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(479,22,15,'法规信息','国际化学品名录\n\n1,3-二甲苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,3-二甲苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(480,22,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(481,23,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,3-二氯丙酮\n\n产品英文名称\n1,3-dichloroacetone|α,γ-dichloroacetone|1,3-dichloro-2-propanone\n\n别名\nα,γ-二氯丙酮\n\nCAS NO.\n534-07-6\n\nEC NO.\n208-585-6\n\n分子式\nC3H4Cl2O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(482,23,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\n防范说明->预防措施\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可导致严重的毒性反应。\n\n皮肤接触\n皮肤接触可产生严重毒害作用，吸收后可产生全身影响，并可致命。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(483,23,3,'成分/组成信息','1,3-二氯丙酮\n\nCas No.\n534-07-6\n\nEC No.\n208-585-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(484,23,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(485,23,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(486,23,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(487,23,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(488,23,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(489,23,9,'理化特性','外观与性状\n无色至浅褐色结晶\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n4.2（20℃，10g/L）\n\n熔点/凝固点(℃)\n39\n\n初沸点和沸程(℃)\n173\n\n闪点(闭杯，℃)\n89.44\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.383\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n590\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(490,23,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(491,23,11,'毒理学信息','急性毒性\n\n1,3-二氯丙酮\n534-07-6\n\nLD\n50\n(经口)\n20mg/kg(大鼠)\n\nLD\n50\n(经皮)\n20mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,3-二氯丙酮\n534-07-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,3-二氯丙酮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(492,23,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n1,3-二氯丙酮：水/土壤-高 空气-高\n\n生物富集或生物积累性\n1,3-二氯丙酮：生物富集性-低（LogKOW=0.273）\n\n土壤中的迁移性\n1,3-二氯丙酮：土壤迁移性-低（koc=7.395）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(493,23,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(494,23,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2649\n\n联合国正确运输名称\n1,3-二氯丙酮\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(495,23,15,'法规信息','国际化学品名录\n\n1,3-二氯丙酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,3-二氯丙酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(496,23,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(497,24,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,4-苯二酚\n\n产品英文名称\n1,4-dihydroxybenzene|quinol|hydroquinone|hydroquinone\n\n别名\n对苯二酚|氢醌\n\nCAS NO.\n123-31-9\n\nEC NO.\n204-617-8\n\n分子式\nC6H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(498,24,2,'危险性概述','紧急情况概述\n\n固体。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。可能有发生不可逆性作用的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n生殖细胞致突变性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH341\n怀疑可造成遗传性缺陷\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，呼吸困难。\n\n食入\n头晕,头痛,恶心,气促,惊厥,呕吐,耳鸣。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(499,24,3,'成分/组成信息','1,4-苯二酚\n\nCas No.\n123-31-9\n\nEC No.\n204-617-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(500,24,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口,催吐(仅对清醒病人!)。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(501,24,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(502,24,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(503,24,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(504,24,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,4-苯二酚\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(505,24,9,'理化特性','外观与性状\n灰白色粉末或白色针状晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n172\n\n初沸点和沸程(℃)\n287\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.3\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n0.59\n\n自燃温度(℃)\n515\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(506,24,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与三氯化铝/硝基化合物的混合物接触，发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n三氯化铝、强氧化剂、硝酸盐、亚硝酸盐和卤素含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(507,24,11,'毒理学信息','急性毒性\n\n1,4-苯二酚\n123-31-9\n\nLD\n50\n(经口)\n302mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,4-苯二酚\n123-31-9\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,4-苯二酚\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(508,24,12,'生态学信息','急性水生毒性\n\n1,4-苯二酚\n123-31-9\n\n鱼类\nLC\n50\n：0.134mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.061mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：0.053mg/L (72h)()\n\n慢性水生毒性\n\n1,4-苯二酚\n123-31-9\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.0029mg/L()\n\n藻类/水生植物\nNOEC：0.0015mg/L()\n\n其他信息\n\n持久性和降解性\n1,4-苯二酚：水/土壤-低 空气-低\n\n生物富集或生物积累性\n1,4-苯二酚：生物富集性-低（BCF=65）\n\n土壤中的迁移性\n1,4-苯二酚：土壤迁移性-低（koc=434）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(509,24,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(510,24,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(511,24,15,'法规信息','国际化学品名录\n\n1,4-苯二酚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,4-苯二酚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(512,24,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(513,25,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,8-萘二甲酸酐\n\n产品英文名称\nnaphthalene-1,8-dicarboxylic anhydride|1,8-naphthalic anhydride\n\n别名\n萘酐\n\nCAS NO.\n81-84-5\n\nEC NO.\n201-380-2\n\n分子式\nC12H6O3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(514,25,2,'危险性概述','紧急情况概述\n\n固体。易燃，其粉体与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃固体\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH228\n易燃固体\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n遇火或摩擦可被引燃，其粉体与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:12','2025-10-21 07:50:12'),(515,25,3,'成分/组成信息','1,8-萘二甲酸酐\n\nCas No.\n81-84-5\n\nEC No.\n201-380-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(516,25,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(517,25,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(518,25,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(519,25,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃。',NULL,'2025-10-21 07:50:12','2025-10-21 07:50:12'),(520,25,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(521,25,9,'理化特性','外观与性状\n米色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n267\n\n初沸点和沸程(℃)\n215\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n0.3~0.31\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n625\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(522,25,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(523,25,11,'毒理学信息','急性毒性\n\n1,8-萘二甲酸酐\n81-84-5\n\nLD\n50\n(经口)\n12340mg/kg(大鼠)\n\nLD\n50\n(经皮)\n12340mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1,8-萘二甲酸酐\n81-84-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,8-萘二甲酸酐\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(524,25,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n1,8-萘二甲酸酐：水/土壤-高 空气-高\n\n生物富集或生物积累性\n1,8-萘二甲酸酐：生物富集性-低（LogKOW=3.2448）\n\n土壤中的迁移性\n1,8-萘二甲酸酐：土壤迁移性-低（koc=122.9）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(525,25,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(526,25,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1325\n\n联合国正确运输名称\n有机易燃固体，未另作规定的\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(527,25,15,'法规信息','国际化学品名录\n\n1,8-萘二甲酸酐\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,8-萘二甲酸酐\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(528,25,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(529,26,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1-丙醇\n\n产品英文名称\n1-propanol|n-propanol\n\n别名\n正丙醇\n\nCAS NO.\n71-23-8\n\nEC NO.\n200-746-9\n\n分子式\nC3H8O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(530,26,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。有严重损害眼睛的危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH318\n造成严重眼损伤\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n共济失调，意识模糊，头晕，倦睡，头痛，恶心，虚弱。\n\n食入\n腹部疼痛，咽喉疼痛，呕吐。（见吸入）。\n\n皮肤接触\n皮肤发干。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(531,26,3,'成分/组成信息','1-丙醇\n\nCas No.\n71-23-8\n\nEC No.\n200-746-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(532,26,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(533,26,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(534,26,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(535,26,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(536,26,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1-丙醇\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n300 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(537,26,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-127\n\n初沸点和沸程(℃)\n97\n\n闪点(闭杯，℃)\n15\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：13.5；下限：2.1\n\n蒸气压\n2kPa（20℃）\n\n蒸气密度(空气=1)\n2.1\n\n相对密度(水=1)\n0.8\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.25\n\n自燃温度(℃)\n371\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(538,26,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂反应剧烈，有引起燃烧爆炸的危险。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、碱金属、碱土金属和铝。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(539,26,11,'毒理学信息','急性毒性\n\n1-丙醇\n71-23-8\n\nLD\n50\n(经口)\n1870mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1870mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1-丙醇\n71-23-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1-丙醇\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(540,26,12,'生态学信息','急性水生毒性\n\n1-丙醇\n71-23-8\n\n鱼类\nLC\n50\n：4480mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4130mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：4480mg/L (96h)()\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(541,26,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(542,26,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1274\n\n联合国正确运输名称\n正丙醇\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(543,26,15,'法规信息','国际化学品名录\n\n1-丙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1-丙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(544,26,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(545,27,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1-氯-2,3-环氧丙烷\n\n产品英文名称\n1-chloro-2,3-epoxypropane|epichlorhydrin|3-chloro-1,2-epoxypropane\n\n别名\n环氧氯丙烷|3-氯-1,2-环氧丙烷\n\nCAS NO.\n106-89-8\n\nEC NO.\n203-439-8\n\n分子式\nC3H5ClO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(546,27,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n致癌性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH350\n可能致癌\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,咽喉痛,头痛,呼吸困难,恶心,气促,呕吐,震颤,症状可能推迟显现。\n\n食入\n胃痉挛,咽喉和胸腔灼烧感,腹泻,头痛,恶心,咽喉疼痛,呕吐,休克或虚脱。\n\n皮肤接触\n可能被吸收！发红。严重皮肤烧伤。灼烧感。疼痛。水疱。\n\n眼睛\n疼痛。发红。永久性视力丧失。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(547,27,3,'成分/组成信息','1-氯-2,3-环氧丙烷\n\nCas No.\n106-89-8\n\nEC No.\n203-439-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(548,27,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口,不要催吐,大量饮水,休息,给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(549,27,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(550,27,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(551,27,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(552,27,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1-氯-2,3-环氧丙烷\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n皮，G2A\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(553,27,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-48\n\n初沸点和沸程(℃)\n116\n\n闪点(闭杯，℃)\n31\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：21；下限：3.8\n\n蒸气压\n1.6kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.2\n\n相对密度(水=1)\n1.18（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.26\n\n自燃温度(℃)\n385\n\n分解温度(℃)\n225\n\n黏度\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(554,27,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸或高氯酸镁接触发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、共价卤化物、无机碱、胺、金属烷氧化物、金属氧化物和高氯酸镁。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(555,27,11,'毒理学信息','急性毒性\n\n1-氯-2,3-环氧丙烷\n106-89-8\n\nLD\n50\n(经口)\n90mg/kg(大鼠)\n\nLD\n50\n(经皮)\n90mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1-氯-2,3-环氧丙烷\n106-89-8\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n1-氯-2,3-环氧丙烷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(556,27,12,'生态学信息','急性水生毒性\n\n1-氯-2,3-环氧丙烷\n106-89-8\n\n鱼类\nLC\n50\n：15.6mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(557,27,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(558,27,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2023\n\n联合国正确运输名称\n3-氯-1,2-环氧丙烷(表氯醇)\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(559,27,15,'法规信息','国际化学品名录\n\n1-氯-2,3-环氧丙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1-氯-2,3-环氧丙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(560,27,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(561,28,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1-氯-2,4-二硝基苯\n\n产品英文名称\n1-chloro-2,4-dinitrobenzene|2,4 - dinitrochlorobenzene\n\n别名\n2,4-二硝基氯苯\n\nCAS NO.\n97-00-7\n\nEC NO.\n202-551-4\n\n分子式\nC6H3ClN2O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(562,28,2,'危险性概述','紧急情况概述\n\n固体。跟皮肤接触有剧毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。对呼吸道有刺激作用。可能有发生不可逆性作用的危险。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n嘴唇发青或手指发青，皮肤发青，头晕，头痛，呼吸困难，恶心，呕吐，视力障碍。\n\n食入\n腹部疼痛，皮肤发青，头晕，头痛，呼吸困难，恶心，呕吐。\n\n皮肤接触\n可能被吸收！发红，疼痛。（见吸入）。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(563,28,3,'成分/组成信息','1-氯-2,4-二硝基苯\n\nCas No.\n97-00-7\n\nEC No.\n202-551-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(564,28,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤，给予医疗护理。\n\n食入\n漱口，催吐（仅对清醒病人!),催吐时戴防护手套，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(565,28,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(566,28,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(567,28,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(568,28,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1-氯-2,4-二硝基苯\nGBZ 2.1-2007\n\nPC-TWA\n0.6 mg/m3\n\nPC-STEL\n-\n\n备注\n皮，敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(569,28,9,'理化特性','外观与性状\n黄色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n54\n\n初沸点和沸程(℃)\n315\n\n闪点(闭杯，℃)\n179\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：22；下限：2\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n＞1\n\n相对密度(水=1)\n1.7\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.17\n\n自燃温度(℃)\n432\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(570,28,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氨、无机强碱、活泼金属、碱金属碳酸盐、金属氧化物、金属烷氧化物等接触发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氨、无机强碱、活泼金属、碱金属碳酸盐、金属氧化物、金属烷氧化物和硝酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(571,28,11,'毒理学信息','急性毒性\n\n1-氯-2,4-二硝基苯\n97-00-7\n\nLD\n50\n(经口)\n640mg/kg(大鼠)\n\nLD\n50\n(经皮)\n640mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n1-氯-2,4-二硝基苯\n97-00-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n1-氯-2,4-二硝基苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(572,28,12,'生态学信息','急性水生毒性\n\n1-氯-2,4-二硝基苯\n97-00-7\n\n鱼类\nLC\n50\n：0.16mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.54mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：0.18mg/L (72h)()\n\n慢性水生毒性\n\n1-氯-2,4-二硝基苯\n97-00-7\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.18mg/L()\n\n藻类/水生植物\nNOEC：0.0060mg/L()\n\n其他信息\n\n持久性和降解性\n1-氯-2,4-二硝基苯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n1-氯-2,4-二硝基苯：生物富集性-低（BCF=44）\n\n土壤中的迁移性\n1-氯-2,4-二硝基苯：土壤迁移性-低（koc=363.8）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(573,28,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(574,28,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3441\n\n联合国正确运输名称\n固态二硝基氯苯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(575,28,15,'法规信息','国际化学品名录\n\n1-氯-2,4-二硝基苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1-氯-2,4-二硝基苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(576,28,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(577,29,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2,2,4-三甲基戊烷\n\n产品英文名称\n2,2,4-trimethylpentane\n\n别名\n-\n\nCAS NO.\n540-84-1\n\nEC NO.\n208-759-1\n\n分子式\nC8H18\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(578,29,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对皮肤有刺激性。气体可能会引起头晕或窒息。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH315\n造成皮肤刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n意识模糊，头晕，头痛，恶心，呕吐。\n\n食入\n（见吸入）。\n\n皮肤接触\n皮肤干燥，发红，疼痛。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(579,29,3,'成分/组成信息','2,2,4-三甲基戊烷\n\nCas No.\n540-84-1\n\nEC No.\n208-759-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(580,29,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(581,29,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(582,29,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(583,29,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(584,29,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(585,29,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-107\n\n初沸点和沸程(℃)\n99\n\n闪点(闭杯，℃)\n-12\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：6；下限：1.1\n\n蒸气压\n5.1kPa（20℃）\n\n蒸气密度(空气=1)\n3.9\n\n相对密度(水=1)\n0.69\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n417\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(586,29,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(587,29,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n2,2,4-三甲基戊烷\n540-84-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2,2,4-三甲基戊烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(588,29,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n2,2,4-三甲基戊烷：水/土壤-高 空气-高\n\n生物富集或生物积累性\n2,2,4-三甲基戊烷：生物富集性-中等（BCF=650）\n\n土壤中的迁移性\n2,2,4-三甲基戊烷：土壤迁移性-低（koc=275.5）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(589,29,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(590,29,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1262\n\n联合国正确运输名称\n辛烷\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(591,29,15,'法规信息','国际化学品名录\n\n2,2,4-三甲基戊烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2,2,4-三甲基戊烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(592,29,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(593,30,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2,2\'-二羟基二乙胺\n\n产品英文名称\n2,2\'-iminodiethanol|diethanolamine\n\n别名\n二乙醇胺\n\nCAS NO.\n111-42-2\n\nEC NO.\n203-868-0\n\n分子式\nC4H11NO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(594,30,2,'危险性概述','紧急情况概述\n\n固体。对皮肤有刺激性。有严重损害眼睛的危险。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH318\n造成严重眼损伤\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n腹部疼痛。灼烧感。\n\n皮肤接触\n皮肤直接接触可造成皮肤刺激。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(595,30,3,'成分/组成信息','2,2\'-二羟基二乙胺\n\nCas No.\n111-42-2\n\nEC No.\n203-868-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(596,30,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。大量饮水。给予医疗护理。休息。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(597,30,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(598,30,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(599,30,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(600,30,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(601,30,9,'理化特性','外观与性状\n无色粘性液体或结晶固体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n11\n\n熔点/凝固点(℃)\n28\n\n初沸点和沸程(℃)\n269\n\n闪点(闭杯，℃)\n137\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：9.8；下限：1.7\n\n蒸气压\n1Pa（20℃）\n\n蒸气密度(空气=1)\n3.65\n\n相对密度(水=1)\n1.092（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-1.43\n\n自燃温度(℃)\n662\n\n分解温度(℃)\n268.4\n\n黏度\n不适用',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(602,30,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(603,30,11,'毒理学信息','急性毒性\n\n2,2\'-二羟基二乙胺\n111-42-2\n\nLD\n50\n(经口)\n3300mg/kg(小鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2,2\'-二羟基二乙胺\n111-42-2\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n2,2\'-二羟基二乙胺\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(604,30,12,'生态学信息','急性水生毒性\n\n2,2\'-二羟基二乙胺\n111-42-2\n\n鱼类\nLC\n50\n：1480mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：72.9mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n2,2\'-二羟基二乙胺：水/土壤-低(半衰期=14天) 空气-低(半衰期=0.3天)\n\n生物富集或生物积累性\n2,2\'-二羟基二乙胺：生物富集性-低（BCF=1）\n\n土壤中的迁移性\n2,2\'-二羟基二乙胺：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(605,30,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(606,30,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:13','2025-10-21 07:50:13'),(607,30,15,'法规信息','国际化学品名录\n\n2,2\'-二羟基二乙胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2,2\'-二羟基二乙胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(608,30,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:13','2025-10-21 07:50:13'),(609,31,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2,2\'-偶氮二异丁腈\n\n产品英文名称\n2,2\'-dimethyl-2,2\'-azodipropiononitrile|foaming agent N|ADIN\n\n别名\n发泡剂N|ADIN|2-甲基丙腈\n\nCAS NO.\n78-67-1\n\nEC NO.\n201-132-3\n\n分子式\nC8H12N4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(610,31,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n自反应物质和混合物\nC型\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH242\n加热可能起火\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP411\n贮存温度不超过 ……°C/……°F。\n\nP420\n远离其他材料存放。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n有爆炸性，遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n头痛。恶心。虚弱。惊厥。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(611,31,3,'成分/组成信息','2,2\'-偶氮二异丁腈\n\nCas No.\n78-67-1\n\nEC No.\n201-132-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(612,31,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n催吐(仅对清醒病人!)。用水冲服活性炭浆。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(613,31,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(614,31,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(615,31,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(616,31,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(617,31,9,'理化特性','外观与性状\n白色固体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n97~102（分解）\n\n初沸点和沸程(℃)\n106\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：8.7；下限：1.15\n\n蒸气压\n1Pa（20℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.1\n\n溶解性(mg/L)\n0.35 g/L（25℃）\n\n辛醇 /水分配系数\n0.84\n\n自燃温度(℃)\n64\n\n分解温度(℃)\n97~102\n\n黏度\n不适用',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(618,31,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与N-卤代化合物接触具有潜在的爆炸危险性。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\nN-卤代化合物、硫酸和强氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(619,31,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n2,2\'-偶氮二异丁腈\n78-67-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2,2\'-偶氮二异丁腈\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(620,31,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n2,2\'-偶氮二异丁腈：水/土壤-高 空气-高\n\n生物富集或生物积累性\n2,2\'-偶氮二异丁腈：生物富集性-低（LogKOW=1.1）\n\n土壤中的迁移性\n2,2\'-偶氮二异丁腈：土壤迁移性-低（koc=50.9）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(621,31,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(622,31,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3234\n\n联合国正确运输名称\nC型自反应固体，控制温度的\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(623,31,15,'法规信息','国际化学品名录\n\n2,2\'-偶氮二异丁腈\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2,2\'-偶氮二异丁腈\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(624,31,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(625,32,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2,5-二甲基-2,5-二(叔丁基过氧)己烷[糊状物,含量≤47%]\n\n产品英文名称\n2,5-dimethyl-2,5-di-(tert-butylperoxy)hexane (not more than 47% as a paste)\n\n别名\n-\n\nCAS NO.\n78-63-7\n\nEC NO.\n201-128-1\n\n分子式\nC16H34O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(626,32,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。\n\nGHS危险性类别\n\n有机过氧化物\nE型\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH242\n加热可能起火\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410\n防日晒。\n\nP420\n远离其他材料存放。\n\nP411+P235\n贮存温度不超过 ……°C/……°F。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(627,32,3,'成分/组成信息','2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n\nCas No.\n78-63-7\n\nEC No.\n201-128-1\n\n含量范围（质量分数，%）\n<= 47',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(628,32,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(629,32,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(630,32,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(631,32,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(632,32,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(633,32,9,'理化特性','外观与性状\n糊状物\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n8\n\n初沸点和沸程(℃)\n55~57（7 hPa）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n0.87\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞90\n\n黏度\n不适用',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(634,32,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(635,32,11,'毒理学信息','急性毒性\n\n2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n78-63-7\n\nLD\n50\n(经口)\n> 3200mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n78-63-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(636,32,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(637,32,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(638,32,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3108\n\n联合国正确运输名称\n固态E 型有机过氧化物\n\n运输主要危险类别\n5.2\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/3f0bb4fa98ae.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.2.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(639,32,15,'法规信息','国际化学品名录\n\n2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2,5-二甲基-2,5-二(叔丁基过氧基)己烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(640,32,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(641,33,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-氨基丙烷\n\n产品英文名称\n2-aminopropane|isopropylamine\n\n别名\n异丙胺\n\nCAS NO.\n75-31-0\n\nEC NO.\n200-860-9\n\n分子式\nC3H9N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(642,33,2,'危险性概述','紧急情况概述\n\n液体。极端易燃，有爆炸危险。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH224\n极易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃液体，有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咽喉疼痛,咳嗽,灼烧感,气促，呼吸困难。症状可能推迟显现。。\n\n食入\n灼烧感，胃痉挛，休克或虚脱。\n\n皮肤接触\n疼痛，发红，起疱，皮肤烧伤。\n\n眼睛\n发红，疼痛，严重深度烧伤，视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(643,33,3,'成分/组成信息','2-氨基丙烷\n\nCas No.\n75-31-0\n\nEC No.\n200-860-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(644,33,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口，大量饮水，不要催吐，给予医疗护理，催吐时戴防护手套。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(645,33,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(646,33,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(647,33,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(648,33,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-氨基丙烷\nGBZ 2.1-2007\n\nPC-TWA\n12 mg/m3\n\nPC-STEL\n24 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(649,33,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n10.6\n\n熔点/凝固点(℃)\n-101\n\n初沸点和沸程(℃)\n33~34\n\n闪点(闭杯，℃)\n≤~25\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：10；下限：2.3\n\n蒸气压\n63.7（20℃ ）\n\n蒸气密度(空气=1)\n2.0\n\n相对密度(水=1)\n0.69（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.3\n\n自燃温度(℃)\n402\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(650,33,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(651,33,11,'毒理学信息','急性毒性\n\n2-氨基丙烷\n75-31-0\n\nLD\n50\n(经口)\n111mg/kg(大鼠)\n\nLD\n50\n(经皮)\n111mg/kg(大鼠)\n\nLD\n50\n(吸入)\n111mg/kg(大鼠)\n\n致癌性\n\n2-氨基丙烷\n75-31-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-氨基丙烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(652,33,12,'生态学信息','急性水生毒性\n\n2-氨基丙烷\n75-31-0\n\n鱼类\nLC\n50\n：5390mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(653,33,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(654,33,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1221\n\n联合国正确运输名称\n异丙胺\n\n运输主要危险类别\n3\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(655,33,15,'法规信息','国际化学品名录\n\n2-氨基丙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-氨基丙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(656,33,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(657,34,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-苯基丙烯\n\n产品英文名称\n2-phenylpropene|isopropenylbenzene|α-methylstyrene\n\n别名\n异丙烯基苯|α-甲基苯乙烯\n\nCAS NO.\n98-83-9\n\nEC NO.\n202-705-0\n\n分子式\nC9H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(658,34,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，咽喉疼痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(659,34,3,'成分/组成信息','2-苯基丙烯\n\nCas No.\n98-83-9\n\nEC No.\n202-705-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(660,34,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂洗皮肤。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(661,34,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(662,34,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(663,34,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(664,34,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(665,34,9,'理化特性','外观与性状\n无色至黄色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-23\n\n初沸点和沸程(℃)\n164\n\n闪点(闭杯，℃)\n54\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：6.6；下限：0.9\n\n蒸气压\n300Pa（20℃ ）\n\n蒸气密度(空气=1)\n4.08\n\n相对密度(水=1)\n0.91\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.38\n\n自燃温度(℃)\n574\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(666,34,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(667,34,11,'毒理学信息','急性毒性\n\n2-苯基丙烯\n98-83-9\n\nLD\n50\n(经口)\n4900mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2-苯基丙烯\n98-83-9\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-苯基丙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(668,34,12,'生态学信息','急性水生毒性\n\n2-苯基丙烯\n98-83-9\n\n鱼类\nLC\n50\n：7.3mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：2.6mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：4.8mg/L (72h)()\n\n慢性水生毒性\n\n2-苯基丙烯\n98-83-9\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.40mg/L()\n\n藻类/水生植物\nNOEC：0.30mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(669,34,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(670,34,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2303\n\n联合国正确运输名称\n异丙烯基苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(671,34,15,'法规信息','国际化学品名录\n\n2-苯基丙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-苯基丙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(672,34,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(673,35,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-丙醇\n\n产品英文名称\n2-propanol|isopropanol|isopropyl alcohol|\n\n别名\n异丙醇\n\nCAS NO.\n67-63-0\n\nEC NO.\n200-661-7\n\n分子式\nC3H8O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(674,35,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，倦睡，头痛，咽喉痛(见食入)。\n\n食入\n腹部疼痛，呼吸困难，恶心，神志不清，呕吐。（另见吸入）。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(675,35,3,'成分/组成信息','2-丙醇\n\nCas No.\n67-63-0\n\nEC No.\n200-661-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(676,35,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，不要催吐，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(677,35,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(678,35,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(679,35,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(680,35,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-丙醇\nGBZ 2.1-2007\n\nPC-TWA\n350 mg/m3\n\nPC-STEL\n700 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(681,35,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-90\n\n初沸点和沸程(℃)\n83\n\n闪点(闭杯，℃)\n11.7\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：12；下限：2\n\n蒸气压\n4.4kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.1\n\n相对密度(水=1)\n0.78（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.05\n\n自燃温度(℃)\n456\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(682,35,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂反应剧烈，有引起燃烧爆炸的危险。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、碱金属、碱土金属和铝。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(683,35,11,'毒理学信息','急性毒性\n\n2-丙醇\n67-63-0\n\nLD\n50\n(经口)\n5045mg/kg(大鼠)\n\nLD\n50\n(经皮)\n5045mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2-丙醇\n67-63-0\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-丙醇\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(684,35,12,'生态学信息','急性水生毒性\n\n2-丙醇\n67-63-0\n\n鱼类\nLC\n50\n：9640mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：>1000mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：>1000mg/L (72h)()\n\n慢性水生毒性\n\n2-丙醇\n67-63-0\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：>100mg/L()\n\n藻类/水生植物\nNOEC：1000mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(685,35,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(686,35,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1219\n\n联合国正确运输名称\n异丙醇\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(687,35,15,'法规信息','国际化学品名录\n\n2-丙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-丙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(688,35,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(689,36,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-丙烯腈[稳定的]\n\n产品英文名称\n2-acrylonitrile,stabilized| acrylonitrile|cyanoethylene\n\n别名\n丙烯腈|乙烯基氰|氰基乙烯\n\nCAS NO.\n107-13-1\n\nEC NO.\n203-466-5\n\n分子式\nC3H3N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(690,36,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有毒。对呼吸道有刺激作用。有轻微致癌性风险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n致癌性\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH351\n怀疑致癌\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕,头痛,恶心,气促,呕吐,虚弱,惊厥,胸闷。\n\n食入\n腹部疼痛，呕吐。另见吸入。\n\n皮肤接触\n可能被吸收！发红，疼痛，水疱。另见吸入。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(691,36,3,'成分/组成信息','2-丙烯腈\n\nCas No.\n107-13-1\n\nEC No.\n203-466-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(692,36,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医\n\n皮肤接触\n先用大量水,然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口,用水冲服活性炭浆,催吐(仅对清醒病人!),给予医疗护理。\n\n吸入\n新鲜空气,休息,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(693,36,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(694,36,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(695,36,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(696,36,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-丙烯腈\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n皮，G2B\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(697,36,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n6~7.5（5%溶液）\n\n熔点/凝固点(℃)\n-84\n\n初沸点和沸程(℃)\n77\n\n闪点(闭杯，℃)\n-1\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：17；下限：3\n\n蒸气压\n11kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.8\n\n相对密度(水=1)\n0.806~0.82（26℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.25\n\n自燃温度(℃)\n481\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(698,36,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(699,36,11,'毒理学信息','急性毒性\n\n2-丙烯腈\n107-13-1\n\nLD\n50\n(经口)\n78mg/kg(大鼠)\n\nLD\n50\n(经皮)\n78mg/kg(大鼠)\n\nLD\n50\n(吸入)\n78mg/kg(大鼠)\n\n致癌性\n\n2-丙烯腈\n107-13-1\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-丙烯腈\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(700,36,12,'生态学信息','急性水生毒性\n\n2-丙烯腈\n107-13-1\n\n鱼类\nLC\n50\n：5.1mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：2.5mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：10mg/L (72h)()\n\n慢性水生毒性\n\n2-丙烯腈\n107-13-1\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：0.95mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(701,36,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(702,36,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1093\n\n联合国正确运输名称\n丙烯腈，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:14','2025-10-21 07:50:14'),(703,36,15,'法规信息','国际化学品名录\n\n2-丙烯腈\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-丙烯腈\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(704,36,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:14','2025-10-21 07:50:14'),(705,37,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-丁酮\n\n产品英文名称\n2-butanone|ethyl methyl ketone|methylethyl ketone\n\n别名\n丁酮|乙基甲基酮|甲乙酮\n\nCAS NO.\n78-93-3\n\nEC NO.\n201-159-0\n\n分子式\nC4H8O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(706,37,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，倦睡，头痛，恶心，呕吐。\n\n食入\n神志不清。（另见吸入）。\n\n皮肤接触\n可能被吸收！发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(707,37,3,'成分/组成信息','2-丁酮\n\nCas No.\n78-93-3\n\nEC No.\n201-159-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(708,37,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口，饮用大量水，给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(709,37,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(710,37,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(711,37,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(712,37,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-丁酮\nGBZ 2.1-2007\n\nPC-TWA\n300 mg/m3\n\nPC-STEL\n600 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(713,37,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-86\n\n初沸点和沸程(℃)\n80\n\n闪点(闭杯，℃)\n-9\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：11.5；下限：1.8\n\n蒸气压\n10.5（20℃ ）\n\n蒸气密度(空气=1)\n2.41\n\n相对密度(水=1)\n0.81（20℃）\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n0.29\n\n自燃温度(℃)\n505\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(714,37,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触易发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、氯仿、溴仿以及其它有机溶剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(715,37,11,'毒理学信息','急性毒性\n\n2-丁酮\n78-93-3\n\nLD\n50\n(经口)\n2737mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2737mg/kg(大鼠)\n\nLD\n50\n(吸入)\n2737mg/kg(大鼠)\n\n致癌性\n\n2-丁酮\n78-93-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-丁酮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(716,37,12,'生态学信息','急性水生毒性\n\n2-丁酮\n78-93-3\n\n鱼类\nLC\n50\n：3220mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：5090mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：>1200mg/L (72h)()\n\n慢性水生毒性\n\n2-丁酮\n78-93-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：100mg/L()\n\n藻类/水生植物\nNOEC：93mg/L()\n\n其他信息\n\n持久性和降解性\n2-丁酮：水/土壤-低(半衰期=14天) 空气-低(半衰期=26.75天)\n\n生物富集或生物积累性\n2-丁酮：生物富集性-低（LogKOW=0.29）\n\n土壤中的迁移性\n2-丁酮：土壤迁移性-中等（koc=3.827）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(717,37,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(718,37,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1193\n\n联合国正确运输名称\n乙基·甲基酮(甲乙酮)\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(719,37,15,'法规信息','国际化学品名录\n\n2-丁酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-丁酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(720,37,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(721,38,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-丁氧基乙醇\n\n产品英文名称\n2-butoxyethanol|ethylene glycol monobutyl ether|butyl cellosolve\n\n别名\n乙二醇丁醚|丁基溶纤剂\n\nCAS NO.\n111-76-2\n\nEC NO.\n203-905-0\n\n分子式\nC6H14O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(722,38,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有剧毒。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH311\n皮肤接触会中毒\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。头晕。倦睡。头痛。恶心。虚弱。\n\n食入\n腹部疼痛。腹泻。恶心。呕吐。（另见吸入）。\n\n皮肤接触\n可能被吸收！皮肤干燥。（另见吸入）。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(723,38,3,'成分/组成信息','2-丁氧基乙醇\n\nCas No.\n111-76-2\n\nEC No.\n203-905-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(724,38,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(725,38,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(726,38,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(727,38,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(728,38,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-丁氧基乙醇\nGBZ 2.1-2007\n\nPC-TWA\n97 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(729,38,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-75\n\n初沸点和沸程(℃)\n171\n\n闪点(闭杯，℃)\n60\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：12.7；下限：1.1\n\n蒸气压\n0.1kPa（20℃）\n\n蒸气密度(空气=1)\n4.1\n\n相对密度(水=1)\n0.9（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.830\n\n自燃温度(℃)\n238\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(730,38,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(731,38,11,'毒理学信息','急性毒性\n\n2-丁氧基乙醇\n111-76-2\n\nLD\n50\n(经口)\n470mg/kg(大鼠)\n\nLD\n50\n(经皮)\n470mg/kg(大鼠)\n\nLD\n50\n(吸入)\n470mg/kg(大鼠)\n\n致癌性\n\n2-丁氧基乙醇\n111-76-2\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-丁氧基乙醇\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(732,38,12,'生态学信息','急性水生毒性\n\n2-丁氧基乙醇\n111-76-2\n\n鱼类\nLC\n50\n：1370mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：>1000mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：>1000mg/L (72h)()\n\n慢性水生毒性\n\n2-丁氧基乙醇\n111-76-2\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：>100mg/L()\n\n藻类/水生植物\nNOEC：130mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(733,38,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(734,38,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2810\n\n联合国正确运输名称\n有机毒性液体，未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(735,38,15,'法规信息','国际化学品名录\n\n2-丁氧基乙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-丁氧基乙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(736,38,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(737,39,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-甲基-1-丙醇\n\n产品英文名称\n2-methylpropan-1-ol|isobutanol\n\n别名\n异丁醇\n\nCAS NO.\n78-83-1\n\nEC NO.\n201-148-0\n\n分子式\nC4H10O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(738,39,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。有严重损害眼睛的危险。对呼吸道有刺激作用。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头痛。头晕。倦睡。\n\n食入\n腹部疼痛。倦睡。头晕。恶心。腹泻。呕吐。\n\n皮肤接触\n发红。疼痛。皮肤干燥。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(739,39,3,'成分/组成信息','2-甲基-1-丙醇\n\nCas No.\n78-83-1\n\nEC No.\n201-148-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(740,39,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(741,39,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(742,39,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(743,39,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(744,39,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(745,39,9,'理化特性','外观与性状\n无色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-108\n\n初沸点和沸程(℃)\n108\n\n闪点(闭杯，℃)\n28\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：10.9；下限：1.7\n\n蒸气压\n1.2kPa（20℃）\n\n蒸气密度(空气=1)\n2.55\n\n相对密度(水=1)\n0.80\n\n溶解性(mg/L)\n85g/L（20℃）\n\n辛醇 /水分配系数\n0.8\n\n自燃温度(℃)\n415\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(746,39,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂反应剧烈，有引起燃烧爆炸的危险。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、碱金属、碱土金属和铝。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(747,39,11,'毒理学信息','急性毒性\n\n2-甲基-1-丙醇\n78-83-1\n\nLD\n50\n(经口)\n2460mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2460mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2-甲基-1-丙醇\n78-83-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-甲基-1-丙醇\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(748,39,12,'生态学信息','急性水生毒性\n\n2-甲基-1-丙醇\n78-83-1\n\n鱼类\nLC\n50\n：1510mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1200mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(749,39,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(750,39,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1212\n\n联合国正确运输名称\n异丁醇\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(751,39,15,'法规信息','国际化学品名录\n\n2-甲基-1-丙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-甲基-1-丙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(752,39,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(753,40,1,'化学品及企业标识','产品标识\n\n产品中文名称\n2-氯乙醇\n\n产品英文名称\n2-chloroethanol|ethylene chlorohydrin|2-chloroethyl alcohol|glycol chlorohydrin|β-chloroethyl alcohol\n\n别名\n乙撑氯醇|氯乙醇\n\nCAS NO.\n107-07-3\n\nEC NO.\n203-459-7\n\n分子式\nC2H5ClO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(754,40,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH330\n吸入致命\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。头晕。头痛。恶心。咽喉痛。呕吐。\n\n食入\n（另见吸入）。\n\n皮肤接触\n可能被吸收！（另见吸入）。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(755,40,3,'成分/组成信息','2-氯乙醇\n\nCas No.\n107-07-3\n\nEC No.\n203-459-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(756,40,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗,然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n漱口。催吐(仅对清醒病人!)。给予医疗护理。\n\n吸入\n新鲜空气,休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(757,40,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(758,40,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(759,40,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(760,40,8,'接触控制/个体防护','控制参数->职业接触限值\n\n2-氯乙醇\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(761,40,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-67\n\n初沸点和沸程(℃)\n128~130\n\n闪点(闭杯，℃)\n60\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：15.9；下限：4.9\n\n蒸气压\n0.65kPa（20℃）\n\n蒸气密度(空气=1)\n2.78\n\n相对密度(水=1)\n1.2\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.06\n\n自燃温度(℃)\n425\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(762,40,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(763,40,11,'毒理学信息','急性毒性\n\n2-氯乙醇\n107-07-3\n\nLD\n50\n(经口)\n71mg/kg(大鼠)\n\nLD\n50\n(经皮)\n71mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n2-氯乙醇\n107-07-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n2-氯乙醇\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(764,40,12,'生态学信息','急性水生毒性\n\n2-氯乙醇\n107-07-3\n\n鱼类\nLC\n50\n：37.2mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：320mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(765,40,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(766,40,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1135\n\n联合国正确运输名称\n2-氯乙醇\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n3\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(767,40,15,'法规信息','国际化学品名录\n\n2-氯乙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n2-氯乙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(768,40,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(769,41,1,'化学品及企业标识','产品标识\n\n产品中文名称\n3-氯甲苯\n\n产品英文名称\n3-chlorotoluene|m-chlorotoluene\n\n别名\n间氯甲苯\n\nCAS NO.\n108-41-8\n\nEC NO.\n203-580-5\n\n分子式\nC7H7Cl\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(770,41,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(771,41,3,'成分/组成信息','3-氯甲苯\n\nCas No.\n108-41-8\n\nEC No.\n203-580-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(772,41,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(773,41,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(774,41,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(775,41,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(776,41,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(777,41,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-48\n\n初沸点和沸程(℃)\n162\n\n闪点(闭杯，℃)\n51\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.4kPa（20℃）\n\n蒸气密度(空气=1)\n40\n\n相对密度(水=1)\n1.070~1.072（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(778,41,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(779,41,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n3-氯甲苯\n108-41-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n3-氯甲苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(780,41,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n3-氯甲苯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n3-氯甲苯：生物富集性-低（LogKOW=3.28）\n\n土壤中的迁移性\n3-氯甲苯：土壤迁移性-低（koc=434）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(781,41,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(782,41,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2238\n\n联合国正确运输名称\n氯甲苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(783,41,15,'法规信息','国际化学品名录\n\n3-氯甲苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n3-氯甲苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(784,41,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(785,42,1,'化学品及企业标识','产品标识\n\n产品中文名称\n4-甲基-2-戊酮\n\n产品英文名称\n4-methylpentan-2-one|isobutyl methyl ketone|methyl isobutyl ketone|isohexanone\n\n别名\n甲基异丁基酮|异己酮\n\nCAS NO.\n108-10-1\n\nEC NO.\n203-550-1\n\n分子式\nC6H12O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(786,42,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感，腹泻，头痛，头晕，恶心，咽喉痛，神志不清，呕吐，虚弱，失去胃口。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(787,42,3,'成分/组成信息','4-甲基-2-戊酮\n\nCas No.\n108-10-1\n\nEC No.\n203-550-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(788,42,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(789,42,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(790,42,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(791,42,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(792,42,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(793,42,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-84.7\n\n初沸点和沸程(℃)\n117~118\n\n闪点(闭杯，℃)\n14\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.5；下限：1.4\n\n蒸气压\n2.1kPa（20℃）\n\n蒸气密度(空气=1)\n3.45\n\n相对密度(水=1)\n0.80\n\n溶解性(mg/L)\n19g/L（20℃）\n\n辛醇 /水分配系数\n1.38\n\n自燃温度(℃)\n460\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(794,42,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触易发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、氯仿、溴仿以及其它有机溶剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(795,42,11,'毒理学信息','急性毒性\n\n4-甲基-2-戊酮\n108-10-1\n\nLD\n50\n(经口)\n2080mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n4-甲基-2-戊酮\n108-10-1\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n4-甲基-2-戊酮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(796,42,12,'生态学信息','急性水生毒性\n\n4-甲基-2-戊酮\n108-10-1\n\n鱼类\nLC\n50\n：537mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(797,42,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(798,42,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1245\n\n联合国正确运输名称\n甲基·异丁基酮\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:15','2025-10-21 07:50:15'),(799,42,15,'法规信息','国际化学品名录\n\n4-甲基-2-戊酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n4-甲基-2-戊酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(800,42,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:15','2025-10-21 07:50:15'),(801,43,1,'化学品及企业标识','产品标识\n\n产品中文名称\n4-甲基苯胺\n\n产品英文名称\n4-methylaniline|p-toluidine|4-aminotoluene|p-aminotoluene\n\n别名\n对甲基苯胺|4-氨甲苯|对氨基甲苯\n\nCAS NO.\n106-49-0\n\nEC NO.\n203-403-1\n\n分子式\nC7H9N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(802,43,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。吸入有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH331\n吸入会中毒\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n嘴唇发青或指甲发青。皮肤发青。意识模糊。头晕。头痛。呼吸短促。虚弱。惊厥。恶心。神志不清。\n\n食入\n嘴唇发青或指甲发青。皮肤发青。头晕。头痛。呼吸困难。(另见吸入)。\n\n皮肤接触\n可能被吸收！发红。嘴唇发青或指甲发青。皮肤发青。(另见吸入)。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(803,43,3,'成分/组成信息','4-甲基苯胺\n\nCas No.\n106-49-0\n\nEC No.\n203-403-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(804,43,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。立即给予医疗护理。\n\n食入\n漱口。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(805,43,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(806,43,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(807,43,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(808,43,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(809,43,9,'理化特性','外观与性状\n白色或微黄色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n44~45\n\n初沸点和沸程(℃)\n200\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：6.6；下限：1.1\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.05\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n1.39\n\n自燃温度(℃)\n480\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(810,43,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(811,43,11,'毒理学信息','急性毒性\n\n4-甲基苯胺\n106-49-0\n\nLD\n50\n(经口)\n336mg/kg(大鼠)\n\nLD\n50\n(经皮)\n336mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n4-甲基苯胺\n106-49-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n4-甲基苯胺\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(812,43,12,'生态学信息','急性水生毒性\n\n4-甲基苯胺\n106-49-0\n\n鱼类\nLC\n50\n：120mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.12mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：24mg/L (72h)(藻类)\n\n慢性水生毒性\n\n4-甲基苯胺\n106-49-0\n\n鱼类\nNOEC：13mg/L(鱼)\n\n甲壳纲动物\nNOEC：0.011mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：3.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n4-甲基苯胺：水/土壤-高 空气-高\n\n生物富集或生物积累性\n4-甲基苯胺：生物富集性-低（BCF=13）\n\n土壤中的迁移性\n4-甲基苯胺：土壤迁移性-低（koc=72.53）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(813,43,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(814,43,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3451\n\n联合国正确运输名称\n固态甲苯胺\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(815,43,15,'法规信息','国际化学品名录\n\n4-甲基苯胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n4-甲基苯胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(816,43,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(817,44,1,'化学品及企业标识','产品标识\n\n产品中文名称\nN,N-二甲基-1,3-丙二胺\n\n产品英文名称\nN,N-dimethyl-1,3-diaminopropane|3-dimethylamino-1-propane|3-aminopropyldimethylamine\n\n别名\n3-二甲氨基-1-丙胺\n\nCAS NO.\n109-55-7\n\nEC NO.\n203-680-9\n\n分子式\nC5H14N2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(818,44,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感,气促,呼吸困难,症状可能推迟显现。\n\n食入\n灼烧感。腹部疼痛。休克或虚脱。\n\n皮肤接触\n疼痛。发红。严重的皮肤烧伤。\n\n眼睛\n疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(819,44,3,'成分/组成信息','N,N-二甲基-1,3-丙二胺\n\nCas No.\n109-55-7\n\nEC No.\n203-680-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(820,44,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(821,44,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(822,44,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(823,44,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(824,44,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(825,44,9,'理化特性','外观与性状\n无色或淡黄色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n12.2（10%溶液）\n\n熔点/凝固点(℃)\n-70\n\n初沸点和沸程(℃)\n135\n\n闪点(闭杯，℃)\n35\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：12.3；下限：2.3\n\n蒸气压\n1.33kPa（30℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n0.8（30℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.352\n\n自燃温度(℃)\n215\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(826,44,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(827,44,11,'毒理学信息','急性毒性\n\nN,N-二甲基-1,3-丙二胺\n109-55-7\n\nLD\n50\n(经口)\n1870mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\nN,N-二甲基-1,3-丙二胺\n109-55-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\nN,N-二甲基-1,3-丙二胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(828,44,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\nN,N-二甲基-1,3-丙二胺：水/土壤-高 空气-高\n\n生物富集或生物积累性\nN,N-二甲基-1,3-丙二胺：生物富集性-低（LogKOW=-0.352）\n\n土壤中的迁移性\nN,N-二甲基-1,3-丙二胺：土壤迁移性-低（koc=73.36）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(829,44,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(830,44,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2734\n\n联合国正确运输名称\n液态胺，腐蚀性，易燃，未另作规定的\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(831,44,15,'法规信息','国际化学品名录\n\nN,N-二甲基-1,3-丙二胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\nN,N-二甲基-1,3-丙二胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(832,44,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(833,45,1,'化学品及企业标识','产品标识\n\n产品中文名称\nN,N-二甲基乙醇胺\n\n产品英文名称\n2-dimethylaminoethanol|N,N-dimethylethanolamine|2-dimethylaminoethenol\n\n别名\nN,N-二甲基-2-羟基乙胺|2-二甲氨基乙醇\n\nCAS NO.\n108-01-0\n\nEC NO.\n203-542-8\n\n分子式\nC4H11NO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(834,45,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,灼烧感,呼吸困难,症状可能推迟显现。\n\n食入\n腹部疼痛。恶心。呕吐。休克或虚脱。灼烧感。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。\n\n眼睛\n发红，疼痛，严重深度烧伤\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(835,45,3,'成分/组成信息','N,N-二甲基乙醇胺\n\nCas No.\n108-01-0\n\nEC No.\n203-542-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(836,45,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医\n\n皮肤接触\n先用大量水洗涤，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。休息。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(837,45,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(838,45,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(839,45,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(840,45,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(841,45,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n10.5~11（20℃，100g/L）\n\n熔点/凝固点(℃)\n-59\n\n初沸点和沸程(℃)\n135\n\n闪点(闭杯，℃)\n38\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11.9；下限：1.6\n\n蒸气压\n612Pa（20℃ ）\n\n蒸气密度(空气=1)\n3.03\n\n相对密度(水=1)\n0.89\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.55\n\n自燃温度(℃)\n220\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(842,45,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(843,45,11,'毒理学信息','急性毒性\n\nN,N-二甲基乙醇胺\n108-01-0\n\nLD\n50\n(经口)\n2000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2000mg/kg(大鼠)\n\nLD\n50\n(吸入)\n2000mg/kg(大鼠)\n\n致癌性\n\nN,N-二甲基乙醇胺\n108-01-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\nN,N-二甲基乙醇胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(844,45,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(845,45,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(846,45,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2051\n\n联合国正确运输名称\n2-二甲氨基乙醇\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(847,45,15,'法规信息','国际化学品名录\n\nN,N-二甲基乙醇胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\nN,N-二甲基乙醇胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(848,45,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(849,46,1,'化学品及企业标识','产品标识\n\n产品中文名称\nN,N-二乙基苯胺\n\n产品英文名称\nN,N-diethylaniline|diethylaminobenzene\n\n别名\n二乙氨基苯\n\nCAS NO.\n91-66-7\n\nEC NO.\n202-088-8\n\n分子式\nC10H15N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(850,46,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。跟皮肤接触有毒。吸入有毒。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n嘴唇发青或指甲发青,皮肤发青,惊厥,头晕,呼吸困难,呕吐,症状可能推迟显现。\n\n食入\n（另见吸入）。\n\n皮肤接触\n发红。可能被吸收！（另见吸入）。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(851,46,3,'成分/组成信息','N,N-二乙基苯胺\n\nCas No.\n91-66-7\n\nEC No.\n202-088-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(852,46,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤,给予医疗护理。\n\n食入\n漱口。大量饮水。用水冲服活性炭浆。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(853,46,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(854,46,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(855,46,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(856,46,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(857,46,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n8（20℃，0.1g/L，计算值）\n\n熔点/凝固点(℃)\n-38\n\n初沸点和沸程(℃)\n215（分解）\n\n闪点(闭杯，℃)\n79\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n19Pa（20℃）\n\n蒸气密度(空气=1)\n5.1\n\n相对密度(水=1)\n0.93\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n3.31\n\n自燃温度(℃)\n630\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(858,46,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(859,46,11,'毒理学信息','急性毒性\n\nN,N-二乙基苯胺\n91-66-7\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\nN,N-二乙基苯胺\n91-66-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\nN,N-二乙基苯胺\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(860,46,12,'生态学信息','急性水生毒性\n\nN,N-二乙基苯胺\n91-66-7\n\n鱼类\nLC\n50\n：16.4mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.3mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：2.8mg/L (72h)(藻类)\n\n慢性水生毒性\n\nN,N-二乙基苯胺\n91-66-7\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：0.77mg/L(藻类)\n\n其他信息\n\n持久性和降解性\nN,N-二乙基苯胺：水/土壤-高 空气-高\n\n生物富集或生物积累性\nN,N-二乙基苯胺：生物富集性-低（BCF=161）\n\n土壤中的迁移性\nN,N-二乙基苯胺：土壤迁移性-低（koc=287.8）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(861,46,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(862,46,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2432\n\n联合国正确运输名称\nN,N-二乙基苯胺\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(863,46,15,'法规信息','国际化学品名录\n\nN,N-二乙基苯胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\nN,N-二乙基苯胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(864,46,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(865,47,1,'化学品及企业标识','产品标识\n\n产品中文名称\nN-苯基乙酰胺\n\n产品英文名称\nN-phenylacetamide|acetanilide|antifebrine\n\n别名\n乙酰苯胺|退热冰\n\nCAS NO.\n103-84-4\n\nEC NO.\n203-150-7\n\n分子式\nC8H9NO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(866,47,2,'危险性概述','紧急情况概述\n\n固体。对皮肤有刺激性。对眼睛有严重刺激性。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触可造成皮肤刺激。\n\n眼睛\n本品能造成严重眼刺激。眼睛直接接触可能会造成严重的炎症并伴随有疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(867,47,3,'成分/组成信息','N-苯基乙酰胺\n\nCas No.\n103-84-4\n\nEC No.\n203-150-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(868,47,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(869,47,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(870,47,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(871,47,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(872,47,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(873,47,9,'理化特性','外观与性状\n白色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n5~7（25℃，10g/L）\n\n熔点/凝固点(℃)\n114\n\n初沸点和沸程(℃)\n303.8\n\n闪点(闭杯，℃)\n173\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（114℃）\n\n蒸气密度(空气=1)\n4.65\n\n相对密度(水=1)\n1.21\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n1.16\n\n自燃温度(℃)\n539\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(874,47,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(875,47,11,'毒理学信息','急性毒性\n\nN-苯基乙酰胺\n103-84-4\n\nLD\n50\n(经口)\n800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\nN-苯基乙酰胺\n103-84-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\nN-苯基乙酰胺\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(876,47,12,'生态学信息','急性水生毒性\n\nN-苯基乙酰胺\n103-84-4\n\n鱼类\nLC\n50\n：108mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\nN-苯基乙酰胺：水/土壤-高 空气-高\n\n生物富集或生物积累性\nN-苯基乙酰胺：生物富集性-低（LogKOW=1.16）\n\n土壤中的迁移性\nN-苯基乙酰胺：土壤迁移性-低（koc=38.11）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(877,47,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(878,47,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(879,47,15,'法规信息','国际化学品名录\n\nN-苯基乙酰胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\nN-苯基乙酰胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(880,47,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(881,48,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氨\n\n产品英文名称\nAmmonia|Liquid ammonia\n\n别名\n液氨|氨气\n\nCAS NO.\n7664-41-7\n\nEC NO.\n231-635-3\n\n分子式\nNH3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(882,48,2,'危险性概述','紧急情况概述\n\n气体。易燃,有爆炸危险。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃气体\n类别 2\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH221\n易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，呼吸困难，气促,咽喉痛。症状可能推迟显现。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n发红，皮肤烧伤，疼痛，水疱。与液体接触：冻伤。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(883,48,3,'成分/组成信息','氨\n\nCas No.\n7664-41-7\n\nEC No.\n231-635-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(884,48,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱掉衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气,休息,半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(885,48,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(886,48,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(887,48,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(888,48,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氨\nGBZ 2.1-2007\n\nPC-TWA\n20 mg/m3\n\nPC-STEL\n30 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(889,48,9,'理化特性','外观与性状\n液化气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-78\n\n初沸点和沸程(℃)\n-33\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：28；下限：15\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n651\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(890,48,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与卤素或强氧化剂接触引起燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素和强氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(891,48,11,'毒理学信息','急性毒性\n\n氨\n7664-41-7\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n氨\n7664-41-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氨\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(892,48,12,'生态学信息','急性水生毒性\n\n氨\n7664-41-7\n\n鱼类\nLC\n50\n：27.1mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氨：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氨：生物富集性-低（LogKOW=0.229）\n\n土壤中的迁移性\n氨：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(893,48,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(894,48,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1005\n\n联合国正确运输名称\n无水氨\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:16','2025-10-21 07:50:16'),(895,48,15,'法规信息','国际化学品名录\n\n氨\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氨\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(896,48,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:16','2025-10-21 07:50:16'),(897,49,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氨溶液[含氨＞10%]\n\n产品英文名称\nammonia solution(more than 10%)\n\n别名\n氨水\n\nCAS NO.\n1336-21-6\n\nEC NO.\n215-647-6\n\n分子式\nH5NO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(898,49,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(899,49,3,'成分/组成信息','氨\n\nCas No.\n1336-21-6\n\nEC No.\n215-647-6\n\n含量范围（质量分数，%）\n> 10',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(900,49,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(901,49,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(902,49,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(903,49,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(904,49,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(905,49,9,'理化特性','外观与性状\n无色溶液\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-58（0.25）\n\n初沸点和沸程(℃)\n38（0.25）\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n48（20℃,25%）\n\n蒸气密度(空气=1)\n0.6~1.2\n\n相对密度(水=1)\n0.9\n\n溶解性(mg/L)\n可溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n630\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(906,49,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(907,49,11,'毒理学信息','急性毒性\n\n氨\n1336-21-6\n\nLD\n50\n(经口)\n350mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氨\n1336-21-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氨\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(908,49,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氨：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氨：生物富集性-低（LogKOW=0.229）\n\n土壤中的迁移性\n氨：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(909,49,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(910,49,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2672\n\n联合国正确运输名称\n氨溶液，水溶液在15℃时的相对密度为0.880 至0.975, 含氨量10%-35%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(911,49,15,'法规信息','国际化学品名录\n\n氨\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氨\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(912,49,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(913,50,1,'化学品及企业标识','产品标识\n\n产品中文名称\n八氟异丁烯\n\n产品英文名称\noctafluoroisobutylene|perfluoroisobutylene|1,1,3,3,3-pentafluoro-2-(trifluoromethyl)-1-propene\n\n别名\n全氟异丁烯|1,1,3,3,3-五氟-2-(三氟甲基)-1-丙烯\n\nCAS NO.\n382-21-8\n\nEC NO.\n609-533-9\n\n分子式\nC4F8\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(914,50,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。吸入有剧毒。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n急性吸入毒性\n类别 1\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH330\n吸入致命\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咽喉痛。咳嗽。恶心。头痛。虚弱。气促。呼吸困难。症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(915,50,3,'成分/组成信息','八氟异丁烯\n\nCas No.\n382-21-8\n\nEC No.\n-\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(916,50,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(917,50,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(918,50,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(919,50,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(920,50,8,'接触控制/个体防护','控制参数->职业接触限值\n\n八氟异丁烯\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(921,50,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n7\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(922,50,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(923,50,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n八氟异丁烯\n382-21-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n八氟异丁烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(924,50,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n八氟异丁烯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n八氟异丁烯：生物富集性-低（LogKOW=3.0312）\n\n土壤中的迁移性\n八氟异丁烯：土壤迁移性-低（koc=2074）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(925,50,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(926,50,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1955\n\n联合国正确运输名称\n压缩气体, 毒性，未另作规定的\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(927,50,15,'法规信息','国际化学品名录\n\n八氟异丁烯\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n未列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n未列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n未列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n八氟异丁烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(928,50,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(929,51,1,'化学品及企业标识','产品标识\n\n产品中文名称\n白磷\n\n产品英文名称\nphosphorus white|phosphorus yellow\n\n别名\n黄磷\n\nCAS NO.\n12185-10-3\n\nEC NO.\n601-810-2\n\n分子式\nP4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(930,51,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易自身燃烧,有引发火灾的危险。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n自燃固体\n类别 1\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH250\n暴露在空气中会自燃\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP222\n不得与空气接触。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP422\n内装物存放在适当的液体或惰性气体中。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n即使数量很少，在与空气接触五分钟内即可自燃。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,呼吸困难,气促,咽喉痛,神志不清,症状可能推迟显现。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。神志不清。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。水疱。\n\n眼睛\n发红。疼痛。视力丧失。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(931,51,3,'成分/组成信息','白磷\n\nCas No.\n12185-10-3\n\nEC No.\n-\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(932,51,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗,然后脱去污染的衣服并再次冲洗,给予医疗护理,急救时戴防护手套,\n\n食入\n漱口,催吐(仅对清醒病人!),休息,催吐时戴防护手套,给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(933,51,5,'消防措施','灭火介质\n\n适合的灭火介质\n干式化学灭火剂、纯碱、石灰或干砂。\n\n不适合的灭火介质\n不要使用水、二氧化碳或泡沫灭火剂。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(934,51,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(935,51,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(936,51,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(937,51,9,'理化特性','外观与性状\n白色或浅黄色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n44（分解）\n\n初沸点和沸程(℃)\n280\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.83\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n30\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(938,51,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(939,51,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n白磷\n12185-10-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n白磷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(940,51,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n白磷：生物富集性-高（BCF=2310000）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(941,51,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(942,51,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1381\n\n联合国正确运输名称\n白磷，干的\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(943,51,15,'法规信息','国际化学品名录\n\n白磷\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n未列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n白磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(944,51,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(945,8,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯\n\n产品英文名称\nbenzene|benzol\n\n别名\n纯苯\n\nCAS NO.\n71-43-2\n\nEC NO.\n200-753-7\n\n分子式\nC6H6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(946,8,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对皮肤有刺激性。对眼睛有严重刺激性。长期暴露有严重损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH372\n长期或反复接触会对器官造成损害\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP331\n不得诱导呕吐。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕,倦睡,头痛,恶心,气促,惊厥,神志不清。\n\n食入\n腹部疼痛。咽喉疼痛。呕吐。（另见吸入）。\n\n皮肤接触\n可能被吸收!皮肤干燥,发红,疼痛(另见吸入)。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(947,8,3,'成分/组成信息','苯\n\nCas No.\n71-43-2\n\nEC No.\n200-753-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(948,8,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(949,8,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(950,8,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(951,8,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(952,8,8,'接触控制/个体防护','控制参数->职业接触限值\n\n苯\nGBZ 2.1-2007\n\nPC-TWA\n3 mg/m3\n\nPC-STEL\n6 mg/m3\n\n备注\n皮，G1\n\n控制参数->生物限值\n\n苯\nGBZ 2.1-2019\n\n生物检测指标\n尿中苯巯基尿酸\n\n生物限值\n47 μmol/mol Cr（100 μg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n生物检测指标\n尿中反-反式粘糠酸\n\n生物限值\n2.4 mmol/mol Cr（3.0 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(953,8,9,'理化特性','外观与性状\n透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n6\n\n初沸点和沸程(℃)\n80\n\n闪点(闭杯，℃)\n-11\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8；下限：1.2\n\n蒸气压\n10（20℃）\n\n蒸气密度(空气=1)\n2.7\n\n相对密度(水=1)\n0.879（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.13\n\n自燃温度(℃)\n498\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(954,8,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(955,8,11,'毒理学信息','急性毒性\n\n苯\n71-43-2\n\nLD\n50\n(经口)\n930mg/kg(大鼠)\n\nLD\n50\n(经皮)\n930mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n苯\n71-43-2\n\nIARC\n类别1\n\nNTP\n类别K\n\n其他信息\n\n组分\n苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(956,8,12,'生态学信息','急性水生毒性\n\n苯\n71-43-2\n\n鱼类\nLC\n50\n：21.6mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：10.9mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：1600mg/L (96h)()\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(957,8,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(958,8,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1114\n\n联合国正确运输名称\n苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(959,8,15,'法规信息','国际化学品名录\n\n苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(960,8,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(961,52,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯胺\n\n产品英文名称\naniline|aminobenzene\n\n别名\n氨基苯\n\nCAS NO.\n62-53-3\n\nEC NO.\n200-539-3\n\n分子式\nC6H7N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(962,52,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有毒。可能有发生不可逆性作用的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH341\n怀疑可造成遗传性缺陷\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n嘴唇发青或手指发青。皮肤发青,头痛,头晕,呼吸困难,惊厥,心跳增加,呕吐,虚弱,神志不清。症状可能推迟显现。\n\n食入\n另见吸入。\n\n皮肤接触\n可能被吸收！发红。另见吸入。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(963,52,3,'成分/组成信息','苯胺\n\nCas No.\n62-53-3\n\nEC No.\n200-539-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(964,52,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n漱口。催吐（仅对清醒病人！），给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(965,52,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(966,52,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(967,52,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(968,52,8,'接触控制/个体防护','控制参数->职业接触限值\n\n苯胺\nGBZ 2.1-2007\n\nPC-TWA\n3 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(969,52,9,'理化特性','外观与性状\n无色至淡黄色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n8（2%溶液）\n\n熔点/凝固点(℃)\n-6\n\n初沸点和沸程(℃)\n184\n\n闪点(闭杯，℃)\n70\n\n蒸发速率\n无资料\n\n易燃性\n可燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11；下限：1.2\n\n蒸气压\n40Pa（20℃）\n\n蒸气密度(空气=1)\n3.2\n\n相对密度(水=1)\n1.02（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.94\n\n自燃温度(℃)\n615\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(970,52,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(971,52,11,'毒理学信息','急性毒性\n\n苯胺\n62-53-3\n\nLD\n50\n(经口)\n250mg/kg(大鼠)\n\nLD\n50\n(经皮)\n250mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n苯胺\n62-53-3\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯胺\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(972,52,12,'生态学信息','急性水生毒性\n\n苯胺\n62-53-3\n\n鱼类\nLC\n50\n：27mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.25mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：20mg/L (96h)()\n\n慢性水生毒性\n\n苯胺\n62-53-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.0063mg/L()\n\n藻类/水生植物\nNOEC：3.7mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(973,52,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(974,52,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1547\n\n联合国正确运输名称\n苯胺\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:17','2025-10-21 07:50:17'),(975,52,15,'法规信息','国际化学品名录\n\n苯胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(976,52,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:17','2025-10-21 07:50:17'),(977,53,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯酚\n\n产品英文名称\nphenol|carbolic acid|hydroxybenzene|phenylalcohol\n\n别名\n酚|石炭酸\n\nCAS NO.\n108-95-2\n\nEC NO.\n203-632-7\n\n分子式\nC6H6O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(978,53,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。可能有发生不可逆性作用的危险。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH341\n怀疑可造成遗传性缺陷\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛，灼烧感，咳嗽，头晕，头痛，恶心，呕吐，气促，呼吸困难，神志不清，症状可能推迟显现。\n\n食入\n腐蚀。腹部疼痛，惊厥，腹泻，休克或虚脱，咽喉疼痛。烟灰色、浅绿-暗色尿液。\n\n皮肤接触\n容易被吸收。严重皮肤烧伤。麻木，惊厥，虚脱，昏迷，死亡。\n\n眼睛\n疼痛，发红，永久失明，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(979,53,3,'成分/组成信息','苯酚\n\nCas No.\n108-95-2\n\nEC No.\n203-632-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(980,53,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。使用聚乙二醇300或植物油可以去除该物质。给予医疗护理。急救时戴防护手套。\n\n食入\n漱口。饮用1或2杯水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(981,53,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(982,53,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(983,53,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(984,53,8,'接触控制/个体防护','控制参数->职业接触限值\n\n苯酚\nGBZ 2.1-2007\n\nPC-TWA\n10 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n苯酚\nGBZ 2.1-2019\n\n生物检测指标\n尿中总酚\n\n生物限值\n150 mmol/mol Cr（125 mg/g Cr）\n\n采样时间\n工作周末的班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(985,53,9,'理化特性','外观与性状\n透明结晶固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n43\n\n初沸点和沸程(℃)\n182\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：10；下限：1.36\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.06（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n1.46\n\n自燃温度(℃)\n715\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(986,53,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与三氯化铝/硝基化合物的混合物接触，发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n三氯化铝、强氧化剂、硝酸盐、亚硝酸盐和卤素含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(987,53,11,'毒理学信息','急性毒性\n\n苯酚\n108-95-2\n\nLD\n50\n(经口)\n317mg/kg(大鼠)\n\nLD\n50\n(经皮)\n317mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n苯酚\n108-95-2\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯酚\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(988,53,12,'生态学信息','急性水生毒性\n\n苯酚\n108-95-2\n\n鱼类\nLC\n50\n：20.5mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：12.6mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：84.5mg/L (96h)(藻类)\n\n慢性水生毒性\n\n苯酚\n108-95-2\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：1.2mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：25mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(989,53,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(990,53,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1671\n\n联合国正确运输名称\n固态苯酚\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(991,53,15,'法规信息','国际化学品名录\n\n苯酚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯酚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(992,53,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(993,54,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯酚钠\n\n产品英文名称\nsodium phenolate|sodium phenoxide\n\n别名\n苯氧基钠\n\nCAS NO.\n139-02-6\n\nEC NO.\n205-347-3\n\n分子式\nC6H6O.Na\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(994,54,2,'危险性概述','紧急情况概述\n\n固体。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(995,54,3,'成分/组成信息','苯酚钠\n\nCas No.\n139-02-6\n\nEC No.\n205-347-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(996,54,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(997,54,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(998,54,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(999,54,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1000,54,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1001,54,9,'理化特性','外观与性状\n无色针状结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＞7（碱性）\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1002,54,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1003,54,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n苯酚钠\n139-02-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯酚钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1004,54,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1005,54,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1006,54,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1759\n\n联合国正确运输名称\n腐蚀性固体，未另作规定的\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1007,54,15,'法规信息','国际化学品名录\n\n苯酚钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯酚钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1008,54,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1009,55,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯醌\n\n产品英文名称\nbenzoquinone\n\n别名\n-\n\nCAS NO.\n106-51-4\n\nEC NO.\n203-405-2\n\n分子式\nC6H4O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1010,55,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,呼吸困难,气促，咽喉疼痛。\n\n食入\n腹部疼痛，灼烧感，腹泻，呕吐。\n\n皮肤接触\n发红,疼痛,脱色,水疱。\n\n眼睛\n发红，疼痛，视力模糊，棕色斑。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1011,55,3,'成分/组成信息','苯醌\n\nCas No.\n106-51-4\n\nEC No.\n203-405-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1012,55,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱掉污染的衣服,冲洗,然后用水和肥皂洗皮肤，给予医疗护理。\n\n食入\n漱口,用水冲服活性炭浆,不要催吐,给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1013,55,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1014,55,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1015,55,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1016,55,8,'接触控制/个体防护','控制参数->职业接触限值\n\n苯醌\nGBZ 2.1-2007\n\nPC-TWA\n0.45 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1017,55,9,'理化特性','外观与性状\n黄色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n4（20℃，1g/L）\n\n熔点/凝固点(℃)\n116\n\n初沸点和沸程(℃)\n180\n\n闪点(闭杯，℃)\n38~93\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n12Pa（20℃）\n\n蒸气密度(空气=1)\n3.7\n\n相对密度(水=1)\n1.3\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n0.2\n\n自燃温度(℃)\n560\n\n分解温度(℃)\n60~70\n\n黏度\n不适用',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1018,55,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1019,55,11,'毒理学信息','急性毒性\n\n苯醌\n106-51-4\n\nLD\n50\n(经口)\n130mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n苯醌\n106-51-4\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯醌\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1020,55,12,'生态学信息','急性水生毒性\n\n苯醌\n106-51-4\n\n鱼类\nLC\n50\n：0.125mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n苯醌：水/土壤-低(半衰期=10天) 空气-低(半衰期=0.28天)\n\n生物富集或生物积累性\n苯醌：生物富集性-低（LogKOW=0.2）\n\n土壤中的迁移性\n苯醌：土壤迁移性-高（koc=1.387）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1021,55,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1022,55,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2587\n\n联合国正确运输名称\n苯醌\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1023,55,15,'法规信息','国际化学品名录\n\n苯醌\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯醌\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1024,55,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1025,56,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯四甲酸酐\n\n产品英文名称\npyromellitic dianhydride|benzene-1,2,4,5-tetracarboxylic dianhydride\n\n别名\n均苯四甲酸酐\n\nCAS NO.\n89-32-7\n\nEC NO.\n201-898-9\n\n分子式\nC10H2O6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1026,56,2,'危险性概述','紧急情况概述\n\n固体。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。有引起过敏、哮喘病症状或呼吸困难的风险。\n\nGHS危险性类别\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n呼吸道致敏物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛，喘息，气促。\n\n食入\n灼烧感。\n\n皮肤接触\n发红，灼烧感。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1027,56,3,'成分/组成信息','苯四甲酸酐\n\nCas No.\n89-32-7\n\nEC No.\n201-898-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1028,56,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。不要催吐。\n\n吸入\n新鲜空气，休息。半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1029,56,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1030,56,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1031,56,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1032,56,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1033,56,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n287\n\n初沸点和沸程(℃)\n397~400\n\n闪点(闭杯，℃)\n380\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.68\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n630\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1034,56,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1035,56,11,'毒理学信息','急性毒性\n\n苯四甲酸酐\n89-32-7\n\nLD\n50\n(经口)\n2250mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n苯四甲酸酐\n89-32-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯四甲酸酐\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1036,56,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n苯四甲酸酐：水/土壤-高 空气-高\n\n生物富集或生物积累性\n苯四甲酸酐：生物富集性-低（LogKOW=2.1446）\n\n土壤中的迁移性\n苯四甲酸酐：土壤迁移性-低（koc=178.4）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1037,56,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1038,56,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1039,56,15,'法规信息','国际化学品名录\n\n苯四甲酸酐\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯四甲酸酐\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1040,56,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1041,57,1,'化学品及企业标识','产品标识\n\n产品中文名称\n苯乙烯[稳定的]\n\n产品英文名称\nstyrene,stabilized|vinyl benzene\n\n别名\n乙烯苯\n\nCAS NO.\n100-42-5\n\nEC NO.\n202-851-5\n\n分子式\nC8H8\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1042,57,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对眼睛有严重刺激性。有轻微致癌性风险。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n致癌性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH351\n怀疑致癌\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕。倦睡。头痛。恶心。呕吐。虚弱。神志不清。\n\n食入\n恶心。呕吐。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1043,57,3,'成分/组成信息','苯乙烯\n\nCas No.\n100-42-5\n\nEC No.\n202-851-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1044,57,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。大量饮水。休息。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1045,57,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1046,57,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1047,57,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1048,57,8,'接触控制/个体防护','控制参数->职业接触限值\n\n苯乙烯\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n100 mg/m3\n\n备注\n皮，G2B\n\n控制参数->生物限值\n\n苯乙烯\nGBZ 2.1-2019\n\n生物检测指标\n尿中苯乙醇酸加苯乙醛酸\n\n生物限值\n295 mmol/mol Cr（400 mg/g Cr）\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1049,57,9,'理化特性','外观与性状\n无色油状液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-30.6\n\n初沸点和沸程(℃)\n145\n\n闪点(闭杯，℃)\n31\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：6.8；下限：0.9\n\n蒸气压\n0.67kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.6\n\n相对密度(水=1)\n0.99（25℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.0\n\n自燃温度(℃)\n490\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1050,57,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1051,57,11,'毒理学信息','急性毒性\n\n苯乙烯\n100-42-5\n\nLD\n50\n(经口)\n2650mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n2650mg/kg(大鼠)\n\n致癌性\n\n苯乙烯\n100-42-5\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n苯乙烯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1052,57,12,'生态学信息','急性水生毒性\n\n苯乙烯\n100-42-5\n\n鱼类\nLC\n50\n：25mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4.7mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：0.72mg/L (96h)()\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1053,57,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1054,57,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2055\n\n联合国正确运输名称\n单体苯乙烯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1055,57,15,'法规信息','国际化学品名录\n\n苯乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n苯乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1056,57,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1057,58,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙二腈\n\n产品英文名称\nmalononitrile|dicyanomethane|methylene cyanide\n\n别名\n二氰甲烷|氰化亚甲基|缩苹果腈\n\nCAS NO.\n109-77-3\n\nEC NO.\n203-703-2\n\n分子式\nC3H2N2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1058,58,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。吸入有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n头晕,呼吸困难,恶心,呕吐,虚弱,意识模糊,惊厥,神志不清。\n\n食入\n腹部疼痛(另见吸入)。\n\n皮肤接触\n可能被吸收！发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1059,58,3,'成分/组成信息','丙二腈\n\nCas No.\n109-77-3\n\nEC No.\n203-703-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1060,58,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤,给予医疗护理。\n\n食入\n漱口。用水冲服活性炭浆。催吐(仅对清醒病人!)。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1061,58,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1062,58,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1063,58,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1064,58,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1065,58,9,'理化特性','外观与性状\n白色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n30~34\n\n初沸点和沸程(℃)\n218~220\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.19\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.6\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1066,58,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1067,58,11,'毒理学信息','急性毒性\n\n丙二腈\n109-77-3\n\nLD\n50\n(经口)\n14mg/kg(大鼠)\n\nLD\n50\n(经皮)\n14mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n丙二腈\n109-77-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙二腈\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1068,58,12,'生态学信息','急性水生毒性\n\n丙二腈\n109-77-3\n\n鱼类\nLC\n50\n：1.56mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n丙二腈：水/土壤-低 空气-低\n\n生物富集或生物积累性\n丙二腈：生物富集性-低（LogKOW=-0.6）\n\n土壤中的迁移性\n丙二腈：土壤迁移性-低（koc=15.31）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1069,58,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1070,58,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2647\n\n联合国正确运输名称\n丙二腈\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:18','2025-10-21 07:50:18'),(1071,58,15,'法规信息','国际化学品名录\n\n丙二腈\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙二腈\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1072,58,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:18','2025-10-21 07:50:18'),(1073,59,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙酸\n\n产品英文名称\npropionic acid\n\n别名\n-\n\nCAS NO.\n79-09-4\n\nEC NO.\n201-176-3\n\n分子式\nC3H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1074,59,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，气促，咽喉痛。\n\n食入\n胃痉挛，灼烧感，恶心，咽喉痛，休克或虚脱，呕吐。\n\n皮肤接触\n皮肤烧伤，疼痛，水疱。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1075,59,3,'成分/组成信息','丙酸\n\nCas No.\n79-09-4\n\nEC No.\n201-176-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1076,59,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，饮用1或2杯水，不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1077,59,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1078,59,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1079,59,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1080,59,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙酸\nGBZ 2.1-2007\n\nPC-TWA\n30 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1081,59,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n2.5（20℃，100g/L）\n\n熔点/凝固点(℃)\n-21\n\n初沸点和沸程(℃)\n141\n\n闪点(闭杯，℃)\n54\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：12；下限：2.1\n\n蒸气压\n390Pa（20℃）\n\n蒸气密度(空气=1)\n2.6\n\n相对密度(水=1)\n0.99（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.33\n\n自燃温度(℃)\n485\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1082,59,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n具有可燃性，其蒸气（或粉末）与空气接触可形成爆炸性混合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、糠醇、乙醛、硝酸、硝酸盐、亚硝酸盐、卤素的含氧酸盐和无机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1083,59,11,'毒理学信息','急性毒性\n\n丙酸\n79-09-4\n\nLD\n50\n(经口)\n2600mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n丙酸\n79-09-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1084,59,12,'生态学信息','急性水生毒性\n\n丙酸\n79-09-4\n\n鱼类\nLC\n50\n：76.2mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：22.7mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n丙酸：水/土壤-低 空气-低\n\n生物富集或生物积累性\n丙酸：生物富集性-低（LogKOW=0.33）\n\n土壤中的迁移性\n丙酸：土壤迁移性-高（koc=1.201）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1085,59,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1086,59,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3463\n\n联合国正确运输名称\n丙酸，按重量含酸不小于90%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1087,59,15,'法规信息','国际化学品名录\n\n丙酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1088,59,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1089,60,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙酮\n\n产品英文名称\nacetone|propanone|dimethyl ketone\n\n别名\n二甲基酮\n\nCAS NO.\n67-64-1\n\nEC NO.\n200-662-2\n\n分子式\nC3H6O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1090,60,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咽喉痛。咳嗽。意识模糊。头痛。头晕。倦睡。神志不清。\n\n食入\n恶心。呕吐。(另见吸入)。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1091,60,3,'成分/组成信息','丙酮\n\nCas No.\n67-64-1\n\nEC No.\n200-662-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1092,60,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1093,60,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1094,60,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1095,60,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1096,60,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙酮\nGBZ 2.1-2007\n\nPC-TWA\n300 mg/m3\n\nPC-STEL\n450 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n丙酮\nGBZ 2.1-2019\n\n生物检测指标\n尿中丙酮\n\n生物限值\n50 mg/L\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1097,60,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-95\n\n初沸点和沸程(℃)\n56\n\n闪点(闭杯，℃)\n-18\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：13；下限：2.2\n\n蒸气压\n24kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.0\n\n相对密度(水=1)\n0.79（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.24\n\n自燃温度(℃)\n465\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1098,60,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触易发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、氯仿、溴仿以及其它有机溶剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1099,60,11,'毒理学信息','急性毒性\n\n丙酮\n67-64-1\n\nLD\n50\n(经口)\n5800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n5800mg/kg(大鼠)\n\n致癌性\n\n丙酮\n67-64-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙酮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1100,60,12,'生态学信息','急性水生毒性\n\n丙酮\n67-64-1\n\n鱼类\nLC\n50\n：8300mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：18500mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：7200mg/L (96h)()\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1101,60,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1102,60,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1090\n\n联合国正确运输名称\n丙酮\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1103,60,15,'法规信息','国际化学品名录\n\n丙酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1104,60,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1105,61,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烷\n\n产品英文名称\npropane\n\n别名\n-\n\nCAS NO.\n74-98-6\n\nEC NO.\n200-827-9\n\n分子式\nC3H8\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1106,61,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n倦睡。神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n与液体接触：冻伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1107,61,3,'成分/组成信息','丙烷\n\nCas No.\n74-98-6\n\nEC No.\n200-827-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1108,61,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1109,61,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1110,61,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1111,61,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1112,61,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1113,61,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-189.7\n\n初沸点和沸程(℃)\n-42\n\n闪点(闭杯，℃)\n-104\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：9.5；下限：2.1\n\n蒸气压\n840kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.6\n\n相对密度(水=1)\n0.5\n\n溶解性(mg/L)\n微溶于水\n\n辛醇 /水分配系数\n2.36\n\n自燃温度(℃)\n450\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1114,61,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1115,61,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n丙烷\n74-98-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1116,61,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1117,61,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1118,61,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1978\n\n联合国正确运输名称\n丙烷\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1119,61,15,'法规信息','国际化学品名录\n\n丙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1120,61,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1121,62,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烯酸[稳定的]\n\n产品英文名称\nacrylic acid,stabilized|prop-2-enoic acid\n\n别名\n-\n\nCAS NO.\n79-10-7\n\nEC NO.\n201-177-9\n\n分子式\nC3H4O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1122,62,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,气促,腐蚀作用,呼吸困难,咽喉疼痛。症状可能推迟显现。\n\n食入\n灼烧感,虚弱,腐蚀作用,胃痉挛,腹泻,神志不清,休克。\n\n皮肤接触\n可能被吸收，发红，疼痛，水疱。\n\n眼睛\n发红，疼痛，视力丧失，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1123,62,3,'成分/组成信息','丙烯酸\n\nCas No.\n79-10-7\n\nEC No.\n201-177-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1124,62,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1125,62,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、泡沫、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1126,62,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1127,62,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1128,62,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙烯酸\nGBZ 2.1-2007\n\nPC-TWA\n6 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1129,62,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n2.1（20℃，72.06g/L，计算值）\n\n熔点/凝固点(℃)\n14\n\n初沸点和沸程(℃)\n141\n\n闪点(闭杯，℃)\n54\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8；下限：2.4\n\n蒸气压\n413Pa（20℃）\n\n蒸气密度(空气=1)\n2.5\n\n相对密度(水=1)\n1.05（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.36\n\n自燃温度(℃)\n360\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1130,62,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸和有机过氧化物接触发生剧烈聚合。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、碱和有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1131,62,11,'毒理学信息','急性毒性\n\n丙烯酸\n79-10-7\n\nLD\n50\n(经口)\n33.5mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n丙烯酸\n79-10-7\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烯酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1132,62,12,'生态学信息','急性水生毒性\n\n丙烯酸\n79-10-7\n\n鱼类\nLC\n50\n：62mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：47mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.75mg/L (72h)(藻类)\n\n慢性水生毒性\n\n丙烯酸\n79-10-7\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：0.030mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1133,62,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1134,62,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2218\n\n联合国正确运输名称\n丙烯酸，稳定的\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1135,62,15,'法规信息','国际化学品名录\n\n丙烯酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烯酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1136,62,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1137,63,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烯酸甲酯[稳定的]\n\n产品英文名称\nmethyl acrylate,stabilized|methyl propenoate\n\n别名\n-\n\nCAS NO.\n96-33-3\n\nEC NO.\n202-500-6\n\n分子式\nC4H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1138,63,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。气促。咽喉痛。\n\n食入\n腹部疼痛。腹泻。恶心。呕吐。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1139,63,3,'成分/组成信息','丙烯酸甲酯\n\nCas No.\n96-33-3\n\nEC No.\n202-500-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1140,63,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1141,63,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1142,63,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1143,63,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1144,63,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙烯酸甲酯\nGBZ 2.1-2007\n\nPC-TWA\n20 mg/m3\n\nPC-STEL\n-\n\n备注\n皮，敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1145,63,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-76.5\n\n初沸点和沸程(℃)\n80.5\n\n闪点(闭杯，℃)\n-2.8\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：25；下限：2.8\n\n蒸气压\n9.1kPa（20℃）\n\n蒸气密度(空气=1)\n3.0\n\n相对密度(水=1)\n0.956（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.8\n\n自燃温度(℃)\n468\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1146,63,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸和有机过氧化物接触发生剧烈聚合。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、碱和有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1147,63,11,'毒理学信息','急性毒性\n\n丙烯酸甲酯\n96-33-3\n\nLD\n50\n(经口)\n277mg/kg(大鼠)\n\nLD\n50\n(经皮)\n277mg/kg(大鼠)\n\nLD\n50\n(吸入)\n277mg/kg(大鼠)\n\n致癌性\n\n丙烯酸甲酯\n96-33-3\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烯酸甲酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1148,63,12,'生态学信息','急性水生毒性\n\n丙烯酸甲酯\n96-33-3\n\n鱼类\nLC\n50\n：1.4mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：2.6mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：3.1mg/L (72h)(藻类)\n\n慢性水生毒性\n\n丙烯酸甲酯\n96-33-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.36mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：1.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1149,63,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1150,63,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1919\n\n联合国正确运输名称\n丙烯酸甲酯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1151,63,15,'法规信息','国际化学品名录\n\n丙烯酸甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烯酸甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1152,63,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1153,64,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烯酸乙酯[稳定的]\n\n产品英文名称\nethyl acrylate,stabilized\n\n别名\n-\n\nCAS NO.\n140-88-5\n\nEC NO.\n205-438-8\n\n分子式\nC5H8O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1154,64,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有刺激作用。有轻微致癌性风险。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n致癌性\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH351\n怀疑致癌\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咳嗽。气促。咽喉痛。\n\n食入\n腹部疼痛。腹泻。恶心。呕吐。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1155,64,3,'成分/组成信息','丙烯酸乙酯\n\nCas No.\n140-88-5\n\nEC No.\n205-438-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1156,64,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1157,64,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1158,64,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1159,64,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1160,64,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1161,64,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-71\n\n初沸点和沸程(℃)\n99\n\n闪点(闭杯，℃)\n9\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：14；下限：1.4\n\n蒸气压\n3.9kPa（20℃）\n\n蒸气密度(空气=1)\n3.45\n\n相对密度(水=1)\n0.92\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.32\n\n自燃温度(℃)\n345\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1162,64,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸和有机过氧化物接触发生剧烈聚合。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、碱和有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1163,64,11,'毒理学信息','急性毒性\n\n丙烯酸乙酯\n140-88-5\n\nLD\n50\n(经口)\n800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n800mg/kg(大鼠)\n\nLD\n50\n(吸入)\n800mg/kg(大鼠)\n\n致癌性\n\n丙烯酸乙酯\n140-88-5\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烯酸乙酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1164,64,12,'生态学信息','急性水生毒性\n\n丙烯酸乙酯\n140-88-5\n\n鱼类\nLC\n50\n：1.2mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4.4mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：2.3mg/L (72h)(藻类)\n\n慢性水生毒性\n\n丙烯酸乙酯\n140-88-5\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.46mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：0.96mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1165,64,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1166,64,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1917\n\n联合国正确运输名称\n丙烯酸乙酯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:19','2025-10-21 07:50:19'),(1167,64,15,'法规信息','国际化学品名录\n\n丙烯酸乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烯酸乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1168,64,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:19','2025-10-21 07:50:19'),(1169,65,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烯酸正丁酯[稳定的]\n\n产品英文名称\nn-butyl acrylate,stabilized\n\n别名\n-\n\nCAS NO.\n141-32-2\n\nEC NO.\n205-480-7\n\n分子式\nC7H12O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1170,65,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咳嗽。气促。咽喉痛。\n\n食入\n腹部疼痛。恶心。呕吐。腹泻。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1171,65,3,'成分/组成信息','丙烯酸正丁酯\n\nCas No.\n141-32-2\n\nEC No.\n205-480-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1172,65,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1173,65,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1174,65,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1175,65,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1176,65,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙烯酸正丁酯\nGBZ 2.1-2007\n\nPC-TWA\n25 mg/m3\n\nPC-STEL\n-\n\n备注\n敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1177,65,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-64\n\n初沸点和沸程(℃)\n145~149\n\n闪点(闭杯，℃)\n36\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：9.9；下限：1.3\n\n蒸气压\n0.43kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.42\n\n相对密度(水=1)\n0.90\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.38\n\n自燃温度(℃)\n267\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1178,65,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸和有机过氧化物接触发生剧烈聚合。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、碱和有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1179,65,11,'毒理学信息','急性毒性\n\n丙烯酸正丁酯\n141-32-2\n\nLD\n50\n(经口)\n900mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n900mg/kg(大鼠)\n\n致癌性\n\n丙烯酸正丁酯\n141-32-2\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烯酸正丁酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1180,65,12,'生态学信息','急性水生毒性\n\n丙烯酸正丁酯\n141-32-2\n\n鱼类\nLC\n50\n：2.4mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：5.2mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：1.7mg/L (72h)()\n\n慢性水生毒性\n\n丙烯酸正丁酯\n141-32-2\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：1.0mg/L()\n\n藻类/水生植物\nNOEC：0.077mg/L()\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1181,65,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1182,65,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2348\n\n联合国正确运输名称\n丙烯酸丁酯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1183,65,15,'法规信息','国际化学品名录\n\n丙烯酸正丁酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烯酸正丁酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1184,65,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1185,66,1,'化学品及企业标识','产品标识\n\n产品中文名称\n丙烯酰胺\n\n产品英文名称\nacrylamide\n\n别名\n-\n\nCAS NO.\n79-06-1\n\nEC NO.\n201-173-7\n\n分子式\nC3H5NO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1186,66,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1B\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛，虚弱。\n\n食入\n腹部疼痛，虚弱。\n\n皮肤接触\n可能被吸收！发红，疼痛。（另见吸入）。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1187,66,3,'成分/组成信息','丙烯酰胺\n\nCas No.\n79-06-1\n\nEC No.\n201-173-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1188,66,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理\n\n食入\n漱口，催吐（仅对清醒病人！），大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1189,66,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1190,66,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1191,66,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1192,66,8,'接触控制/个体防护','控制参数->职业接触限值\n\n丙烯酰胺\nGBZ 2.1-2007\n\nPC-TWA\n0.3 mg/m3\n\nPC-STEL\n-\n\n备注\n皮，G2A\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1193,66,9,'理化特性','外观与性状\n白色晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n5.0~7.0（20℃，50g/L）\n\n熔点/凝固点(℃)\n84.5\n\n初沸点和沸程(℃)\n125\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.122（30℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-1.65~-0.67\n\n自燃温度(℃)\n424\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1194,66,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在酸或碱的催化下可水解为酸和胺(氨）。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n酸、碱、氧化剂、氨、异氰酸酯、苯酚和甲酚。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1195,66,11,'毒理学信息','急性毒性\n\n丙烯酰胺\n79-06-1\n\nLD\n50\n(经口)\n124mg/kg(大鼠)\n\nLD\n50\n(经皮)\n124mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n丙烯酰胺\n79-06-1\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n丙烯酰胺\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1196,66,12,'生态学信息','急性水生毒性\n\n丙烯酰胺\n79-06-1\n\n鱼类\nLC\n50\n：122mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：98mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1197,66,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1198,66,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2074\n\n联合国正确运输名称\n丙烯酰胺，固态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1199,66,15,'法规信息','国际化学品名录\n\n丙烯酰胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n丙烯酰胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1200,66,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1201,67,1,'化学品及企业标识','产品标识\n\n产品中文名称\n柴油[闭杯闪点≤60℃]\n\n产品英文名称\nlight diesel oil\n\n别名\n-\n\nCAS NO.\n68334-30-5\n\nEC NO.\n269-822-7\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1202,67,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1203,67,3,'成分/组成信息','柴油\n\nCas No.\n68334-30-5\n\nEC No.\n269-822-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1204,67,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1205,67,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1206,67,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1207,67,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1208,67,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1209,67,9,'理化特性','外观与性状\n油状液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n&gt;=23,&lt;=60\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n无资料\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1210,67,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1211,67,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n柴油\n68334-30-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n柴油\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1212,67,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1213,67,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1214,67,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1202\n\n联合国正确运输名称\n柴油\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1215,67,15,'法规信息','国际化学品名录\n\n柴油\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n柴油\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1216,67,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1217,68,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氮[压缩的]\n\n产品英文名称\nnitrogen,compressed\n\n别名\n-\n\nCAS NO.\n7727-37-9\n\nEC NO.\n231-783-9\n\n分子式\nN2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1218,68,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n神志不清，虚弱，窒息。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1219,68,3,'成分/组成信息','氮\n\nCas No.\n7727-37-9\n\nEC No.\n231-783-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1220,68,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1221,68,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1222,68,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1223,68,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1224,68,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1225,68,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-210\n\n初沸点和沸程(℃)\n-196\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1226,68,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属乙炔化合物的混合物在加热时，发生燃烧或白炽化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属乙炔化合物、卤素及卤间化合物、卤素的氧化物、硝酸、氧化氮、硝酸盐、亚硝酸盐、卤素含氧酸盐、铬酸盐、高锰酸盐、无机过氧化物、金属氧化物和过氧甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1227,68,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氮\n7727-37-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1228,68,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1229,68,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1230,68,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1066\n\n联合国正确运输名称\n压缩氮\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1231,68,15,'法规信息','国际化学品名录\n\n氮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1232,68,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1233,69,1,'化学品及企业标识','产品标识\n\n产品中文名称\n碘化氢[无水]\n\n产品英文名称\nhydrogen iodide,anhydrous\n\n别名\n-\n\nCAS NO.\n10034-85-2\n\nEC NO.\n233-109-9\n\n分子式\nHI\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1234,69,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。胸骨后灼烧感。呼吸短促。呼吸困难。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n发红。疼痛。严重的皮肤烧伤。水疱。与液体接触：冻伤。\n\n眼睛\n发红。疼痛。严重烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1235,69,3,'成分/组成信息','碘化氢\n\nCas No.\n10034-85-2\n\nEC No.\n233-109-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1236,69,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴至少15分钟。冻伤时，用大量水冲洗，不要脱去衣服。立即给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n半直立体位。必要时进行人工呼吸。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1237,69,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1238,69,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1239,69,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1240,69,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1241,69,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-50.8\n\n初沸点和沸程(℃)\n-35.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n733kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.4\n\n相对密度(水=1)\n1.50~1.70\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1242,69,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1243,69,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n碘化氢\n10034-85-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n碘化氢\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1244,69,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1245,69,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1246,69,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2197\n\n联合国正确运输名称\n无水碘化氢\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:20','2025-10-21 07:50:20'),(1247,69,15,'法规信息','国际化学品名录\n\n碘化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n碘化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1248,69,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:20','2025-10-21 07:50:20'),(1249,70,1,'化学品及企业标识','产品标识\n\n产品中文名称\n叠氮化钠\n\n产品英文名称\nsodium azide\n\n别名\n三氮化钠\n\nCAS NO.\n26628-22-8\n\nEC NO.\n247-852-1\n\n分子式\nNaN3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1250,70,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，头痛，气促，神志不清，鼻塞，视力模糊，心跳缓慢，血压降低。\n\n食入\n腹部疼痛，恶心，出汗。另见吸入。\n\n皮肤接触\n可能被吸收！发红，水疱。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1251,70,3,'成分/组成信息','叠氮化钠\n\nCas No.\n26628-22-8\n\nEC No.\n247-852-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1252,70,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。不要催吐。饮用1或2杯水。休息，给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1253,70,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1254,70,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1255,70,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1256,70,8,'接触控制/个体防护','控制参数->职业接触限值\n\n叠氮化钠\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1257,70,9,'理化特性','外观与性状\n白色晶体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n275（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.8475\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n309\n\n分解温度(℃)\n275\n\n黏度\n不适用',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1258,70,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属镁、锌、白磷接触会发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n酸、镁、锌和白磷。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1259,70,11,'毒理学信息','急性毒性\n\n叠氮化钠\n26628-22-8\n\nLD\n50\n(经口)\n27mg/kg(大鼠)\n\nLD\n50\n(经皮)\n27mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n叠氮化钠\n26628-22-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n叠氮化钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1260,70,12,'生态学信息','急性水生毒性\n\n叠氮化钠\n26628-22-8\n\n鱼类\nLC\n50\n：2.8mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：5.3mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：0.348mg/L (96h)()\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1261,70,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1262,70,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1687\n\n联合国正确运输名称\n叠氮化钠\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1263,70,15,'法规信息','国际化学品名录\n\n叠氮化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n叠氮化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1264,70,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1265,71,1,'化学品及企业标识','产品标识\n\n产品中文名称\n多聚甲醛\n\n产品英文名称\npolymerized formaldehyde|paraform\n\n别名\n聚蚁醛|聚合甲醛\n\nCAS NO.\n30525-89-4\n\nEC NO.\n200-001-8\n\n分子式\n(CH2O)x\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1266,71,2,'危险性概述','紧急情况概述\n\n固体。易燃，其粉体与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。短期暴露有严重损伤健康的危险。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃固体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-一次接触\n类别 1\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH228\n易燃固体\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH370\n会损害器官\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇火或摩擦可被引燃，其粉体与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。呼吸困难。\n\n食入\n咽喉和胸腔灼烧感。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红,疼痛,烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1267,71,3,'成分/组成信息','多聚甲醛\n\nCas No.\n30525-89-4\n\nEC No.\n200-001-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1268,71,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。饮用1杯或2杯水。如果感觉不舒服，给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1269,71,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1270,71,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1271,71,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1272,71,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1273,71,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n5.5（20℃，饱和溶液，计算值）\n\n熔点/凝固点(℃)\n120~180（分解）\n\n初沸点和沸程(℃)\n150\n\n闪点(闭杯，℃)\n71\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：73；下限：7\n\n蒸气压\n0.16kPa（25℃）\n\n蒸气密度(空气=1)\n1.03\n\n相对密度(水=1)\n1.5\n\n溶解性(mg/L)\n微溶于水（20℃）\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n300\n\n分解温度(℃)\n120~180\n\n黏度\n不适用',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1274,71,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1275,71,11,'毒理学信息','急性毒性\n\n多聚甲醛\n30525-89-4\n\nLD\n50\n(经口)\n800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n800mg/kg(大鼠)\n\n致癌性\n\n多聚甲醛\n30525-89-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n多聚甲醛\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1276,71,12,'生态学信息','急性水生毒性\n\n多聚甲醛\n30525-89-4\n\n鱼类\nLC\n50\n：60mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1277,71,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1278,71,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2213\n\n联合国正确运输名称\n仲甲醛\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1279,71,15,'法规信息','国际化学品名录\n\n多聚甲醛\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n多聚甲醛\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1280,71,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1281,72,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二碘化汞\n\n产品英文名称\nmercury(Ⅱ)iodide|red mercuric iodide\n\n别名\n碘化汞|碘化高汞|红色碘化汞\n\nCAS NO.\n7774-29-0\n\nEC NO.\n231-873-8\n\n分子式\nHgI2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1282,72,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可导致严重的毒性反应。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。皮肤直接接触可造成皮肤刺激。皮肤接触可产生严重毒害作用，吸收后可产生全身影响，并可致命。\n\n眼睛\n本品能造成严重眼刺激。眼睛直接接触可能会造成严重的炎症并伴随有疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1283,72,3,'成分/组成信息','二碘化汞\n\nCas No.\n7774-29-0\n\nEC No.\n231-873-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1284,72,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1285,72,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1286,72,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1287,72,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1288,72,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n二碘化汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1289,72,9,'理化特性','外观与性状\n红色固体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n257~259\n\n初沸点和沸程(℃)\n349~354\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n6.28\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1290,72,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1291,72,11,'毒理学信息','急性毒性\n\n二碘化汞\n7774-29-0\n\nLD\n50\n(经口)\n18mg/kg(大鼠)\n\nLD\n50\n(经皮)\n18mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n二碘化汞\n7774-29-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二碘化汞\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1292,72,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1293,72,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1294,72,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2025\n\n联合国正确运输名称\n固态汞化合物，未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1295,72,15,'法规信息','国际化学品名录\n\n二碘化汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二碘化汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1296,72,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1297,73,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二甲苯异构体混合物\n\n产品英文名称\nxylene isomers mixture\n\n别名\n-\n\nCAS NO.\n1330-20-7\n\nEC NO.\n215-535-7\n\n分子式\nC8H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1298,73,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触可造成皮肤刺激。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1299,73,3,'成分/组成信息','二甲苯异构体混合物\n\nCas No.\n1330-20-7\n\nEC No.\n215-535-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1300,73,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1301,73,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1302,73,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1303,73,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1304,73,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二甲苯异构体混合物\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n100 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n二甲苯异构体混合物\nGBZ 2.1-2019\n\n生物检测指标\n尿中甲基马尿酸\n\n生物限值\n0.3 g/g Cr 或 0.4 g/L\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1305,73,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-48\n\n初沸点和沸程(℃)\n138~144\n\n闪点(闭杯，℃)\n27\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.7；下限：1.1\n\n蒸气压\n0.5kPa（15℃）\n\n蒸气密度(空气=1)\n3.66（15℃）\n\n相对密度(水=1)\n0.87（15℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n495~516\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1306,73,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1307,73,11,'毒理学信息','急性毒性\n\n二甲苯异构体混合物\n1330-20-7\n\nLD\n50\n(经口)\n4300mg/kg(大鼠)\n\nLD\n50\n(经皮)\n4300mg/kg(大鼠)\n\nLD\n50\n(吸入)\n4300mg/kg(大鼠)\n\n致癌性\n\n二甲苯异构体混合物\n1330-20-7\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n二甲苯异构体混合物\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1308,73,12,'生态学信息','急性水生毒性\n\n二甲苯异构体混合物\n1330-20-7\n\n鱼类\nLC\n50\n：15.7mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：8.5mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n二甲苯异构体混合物：水/土壤-高(半衰期=360天) 空气-低(半衰期=1.83天)\n\n生物富集或生物积累性\n二甲苯异构体混合物：生物富集性-中等（BCF=740）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1309,73,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1310,73,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1307\n\n联合国正确运输名称\n二甲苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1311,73,15,'法规信息','国际化学品名录\n\n二甲苯异构体混合物\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二甲苯异构体混合物\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1312,73,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1313,74,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二聚环戊二烯\n\n产品英文名称\ndicyclopentadiene|dimer|cyclopentadiene|3a,4,7,7a-tetrahydro-4,7-methanoindene|\n\n别名\n双茂|双环戊二烯|4,7-亚甲基-3a,4,7,7a-四氢茚\n\nCAS NO.\n77-73-6\n\nEC NO.\n201-052-9\n\n分子式\nC10H12\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1314,74,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头痛。\n\n食入\n腹部疼痛。恶心。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1315,74,3,'成分/组成信息','二聚环戊二烯\n\nCas No.\n77-73-6\n\nEC No.\n201-052-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1316,74,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1317,74,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1318,74,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1319,74,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1320,74,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二聚环戊二烯\nGBZ 2.1-2007\n\nPC-TWA\n25 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1321,74,9,'理化特性','外观与性状\n无色或淡黄色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n32~34\n\n初沸点和沸程(℃)\n170~172（分解）\n\n闪点(闭杯，℃)\n26.67\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：6.3；下限：0.8\n\n蒸气压\n180Pa（20℃）\n\n蒸气密度(空气=1)\n4.6~4.7\n\n相对密度(水=1)\n0.98\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.78\n\n自燃温度(℃)\n503\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1322,74,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1323,74,11,'毒理学信息','急性毒性\n\n二聚环戊二烯\n77-73-6\n\nLD\n50\n(经口)\n353mg/kg(大鼠)\n\nLD\n50\n(经皮)\n353mg/kg(大鼠)\n\nLD\n50\n(吸入)\n353mg/kg(大鼠)\n\n致癌性\n\n二聚环戊二烯\n77-73-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二聚环戊二烯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1324,74,12,'生态学信息','急性水生毒性\n\n二聚环戊二烯\n77-73-6\n\n鱼类\nLC\n50\n：29.4mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4.2mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1325,74,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1326,74,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2048\n\n联合国正确运输名称\n二聚环戊二烯(双茂)\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1327,74,15,'法规信息','国际化学品名录\n\n二聚环戊二烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二聚环戊二烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1328,74,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1329,75,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二硫化碳\n\n产品英文名称\ncarbon disulphide\n\n别名\n-\n\nCAS NO.\n75-15-0\n\nEC NO.\n200-843-6\n\n分子式\nCS2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1330,75,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH301\n吞咽会中毒\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n（另见吸入）。\n\n皮肤接触\n可能被吸收!皮肤干燥,发红(另见吸入)。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1331,75,3,'成分/组成信息','二硫化碳\n\nCas No.\n75-15-0\n\nEC No.\n200-843-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1332,75,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗,给予医疗护理。\n\n食入\n不要饮用任何东西，给予医疗护理。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1333,75,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1334,75,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1335,75,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1336,75,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二硫化碳\nGBZ 2.1-2007\n\nPC-TWA\n5 mg/m3\n\nPC-STEL\n10 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n二硫化碳\nGBZ 2.1-2019\n\n生物检测指标\n尿中 2 -硫代噻唑烷-4-羧酸\n\n生物限值\n1.5 mmol/ mol C（r 2.2 mg/g Cr）\n\n采样时间\n工作班末或接触末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1337,75,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-111\n\n初沸点和沸程(℃)\n46\n\n闪点(闭杯，℃)\n-30\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：50；下限：1\n\n蒸气压\n48kPa（25℃ ）\n\n蒸气密度(空气=1)\n2.63\n\n相对密度(水=1)\n1.26（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.84\n\n自燃温度(℃)\n90\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1338,75,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在空气中自燃。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝酸盐及亚硝酸盐、卤素的含氧酸盐、高锰酸盐、过硫酸盐、卤素和强氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1339,75,11,'毒理学信息','急性毒性\n\n二硫化碳\n75-15-0\n\nLD\n50\n(经口)\n1200mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n二硫化碳\n75-15-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二硫化碳\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1340,75,12,'生态学信息','急性水生毒性\n\n二硫化碳\n75-15-0\n\n鱼类\nLC\n50\n：4mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：21mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1341,75,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1342,75,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1131\n\n联合国正确运输名称\n二硫化碳\n\n运输主要危险类别\n3\n\n运输次要危险类别\n6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:21','2025-10-21 07:50:21'),(1343,75,15,'法规信息','国际化学品名录\n\n二硫化碳\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二硫化碳\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1344,75,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:21','2025-10-21 07:50:21'),(1345,76,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二氯硅烷\n\n产品英文名称\ndichlorosilane\n\n别名\n-\n\nCAS NO.\n4109-96-0\n\nEC NO.\n223-888-3\n\n分子式\nCl2H2Si\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1346,76,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。有严重损害眼睛的危险。吸入有剧毒。短期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH371\n可能损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n喉咙痛，咳嗽，烧灼感，气短，呼吸困难，症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n疼痛，发红，水泡，皮肤灼伤，严重的冻伤。\n\n眼睛\n疼痛，发红，严重深度烧伤，视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1347,76,3,'成分/组成信息','二氯硅烷\n\nCas No.\n4109-96-0\n\nEC No.\n223-888-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1348,76,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。立即给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1349,76,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1350,76,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1351,76,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1352,76,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1353,76,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-122\n\n初沸点和沸程(℃)\n8.3\n\n闪点(闭杯，℃)\n-52\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：96；下限：4.7\n\n蒸气压\n166.8kPa（20℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n41~47\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1354,76,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与空气、氯或溴接触会燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氯、溴、四氯化碳、氨、水和乙腈。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1355,76,11,'毒理学信息','急性毒性\n\n二氯硅烷\n4109-96-0\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n二氯硅烷\n4109-96-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二氯硅烷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1356,76,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1357,76,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1358,76,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2189\n\n联合国正确运输名称\n二氯硅烷\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1+8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1359,76,15,'法规信息','国际化学品名录\n\n二氯硅烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二氯硅烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1360,76,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1361,77,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二氯甲烷\n\n产品英文名称\ndichloromethane|methylene chloride|methylene dichloride\n\n别名\n亚甲基氯|甲撑氯\n\nCAS NO.\n75-09-2\n\nEC NO.\n200-838-9\n\n分子式\nCH2Cl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1362,77,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。对眼睛有严重刺激性。气体可能会引起头晕或窒息。有轻微致癌性风险。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n致癌性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH351\n怀疑致癌\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，头痛，恶心，虚弱，神志不清，死亡。\n\n食入\n腹部疼痛（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红，灼烧感。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1363,77,3,'成分/组成信息','二氯甲烷\n\nCas No.\n75-09-2\n\nEC No.\n200-838-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1364,77,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。大量饮水。休息。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1365,77,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1366,77,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22');
INSERT INTO `msds章节` VALUES (1367,77,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1368,77,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二氯甲烷\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n-\n\n备注\nG2A\n\n控制参数->生物限值\n\n二氯甲烷\nGBZ 2.1-2019\n\n生物检测指标\n尿中二氯甲烷\n\n生物限值\n0.3 mg/L\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1369,77,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-95.1\n\n初沸点和沸程(℃)\n40\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：25；下限：12\n\n蒸气压\n47.4kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.9\n\n相对密度(水=1)\n1.3\n\n溶解性(mg/L)\n20g/l（20℃）\n\n辛醇 /水分配系数\n1.25\n\n自燃温度(℃)\n556\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1370,77,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1371,77,11,'毒理学信息','急性毒性\n\n二氯甲烷\n75-09-2\n\nLD\n50\n(经口)\n1600mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n二氯甲烷\n75-09-2\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n二氯甲烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1372,77,12,'生态学信息','急性水生毒性\n\n二氯甲烷\n75-09-2\n\n鱼类\nLC\n50\n：310mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1470mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1373,77,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1374,77,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1593\n\n联合国正确运输名称\n二氯甲烷\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1375,77,15,'法规信息','国际化学品名录\n\n二氯甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二氯甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1376,77,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1377,78,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二氧化硫\n\n产品英文名称\nsulphur dioxide|sulfurous acid anhydride\n\n别名\n亚硫酸酐\n\nCAS NO.\n7446-09-5\n\nEC NO.\n231-195-2\n\n分子式\nSO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1378,78,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽。呼吸短促。咽喉痛。呼吸困难。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1379,78,3,'成分/组成信息','二氧化硫\n\nCas No.\n7446-09-5\n\nEC No.\n231-195-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1380,78,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗（如可能易行，摘除隐形眼镜）。给予医疗护理。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1381,78,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1382,78,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1383,78,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1384,78,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二氧化硫\nGBZ 2.1-2007\n\nPC-TWA\n5 mg/m3\n\nPC-STEL\n10 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1385,78,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-75.5\n\n初沸点和沸程(℃)\n-10\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1386,78,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1387,78,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n二氧化硫\n7446-09-5\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n二氧化硫\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1388,78,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1389,78,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1390,78,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1079\n\n联合国正确运输名称\n二氧化硫\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1391,78,15,'法规信息','国际化学品名录\n\n二氧化硫\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二氧化硫\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1392,78,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1393,79,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二氧化碳[压缩的]\n\n产品英文名称\ncarbon dioxide,compressed|carbonic anhydride\n\n别名\n碳酸酐\n\nCAS NO.\n124-38-9\n\nEC NO.\n204-696-9\n\n分子式\nCO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1394,79,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕。头痛。血压升高，心率增加。窒息。神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n与液体接触：冻伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1395,79,3,'成分/组成信息','二氧化碳\n\nCas No.\n124-38-9\n\nEC No.\n204-696-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1396,79,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1397,79,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1398,79,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1399,79,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1400,79,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二氧化碳\nGBZ 2.1-2007\n\nPC-TWA\n9000 mg/m3\n\nPC-STEL\n18000 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1401,79,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-78.5\n\n初沸点和沸程(℃)\n-56.6\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n5720kPa\n\n蒸气密度(空气=1)\n1.5\n\n相对密度(水=1)\n1.1\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.83\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1402,79,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1403,79,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n二氧化碳\n124-38-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二氧化碳\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1404,79,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1405,79,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1406,79,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1013\n\n联合国正确运输名称\n二氧化碳\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1407,79,15,'法规信息','国际化学品名录\n\n二氧化碳\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二氧化碳\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1408,79,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1409,80,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二氧化硒\n\n产品英文名称\nselenium dioxide\n\n别名\n亚硒酐\n\nCAS NO.\n7446-08-4\n\nEC NO.\n231-194-7\n\n分子式\nSeO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1410,80,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。对眼睛有严重刺激性。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH319\n造成严重眼刺激\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，呼吸困难，咽喉痛，气促。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，咽喉疼痛，休克或虚脱。\n\n皮肤接触\n发红，疼痛，皮肤烧伤，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1411,80,3,'成分/组成信息','二氧化硒\n\nCas No.\n7446-08-4\n\nEC No.\n231-194-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1412,80,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1413,80,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1414,80,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1415,80,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1416,80,8,'接触控制/个体防护','控制参数->职业接触限值\n\n二氧化硒\nGBZ 2.1-2007\n\nPC-TWA\n0.1 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1417,80,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n2（20℃，10g/L）\n\n熔点/凝固点(℃)\n340\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n1.65kPa（70℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.95\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1418,80,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1419,80,11,'毒理学信息','急性毒性\n\n二氧化硒\n7446-08-4\n\nLD\n50\n(经口)\n68.1mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n二氧化硒\n7446-08-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二氧化硒\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1420,80,12,'生态学信息','急性水生毒性\n\n二氧化硒\n7446-08-4\n\n鱼类\nLC\n50\n：7.46mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n二氧化硒：水/土壤-高 空气-高\n\n生物富集或生物积累性\n二氧化硒：生物富集性-低（LogKOW=-0.771）\n\n土壤中的迁移性\n二氧化硒：土壤迁移性-低（koc=23.74）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1421,80,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1422,80,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3283\n\n联合国正确运输名称\n硒化合物，固态，未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1423,80,15,'法规信息','国际化学品名录\n\n二氧化硒\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二氧化硒\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1424,80,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1425,81,1,'化学品及企业标识','产品标识\n\n产品中文名称\n二异丙胺\n\n产品英文名称\ndiisopropylamine\n\n别名\n-\n\nCAS NO.\n108-18-9\n\nEC NO.\n203-558-5\n\n分子式\nC6H15N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1426,81,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，头痛，恶心，气促。症状可能推迟显现。。\n\n食入\n胃痉挛,咽喉疼痛,灼烧感,恶心,休克或虚脱。\n\n皮肤接触\n可能被吸收！疼痛，水疱。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1427,81,3,'成分/组成信息','二异丙胺\n\nCas No.\n108-18-9\n\nEC No.\n203-558-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1428,81,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n用大量水冲洗，然后脱掉污染的衣服，再次冲洗，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位，必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1429,81,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1430,81,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1431,81,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1432,81,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1433,81,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n11.8（20℃，6g/L）\n\n熔点/凝固点(℃)\n-61\n\n初沸点和沸程(℃)\n84\n\n闪点(闭杯，℃)\n-7\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.1；下限：0.8\n\n蒸气压\n9.3kPa（20℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n0.715~0.722（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n1.64\n\n自燃温度(℃)\n316\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1434,81,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1435,81,11,'毒理学信息','急性毒性\n\n二异丙胺\n108-18-9\n\nLD\n50\n(经口)\n770mg/kg(大鼠)\n\nLD\n50\n(经皮)\n770mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n二异丙胺\n108-18-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n二异丙胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1436,81,12,'生态学信息','急性水生毒性\n\n二异丙胺\n108-18-9\n\n鱼类\nLC\n50\n：555mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：44.5mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1437,81,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1438,81,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1158\n\n联合国正确运输名称\n二异丙胺\n\n运输主要危险类别\n3\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:22','2025-10-21 07:50:22'),(1439,81,15,'法规信息','国际化学品名录\n\n二异丙胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n二异丙胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1440,81,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:22','2025-10-21 07:50:22'),(1441,82,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟\n\n产品英文名称\nfluorine\n\n别名\n-\n\nCAS NO.\n7782-41-4\n\nEC NO.\n231-954-8\n\n分子式\nF2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1442,82,2,'危险性概述','紧急情况概述\n\n气体。跟可燃物质接触可能会引起火灾。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。\n\nGHS危险性类别\n\n氧化性气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH270\n可能导致或加剧燃烧；氧化剂\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP244\n阀门或紧固装置不得带有油脂或油剂。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P376\n火灾时：如能保证安全，设法堵塞泄漏。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，咽喉痛，气促，呼吸困难。症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n发红，疼痛，皮肤烧伤。与液体接触：冻伤。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1443,82,3,'成分/组成信息','氟\n\nCas No.\n7782-41-4\n\nEC No.\n231-954-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1444,82,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1445,82,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1446,82,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1447,82,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1448,82,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1449,82,9,'理化特性','外观与性状\n轻微黄绿色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-219\n\n初沸点和沸程(℃)\n-188\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n＞100kPa（20℃）\n\n蒸气密度(空气=1)\n1.3\n\n相对密度(水=1)\n1.14（-10℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1450,82,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与水接触立即分解，放出氧气。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、烷烃、炔烃、芳香烃、卤代烷烃、含氧有机化合物、金属、金属氢化物、非金属氢化物、非金属、金属乙炔化物、碳化物、叠氮化物、苛性碱、非金属氧化物和硫化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1451,82,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟\n7782-41-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1452,82,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1453,82,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1454,82,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1045\n\n联合国正确运输名称\n压缩氟\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n5.1+8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1455,82,15,'法规信息','国际化学品名录\n\n氟\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1456,82,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1457,83,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化铵\n\n产品英文名称\nammonium fluoride\n\n别名\n-\n\nCAS NO.\n12125-01-8\n\nEC NO.\n235-185-9\n\n分子式\nNH4F\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1458,83,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。吸入有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n腹泻。恶心。呕吐。腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1459,83,3,'成分/组成信息','氟化铵\n\nCas No.\n12125-01-8\n\nEC No.\n235-185-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1460,83,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1461,83,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1462,83,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1463,83,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1464,83,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化铵\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化铵\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1465,83,9,'理化特性','外观与性状\n白色潮解性晶体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n6（20℃，50g/L）\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.01（20℃）\n\n溶解性(mg/L)\n820g/L（20℃）\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n100\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1466,83,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1467,83,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟化铵\n12125-01-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化铵\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1468,83,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氟化铵：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氟化铵：生物富集性-低（LogKOW=0.229）\n\n土壤中的迁移性\n氟化铵：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1469,83,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1470,83,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2505\n\n联合国正确运输名称\n氟化铵\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1471,83,15,'法规信息','国际化学品名录\n\n氟化铵\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化铵\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1472,83,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1473,84,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化钾\n\n产品英文名称\npotassium fluoride\n\n别名\n-\n\nCAS NO.\n7789-23-3\n\nEC NO.\n232-151-5\n\n分子式\nKF\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1474,84,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。吸入有毒。对水生物有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入本品在正常生产过程中生成的粉尘可对身体产生毒害作用。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n皮肤接触会中毒，吸收后可导致全身发生反应。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1475,84,3,'成分/组成信息','氟化钾\n\nCas No.\n7789-23-3\n\nEC No.\n232-151-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1476,84,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1477,84,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1478,84,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1479,84,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1480,84,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化钾\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化钾\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1481,84,9,'理化特性','外观与性状\n白色粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n858\n\n初沸点和沸程(℃)\n1505\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（885℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.48（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1482,84,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1483,84,11,'毒理学信息','急性毒性\n\n氟化钾\n7789-23-3\n\nLD\n50\n(经口)\n245mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氟化钾\n7789-23-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1484,84,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1485,84,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1486,84,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1812\n\n联合国正确运输名称\n氟化钾，固态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1487,84,15,'法规信息','国际化学品名录\n\n氟化钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1488,84,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1489,85,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化钠\n\n产品英文名称\nsodium fluoride\n\n别名\n-\n\nCAS NO.\n7681-49-4\n\nEC NO.\n231-667-8\n\n分子式\nNaF\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1490,85,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激性。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n腹部疼痛。灼烧感。惊厥。倦睡。咳嗽。腹泻。咽喉疼痛。呕吐。神志不清。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1491,85,3,'成分/组成信息','氟化钠\n\nCas No.\n7681-49-4\n\nEC No.\n231-667-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1492,85,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。催吐（仅对清醒病人！）。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1493,85,5,'消防措施','灭火介质\n\n适合的灭火介质\n矽土、水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1494,85,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1495,85,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1496,85,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化钠\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化钠\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1497,85,9,'理化特性','外观与性状\n无色晶体或白色粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n7.4（饱和溶液）\n\n熔点/凝固点(℃)\n993\n\n初沸点和沸程(℃)\n1700\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（1077℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.8\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1498,85,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1499,85,11,'毒理学信息','急性毒性\n\n氟化钠\n7681-49-4\n\nLD\n50\n(经口)\n52mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氟化钠\n7681-49-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化钠\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1500,85,12,'生态学信息','急性水生毒性\n\n氟化钠\n7681-49-4\n\n鱼类\nLC\n50\n：300mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：98mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：900mg/L (96h)()\n\n慢性水生毒性\n\n氟化钠\n7681-49-4\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：≧210mg/L()\n\n其他信息\n\n持久性和降解性\n氟化钠：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氟化钠：生物富集性-低（BCF=6.4）\n\n土壤中的迁移性\n氟化钠：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1501,85,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1502,85,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1690\n\n联合国正确运输名称\n氟化钠，固态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1503,85,15,'法规信息','国际化学品名录\n\n氟化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1504,85,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1505,86,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化氢[无水]\n\n产品英文名称\nhydrogen fluoride,anhydrous\n\n别名\n-\n\nCAS NO.\n7664-39-3\n\nEC NO.\n231-634-8\n\n分子式\nHF\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1506,86,2,'危险性概述','紧急情况概述\n\n气体。吞食后有剧毒。跟皮肤接触有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,头晕,头痛,呼吸困难,恶心，气促,咽喉痛,呕吐。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，腹泻，恶心，呕吐，虚弱，虚脱。\n\n皮肤接触\n可能被吸收！发红，疼痛，严重的皮肤烧伤，水疱。（见吸入）。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1507,86,3,'成分/组成信息','氟化氢\n\nCas No.\n7664-39-3\n\nEC No.\n231-634-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1508,86,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1509,86,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1510,86,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1511,86,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1512,86,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化氢\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化氢\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1513,86,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n1（2%溶液）\n\n熔点/凝固点(℃)\n-83\n\n初沸点和沸程(℃)\n20\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n122kPa（25℃）\n\n蒸气密度(空气=1)\n0.7\n\n相对密度(水=1)\n1.26（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1514,86,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1515,86,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟化氢\n7664-39-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化氢\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1516,86,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氟化氢：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氟化氢：生物富集性-低（LogKOW=-1.38）\n\n土壤中的迁移性\n氟化氢：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1517,86,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1518,86,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1052\n\n联合国正确运输名称\n无水氟化氢\n\n运输主要危险类别\n8\n\n运输次要危险类别\n6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1519,86,15,'法规信息','国际化学品名录\n\n氟化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1520,86,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1521,87,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化氢钾\n\n产品英文名称\npotassium bifluoride|potassium hydrogen difluoride\n\n别名\n酸性氟化钾|二氟化氢钾\n\nCAS NO.\n7789-29-9\n\nEC NO.\n232-156-2\n\n分子式\nKHF2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1522,87,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1523,87,3,'成分/组成信息','氟化氢钾\n\nCas No.\n7789-29-9\n\nEC No.\n232-156-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1524,87,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1525,87,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1526,87,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1527,87,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1528,87,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化氢钾\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化氢钾\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1529,87,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.37\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1530,87,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1531,87,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟化氢钾\n7789-29-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化氢钾\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1532,87,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1533,87,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1534,87,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1811\n\n联合国正确运输名称\n固态二氟化氢钾\n\n运输主要危险类别\n8\n\n运输次要危险类别\n6.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:23','2025-10-21 07:50:23'),(1535,87,15,'法规信息','国际化学品名录\n\n氟化氢钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化氢钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1536,87,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:23','2025-10-21 07:50:23'),(1537,88,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化氢钠\n\n产品英文名称\nsodium hydrogenfluoride|sodium bifluoride|sodium hydrogen difluoride\n\n别名\n酸性氟化钠|二氟化氢钠\n\nCAS NO.\n1333-83-1\n\nEC NO.\n215-608-3\n\n分子式\nNaHF2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1538,88,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1539,88,3,'成分/组成信息','氟化氢钠\n\nCas No.\n1333-83-1\n\nEC No.\n215-608-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1540,88,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1541,88,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1542,88,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1543,88,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1544,88,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化氢钠\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化氢钠\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1545,88,9,'理化特性','外观与性状\n白色结晶\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.08\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1546,88,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1547,88,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟化氢钠\n1333-83-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化氢钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1548,88,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1549,88,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1550,88,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2439\n\n联合国正确运输名称\n二氟化氢钠\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1551,88,15,'法规信息','国际化学品名录\n\n氟化氢钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化氢钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1552,88,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1553,89,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟化锌\n\n产品英文名称\nzinc fluoride\n\n别名\n-\n\nCAS NO.\n7783-49-5\n\nEC NO.\n232-001-9\n\n分子式\nZnF2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1554,89,2,'危险性概述','紧急情况概述\n\n固体。对眼睛有刺激性。对呼吸道有刺激作用。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n严重眼损伤/眼刺激\n类别 2B\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH320\n造成眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入粉尘或烟雾(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n本品对眼睛有轻微刺激。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1555,89,3,'成分/组成信息','氟化锌\n\nCas No.\n7783-49-5\n\nEC No.\n232-001-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1556,89,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1557,89,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1558,89,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1559,89,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1560,89,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟化锌\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氟化锌\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1561,89,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n872\n\n初沸点和沸程(℃)\n1500\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n5（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1562,89,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1563,89,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟化锌\n7783-49-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟化锌\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成眼刺激(类别 2B)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1564,89,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1565,89,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1566,89,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1567,89,15,'法规信息','国际化学品名录\n\n氟化锌\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氟化锌\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1568,89,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1569,11,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氟甲烷\n\n产品英文名称\nmethyl fluoride|fluoromethane\n\n别名\nR41|甲基氟\n\nCAS NO.\n593-53-3\n\nEC NO.\n209-796-6\n\n分子式\nCH3F\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1570,11,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1571,11,3,'成分/组成信息','氟甲烷\n\nCas No.\n593-53-3\n\nEC No.\n209-796-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1572,11,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1573,11,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1574,11,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1575,11,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1576,11,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氟甲烷\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1577,11,9,'理化特性','外观与性状\n无色气体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-137.8\n\n初沸点和沸程(℃)\n-78.4\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1578,11,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1579,11,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氟甲烷\n593-53-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氟甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1580,11,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氟甲烷：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氟甲烷：生物富集性-低（LogKOW=0.51）\n\n土壤中的迁移性\n氟甲烷：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1581,11,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1582,11,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2454\n\n联合国正确运输名称\n甲基氟\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1583,11,15,'法规信息','国际化学品名录\n\n氟甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n氟甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1584,11,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1585,90,1,'化学品及企业标识','产品标识\n\n产品中文名称\n高氯酸[浓度≤50%]\n\n产品英文名称\nperchloric acid with not more than 50% acid,by mass\n\n别名\n-\n\nCAS NO.\n7601-90-3\n\nEC NO.\n231-512-4\n\n分子式\nHClO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1586,90,2,'危险性概述','紧急情况概述\n\n液体。跟可燃物质接触可能会引起火灾。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n氧化性液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可能加剧燃烧；氧化剂\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n腐蚀作用,咽喉痛,灼烧感,咳嗽,呼吸困难,症状可能推迟显现。\n\n食入\n腐蚀作用,咽喉疼痛,腹部疼痛,灼烧感,腹泻,休克或虚脱,呕吐。\n\n皮肤接触\n腐蚀作用,发红,疼痛,严重皮肤烧伤。\n\n眼睛\n腐蚀作用,发红,疼痛,永久失明,严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1587,90,3,'成分/组成信息','高氯酸\n\nCas No.\n7601-90-3\n\nEC No.\n231-512-4\n\n含量范围（质量分数，%）\n<= 50',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1588,90,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,用大量水冲洗皮肤或淋浴,给予医疗护理。\n\n食入\n漱口,不要催吐,给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理,\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入蒸气。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1589,90,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1590,90,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n3\r\n						.\r\n						不要触摸或穿越泄漏物。\n4\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1591,90,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1592,90,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1593,90,9,'理化特性','外观与性状\n无色透明的发烟液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-112\n\n初沸点和沸程(℃)\n19（分解）\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n40hPa（20℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n1.41~1.67（15℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1594,90,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属单质或有机物接触发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属单质、有机物和纤维类物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1595,90,11,'毒理学信息','急性毒性\n\n高氯酸\n7601-90-3\n\nLD\n50\n(经口)\n1100mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n高氯酸\n7601-90-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n高氯酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1596,90,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1597,90,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1598,90,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1802\n\n联合国正确运输名称\n高氯酸，按重量含酸不超过50%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n5.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1599,90,15,'法规信息','国际化学品名录\n\n高氯酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n高氯酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1600,90,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1601,91,1,'化学品及企业标识','产品标识\n\n产品中文名称\n高氯酸钾\n\n产品英文名称\npotassium perchlorate|potassium hyperchlorate\n\n别名\n过氯酸钾\n\nCAS NO.\n7778-74-7\n\nEC NO.\n231-912-9\n\n分子式\nClKO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1602,91,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触容易引起火灾。\n\nGHS危险性类别\n\n氧化性固体\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH271\n可能引起燃烧或爆炸；强氧化剂\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP283\n穿防火/阻燃服装。\n\n防范说明->事故响应\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触容易引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1603,91,3,'成分/组成信息','高氯酸钾\n\nCas No.\n7778-74-7\n\nEC No.\n231-912-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1604,91,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1605,91,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1606,91,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1607,91,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1608,91,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1609,91,9,'理化特性','外观与性状\n白色晶体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n5.0（25℃，10g/L）\n\n熔点/凝固点(℃)\n400（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.5\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞400\n\n黏度\n不适用',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1610,91,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物当受热、撞击或摩擦时会引发爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、金属氨基化物、氨、铵盐、胺、酰胺、醇、酚、羧酸、羧酸酯、腈类、硫酸、浓硝酸和磷酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1611,91,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n高氯酸钾\n7778-74-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n高氯酸钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1612,91,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1613,91,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1614,91,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1489\n\n联合国正确运输名称\n高氯酸钾\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:24','2025-10-21 07:50:24'),(1615,91,15,'法规信息','国际化学品名录\n\n高氯酸钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n高氯酸钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1616,91,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:24','2025-10-21 07:50:24'),(1617,92,1,'化学品及企业标识','产品标识\n\n产品中文名称\n高锰酸钾\n\n产品英文名称\npotassium permanganate|potassium hypermanganate|purple salt\n\n别名\n过锰酸钾|灰锰氧\n\nCAS NO.\n7722-64-7\n\nEC NO.\n231-760-3\n\n分子式\nKMnO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1618,92,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,咽喉痛,气促,呼吸困难。症状可能推迟显现。。\n\n食入\n灼烧感,腹部疼痛,腹泻,恶心,呕吐,休克或虚脱。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1619,92,3,'成分/组成信息','高锰酸钾\n\nCas No.\n7722-64-7\n\nEC No.\n231-760-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1620,92,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1621,92,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1622,92,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1623,92,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1624,92,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1625,92,9,'理化特性','外观与性状\n深紫色结晶固体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n＞7（碱性）\n\n熔点/凝固点(℃)\n240（分解）\n\n初沸点和沸程(℃)\n在沸腾之前已经分解\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.7\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n240\n\n黏度\n不适用',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1626,92,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物在加热时，发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、非金属单质、氢卤酸、过氧化氢、硫化物、醇、醛、酮、羧酸、羧酸酐、羧酸酯、二甲亚砜、有机硝基化合物、铵盐、氨、羟胺酰胺等含氮碱和硫酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1627,92,11,'毒理学信息','急性毒性\n\n高锰酸钾\n7722-64-7\n\nLD\n50\n(经口)\n1090mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n高锰酸钾\n7722-64-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n高锰酸钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1628,92,12,'生态学信息','急性水生毒性\n\n高锰酸钾\n7722-64-7\n\n鱼类\nLC\n50\n：1.72mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.08mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1629,92,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1630,92,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1490\n\n联合国正确运输名称\n高锰酸钾\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1631,92,15,'法规信息','国际化学品名录\n\n高锰酸钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n高锰酸钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1632,92,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1633,93,1,'化学品及企业标识','产品标识\n\n产品中文名称\n铬酸溶液\n\n产品英文名称\nchromic acid,solution\n\n别名\n-\n\nCAS NO.\n7738-94-5\n\nEC NO.\n231-801-5\n\n分子式\nCrH2O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1634,93,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n致癌性\n类别 1A\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH350\n可能致癌\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1635,93,3,'成分/组成信息','铬酸溶液\n\nCas No.\n7738-94-5\n\nEC No.\n231-801-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1636,93,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1637,93,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1638,93,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1639,93,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1640,93,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1641,93,9,'理化特性','外观与性状\n液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n无资料\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n1.5（15.6℃，50 % (w/w) CrO3）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1642,93,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属单质或有机物接触发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属单质、有机物和纤维类物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1643,93,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n铬酸溶液\n7738-94-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n铬酸溶液\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1644,93,12,'生态学信息','急性水生毒性\n\n铬酸溶液\n7738-94-5\n\n鱼类\nLC\n50\n：39mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.76mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1645,93,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1646,93,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1755\n\n联合国正确运输名称\n铬酸溶液\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1647,93,15,'法规信息','国际化学品名录\n\n铬酸溶液\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n铬酸溶液\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1648,93,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1649,94,1,'化学品及企业标识','产品标识\n\n产品中文名称\n汞\n\n产品英文名称\nmercury|liquid silver\n\n别名\n水银\n\nCAS NO.\n7439-97-6\n\nEC NO.\n231-106-7\n\n分子式\nHg\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1650,94,2,'危险性概述','紧急情况概述\n\n液体。吸入有剧毒。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性吸入毒性\n类别 2\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH330\n吸入致命\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腹部疼痛。咳嗽。腹泻。气促。呕吐。发烧或体温升高。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n可能被吸收！发红。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1651,94,3,'成分/组成信息','汞\n\nCas No.\n7439-97-6\n\nEC No.\n231-106-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1652,94,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1653,94,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1654,94,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1655,94,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1656,94,8,'接触控制/个体防护','控制参数->职业接触限值\n\n汞\nGBZ 2.1-2007\n\nPC-TWA\n0.02 mg/m3\n\nPC-STEL\n0.04 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1657,94,9,'理化特性','外观与性状\n银色液体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-39\n\n初沸点和沸程(℃)\n357\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.26Pa（20℃）\n\n蒸气密度(空气=1)\n6.93\n\n相对密度(水=1)\n13.5\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1658,94,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与卤素、卤间化合物及其他强氧化剂发生猛烈反应，或引起爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素、卤间化合物、强氧化剂、非金属、水和酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1659,94,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n汞\n7439-97-6\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n汞\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1660,94,12,'生态学信息','急性水生毒性\n\n汞\n7439-97-6\n\n鱼类\nLC\n50\n：0.16mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1661,94,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1662,94,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2809\n\n联合国正确运输名称\n汞\n\n运输主要危险类别\n8\n\n运输次要危险类别\n6.1\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1663,94,15,'法规信息','国际化学品名录\n\n汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1664,94,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1665,95,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硅酸四乙酯\n\n产品英文名称\ntetraethyl silicate|tetraethoxysilane|TEOS\n\n别名\n四乙氧基硅烷|正硅酸乙酯\n\nCAS NO.\n78-10-4\n\nEC NO.\n201-083-8\n\n分子式\nC8H20O4Si\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1666,95,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，头痛，咽喉疼痛。\n\n食入\n意识模糊，呕吐。（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1667,95,3,'成分/组成信息','硅酸四乙酯\n\nCas No.\n78-10-4\n\nEC No.\n201-083-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1668,95,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗数分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗或淋浴。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1669,95,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1670,95,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1671,95,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1672,95,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1673,95,9,'理化特性','外观与性状\n无色或淡棕色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-77\n\n初沸点和沸程(℃)\n166\n\n闪点(闭杯，℃)\n37\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：23；下限：1.3\n\n蒸气压\n200Pa（20℃ ）\n\n蒸气密度(空气=1)\n7.22\n\n相对密度(水=1)\n0.935~0.94（20℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n260\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1674,95,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1675,95,11,'毒理学信息','急性毒性\n\n硅酸四乙酯\n78-10-4\n\nLD\n50\n(经口)\n6270mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硅酸四乙酯\n78-10-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硅酸四乙酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1676,95,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1677,95,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1678,95,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1292\n\n联合国正确运输名称\n硅酸四乙酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1679,95,15,'法规信息','国际化学品名录\n\n硅酸四乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硅酸四乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1680,95,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1681,96,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过二硫酸铵\n\n产品英文名称\ndiammonium peroxodisulphate|ammonium persulphate|ammonium peroxydisulfate\n\n别名\n高硫酸铵|过硫酸铵\n\nCAS NO.\n7727-54-0\n\nEC NO.\n231-786-5\n\n分子式\nH8N2O8S2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1682,96,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛，喘息，呼吸困难。\n\n食入\n恶心，腹泻，呕吐，咽喉疼痛。\n\n皮肤接触\n发红，灼烧感，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1683,96,3,'成分/组成信息','过二硫酸铵\n\nCas No.\n7727-54-0\n\nEC No.\n231-786-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1684,96,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗。\n\n食入\n大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1685,96,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1686,96,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1687,96,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1688,96,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1689,96,9,'理化特性','外观与性状\n白色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n2.3~4.0\n\n熔点/凝固点(℃)\n120（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.9\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n177\n\n黏度\n不适用',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1690,96,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无机碱可使其剧烈分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机碱、金属、硫和磷。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1691,96,11,'毒理学信息','急性毒性\n\n过二硫酸铵\n7727-54-0\n\nLD\n50\n(经口)\n689mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n过二硫酸铵\n7727-54-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n过二硫酸铵\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1692,96,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1693,96,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1694,96,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1444\n\n联合国正确运输名称\n过硫酸铵\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1695,96,15,'法规信息','国际化学品名录\n\n过二硫酸铵\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过二硫酸铵\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1696,96,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1697,97,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过二硫酸钾\n\n产品英文名称\ndipotassium peroxodisulphate|potassium persulphate|potassium persulfate\n\n别名\n高硫酸钾|过硫酸钾\n\nCAS NO.\n7727-21-1\n\nEC NO.\n231-781-8\n\n分子式\nK2S2O8\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1698,97,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽。喘息。咽喉痛。呼吸困难。\n\n食入\n恶心。呕吐。腹部疼痛。腹泻。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1699,97,3,'成分/组成信息','过二硫酸钾\n\nCas No.\n7727-21-1\n\nEC No.\n231-781-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1700,97,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1701,97,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1702,97,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1703,97,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1704,97,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1705,97,9,'理化特性','外观与性状\n白色晶体或粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n100（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.5\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n100\n\n黏度\n不适用',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1706,97,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无机碱可使其剧烈分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机碱、金属、硫和磷。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1707,97,11,'毒理学信息','急性毒性\n\n过二硫酸钾\n7727-21-1\n\nLD\n50\n(经口)\n802mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n过二硫酸钾\n7727-21-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n过二硫酸钾\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1708,97,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1709,97,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1710,97,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1492\n\n联合国正确运输名称\n过硫酸钾\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:25','2025-10-21 07:50:25'),(1711,97,15,'法规信息','国际化学品名录\n\n过二硫酸钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过二硫酸钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1712,97,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:25','2025-10-21 07:50:25'),(1713,98,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过氧化二苯甲酰[糊状物,52%＜含量≤62%]\n\n产品英文名称\ndibenzoyl peroxide (more than 52% but not more than 62% as a paste)\n\n别名\n-\n\nCAS NO.\n94-36-0\n\nEC NO.\n202-327-6\n\n分子式\nC14H10O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1714,98,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n有机过氧化物\nD型\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH242\n加热可能起火\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP410\n防日晒。\n\nP420\n远离其他材料存放。\n\nP411+P235\n贮存温度不超过 ……°C/……°F。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1715,98,3,'成分/组成信息','过氧化二苯甲酰\n\nCas No.\n94-36-0\n\nEC No.\n202-327-6\n\n含量范围（质量分数，%）\n52~62',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1716,98,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1717,98,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1718,98,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1719,98,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度应在2~25℃之间。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1720,98,8,'接触控制/个体防护','控制参数->职业接触限值\n\n过氧化二苯甲酰\nGBZ 2.1-2007\n\nPC-TWA\n5 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1721,98,9,'理化特性','外观与性状\n糊状物\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.3\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.46\n\n自燃温度(℃)\n80\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1722,98,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与大部分的有机化合物,金属，金属氧化物或无机还原性物质接触都会发生剧烈反应或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n有机化合物、金属氯化物、金属、金属氧化物、非金属、无机还原性物质、强酸和碱性物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1723,98,11,'毒理学信息','急性毒性\n\n过氧化二苯甲酰\n94-36-0\n\nLD\n50\n(经口)\n7710mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n过氧化二苯甲酰\n94-36-0\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n过氧化二苯甲酰\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1724,98,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n过氧化二苯甲酰：水/土壤-低(半衰期=14天) 空气-低(半衰期=21.25天)\n\n生物富集或生物积累性\n过氧化二苯甲酰：生物富集性-低（LogKOW=3.46）\n\n土壤中的迁移性\n过氧化二苯甲酰：土壤迁移性-低（koc=771）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1725,98,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1726,98,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3106\n\n联合国正确运输名称\n固态D 型有机过氧化物\n\n运输主要危险类别\n5.2\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/3f0bb4fa98ae.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1727,98,15,'法规信息','国际化学品名录\n\n过氧化二苯甲酰\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过氧化二苯甲酰\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1728,98,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1729,99,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过氧化二异丙苯[52%＜含量≤100%]\n\n产品英文名称\nbis(α,α-dimethylbenzyl)peroxide (more than 52%)|dicumyl peroxide|vulcanizing agent DCP\n\n别名\n二枯基过氧化物|硫化剂DCP\n\nCAS NO.\n80-43-3\n\nEC NO.\n201-279-3\n\n分子式\nC18H22O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1730,99,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。对皮肤有刺激性。对眼睛有严重刺激性。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n有机过氧化物\nF型\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH242\n加热可能起火\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP410\n防日晒。\n\nP420\n远离其他材料存放。\n\nP411+P235\n贮存温度不超过 ……°C/……°F。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1731,99,3,'成分/组成信息','过氧化二异丙苯\n\nCas No.\n80-43-3\n\nEC No.\n201-279-3\n\n含量范围（质量分数，%）\n52~100',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1732,99,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口，大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1733,99,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1734,99,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1735,99,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1736,99,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1737,99,9,'理化特性','外观与性状\n白色菱形的结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n39\n\n初沸点和沸程(℃)\n130（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n5.5\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n130\n\n黏度\n不适用',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1738,99,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1739,99,11,'毒理学信息','急性毒性\n\n过氧化二异丙苯\n80-43-3\n\nLD\n50\n(经口)\n4100mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n过氧化二异丙苯\n80-43-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n过氧化二异丙苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1740,99,12,'生态学信息','急性水生毒性\n\n过氧化二异丙苯\n80-43-3\n\n鱼类\nLC\n50\n：0.47mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.26mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>15mg/L (72h)(藻类)\n\n慢性水生毒性\n\n过氧化二异丙苯\n80-43-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.12mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：2.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1741,99,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1742,99,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3110\n\n联合国正确运输名称\n固态F 型有机过氧化物\n\n运输主要危险类别\n5.2\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/3f0bb4fa98ae.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1743,99,15,'法规信息','国际化学品名录\n\n过氧化二异丙苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过氧化二异丙苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1744,99,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1745,100,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过氧化二异壬酰[含量≤100%]\n\n产品英文名称\ndi-n-octanoyl peroxide(not more than 100%)| Di-(3,5,5-trimethyl hexanoyl)peroxide\n\n别名\n过氧化二-(3,5,5-三甲基)己酰\n\nCAS NO.\n3851-87-4\n\nEC NO.\n223-356-0\n\n分子式\nC18H34O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1746,100,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。\n\nGHS危险性类别\n\n有机过氧化物\nC型\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH242\n加热可能起火\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410\n防日晒。\n\nP420\n远离其他材料存放。\n\nP411+P235\n贮存温度不超过 ……°C/……°F。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n有爆炸性，遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1747,100,3,'成分/组成信息','过氧化二异壬酰\n\nCas No.\n3851-87-4\n\nEC No.\n223-356-0\n\n含量范围（质量分数，%）\n<= 100',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1748,100,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1749,100,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1750,100,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1751,100,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1752,100,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1753,100,9,'理化特性','外观与性状\n白色细碎固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1754,100,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1755,100,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n过氧化二异壬酰\n3851-87-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n过氧化二异壬酰\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1756,100,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1757,100,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1758,100,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3104\n\n联合国正确运输名称\n固态C 型有机过氧化物\n\n运输主要危险类别\n5.2\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/3f0bb4fa98ae.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.2.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1759,100,15,'法规信息','国际化学品名录\n\n过氧化二异壬酰\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过氧化二异壬酰\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1760,100,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1761,101,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过氧化环己酮[糊状物,含量≤72%]\n\n产品英文名称\ncyclohexanone peroxide (not more than 72% as a paste)\n\n别名\n-\n\nCAS NO.\n78-18-2\n\nEC NO.\n201-091-1\n\n分子式\nC12H22O5\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1762,101,2,'危险性概述','紧急情况概述\n\n固体。遇热有火灾危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n有机过氧化物\nD型\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH242\n加热可能起火\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP234\n只能在原容器中存放。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP410\n防日晒。\n\nP420\n远离其他材料存放。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP411+P235\n贮存温度不超过 ……°C/……°F。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇热有火灾危险。\n\n危害描述->健康危害\n\n吸入\n吸入粉尘或烟雾(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1763,101,3,'成分/组成信息','过氧化环己酮\n\nCas No.\n78-18-2\n\nEC No.\n201-091-1\n\n含量范围（质量分数，%）\n<= 72',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1764,101,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1765,101,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1766,101,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1767,101,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1768,101,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1769,101,9,'理化特性','外观与性状\n糊状物\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1770,101,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1771,101,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n过氧化环己酮\n78-18-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n过氧化环己酮\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1772,101,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1773,101,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1774,101,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3106\n\n联合国正确运输名称\n固态D 型有机过氧化物\n\n运输主要危险类别\n5.2\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/3f0bb4fa98ae.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.2.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1775,101,15,'法规信息','国际化学品名录\n\n过氧化环己酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过氧化环己酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1776,101,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1777,102,1,'化学品及企业标识','产品标识\n\n产品中文名称\n过氧化氢溶液[含量＞8%]\n\n产品英文名称\nhydrogen peroxide solution (more than 8%)\n\n别名\n-\n\nCAS NO.\n7722-84-1\n\nEC NO.\n231-765-0\n\n分子式\nH2O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1778,102,2,'危险性概述','紧急情况概述\n\n液体。跟可燃物质接触可能会引起火灾。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n氧化性液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可能加剧燃烧；氧化剂\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1779,102,3,'成分/组成信息','过氧化氢\n\nCas No.\n7722-84-1\n\nEC No.\n231-765-0\n\n含量范围（质量分数，%）\n8~20',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1780,102,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1781,102,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1782,102,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1783,102,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1784,102,8,'接触控制/个体防护','控制参数->职业接触限值\n\n过氧化氢\nGBZ 2.1-2007\n\nPC-TWA\n1.5 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1785,102,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n3.3（30%）\n\n熔点/凝固点(℃)\n-11（0.9）\n\n初沸点和沸程(℃)\n141（0.9）\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.2kPa（20℃,90%）\n\n蒸气密度(空气=1)\n1\n\n相对密度(水=1)\n1.4（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-1.36\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1786,102,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与空气或可燃性物质接触会爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n可燃性物质和有机易燃物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1787,102,11,'毒理学信息','急性毒性\n\n过氧化氢\n7722-84-1\n\nLD\n50\n(经口)\n2000mg/kg(小鼠)\n\nLD\n50\n(经皮)\n2000mg/kg(小鼠)\n\nLD\n50\n(吸入)\n2000mg/kg(小鼠)\n\n致癌性\n\n过氧化氢\n7722-84-1\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n过氧化氢\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1788,102,12,'生态学信息','急性水生毒性\n\n过氧化氢\n7722-84-1\n\n鱼类\nLC\n50\n：24.4mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：13.2mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：5.74mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n过氧化氢：水/土壤-低 空气-低\n\n生物富集或生物积累性\n过氧化氢：生物富集性-低（LogKOW=-1.36）\n\n土壤中的迁移性\n过氧化氢：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1789,102,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1790,102,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2984\n\n联合国正确运输名称\n过氧化氢水溶液，过氧化氢含量8% - 20%(必要时加稳定剂)\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1791,102,15,'法规信息','国际化学品名录\n\n过氧化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n过氧化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1792,102,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1793,103,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氦[压缩的]\n\n产品英文名称\nhelium,compressed\n\n别名\n-\n\nCAS NO.\n7440-59-7\n\nEC NO.\n231-168-5\n\n分子式\nHe\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1794,103,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n高语声。头晕。迟钝。头痛。窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1795,103,3,'成分/组成信息','氦\n\nCas No.\n7440-59-7\n\nEC No.\n231-168-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1796,103,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1797,103,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1798,103,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1799,103,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1800,103,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1801,103,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-272.2\n\n初沸点和沸程(℃)\n-268.9\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1802,103,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1803,103,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氦\n7440-59-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氦\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1804,103,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1805,103,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1806,103,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1046\n\n联合国正确运输名称\n压缩氦\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:26','2025-10-21 07:50:26'),(1807,103,15,'法规信息','国际化学品名录\n\n氦\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氦\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1808,103,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:26','2025-10-21 07:50:26'),(1809,104,1,'化学品及企业标识','产品标识\n\n产品中文名称\n红磷\n\n产品英文名称\nred phosphorus\n\n别名\n赤磷\n\nCAS NO.\n7723-14-0\n\nEC NO.\n231-768-7\n\n分子式\nP\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1810,104,2,'危险性概述','紧急情况概述\n\n固体。高度易燃，其粉体与空气混合，能形成爆炸性混合物。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃固体\n类别 1\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH228\n易燃固体\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇火或摩擦极易引燃，其粉体与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1811,104,3,'成分/组成信息','红磷\n\nCas No.\n7723-14-0\n\nEC No.\n231-768-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1812,104,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1813,104,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1814,104,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1815,104,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃，相对湿度小于80%。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1816,104,8,'接触控制/个体防护','控制参数->职业接触限值\n\n红磷\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n0.1 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1817,104,9,'理化特性','外观与性状\n暗红色粉末\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n44.1\n\n初沸点和沸程(℃)\n280\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n4.77\n\n相对密度(水=1)\n1.83\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n259\n\n分解温度(℃)\n290\n\n黏度\n不适用',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1818,104,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属乙炔化合物的混合物在加热时，发生燃烧或白炽化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属乙炔化合物、卤素及卤间化合物、卤素的氧化物、硝酸、氧化氮、硝酸盐、亚硝酸盐、卤素含氧酸盐、铬酸盐、高锰酸盐、无机过氧化物、金属氧化物和过氧甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1819,104,11,'毒理学信息','急性毒性\n\n红磷\n7723-14-0\n\nLD\n50\n(经口)\n3.03mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n红磷\n7723-14-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n红磷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1820,104,12,'生态学信息','急性水生毒性\n\n红磷\n7723-14-0\n\n鱼类\nLC\n50\n：0.006mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.14mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n红磷：生物富集性-高（BCF=2310000）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1821,104,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1822,104,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1338\n\n联合国正确运输名称\n非晶形磷\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1823,104,15,'法规信息','国际化学品名录\n\n红磷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n红磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1824,104,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1825,105,1,'化学品及企业标识','产品标识\n\n产品中文名称\n环己酮\n\n产品英文名称\ncyclohexanone\n\n别名\n-\n\nCAS NO.\n108-94-1\n\nEC NO.\n203-631-1\n\n分子式\nC6H10O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1826,105,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头晕。倦睡。\n\n食入\n腹部疼痛。灼烧感。\n\n皮肤接触\n可能被吸收！皮肤干燥。发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1827,105,3,'成分/组成信息','环己酮\n\nCas No.\n108-94-1\n\nEC No.\n203-631-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1828,105,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1829,105,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1830,105,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1831,105,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1832,105,8,'接触控制/个体防护','控制参数->职业接触限值\n\n环己酮\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1833,105,9,'理化特性','外观与性状\n无色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-32.1\n\n初沸点和沸程(℃)\n156\n\n闪点(闭杯，℃)\n44\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：9.4；下限：1.1\n\n蒸气压\n500Pa（20℃）\n\n蒸气密度(空气=1)\n3.4\n\n相对密度(水=1)\n0.95\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.81\n\n自燃温度(℃)\n420\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1834,105,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触易发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、氯仿、溴仿以及其它有机溶剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1835,105,11,'毒理学信息','急性毒性\n\n环己酮\n108-94-1\n\nLD\n50\n(经口)\n1400mg/kg(小鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n1400mg/kg(小鼠)\n\n致癌性\n\n环己酮\n108-94-1\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n环己酮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1836,105,12,'生态学信息','急性水生毒性\n\n环己酮\n108-94-1\n\n鱼类\nLC\n50\n：630mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1837,105,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1838,105,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1915\n\n联合国正确运输名称\n环已酮\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1839,105,15,'法规信息','国际化学品名录\n\n环己酮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n环己酮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1840,105,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1841,106,1,'化学品及企业标识','产品标识\n\n产品中文名称\n环己烷\n\n产品英文名称\ncyclohexane|hexahydrobenzene\n\n别名\n六氢化苯\n\nCAS NO.\n110-82-7\n\nEC NO.\n203-806-2\n\n分子式\nC6H12\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1842,106,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对皮肤有刺激性。气体可能会引起头晕或窒息。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH315\n造成皮肤刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。恶心。头痛。头晕。虚弱。倦睡。\n\n食入\n腹部疼痛。恶心。呕吐。吸入危险！(另见吸入)。\n\n皮肤接触\n发红。皮肤干燥。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1843,106,3,'成分/组成信息','环己烷\n\nCas No.\n110-82-7\n\nEC No.\n203-806-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1844,106,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1845,106,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1846,106,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1847,106,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1848,106,8,'接触控制/个体防护','控制参数->职业接触限值\n\n环己烷\nGBZ 2.1-2007\n\nPC-TWA\n250 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1849,106,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n7\n\n初沸点和沸程(℃)\n81\n\n闪点(闭杯，℃)\n-18\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.4；下限：1.3\n\n蒸气压\n10.3kPa（20℃）\n\n蒸气密度(空气=1)\n2.9\n\n相对密度(水=1)\n0.8\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.4\n\n自燃温度(℃)\n260\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1850,106,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1851,106,11,'毒理学信息','急性毒性\n\n环己烷\n110-82-7\n\nLD\n50\n(经口)\n12705mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n环己烷\n110-82-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n环己烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1852,106,12,'生态学信息','急性水生毒性\n\n环己烷\n110-82-7\n\n鱼类\nLC\n50\n：42.3mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1853,106,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1854,106,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1145\n\n联合国正确运输名称\n环己烷\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1855,106,15,'法规信息','国际化学品名录\n\n环己烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n环己烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1856,106,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1857,107,1,'化学品及企业标识','产品标识\n\n产品中文名称\n环戊烷\n\n产品英文名称\ncyclopentane\n\n别名\n-\n\nCAS NO.\n287-92-3\n\nEC NO.\n206-016-6\n\n分子式\nC5H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1858,107,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽,恶心,头痛,头晕,不协调,倦睡,神志不清。\n\n食入\n咽喉疼痛,腹部疼痛,腹泻,恶心,呕吐,另见吸入。\n\n皮肤接触\n发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1859,107,3,'成分/组成信息','环戊烷\n\nCas No.\n287-92-3\n\nEC No.\n206-016-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1860,107,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤,给予医疗护理。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1861,107,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1862,107,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1863,107,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1864,107,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1865,107,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-94\n\n初沸点和沸程(℃)\n49\n\n闪点(闭杯，℃)\n-37\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.7；下限：1.1\n\n蒸气压\n45kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.4\n\n相对密度(水=1)\n0.745（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.0\n\n自燃温度(℃)\n320\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1866,107,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1867,107,11,'毒理学信息','急性毒性\n\n环戊烷\n287-92-3\n\nLD\n50\n(经口)\n11400mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n环戊烷\n287-92-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n环戊烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1868,107,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1869,107,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1870,107,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1146\n\n联合国正确运输名称\n环戊烷\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1871,107,15,'法规信息','国际化学品名录\n\n环戊烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n环戊烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1872,107,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1873,108,1,'化学品及企业标识','产品标识\n\n产品中文名称\n环氧乙烷\n\n产品英文名称\noxirane|ethylene oxide\n\n别名\n氧化乙烯\n\nCAS NO.\n75-21-8\n\nEC NO.\n200-849-9\n\n分子式\nC2H4O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1874,108,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。高压，遇热有爆炸危险。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n化学性质不稳定气体\nA类\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH230\n无空气也可能迅速反应\n\nH280\n内装高压气体；遇热可能爆炸\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽,倦睡,头痛,恶心,咽喉痛,呕吐,虚弱。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。皮肤干燥，发红，疼痛。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1875,108,3,'成分/组成信息','环氧乙烷\n\nCas No.\n75-21-8\n\nEC No.\n200-849-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1876,108,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冻伤时,用大量水冲洗，不要脱去衣服。用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1877,108,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1878,108,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1879,108,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1880,108,8,'接触控制/个体防护','控制参数->职业接触限值\n\n环氧乙烷\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\nG1，皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1881,108,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-111\n\n初沸点和沸程(℃)\n11\n\n闪点(闭杯，℃)\n-57\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：100；下限：3\n\n蒸气压\n146kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.5\n\n相对密度(水=1)\n0.87（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.3\n\n自燃温度(℃)\n429\n\n分解温度(℃)\n＞571\n\n黏度\n不适用',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1882,108,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸或高氯酸镁接触发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、共价卤化物、无机碱、胺、金属烷氧化物、金属氧化物和高氯酸镁。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1883,108,11,'毒理学信息','急性毒性\n\n环氧乙烷\n75-21-8\n\nLD\n50\n(经口)\n72mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n72mg/kg(大鼠)\n\n致癌性\n\n环氧乙烷\n75-21-8\n\nIARC\n类别1\n\nNTP\n类别K\n\n其他信息\n\n组分\n环氧乙烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1884,108,12,'生态学信息','急性水生毒性\n\n环氧乙烷\n75-21-8\n\n鱼类\nLC\n50\n：84mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n环氧乙烷：水/土壤-低(半衰期=11.88天) 空气-高(半衰期=381.96天)\n\n生物富集或生物积累性\n环氧乙烷：生物富集性-低（BCF=35）\n\n土壤中的迁移性\n环氧乙烷：土壤迁移性-高（koc=1.435）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1885,108,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1886,108,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1040\n\n联合国正确运输名称\n环氧乙烷\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1887,108,15,'法规信息','国际化学品名录\n\n环氧乙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n环氧乙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1888,108,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1889,3,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲苯\n\n产品英文名称\ntoluene|methylbenzene\n\n别名\n甲基苯|苯基甲烷\n\nCAS NO.\n108-88-3\n\nEC NO.\n203-625-9\n\n分子式\nC7H8\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1890,3,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对皮肤有刺激性。气体可能会引起头晕或窒息。可能有损伤胎儿或胚胎的危险。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH315\n造成皮肤刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP331\n不得诱导呕吐。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头晕。倦睡。头痛。恶心。神志不清。\n\n食入\n灼烧感。腹部疼痛(另见吸入)。\n\n皮肤接触\n皮肤干燥。发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1891,3,3,'成分/组成信息','甲苯\n\nCas No.\n108-88-3\n\nEC No.\n203-625-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1892,3,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1893,3,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1894,3,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1895,3,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1896,3,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲苯\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n100 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n甲苯\nGBZ 2.1-2019\n\n生物检测指标\n尿中马尿酸\n\n生物限值\n1 mmol/mol Cr（1.5 g/g Cr）\n\n采样时间\n工作班末（停止接触后）\n\n备注\n无\n\n生物检测指标\n尿中马尿酸\n\n生物限值\n11 mmol/L（2.0 g/L）\n\n采样时间\n工作班末（停止接触后）\n\n备注\n无\n\n生物检测指标\n终末呼出气甲苯\n\n生物限值\n20 mg/m3\n\n采样时间\n工作班末（停止接触后15 min  ～30min）\n\n备注\n无\n\n生物检测指标\n终末呼出气甲苯\n\n生物限值\n5 mg/m3\n\n采样时间\n工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1897,3,9,'理化特性','外观与性状\n无色澄清液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-95\n\n初沸点和沸程(℃)\n111\n\n闪点(闭杯，℃)\n4\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.1；下限：1.1\n\n蒸气压\n3.8kPa（25℃）\n\n蒸气密度(空气=1)\n3.1\n\n相对密度(水=1)\n0.87（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.69\n\n自燃温度(℃)\n480\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1898,3,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1899,3,11,'毒理学信息','急性毒性\n\n甲苯\n108-88-3\n\nLD\n50\n(经口)\n636mg/kg(大鼠)\n\nLD\n50\n(经皮)\n636mg/kg(大鼠)\n\nLD\n50\n(吸入)\n636mg/kg(大鼠)\n\n致癌性\n\n甲苯\n108-88-3\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1900,3,12,'生态学信息','急性水生毒性\n\n甲苯\n108-88-3\n\n鱼类\nLC\n50\n：25mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4.1mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：12.5mg/L (72h)(藻类)\n\n慢性水生毒性\n\n甲苯\n108-88-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：1.2mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：9.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1901,3,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1902,3,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1294\n\n联合国正确运输名称\n甲苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:27','2025-10-21 07:50:27'),(1903,3,15,'法规信息','国际化学品名录\n\n甲苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1904,3,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:27','2025-10-21 07:50:27'),(1905,109,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲苯-2,4-二异氰酸酯\n\n产品英文名称\ntoluene-2,4-di-isocyanate|2,4-toluene diisocyanate|2-methyl-m-phenylene diisocyanate\n\n别名\n2,4-二异氰酸甲苯酯|2,4-TDI\n\nCAS NO.\n584-84-9\n\nEC NO.\n209-544-5\n\n分子式\nC9H6N2O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1906,109,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。吸入有剧毒。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。有轻微致癌性风险。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 2\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n致癌性\n类别 2\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH330\n吸入致命\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\nH351\n怀疑致癌\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腹部疼痛,咳嗽,恶心,呼吸短促,咽喉痛,呕吐,症状可能推迟显现。\n\n食入\n另见吸入。\n\n皮肤接触\n发红，疼痛，烧灼感。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1907,109,3,'成分/组成信息','甲苯-2,4-二异氰酸酯\n\nCas No.\n584-84-9\n\nEC No.\n209-544-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1908,109,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗数分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗,然后用水和肥皂冲洗皮肤,给予医疗护理。\n\n食入\n漱口。用水冲服活性炭浆，给予医疗护理。\n\n吸入\n新鲜空气,休息。半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1909,109,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1910,109,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1911,109,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1912,109,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲苯-2,4-二异氰酸酯\nGBZ 2.1-2007\n\nPC-TWA\n0.1 mg/m3\n\nPC-STEL\n0.2 mg/m3\n\n备注\n敏\n\n控制参数->生物限值\n\n甲苯-2,4-二异氰酸酯\nGBZ 2.1-2019\n\n生物检测指标\n尿中甲苯二胺\n\n生物限值\n1 μmol/mol Cr\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1913,109,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n22\n\n初沸点和沸程(℃)\n251\n\n闪点(闭杯，℃)\n127\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：9.5；下限：0.9\n\n蒸气压\n1.3Pa（20℃）\n\n蒸气密度(空气=1)\n6.0\n\n相对密度(水=1)\n1.2\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n0.21\n\n自燃温度(℃)\n620\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1914,109,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、酸、碱、氨类、叔胺、痕量的酰氯和醇类。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1915,109,11,'毒理学信息','急性毒性\n\n甲苯-2,4-二异氰酸酯\n584-84-9\n\nLD\n50\n(经口)\n5800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n5800mg/kg(大鼠)\n\nLD\n50\n(吸入)\n5800mg/kg(大鼠)\n\n致癌性\n\n甲苯-2,4-二异氰酸酯\n584-84-9\n\nIARC\n未列入\n\nNTP\n类别R\n\n其他信息\n\n组分\n甲苯-2,4-二异氰酸酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1916,109,12,'生态学信息','急性水生毒性\n\n甲苯-2,4-二异氰酸酯\n584-84-9\n\n鱼类\nLC\n50\n：164mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1917,109,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1918,109,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2078\n\n联合国正确运输名称\n甲苯二异氰酸酯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1919,109,15,'法规信息','国际化学品名录\n\n甲苯-2,4-二异氰酸酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲苯-2,4-二异氰酸酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1920,109,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1921,110,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲醇\n\n产品英文名称\nmethanol\n\n别名\n木醇|木精\n\nCAS NO.\n67-56-1\n\nEC NO.\n200-659-6\n\n分子式\nCH4O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1922,110,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有毒。跟皮肤接触有毒。吸入有毒。短期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\nH370\n会损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽,头晕,头痛,恶心,虚弱,视力障碍。\n\n食入\n腹部疼痛，气促，呕吐，惊厥，神志不清（另见吸入）。\n\n皮肤接触\n可能被吸收！皮肤干燥，发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1923,110,3,'成分/组成信息','甲醇\n\nCas No.\n67-56-1\n\nEC No.\n200-659-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1924,110,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n催吐（仅对清醒病人！），给予医疗护理。\n\n吸入\n新鲜空气,休息,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1925,110,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1926,110,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1927,110,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1928,110,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲醇\nGBZ 2.1-2007\n\nPC-TWA\n25 mg/m3\n\nPC-STEL\n50 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1929,110,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n7\n\n熔点/凝固点(℃)\n-98\n\n初沸点和沸程(℃)\n65\n\n闪点(闭杯，℃)\n12\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：44；下限：5.5\n\n蒸气压\n12.3kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.1\n\n相对密度(水=1)\n0.79（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.82~-0.66\n\n自燃温度(℃)\n464\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1930,110,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂反应剧烈，有引起燃烧爆炸的危险。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、碱金属、碱土金属和铝。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1931,110,11,'毒理学信息','急性毒性\n\n甲醇\n67-56-1\n\nLD\n50\n(经口)\n5628mg/kg(大鼠)\n\nLD\n50\n(经皮)\n5628mg/kg(大鼠)\n\nLD\n50\n(吸入)\n5628mg/kg(大鼠)\n\n致癌性\n\n甲醇\n67-56-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲醇\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1932,110,12,'生态学信息','急性水生毒性\n\n甲醇\n67-56-1\n\n鱼类\nLC\n50\n：24000mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：24500mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n甲醇：水/土壤-低 空气-低\n\n生物富集或生物积累性\n甲醇：生物富集性-低（BCF=10）\n\n土壤中的迁移性\n甲醇：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1933,110,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1934,110,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1230\n\n联合国正确运输名称\n甲醇\n\n运输主要危险类别\n3\n\n运输次要危险类别\n6.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1935,110,15,'法规信息','国际化学品名录\n\n甲醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1936,110,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1937,111,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲醇钠\n\n产品英文名称\nsodium methanolate|sodium methoxide\n\n别名\n甲氧基钠\n\nCAS NO.\n124-41-4\n\nEC NO.\n204-699-5\n\n分子式\nCH3NaO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1938,111,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 1\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH251\n自热；可能燃烧\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感,呼吸短促,呼吸困难。\n\n食入\n口腔和咽喉烧伤。咽喉和胸腔有灼烧感。休克或虚脱。\n\n皮肤接触\n发红,疼痛,严重的皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1939,111,3,'成分/组成信息','甲醇钠\n\nCas No.\n124-41-4\n\nEC No.\n204-699-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1940,111,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行,摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n先用大量水冲洗至少15分钟，然后脱去污染的衣服并再次冲洗。立即给予医疗护理。\n\n食入\n漱口。不要催吐。立即给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1941,111,5,'消防措施','灭火介质\n\n适合的灭火介质\n干式化学灭火剂、纯碱、石灰或干砂。\n\n不适合的灭火介质\n不要使用水、二氧化碳或泡沫灭火剂。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1942,111,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1943,111,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1944,111,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1945,111,9,'理化特性','外观与性状\n黄色结晶粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n12.8（20℃，10g/L）\n\n熔点/凝固点(℃)\n＞50（分解）\n\n初沸点和沸程(℃)\n在沸腾之前已经分解\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：36；下限：7.3\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.3\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n＞50\n\n分解温度(℃)\n＞280（在惰性气体中）\n\n黏度\n不适用',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1946,111,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在潮湿空气中着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝基化合物、卤代烷烃、环氧化合物、丙烯酰基化合物和二甲亚砜。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1947,111,11,'毒理学信息','急性毒性\n\n甲醇钠\n124-41-4\n\nLD\n50\n(经口)\n2037mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n甲醇钠\n124-41-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲醇钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1948,111,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1949,111,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1950,111,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1431\n\n联合国正确运输名称\n甲醇钠\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1951,111,15,'法规信息','国际化学品名录\n\n甲醇钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲醇钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1952,111,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1953,112,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲硅烷\n\n产品英文名称\nmonosilane|silicon tetrahydride\n\n别名\n硅烷|四氢化硅\n\nCAS NO.\n7803-62-5\n\nEC NO.\n232-263-4\n\n分子式\nSiH4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1954,112,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉疼痛，头痛，恶心。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n发红。与液体接触：冻伤。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1955,112,3,'成分/组成信息','甲硅烷\n\nCas No.\n7803-62-5\n\nEC No.\n232-263-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1956,112,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服；用大量水冲洗皮肤或淋浴。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1957,112,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1958,112,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1959,112,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1960,112,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲硅烷\nGBZ 2.1-2007\n\nPC-TWA\n6.6 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1961,112,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-185\n\n初沸点和沸程(℃)\n-112\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：100；下限：1.37\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n1.3\n\n相对密度(水=1)\n0.68\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞400\n\n黏度\n不适用',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1962,112,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与空气、氯或溴接触会燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氯、溴、四氯化碳、氨、水和乙腈。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1963,112,11,'毒理学信息','急性毒性\n\n甲硅烷\n7803-62-5\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n甲硅烷\n7803-62-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲硅烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1964,112,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1965,112,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1966,112,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2203\n\n联合国正确运输名称\n硅烷\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1967,112,15,'法规信息','国际化学品名录\n\n甲硅烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲硅烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1968,112,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1969,113,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲基丙烯酸[稳定的]\n\n产品英文名称\nmethacrylic acid,stabilized|2-methylpropenoic acid|α-methyl propenoic acid\n\n别名\n异丁烯酸\n\nCAS NO.\n79-41-4\n\nEC NO.\n201-204-4\n\n分子式\nC4H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1970,113,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，灼烧感，气促，呼吸困难。\n\n食入\n胃痉挛，腹部疼痛，灼烧感，虚弱。\n\n皮肤接触\n发红，皮肤烧伤，疼痛，水疱。\n\n眼睛\n发红，疼痛，视力丧失，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1971,113,3,'成分/组成信息','甲基丙烯酸\n\nCas No.\n79-41-4\n\nEC No.\n201-204-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1972,113,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口。休息，给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1973,113,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1974,113,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1975,113,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1976,113,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲基丙烯酸\nGBZ 2.1-2007\n\nPC-TWA\n70 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1977,113,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n2.0~2.2（20℃，100g/L）\n\n熔点/凝固点(℃)\n16\n\n初沸点和沸程(℃)\n159~163\n\n闪点(闭杯，℃)\n68\n\n蒸发速率\n不适用\n\n易燃性\n可燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.8；下限：1.6\n\n蒸气压\n130Pa（25℃ ）\n\n蒸气密度(空气=1)\n2.97\n\n相对密度(水=1)\n1.015（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.93\n\n自燃温度(℃)\n400\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1978,113,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1979,113,11,'毒理学信息','急性毒性\n\n甲基丙烯酸\n79-41-4\n\nLD\n50\n(经口)\n1060mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1060mg/kg(大鼠)\n\nLD\n50\n(吸入)\n1060mg/kg(大鼠)\n\n致癌性\n\n甲基丙烯酸\n79-41-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲基丙烯酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1980,113,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n甲基丙烯酸：水/土壤-低 空气-低\n\n生物富集或生物积累性\n甲基丙烯酸：生物富集性-低（LogKOW=0.93）\n\n土壤中的迁移性\n甲基丙烯酸：土壤迁移性-高（koc=1.895）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1981,113,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1982,113,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2531\n\n联合国正确运输名称\n甲基丙烯酸，稳定的\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:28','2025-10-21 07:50:28'),(1983,113,15,'法规信息','国际化学品名录\n\n甲基丙烯酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲基丙烯酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1984,113,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:28','2025-10-21 07:50:28'),(1985,114,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲基丙烯酸甲酯[稳定的]\n\n产品英文名称\nmethyl methacrylate,stabilized|methyl 2-methylprop-2-enoate|methyl 2-methylpropenoate|methyl methacrylate\n\n别名\n牙托水|有机玻璃单体|异丁烯酸甲酯\n\nCAS NO.\n80-62-6\n\nEC NO.\n201-297-1\n\n分子式\nC5H8O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1986,114,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。气促。咽喉痛。\n\n食入\n恶心。呕吐。腹部疼痛。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(1987,114,3,'成分/组成信息','甲基丙烯酸甲酯\n\nCas No.\n80-62-6\n\nEC No.\n201-297-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1988,114,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1989,114,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1990,114,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1991,114,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1992,114,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲基丙烯酸甲酯\nGBZ 2.1-2007\n\nPC-TWA\n100 mg/m3\n\nPC-STEL\n-\n\n备注\n敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1993,114,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-48\n\n初沸点和沸程(℃)\n100.5\n\n闪点(闭杯，℃)\n13.8\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：12.5；下限：1.7\n\n蒸气压\n3.9kPa（20℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n0.94\n\n溶解性(mg/L)\n15g/l（20℃）\n\n辛醇 /水分配系数\n1.38\n\n自燃温度(℃)\n421\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1994,114,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸和有机过氧化物接触发生剧烈聚合。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、碱和有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1995,114,11,'毒理学信息','急性毒性\n\n甲基丙烯酸甲酯\n80-62-6\n\nLD\n50\n(经口)\n7872mg/kg(大鼠)\n\nLD\n50\n(经皮)\n7872mg/kg(大鼠)\n\nLD\n50\n(吸入)\n7872mg/kg(大鼠)\n\n致癌性\n\n甲基丙烯酸甲酯\n80-62-6\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲基丙烯酸甲酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1996,114,12,'生态学信息','急性水生毒性\n\n甲基丙烯酸甲酯\n80-62-6\n\n鱼类\nLC\n50\n：311mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：84mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>86mg/L (72h)(藻类)\n\n慢性水生毒性\n\n甲基丙烯酸甲酯\n80-62-6\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：3.5mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：86mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1997,114,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(1998,114,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1247\n\n联合国正确运输名称\n甲基丙烯酸甲酯，单体，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(1999,114,15,'法规信息','国际化学品名录\n\n甲基丙烯酸甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲基丙烯酸甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2000,114,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2001,115,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲基丙烯酸异丁酯[稳定的]\n\n产品英文名称\nisobutyl methacrylate,stabilized\n\n别名\n-\n\nCAS NO.\n97-86-9\n\nEC NO.\n202-613-0\n\n分子式\nC8H14O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2002,115,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。皮肤直接接触可造成皮肤刺激。\n\n眼睛\n本品能造成严重眼刺激。眼睛直接接触可能会造成严重的炎症并伴随有疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2003,115,3,'成分/组成信息','甲基丙烯酸异丁酯\n\nCas No.\n97-86-9\n\nEC No.\n202-613-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2004,115,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2005,115,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2006,115,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2007,115,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2008,115,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2009,115,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-33.8\n\n初沸点和沸程(℃)\n155\n\n闪点(闭杯，℃)\n44\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.0；下限：2.0\n\n蒸气压\n0.4kPa\n\n蒸气密度(空气=1)\n4.91\n\n相对密度(水=1)\n0.889\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n294\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2010,115,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2011,115,11,'毒理学信息','急性毒性\n\n甲基丙烯酸异丁酯\n97-86-9\n\nLD\n50\n(经口)\n11990mg/kg(小鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n甲基丙烯酸异丁酯\n97-86-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲基丙烯酸异丁酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2012,115,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2013,115,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2014,115,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2283\n\n联合国正确运输名称\n甲基丙烯酸异丁酯，稳定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2015,115,15,'法规信息','国际化学品名录\n\n甲基丙烯酸异丁酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲基丙烯酸异丁酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2016,115,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2017,116,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲基异丙基苯\n\n产品英文名称\nmethyl isopropylbenzene|cymenes\n\n别名\n伞花烃\n\nCAS NO.\n99-87-6\n\nEC NO.\n202-796-7\n\n分子式\nC10H14\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2018,116,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  气体可能会引起头晕或窒息。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n吸入危害\n类别 1\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，呕吐。\n\n食入\n腹泻，倦睡，头痛，恶心，呕吐，神志不清。\n\n皮肤接触\n皮肤干燥，发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2019,116,3,'成分/组成信息','甲基异丙基苯\n\nCas No.\n99-87-6\n\nEC No.\n202-796-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2020,116,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服,冲洗,然后用水和肥皂洗皮肤,急救时戴防护手套。\n\n食入\n漱口，不要催吐，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2021,116,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2022,116,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2023,116,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2024,116,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2025,116,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-68\n\n初沸点和沸程(℃)\n177\n\n闪点(闭杯，℃)\n47\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：5.6；下限：0.7\n\n蒸气压\n0.2kPa（20℃）\n\n蒸气密度(空气=1)\n4.62\n\n相对密度(水=1)\n0.85\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n4.1\n\n自燃温度(℃)\n435\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2026,116,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2027,116,11,'毒理学信息','急性毒性\n\n甲基异丙基苯\n99-87-6\n\nLD\n50\n(经口)\n4750mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n甲基异丙基苯\n99-87-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲基异丙基苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2028,116,12,'生态学信息','急性水生毒性\n\n甲基异丙基苯\n99-87-6\n\n鱼类\nLC\n50\n：2.0mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.9mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：5.8mg/L (72h)(藻类)\n\n慢性水生毒性\n\n甲基异丙基苯\n99-87-6\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.46mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：0.48mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n甲基异丙基苯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n甲基异丙基苯：生物富集性-中等（LogKOW=4.1）\n\n土壤中的迁移性\n甲基异丙基苯：土壤迁移性-低（koc=1324）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2029,116,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2030,116,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2046\n\n联合国正确运输名称\n伞花烃\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2031,116,15,'法规信息','国际化学品名录\n\n甲基异丙基苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲基异丙基苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2032,116,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2033,1,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲醛溶液\n\n产品英文名称\nformaldehyde solution|formalin solution\n\n别名\n福尔马林溶液\n\nCAS NO.\n50-00-0\n\nEC NO.\n200-001-8\n\n分子式\nCH2O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2034,1,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有毒。对呼吸道有刺激作用。可能有发生不可逆性作用的危险。对水生物有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 1A\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH350\n可能致癌\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。吸入本品在正常生产过程中生成的蒸气或气溶胶(雾、烟)，可对身体产生毒害作用。腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。皮肤直接接触造成严重皮肤灼伤。皮肤接触会中毒，吸收后可导致全身发生反应。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2035,1,3,'成分/组成信息','甲醛\n\nCas No.\n50-00-0\n\nEC No.\n200-001-8\n\n含量范围（质量分数，%）\n>= 25',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2036,1,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2037,1,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2038,1,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2039,1,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2040,1,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲醛\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n敏，G1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2041,1,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：73；下限：7\n\n蒸气压\n2hPa（20℃）\n\n蒸气密度(空气=1)\n1.08\n\n相对密度(水=1)\n0.8\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.35\n\n自燃温度(℃)\n430\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2042,1,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触易发生着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、酸和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2043,1,11,'毒理学信息','急性毒性\n\n甲醛\n50-00-0\n\nLD\n50\n(经口)\n100mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n100mg/kg(大鼠)\n\n致癌性\n\n甲醛\n50-00-0\n\nIARC\n类别1\n\nNTP\n类别K\n\n其他信息\n\n组分\n甲醛\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2044,1,12,'生态学信息','急性水生毒性\n\n甲醛\n50-00-0\n\n鱼类\nLC\n50\n：52.5mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：14mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n甲醛：水/土壤-低(半衰期=14天) 空气-低(半衰期=2.97天)\n\n生物富集或生物积累性\n甲醛：生物富集性-低（LogKOW=0.35）\n\n土壤中的迁移性\n甲醛：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2045,1,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2046,1,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2209\n\n联合国正确运输名称\n甲醛溶液，甲醛含量不低于25%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2047,1,15,'法规信息','国际化学品名录\n\n甲醛\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲醛\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2048,1,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2049,117,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲酸\n\n产品英文名称\nmethane acid|formic acid| methanoic acid\n\n别名\n蚁酸\n\nCAS NO.\n64-18-6\n\nEC NO.\n200-579-1\n\n分子式\nCH2O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2050,117,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咽喉痛，灼烧感，咳嗽，呼吸困难，气促，神志不清。症状可能推迟显现。。\n\n食入\n咽喉疼痛，灼烧感，腹部疼痛，呕吐，腹泻。\n\n皮肤接触\n疼痛，水疱，严重皮肤烧伤。\n\n眼睛\n疼痛，发红，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2051,117,3,'成分/组成信息','甲酸\n\nCas No.\n64-18-6\n\nEC No.\n200-579-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2052,117,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2053,117,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2054,117,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2055,117,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于32℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2056,117,8,'接触控制/个体防护','控制参数->职业接触限值\n\n甲酸\nGBZ 2.1-2007\n\nPC-TWA\n10 mg/m3\n\nPC-STEL\n20 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2057,117,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n2.2（20℃，10g/L）\n\n熔点/凝固点(℃)\n8\n\n初沸点和沸程(℃)\n101\n\n闪点(闭杯，℃)\n69\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：51；下限：18\n\n蒸气压\n4.6kPa（20℃）\n\n蒸气密度(空气=1)\n1.6\n\n相对密度(水=1)\n1.22（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.54\n\n自燃温度(℃)\n520\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2058,117,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n具有可燃性，其蒸气（或粉末）与空气接触可形成爆炸性混合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、糠醇、乙醛、硝酸、硝酸盐、亚硝酸盐、卤素的含氧酸盐和无机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2059,117,11,'毒理学信息','急性毒性\n\n甲酸\n64-18-6\n\nLD\n50\n(经口)\n1100mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n甲酸\n64-18-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2060,117,12,'生态学信息','急性水生毒性\n\n甲酸\n64-18-6\n\n鱼类\n无资料\n\n甲壳纲动物\nEC\n50\n：151mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2061,117,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2062,117,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1779\n\n联合国正确运输名称\n甲酸，按重量含酸大于85%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2063,117,15,'法规信息','国际化学品名录\n\n甲酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2064,117,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2065,118,1,'化学品及企业标识','产品标识\n\n产品中文名称\n甲烷\n\n产品英文名称\nmethane\n\n别名\n-\n\nCAS NO.\n74-82-8\n\nEC NO.\n200-812-7\n\n分子式\nCH4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2066,118,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n窒息。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2067,118,3,'成分/组成信息','甲烷\n\nCas No.\n74-82-8\n\nEC No.\n200-812-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2068,118,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2069,118,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2070,118,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2071,118,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2072,118,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2073,118,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-183\n\n初沸点和沸程(℃)\n-161\n\n闪点(闭杯，℃)\n-218\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：15；下限：5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n0.6\n\n相对密度(水=1)\n0.422\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.09\n\n自燃温度(℃)\n537\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2074,118,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2075,118,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n甲烷\n74-82-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2076,118,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n甲烷：水/土壤-低 空气-低\n\n生物富集或生物积累性\n甲烷：生物富集性-低（LogKOW=1.09）\n\n土壤中的迁移性\n甲烷：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2077,118,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2078,118,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1971\n\n联合国正确运输名称\n压缩甲烷\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:29','2025-10-21 07:50:29'),(2079,118,15,'法规信息','国际化学品名录\n\n甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2080,118,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:29','2025-10-21 07:50:29'),(2081,119,1,'化学品及企业标识','产品标识\n\n产品中文名称\n钾\n\n产品英文名称\npotassium\n\n别名\n金属钾\n\nCAS NO.\n7440-09-7\n\nEC NO.\n231-119-8\n\n分子式\nK\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2082,119,2,'危险性概述','紧急情况概述\n\n固体。会跟水激烈反应, 生成高度易燃的气体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH260\n遇水放出可自燃的易燃气体\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。\n\n食入\n灼烧感。休克或虚脱。\n\n皮肤接触\n疼痛。水疱。严重皮肤烧伤。\n\n眼睛\n严重深度烧伤。视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2083,119,3,'成分/组成信息','钾\n\nCas No.\n7440-09-7\n\nEC No.\n231-119-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2084,119,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气,休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2085,119,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						火焰被扑灭后可能复燃。\n2\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n3\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n4\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2086,119,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2087,119,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2088,119,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2089,119,9,'理化特性','外观与性状\n银色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n14\n\n熔点/凝固点(℃)\n63.2\n\n初沸点和沸程(℃)\n765.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（341℃）\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n0.86（20℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2090,119,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在空气中会被迅速被氧化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、二氧化碳、卤化碳、卤素、卤间化合物、金属卤化物、非金属氧化物、酸、汞和联氨。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2091,119,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n钾\n7440-09-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n钾\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2092,119,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2093,119,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2094,119,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2257\n\n联合国正确运输名称\n钾\n\n运输主要危险类别\n4.3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2095,119,15,'法规信息','国际化学品名录\n\n钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2096,119,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2097,120,1,'化学品及企业标识','产品标识\n\n产品中文名称\n金属钙粉\n\n产品英文名称\ncalcium powder metal\n\n别名\n钙粉\n\nCAS NO.\n7440-70-2\n\nEC NO.\n231-179-5\n\n分子式\nCa\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2098,120,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。跟水接触会生成高度易燃的气体。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 2\n\n遇水放出易燃气体的物质和混合物\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH252\n数量大时自热；可能燃烧\n\nH261\n遇水放出易燃气体\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。可遇水反应生成高度易燃的气体。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2099,120,3,'成分/组成信息','金属钙粉\n\nCas No.\n7440-70-2\n\nEC No.\n231-179-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2100,120,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2101,120,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2102,120,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2103,120,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2104,120,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2105,120,9,'理化特性','外观与性状\n银白色金属\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n11~12（饱和溶液）\n\n熔点/凝固点(℃)\n837~841\n\n初沸点和沸程(℃)\n1484\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.54\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2106,120,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n能在二氧化碳中持续燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、二氧化碳、氧化剂、卤素、卤间化合物和汞。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2107,120,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n金属钙粉\n7440-70-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n金属钙粉\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2108,120,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2109,120,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2110,120,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1855\n\n联合国正确运输名称\n发火钙金属\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2111,120,15,'法规信息','国际化学品名录\n\n金属钙粉\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n金属钙粉\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2112,120,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2113,121,1,'化学品及企业标识','产品标识\n\n产品中文名称\n金属锆粉[干燥的]\n\n产品英文名称\nzirconium metal powder,dry|zirconium powder\n\n别名\n锆粉\n\nCAS NO.\n7440-67-7\n\nEC NO.\n231-176-9\n\n分子式\nZr\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2114,121,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易自身燃烧,有引发火灾的危险。会跟水激烈反应, 生成高度易燃的气体。\n\nGHS危险性类别\n\n自燃固体\n类别 1\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH250\n暴露在空气中会自燃\n\nH260\n遇水放出可自燃的易燃气体\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP222\n不得与空气接触。\n\nP223\n不得与水接触。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP422\n内装物存放在适当的液体或惰性气体中。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n即使数量很少，在与空气接触五分钟内即可自燃。会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2115,121,3,'成分/组成信息','锆粉\n\nCas No.\n7440-67-7\n\nEC No.\n231-176-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2116,121,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2117,121,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2118,121,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2119,121,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2120,121,8,'接触控制/个体防护','控制参数->职业接触限值\n\n锆粉\nGBZ 2.1-2007\n\nPC-TWA\n5 mg/m3\n\nPC-STEL\n10 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2121,121,9,'理化特性','外观与性状\n深灰色金属粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n1857\n\n初沸点和沸程(℃)\n3577\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n6.5\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n20（粉尘）\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2122,121,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2123,121,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n锆粉\n7440-67-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n锆粉\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2124,121,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2125,121,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2126,121,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2008\n\n联合国正确运输名称\n干锆粉\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2127,121,15,'法规信息','国际化学品名录\n\n锆粉\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n锆粉\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2128,121,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2129,122,1,'化学品及企业标识','产品标识\n\n产品中文名称\n肼水溶液[含肼≤64%]\n\n产品英文名称\nhydrazine aqueous solution,with not more than 64％ hydrazine,by mass\n\n别名\n-\n\nCAS NO.\n302-01-2\n\nEC NO.\n206-114-9\n\n分子式\nH4N2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2130,122,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有毒。有轻微致癌性风险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n致癌性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH351\n怀疑致癌\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。灼烧感。头痛。意识模糊。倦睡。恶心。呼吸短促。惊厥。神志不清。\n\n食入\n口腔和咽喉烧伤。腹部疼痛。腹泻。呕吐。休克或虚脱。(另见吸入)。\n\n皮肤接触\n可能被吸收！发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2131,122,3,'成分/组成信息','肼\n\nCas No.\n302-01-2\n\nEC No.\n206-114-9\n\n含量范围（质量分数，%）\n<= 64',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2132,122,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。。立即给予医疗护理。\n\n食入\n漱口。不要饮用任何东西。不要催吐。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2133,122,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2134,122,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2135,122,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2136,122,8,'接触控制/个体防护','控制参数->职业接触限值\n\n肼\nGBZ 2.1-2007\n\nPC-TWA\n0.06 mg/m3\n\nPC-STEL\n0.13 mg/m3\n\n备注\n皮，G2A\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2137,122,9,'理化特性','外观与性状\n无色油性液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n10.7\n\n熔点/凝固点(℃)\n2\n\n初沸点和沸程(℃)\n114\n\n闪点(闭杯，℃)\n40\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：100；下限：4.7\n\n蒸气压\n2.1kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.1\n\n相对密度(水=1)\n1.004（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-2.1\n\n自燃温度(℃)\n270\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2138,122,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2139,122,11,'毒理学信息','急性毒性\n\n肼\n302-01-2\n\nLD\n50\n(经口)\n60mg/kg(大鼠)\n\nLD\n50\n(经皮)\n60mg/kg(大鼠)\n\nLD\n50\n(吸入)\n60mg/kg(大鼠)\n\n致癌性\n\n肼\n302-01-2\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n肼\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2140,122,12,'生态学信息','急性水生毒性\n\n肼\n302-01-2\n\n鱼类\nLC\n50\n：1.6mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.17mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n肼：水/土壤-低(半衰期=14天) 空气-低(半衰期=0.23天)\n\n生物富集或生物积累性\n肼：生物富集性-低（LogKOW=-2.07）\n\n土壤中的迁移性\n肼：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2141,122,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2142,122,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3484\n\n联合国正确运输名称\n肼水溶液，易燃，按重量含肼超过37%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3+6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2143,122,15,'法规信息','国际化学品名录\n\n肼\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n肼\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2144,122,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2145,123,1,'化学品及企业标识','产品标识\n\n产品中文名称\n莰烯\n\n产品英文名称\ncamphene\n\n别名\n樟脑萜|莰芬\n\nCAS NO.\n79-92-5\n\nEC NO.\n201-234-8\n\n分子式\nC10H16\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2146,123,2,'危险性概述','紧急情况概述\n\n固体。高度易燃，其粉体与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃固体\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH228\n易燃固体\n\nH319\n造成严重眼刺激\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n遇火或摩擦极易引燃，其粉体与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2147,123,3,'成分/组成信息','莰烯\n\nCas No.\n79-92-5\n\nEC No.\n201-234-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2148,123,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。\n\n食入\n漱口，饮用1杯或2杯水。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2149,123,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2150,123,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2151,123,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2152,123,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2153,123,9,'理化特性','外观与性状\n无色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n46\n\n初沸点和沸程(℃)\n156~160\n\n闪点(闭杯，℃)\n26\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.4kPa\n\n蒸气密度(空气=1)\n4.7\n\n相对密度(水=1)\n0.87\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n4.1\n\n自燃温度(℃)\n265\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2154,123,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2155,123,11,'毒理学信息','急性毒性\n\n莰烯\n79-92-5\n\nLD\n50\n(经口)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n莰烯\n79-92-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n莰烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2156,123,12,'生态学信息','急性水生毒性\n\n莰烯\n79-92-5\n\n鱼类\nLC\n50\n：1.9mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n莰烯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n莰烯：生物富集性-中等（BCF=1290）\n\n土壤中的迁移性\n莰烯：土壤迁移性-低（koc=1204）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2157,123,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2158,123,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1325\n\n联合国正确运输名称\n有机易燃固体，未另作规定的\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:30','2025-10-21 07:50:30'),(2159,123,15,'法规信息','国际化学品名录\n\n莰烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n莰烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2160,123,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:30','2025-10-21 07:50:30'),(2161,124,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氪[压缩的]\n\n产品英文名称\nkrypton,compressed\n\n别名\n-\n\nCAS NO.\n7439-90-9\n\nEC NO.\n231-098-5\n\n分子式\nKr\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2162,124,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n窒息。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n（见皮肤）。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2163,124,3,'成分/组成信息','氪\n\nCas No.\n7439-90-9\n\nEC No.\n231-098-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2164,124,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2165,124,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2166,124,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2167,124,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2168,124,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2169,124,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-157\n\n初沸点和沸程(℃)\n-153\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n2.9\n\n相对密度(水=1)\n2.155\n\n溶解性(mg/L)\n221 mg/L（20℃）\n\n辛醇 /水分配系数\n1.2\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2170,124,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2171,124,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氪\n7439-90-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氪\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2172,124,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2173,124,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2174,124,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1056\n\n联合国正确运输名称\n压缩氪\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2175,124,15,'法规信息','国际化学品名录\n\n氪\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氪\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2176,124,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2177,125,1,'化学品及企业标识','产品标识\n\n产品中文名称\n喹啉\n\n产品英文名称\nquinoline|benzopyridine|naphthyridine\n\n别名\n苯并吡啶|氮杂萘\n\nCAS NO.\n91-22-5\n\nEC NO.\n202-051-6\n\n分子式\nC9H7N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2178,125,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。可能有发生不可逆性作用的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖细胞致突变性\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH311\n皮肤接触会中毒\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n咽喉疼痛。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2179,125,3,'成分/组成信息','喹啉\n\nCas No.\n91-22-5\n\nEC No.\n202-051-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2180,125,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2181,125,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2182,125,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2183,125,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2184,125,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2185,125,9,'理化特性','外观与性状\n无色至棕色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n7.3（20℃，5g/L）\n\n熔点/凝固点(℃)\n-15\n\n初沸点和沸程(℃)\n238\n\n闪点(闭杯，℃)\n101\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：7；下限：1.2\n\n蒸气压\n8Pa（20℃）\n\n蒸气密度(空气=1)\n4.5\n\n相对密度(水=1)\n1.09\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.06\n\n自燃温度(℃)\n480\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2186,125,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2187,125,11,'毒理学信息','急性毒性\n\n喹啉\n91-22-5\n\nLD\n50\n(经口)\n331mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n喹啉\n91-22-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n喹啉\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2188,125,12,'生态学信息','急性水生毒性\n\n喹啉\n91-22-5\n\n鱼类\nLC\n50\n：40mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：25mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：66mg/L (72h)(藻类)\n\n慢性水生毒性\n\n喹啉\n91-22-5\n\n鱼类\nNOEC：4.4mg/L(鱼)\n\n甲壳纲动物\nNOEC：2.2mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：4.8mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n喹啉：水/土壤-低(半衰期=20天) 空气-低(半衰期=4.13天)\n\n生物富集或生物积累性\n喹啉：生物富集性-低（BCF=150）\n\n土壤中的迁移性\n喹啉：土壤迁移性-低（koc=1837）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2189,125,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2190,125,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2656\n\n联合国正确运输名称\n喹啉\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2191,125,15,'法规信息','国际化学品名录\n\n喹啉\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n喹啉\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2192,125,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2193,126,1,'化学品及企业标识','产品标识\n\n产品中文名称\n连二亚硫酸钠\n\n产品英文名称\nsodium dithionite|sodium hydrosulphite|sodium sulfoxylate\n\n别名\n保险粉|低亚硫酸钠\n\nCAS NO.\n7775-14-6\n\nEC NO.\n231-890-0\n\n分子式\nNa2S2O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2194,126,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH251\n自热；可能燃烧\n\n防范说明->预防措施\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n恶心，腹部疼痛，呕吐，腹泻。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2195,126,3,'成分/组成信息','连二亚硫酸钠\n\nCas No.\n7775-14-6\n\nEC No.\n231-890-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2196,126,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，不要催吐，饮用1杯或2杯水。\n\n吸入\n新鲜空气，休息。如果感觉不舒服，需就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2197,126,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2198,126,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2199,126,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2200,126,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2201,126,9,'理化特性','外观与性状\n白色粉末\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n7~9（50g/L，20℃）\n\n熔点/凝固点(℃)\n＞100（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.4\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n＜-4.7\n\n自燃温度(℃)\n130\n\n分解温度(℃)\n＞100\n\n黏度\n不适用',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2202,126,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无机碱可使其剧烈分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机碱、金属、硫和磷。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2203,126,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n连二亚硫酸钠\n7775-14-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n连二亚硫酸钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2204,126,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2205,126,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2206,126,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1384\n\n联合国正确运输名称\n连二亚硫酸钠\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2207,126,15,'法规信息','国际化学品名录\n\n连二亚硫酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n连二亚硫酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2208,126,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2209,127,1,'化学品及企业标识','产品标识\n\n产品中文名称\n联苯\n\n产品英文名称\nbiphenyl|diphenyl\n\n别名\n-\n\nCAS NO.\n92-52-4\n\nEC NO.\n202-163-5\n\n分子式\nC12H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2210,127,2,'危险性概述','紧急情况概述\n\n固体。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。恶心。呕吐。\n\n食入\n另见吸入。\n\n皮肤接触\n发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2211,127,3,'成分/组成信息','联苯\n\nCas No.\n92-52-4\n\nEC No.\n202-163-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2212,127,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗（如可能易行，摘除隐形眼镜）。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2213,127,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2214,127,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2215,127,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2216,127,8,'接触控制/个体防护','控制参数->职业接触限值\n\n联苯\nGBZ 2.1-2007\n\nPC-TWA\n1.5 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2217,127,9,'理化特性','外观与性状\n白色晶体或薄片\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n70\n\n初沸点和沸程(℃)\n256\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：5.8；下限：0.6\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.04\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.16~4.09\n\n自燃温度(℃)\n540\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2218,127,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2219,127,11,'毒理学信息','急性毒性\n\n联苯\n92-52-4\n\nLD\n50\n(经口)\n3280mg/kg(大鼠)\n\nLD\n50\n(经皮)\n3280mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n联苯\n92-52-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n联苯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2220,127,12,'生态学信息','急性水生毒性\n\n联苯\n92-52-4\n\n鱼类\nLC\n50\n：3.5mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.16mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.78mg/L (72h)(藻类)\n\n慢性水生毒性\n\n联苯\n92-52-4\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.13mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：0.0070mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n联苯：水/土壤-低(半衰期=14天) 空气-低(半衰期=4.58天)\n\n生物富集或生物积累性\n联苯：生物富集性-中等（LogKOW=3.16-4.09）\n\n土壤中的迁移性\n联苯：土壤迁移性-低（koc=6250）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2221,127,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2222,127,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2223,127,15,'法规信息','国际化学品名录\n\n联苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n联苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2224,127,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2225,128,1,'化学品及企业标识','产品标识\n\n产品中文名称\n磷化氢\n\n产品英文名称\nphosphine|trihydrogen phosphide\n\n别名\n磷化三氢|膦\n\nCAS NO.\n7803-51-2\n\nEC NO.\n232-260-8\n\n分子式\nPH3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2226,128,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽,恶心,灼烧感,腹泻,腹痛,头晕,迟钝,头痛,共济失调,胸痛,胸紧,震颤,气促,呕吐,惊厥。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2227,128,3,'成分/组成信息','磷化氢\n\nCas No.\n7803-51-2\n\nEC No.\n232-260-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2228,128,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2229,128,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2230,128,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2231,128,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2232,128,8,'接触控制/个体防护','控制参数->职业接触限值\n\n磷化氢\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2233,128,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-133\n\n初沸点和沸程(℃)\n-87.7\n\n闪点(闭杯，℃)\n-88\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：98；下限：1.8\n\n蒸气压\n4186kPa（20℃）\n\n蒸气密度(空气=1)\n1.17\n\n相对密度(水=1)\n0.8\n\n溶解性(mg/L)\n330\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n38\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2234,128,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与碱、金属、氧化剂、金属氧化物和金属硝酸盐接触会着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、碱、氧化剂、金属氧化物和金属硝酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2235,128,11,'毒理学信息','急性毒性\n\n磷化氢\n7803-51-2\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n磷化氢\n7803-51-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n磷化氢\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2236,128,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2237,128,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2238,128,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2199\n\n联合国正确运输名称\n磷化氢(膦)\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2239,128,15,'法规信息','国际化学品名录\n\n磷化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n磷化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2240,128,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2241,129,1,'化学品及企业标识','产品标识\n\n产品中文名称\n磷酸三甲苯酯\n\n产品英文名称\ntricresyl phosphate,with more than 3% ortho isomer|tritolylphosphate|plasticizer TCP\n\n别名\n磷酸三甲酚酯|增塑剂TCP\n\nCAS NO.\n1330-78-5\n\nEC NO.\n215-548-8\n\n分子式\nC21H21O4P\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2242,129,2,'危险性概述','紧急情况概述\n\n液体。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2243,129,3,'成分/组成信息','磷酸三甲苯酯\n\nCas No.\n1330-78-5\n\nEC No.\n215-548-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2244,129,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2245,129,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2246,129,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2247,129,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2248,129,8,'接触控制/个体防护','控制参数->职业接触限值\n\n磷酸三甲苯酯\nGBZ 2.1-2007\n\nPC-TWA\n0.3 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2249,129,9,'理化特性','外观与性状\n无色至淡黄色油状液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-33\n\n初沸点和沸程(℃)\n410\n\n闪点(闭杯，℃)\n210\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.013kPa（155℃）\n\n蒸气密度(空气=1)\n12.7\n\n相对密度(水=1)\n1.16~1.18\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n5.1\n\n自燃温度(℃)\n385\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2250,129,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2251,129,11,'毒理学信息','急性毒性\n\n磷酸三甲苯酯\n1330-78-5\n\nLD\n50\n(经口)\n3000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n磷酸三甲苯酯\n1330-78-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n磷酸三甲苯酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2252,129,12,'生态学信息','急性水生毒性\n\n磷酸三甲苯酯\n1330-78-5\n\n鱼类\nLC\n50\n：0.84mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.25mg/L (48h)()\n\n藻类/水生植物\nErC\n50\n：2.55mg/L (96h)()\n\n慢性水生毒性\n\n磷酸三甲苯酯\n1330-78-5\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.62mg/L()\n\n藻类/水生植物\nNOEC：0.088mg/L()\n\n其他信息\n\n持久性和降解性\n磷酸三甲苯酯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n磷酸三甲苯酯：生物富集性-高（LogKOW=6.3425）\n\n土壤中的迁移性\n磷酸三甲苯酯：土壤迁移性-低（koc=358300）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2253,129,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2254,129,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2574\n\n联合国正确运输名称\n磷酸三甲苯酯，含邻位异构物大于3%\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:31','2025-10-21 07:50:31'),(2255,129,15,'法规信息','国际化学品名录\n\n磷酸三甲苯酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n磷酸三甲苯酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2256,129,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:31','2025-10-21 07:50:31'),(2257,130,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫化钠\n\n产品英文名称\nsodium sulphide\n\n别名\n臭碱\n\nCAS NO.\n1313-82-2\n\nEC NO.\n215-211-5\n\n分子式\nNa2S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2258,130,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 1\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH251\n自热；可能燃烧\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽。灼烧感。呼吸困难。气促。咽喉痛。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。水疱。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2259,130,3,'成分/组成信息','硫化钠\n\nCas No.\n1313-82-2\n\nEC No.\n215-211-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2260,130,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2261,130,5,'消防措施','灭火介质\n\n适合的灭火介质\n砂土、二氧化碳。\n\n不适合的灭火介质\n水或酸碱式灭火剂。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2262,130,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2263,130,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2264,130,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2265,130,9,'理化特性','外观与性状\n无色结晶固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＞=11.5（强碱）\n\n熔点/凝固点(℃)\n920~950（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.856（14℃）\n\n溶解性(mg/L)\n188 g/L（20℃）\n\n辛醇 /水分配系数\n-3.5\n\n自燃温度(℃)\n＞480\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2266,130,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在空气中自燃。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝酸盐及亚硝酸盐、卤素的含氧酸盐、高锰酸盐、过硫酸盐、卤素和强氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2267,130,11,'毒理学信息','急性毒性\n\n硫化钠\n1313-82-2\n\nLD\n50\n(经口)\n208mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫化钠\n1313-82-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫化钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2268,130,12,'生态学信息','急性水生毒性\n\n硫化钠\n1313-82-2\n\n鱼类\nLC\n50\n：41mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：75mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n硫化钠：水/土壤-高 空气-高\n\n生物富集或生物积累性\n硫化钠：生物富集性-低（BCF=10.9）\n\n土壤中的迁移性\n硫化钠：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2269,130,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2270,130,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1385\n\n联合国正确运输名称\n无水硫化钠\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2271,130,15,'法规信息','国际化学品名录\n\n硫化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2272,130,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2273,131,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫磺\n\n产品英文名称\nsulphur\n\n别名\n硫\n\nCAS NO.\n7704-34-9\n\nEC NO.\n231-722-6\n\n分子式\nS\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2274,131,2,'危险性概述','紧急情况概述\n\n固体。易燃，其粉体与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃固体\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH228\n易燃固体\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n遇火或摩擦可被引燃，其粉体与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，咽喉痛。\n\n食入\n灼烧感，腹泻。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2275,131,3,'成分/组成信息','硫磺\n\nCas No.\n7704-34-9\n\nEC No.\n231-722-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2276,131,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2277,131,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						重度撞击或过度受热能引起爆炸。\n3\r\n						.\r\n						易燃固体，燃烧时火焰容易蔓延 (即使部分用水润湿)。\n4\r\n						.\r\n						可能会剧烈燃烧。\n5\r\n						.\r\n						任何点火源，即摩擦、受热、火花或火焰都可能引起火灾和爆炸。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2278,131,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2279,131,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于35℃。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2280,131,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2281,131,9,'理化特性','外观与性状\n黄色脆性晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n107~120\n\n初沸点和沸程(℃)\n445\n\n闪点(闭杯，℃)\n160\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：2.003；下限：0.035\n\n蒸气压\n0.133kPa（184℃）\n\n蒸气密度(空气=1)\n3.64\n\n相对密度(水=1)\n2.1\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n232\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2282,131,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属乙炔化合物的混合物在加热时，发生燃烧或白炽化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属乙炔化合物、卤素及卤间化合物、卤素的氧化物、硝酸、氧化氮、硝酸盐、亚硝酸盐、卤素含氧酸盐、铬酸盐、高锰酸盐、无机过氧化物、金属氧化物和过氧甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2283,131,11,'毒理学信息','急性毒性\n\n硫磺\n7704-34-9\n\nLD\n50\n(经口)\n>3000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫磺\n7704-34-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫磺\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2284,131,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n硫磺：水/土壤-低 空气-低\n\n生物富集或生物积累性\n硫磺：生物富集性-低（LogKOW=0.229）\n\n土壤中的迁移性\n硫磺：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2285,131,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2286,131,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1350\n\n联合国正确运输名称\n硫\n\n运输主要危险类别\n4.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。两层塑料袋或一层塑料袋外麻袋、塑料编织袋、乳胶布袋。塑料袋外复合塑料编织袋（聚丙烯三合一袋、聚乙烯三合一袋、聚丙烯二合一袋、聚乙烯二合一袋）。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/34bf45a46c7f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.1.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2287,131,15,'法规信息','国际化学品名录\n\n硫磺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫磺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2288,131,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2289,132,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫脲\n\n产品英文名称\nthiourea|thiocarbamide|sulfourea\n\n别名\n硫代尿素\n\nCAS NO.\n62-56-6\n\nEC NO.\n200-543-5\n\n分子式\nCH4N2S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2290,132,2,'危险性概述','紧急情况概述\n\n固体。可能有损伤胎儿或胚胎的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n生殖毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2291,132,3,'成分/组成信息','硫脲\n\nCas No.\n62-56-6\n\nEC No.\n200-543-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2292,132,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤，给予医疗护理。\n\n食入\n催吐(仅对清醒病人!),给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2293,132,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2294,132,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2295,132,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2296,132,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2297,132,9,'理化特性','外观与性状\n白色结晶\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n6~8（20℃，50g/L）\n\n熔点/凝固点(℃)\n182\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.41（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-2.38~-0.95\n\n自燃温度(℃)\n440\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2298,132,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2299,132,11,'毒理学信息','急性毒性\n\n硫脲\n62-56-6\n\nLD\n50\n(经口)\n125mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫脲\n62-56-6\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫脲\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2300,132,12,'生态学信息','急性水生毒性\n\n硫脲\n62-56-6\n\n鱼类\nLC\n50\n：>110mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：16mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：5.6mg/L (96h)(藻类)\n\n慢性水生毒性\n\n硫脲\n62-56-6\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：1.8mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：32mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n硫脲：水/土壤-低 空气-低\n\n生物富集或生物积累性\n硫脲：生物富集性-低（BCF=2）\n\n土壤中的迁移性\n硫脲：土壤迁移性-中等（koc=2.782）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2301,132,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2302,132,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2303,132,15,'法规信息','国际化学品名录\n\n硫脲\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫脲\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2304,132,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2305,133,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫氢化钠\n\n产品英文名称\nsodium hydrosulfide\n\n别名\n氢硫化钠\n\nCAS NO.\n16721-80-5\n\nEC NO.\n240-778-0\n\n分子式\nNaHS\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2306,133,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。吞食后有毒。有严重损害眼睛的危险。对呼吸道有刺激作用。短期暴露有损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 2\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-一次接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH252\n数量大时自热；可能燃烧\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH371\n可能损害器官\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。\n\n危害描述->健康危害\n\n吸入\n咽喉痛。灼烧感。呼吸短促，呼吸困难。神志不清。\n\n食入\n咽喉疼痛。口腔和咽喉烧伤。腹部疼痛，呕吐。休克或虚脱。\n\n皮肤接触\n发红，疼痛，皮肤烧伤。\n\n眼睛\n发红，疼痛，烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2307,133,3,'成分/组成信息','硫氢化钠\n\nCas No.\n16721-80-5\n\nEC No.\n240-778-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2308,133,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。立即给予医疗护理。\n\n食入\n漱口，饮用1杯或2杯水。不要催吐。立即给予医疗护理。\n\n吸入\n半直立体位。必要时进行人工呼吸。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2309,133,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2310,133,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2311,133,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n2\r\n						.\r\n						使用防爆设备。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2312,133,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2313,133,9,'理化特性','外观与性状\n无色至微黄色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n350\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.8\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-3.5\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2314,133,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2315,133,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n硫氢化钠\n16721-80-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫氢化钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2316,133,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2317,133,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2318,133,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2318\n\n联合国正确运输名称\n氢硫化钠，含结晶水低于25%\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2319,133,15,'法规信息','国际化学品名录\n\n硫氢化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫氢化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2320,133,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2321,12,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫酸\n\n产品英文名称\nsulphuric acid\n\n别名\n-\n\nCAS NO.\n7664-93-9\n\nEC NO.\n231-639-5\n\n分子式\nH2SO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2322,12,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腐蚀作用。灼烧感，咽喉痛，咳嗽，呼吸困难，气促。症状可能推迟显现。。\n\n食入\n腐蚀作用，腹部疼痛，灼烧感，休克或虚脱。\n\n皮肤接触\n腐蚀作用，发红，疼痛，水疱，严重皮肤烧伤。\n\n眼睛\n腐蚀作用发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2323,12,3,'成分/组成信息','硫酸\n\nCas No.\n7664-93-9\n\nEC No.\n231-639-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2324,12,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2325,12,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、二氧化碳。\n\n不适合的灭火介质\n水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2326,12,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2327,12,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度应在0~30℃之间，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2328,12,8,'接触控制/个体防护','控制参数->职业接触限值\n\n硫酸\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\nG1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2329,12,9,'理化特性','外观与性状\n无色液体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n1\n\n熔点/凝固点(℃)\n10\n\n初沸点和沸程(℃)\n290（分解）\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（146℃ ）\n\n蒸气密度(空气=1)\n3.4\n\n相对密度(水=1)\n1.84（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n340\n\n黏度\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2330,12,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2331,12,11,'毒理学信息','急性毒性\n\n硫酸\n7664-93-9\n\nLD\n50\n(经口)\n2140mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫酸\n7664-93-9\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2332,12,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n硫酸：水/土壤-低 空气-低\n\n生物富集或生物积累性\n硫酸：生物富集性-低（LogKOW=-1.38）\n\n土壤中的迁移性\n硫酸：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2333,12,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2334,12,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1830\n\n联合国正确运输名称\n硫酸，含酸大于51%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2335,12,15,'法规信息','国际化学品名录\n\n硫酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2336,12,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2337,134,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫酸二甲酯\n\n产品英文名称\ndimethyl sulphate|methyl sulfate\n\n别名\n硫酸甲酯\n\nCAS NO.\n77-78-1\n\nEC NO.\n201-058-1\n\n分子式\nC2H6O4S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2338,134,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有剧毒。对呼吸道有刺激作用。可能有发生不可逆性作用的危险。对水生物有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH335\n可能造成呼吸道刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH350\n可能致癌\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,灼烧感,呼吸短促,头痛,症状可能推迟显现。\n\n食入\n口腔和咽喉烧伤,咽喉有灼烧感,胃痉挛,呕吐,惊厥,休克或虚脱(另见吸入)。\n\n皮肤接触\n可能被吸收！发红。疼痛。水疱。皮肤烧伤。\n\n眼睛\n发红。疼痛。烧伤。永久丧失视力。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2339,134,3,'成分/组成信息','硫酸二甲酯\n\nCas No.\n77-78-1\n\nEC No.\n201-058-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2340,134,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。立即给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。不要催吐。立即给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2341,134,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、泡沫、二氧化碳、雾状水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2342,134,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2343,134,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2344,134,8,'接触控制/个体防护','控制参数->职业接触限值\n\n硫酸二甲酯\nGBZ 2.1-2007\n\nPC-TWA\n0.5 mg/m3\n\nPC-STEL\n-\n\n备注\n皮，G2A\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2345,134,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-32\n\n初沸点和沸程(℃)\n188（分解）\n\n闪点(闭杯，℃)\n83\n\n蒸发速率\n无资料\n\n易燃性\n可燃\n\n爆炸上限 /下限[%(v/v)]\n上限：23.3；下限：3.6\n\n蒸气压\n65Pa（20℃）\n\n蒸气密度(空气=1)\n4.4\n\n相对密度(水=1)\n1.328（20℃）\n\n溶解性(mg/L)\n28 g/L（18℃）\n\n辛醇 /水分配系数\n0.16\n\n自燃温度(℃)\n470\n\n分解温度(℃)\n188\n\n黏度\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2346,134,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在无稀释剂时，与挥发性的碱性化合物接触会剧烈反应而发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n挥发性的碱性化合物、卤素的含氧酸盐、硝酸盐和金属烷氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2347,134,11,'毒理学信息','急性毒性\n\n硫酸二甲酯\n77-78-1\n\nLD\n50\n(经口)\n205mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n205mg/kg(大鼠)\n\n致癌性\n\n硫酸二甲酯\n77-78-1\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫酸二甲酯\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2348,134,12,'生态学信息','急性水生毒性\n\n硫酸二甲酯\n77-78-1\n\n鱼类\nLC\n50\n：11.2mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2349,134,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2350,134,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1595\n\n联合国正确运输名称\n硫酸二甲酯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:32','2025-10-21 07:50:32'),(2351,134,15,'法规信息','国际化学品名录\n\n硫酸二甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫酸二甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2352,134,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:32','2025-10-21 07:50:32'),(2353,135,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫酸二乙酯\n\n产品英文名称\ndiethyl sulphate\n\n别名\n硫酸乙酯\n\nCAS NO.\n64-67-5\n\nEC NO.\n200-589-6\n\n分子式\nC4H10O4S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2354,135,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，呼吸困难，气促，咽喉痛。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，恶心，咽喉疼痛。\n\n皮肤接触\n发红，严重皮肤烧伤，疼痛。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2355,135,3,'成分/组成信息','硫酸二乙酯\n\nCas No.\n64-67-5\n\nEC No.\n200-589-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2356,135,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口，不要催吐，不要饮用任何东西，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2357,135,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2358,135,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2359,135,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2360,135,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2361,135,9,'理化特性','外观与性状\n无色油性液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-25\n\n初沸点和沸程(℃)\n209（分解）\n\n闪点(闭杯，℃)\n104\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：4.1\n\n蒸气压\n20 Pa（20℃）\n\n蒸气密度(空气=1)\n5.3\n\n相对密度(水=1)\n1.2\n\n溶解性(mg/L)\n7 g/L（20℃）\n\n辛醇 /水分配系数\n1.14\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2362,135,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在无稀释剂时，与挥发性的碱性化合物接触会剧烈反应而发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n挥发性的碱性化合物、卤素的含氧酸盐、硝酸盐和金属烷氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2363,135,11,'毒理学信息','急性毒性\n\n硫酸二乙酯\n64-67-5\n\nLD\n50\n(经口)\n880mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫酸二乙酯\n64-67-5\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫酸二乙酯\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2364,135,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2365,135,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2366,135,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1594\n\n联合国正确运输名称\n硫酸二乙酯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2367,135,15,'法规信息','国际化学品名录\n\n硫酸二乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫酸二乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2368,135,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2369,136,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硫酸钴\n\n产品英文名称\ncobalt sulphate\n\n别名\n-\n\nCAS NO.\n10124-43-3\n\nEC NO.\n233-334-2\n\n分子式\nCoO4S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2370,136,2,'危险性概述','紧急情况概述\n\n固体。跟皮肤接触可能会引起敏化作用。有引起过敏、哮喘病症状或呼吸困难的风险。可能有发生不可逆性作用的危险。有轻微致癌性风险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤致敏物\n类别 1\n\n呼吸道致敏物\n类别 1\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 2\n\n生殖毒性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH317\n可能造成皮肤过敏反应\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH341\n怀疑可造成遗传性缺陷\n\nH351\n怀疑致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，呼吸困难，气促，咽喉痛。\n\n食入\n腹部疼痛，恶心，呕吐。\n\n皮肤接触\n发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2371,136,3,'成分/组成信息','硫酸钴\n\nCas No.\n10124-43-3\n\nEC No.\n233-334-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2372,136,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2373,136,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2374,136,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2375,136,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2376,136,8,'接触控制/个体防护','控制参数->职业接触限值\n\n硫酸钴\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n0.1 mg/m3\n\n备注\nG2B；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2377,136,9,'理化特性','外观与性状\n玫红色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n735（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.71（25℃）\n\n溶解性(mg/L)\n383 g/L（25℃）\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n735\n\n黏度\n不适用',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2378,136,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2379,136,11,'毒理学信息','急性毒性\n\n硫酸钴\n10124-43-3\n\nLD\n50\n(经口)\n424mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硫酸钴\n10124-43-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硫酸钴\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2380,136,12,'生态学信息','急性水生毒性\n\n硫酸钴\n10124-43-3\n\n鱼类\nLC\n50\n：3.75mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2381,136,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2382,136,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2383,136,15,'法规信息','国际化学品名录\n\n硫酸钴\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硫酸钴\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2384,136,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2385,137,1,'化学品及企业标识','产品标识\n\n产品中文名称\n六氟化硫\n\n产品英文名称\nsulphur hexafluoride\n\n别名\n-\n\nCAS NO.\n2551-62-4\n\nEC NO.\n219-854-2\n\n分子式\nSF6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2386,137,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n窒息。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n（见皮肤）。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2387,137,3,'成分/组成信息','六氟化硫\n\nCas No.\n2551-62-4\n\nEC No.\n219-854-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2388,137,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2389,137,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2390,137,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2391,137,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2392,137,8,'接触控制/个体防护','控制参数->职业接触限值\n\n六氟化硫\nGBZ 2.1-2007\n\nPC-TWA\n6000 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n六氟化硫\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2393,137,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-51\n\n初沸点和沸程(℃)\n-63.8\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n2450kPa\n\n蒸气密度(空气=1)\n5\n\n相对密度(水=1)\n1.9\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.68\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2394,137,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2395,137,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n六氟化硫\n2551-62-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n六氟化硫\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2396,137,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2397,137,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2398,137,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1080\n\n联合国正确运输名称\n六氟化硫\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2399,137,15,'法规信息','国际化学品名录\n\n六氟化硫\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n六氟化硫\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2400,137,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2401,138,1,'化学品及企业标识','产品标识\n\n产品中文名称\n六氟化钨\n\n产品英文名称\ntungsten(Ⅵ)hexafluoride\n\n别名\n-\n\nCAS NO.\n7783-82-6\n\nEC NO.\n232-029-1\n\n分子式\nF6W\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2402,138,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。吸入有剧毒。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n在正常生产处理过程中，吸入本品可产生严重毒害作用，甚至可致命。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2403,138,3,'成分/组成信息','六氟化钨\n\nCas No.\n7783-82-6\n\nEC No.\n232-029-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2404,138,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2405,138,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2406,138,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2407,138,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2408,138,8,'接触控制/个体防护','控制参数->职业接触限值\n\n六氟化钨\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n六氟化钨\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2409,138,9,'理化特性','外观与性状\n无色气体或浅黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n2.5\n\n初沸点和沸程(℃)\n17.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2410,138,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2411,138,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n六氟化钨\n7783-82-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n六氟化钨\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2412,138,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2413,138,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2414,138,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2196\n\n联合国正确运输名称\n六氟化钨\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2415,138,15,'法规信息','国际化学品名录\n\n六氟化钨\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n六氟化钨\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33');
INSERT INTO `msds章节` VALUES (2416,138,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2417,139,1,'化学品及企业标识','产品标识\n\n产品中文名称\n六氟乙烷\n\n产品英文名称\nhexafluoroethane|freon 116|perfluoroethane\n\n别名\nR116|全氟乙烷\n\nCAS NO.\n76-16-4\n\nEC NO.\n200-939-8\n\n分子式\nC2F6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2418,139,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2419,139,3,'成分/组成信息','六氟乙烷\n\nCas No.\n76-16-4\n\nEC No.\n200-939-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2420,139,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2421,139,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2422,139,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2423,139,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2424,139,8,'接触控制/个体防护','控制参数->职业接触限值\n\n六氟乙烷\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2425,139,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-101\n\n初沸点和沸程(℃)\n-78.2\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n3063kPa（21℃）\n\n蒸气密度(空气=1)\n4.832\n\n相对密度(水=1)\n1.59\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2426,139,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2427,139,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n六氟乙烷\n76-16-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n六氟乙烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2428,139,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2429,139,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2430,139,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2193\n\n联合国正确运输名称\n六氟乙烷\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2431,139,15,'法规信息','国际化学品名录\n\n六氟乙烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n六氟乙烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2432,139,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2433,140,1,'化学品及企业标识','产品标识\n\n产品中文名称\n六甲基二硅烷\n\n产品英文名称\nhexamethyldisilane\n\n别名\n-\n\nCAS NO.\n1450-14-2\n\nEC NO.\n215-911-0\n\n分子式\nC6H18Si2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2434,140,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2435,140,3,'成分/组成信息','六甲基二硅烷\n\nCas No.\n1450-14-2\n\nEC No.\n215-911-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2436,140,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2437,140,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2438,140,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2439,140,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2440,140,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2441,140,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n9\n\n初沸点和沸程(℃)\n111\n\n闪点(闭杯，℃)\n-1.67\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n30 mmHg（25℃）\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n0.729\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2442,140,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2443,140,11,'毒理学信息','急性毒性\n\n六甲基二硅烷\n1450-14-2\n\nLD\n50\n(经口)\n> 20000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n六甲基二硅烷\n1450-14-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n六甲基二硅烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2444,140,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n六甲基二硅烷：水/土壤-高 空气-高\n\n生物富集或生物积累性\n六甲基二硅烷：生物富集性-中等（LogKOW=4.1136）\n\n土壤中的迁移性\n六甲基二硅烷：土壤迁移性-低（koc=224.7）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2445,140,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2446,140,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1993\n\n联合国正确运输名称\n易燃液体，未另作规定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:33','2025-10-21 07:50:33'),(2447,140,15,'法规信息','国际化学品名录\n\n六甲基二硅烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n六甲基二硅烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2448,140,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:33','2025-10-21 07:50:33'),(2449,141,1,'化学品及企业标识','产品标识\n\n产品中文名称\n六氯环戊二烯\n\n产品英文名称\nhexachlorocyclopentadiene|perchlorocyclopentadiene\n\n别名\n全氯环戊二烯\n\nCAS NO.\n77-47-4\n\nEC NO.\n201-029-3\n\n分子式\nC5Cl6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2450,141,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头痛。腹泻。头晕。恶心。呕吐。呼吸困难。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。（另见吸入）。\n\n皮肤接触\n可能被吸收！发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2451,141,3,'成分/组成信息','六氯环戊二烯\n\nCas No.\n77-47-4\n\nEC No.\n201-029-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2452,141,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2453,141,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2454,141,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2455,141,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2456,141,8,'接触控制/个体防护','控制参数->职业接触限值\n\n六氯环戊二烯\nGBZ 2.1-2007\n\nPC-TWA\n0.1 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2457,141,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-9\n\n初沸点和沸程(℃)\n239\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n10.7Pa（20℃）\n\n蒸气密度(空气=1)\n9.4\n\n相对密度(水=1)\n1.7\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n4～5\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2458,141,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2459,141,11,'毒理学信息','急性毒性\n\n六氯环戊二烯\n77-47-4\n\nLD\n50\n(经口)\n315mg/kg(大鼠)\n\nLD\n50\n(经皮)\n315mg/kg(大鼠)\n\nLD\n50\n(吸入)\n315mg/kg(大鼠)\n\n致癌性\n\n六氯环戊二烯\n77-47-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n六氯环戊二烯\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2460,141,12,'生态学信息','急性水生毒性\n\n六氯环戊二烯\n77-47-4\n\n鱼类\nLC\n50\n：0.014mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.0091mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n六氯环戊二烯：水/土壤-低(半衰期=56天) 空气-\n\n生物富集或生物积累性\n六氯环戊二烯：生物富集性-中等（BCF=1634）\n\n土壤中的迁移性\n六氯环戊二烯：土壤迁移性-低（koc=1667）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2461,141,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2462,141,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2646\n\n联合国正确运输名称\n六氯环戊二烯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2463,141,15,'法规信息','国际化学品名录\n\n六氯环戊二烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n六氯环戊二烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2464,141,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2465,142,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯\n\n产品英文名称\nchlorine|liquid chlorine\n\n别名\n液氯|氯气\n\nCAS NO.\n7782-50-5\n\nEC NO.\n231-959-5\n\n分子式\nCl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2466,142,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。对皮肤有刺激性。对眼睛有严重刺激性。吸入有剧毒。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH330\n吸入致命\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,呼吸短促,喘息,呼吸困难,症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。发红。灼烧感。疼痛。皮肤烧伤。\n\n眼睛\n引起流泪。发红。疼痛。烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2467,142,3,'成分/组成信息','氯\n\nCas No.\n7782-50-5\n\nEC No.\n231-959-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2468,142,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行,摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n先用大量水冲洗至少15分钟，然后脱去污染的衣服并再次冲洗。立即给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气,休息,半直立体位,立即给予医疗护理,必要时进行人工呼吸,\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2469,142,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2470,142,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2471,142,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2472,142,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2473,142,9,'理化特性','外观与性状\n黄绿色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-101\n\n初沸点和沸程(℃)\n-34\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n673kPa\n\n蒸气密度(空气=1)\n2.5\n\n相对密度(水=1)\n1.41\n\n溶解性(mg/L)\n可溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2474,142,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与水接触立即分解，放出氧气。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、烷烃、炔烃、芳香烃、卤代烷烃、含氧有机化合物、金属、金属氢化物、非金属氢化物、非金属、金属乙炔化物、碳化物、叠氮化物、苛性碱、非金属氧化物和硫化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2475,142,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氯\n7782-50-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2476,142,12,'生态学信息','急性水生毒性\n\n氯\n7782-50-5\n\n鱼类\nLC\n50\n：0.161mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2477,142,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2478,142,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1017\n\n联合国正确运输名称\n氯\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n5.1+8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2479,142,15,'法规信息','国际化学品名录\n\n氯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2480,142,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2481,143,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯苯\n\n产品英文名称\nchlorobenzene|monochlorobenzene\n\n别名\n一氯化苯\n\nCAS NO.\n108-90-7\n\nEC NO.\n203-628-5\n\n分子式\nC6H5Cl\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2482,143,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n倦睡。头痛。恶心。神志不清。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n发红。皮肤干燥。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2483,143,3,'成分/组成信息','氯苯\n\nCas No.\n108-90-7\n\nEC No.\n203-628-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2484,143,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n给予医疗护理。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2485,143,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2486,143,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2487,143,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2488,143,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯苯\nGBZ 2.1-2007\n\nPC-TWA\n50 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2489,143,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-45\n\n初沸点和沸程(℃)\n132\n\n闪点(闭杯，℃)\n27\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11；下限：1.3\n\n蒸气压\n1.17kPa（20℃）\n\n蒸气密度(空气=1)\n3.88\n\n相对密度(水=1)\n1.11\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.18~2.84\n\n自燃温度(℃)\n590\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2490,143,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2491,143,11,'毒理学信息','急性毒性\n\n氯苯\n108-90-7\n\nLD\n50\n(经口)\n1110mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯苯\n108-90-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2492,143,12,'生态学信息','急性水生毒性\n\n氯苯\n108-90-7\n\n鱼类\nLC\n50\n：6.6mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：5.29mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：202mg/L (96h)(藻类)\n\n慢性水生毒性\n\n氯苯\n108-90-7\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：0.72mg/L(甲壳纲)\n\n藻类/水生植物\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2493,143,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2494,143,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1134\n\n联合国正确运输名称\n氯苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2495,143,15,'法规信息','国际化学品名录\n\n氯苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2496,143,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2497,144,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化钡\n\n产品英文名称\nbarium chloride\n\n别名\n-\n\nCAS NO.\n10361-37-2\n\nEC NO.\n233-788-1\n\n分子式\nBaCl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2498,144,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。（见食入）。\n\n食入\n胃痉挛，惊厥，迟钝，神志不清，呕吐。\n\n皮肤接触\n发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2499,144,3,'成分/组成信息','氯化钡\n\nCas No.\n10361-37-2\n\nEC No.\n233-788-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2500,144,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n催吐(仅对清醒病人!),休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2501,144,5,'消防措施','灭火介质\n\n适合的灭火介质\n矽土、水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2502,144,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2503,144,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2504,144,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯化钡\nGBZ 2.1-2007\n\nPC-TWA\n0.5 mg/m3\n\nPC-STEL\n1.5 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2505,144,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n5~8（20℃，50g/L，计算值）\n\n熔点/凝固点(℃)\n960\n\n初沸点和沸程(℃)\n1560\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.9\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2506,144,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2507,144,11,'毒理学信息','急性毒性\n\n氯化钡\n10361-37-2\n\nLD\n50\n(经口)\n118mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯化钡\n10361-37-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化钡\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2508,144,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氯化钡：水/土壤-高 空气-高\n\n生物富集或生物积累性\n氯化钡：生物富集性-低（BCF=60）\n\n土壤中的迁移性\n氯化钡：土壤迁移性-低（koc=23.74）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2509,144,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2510,144,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1564\n\n联合国正确运输名称\n钡化合物，未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2511,144,15,'法规信息','国际化学品名录\n\n氯化钡\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化钡\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2512,144,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2513,145,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化苄\n\n产品英文名称\nbenzyl chloride|α-chlorotoluene|1-chloromethylbenzene\n\n别名\nα-氯甲苯|苄基氯\n\nCAS NO.\n100-44-7\n\nEC NO.\n202-853-6\n\n分子式\nC7H7Cl\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2514,145,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。有严重损害眼睛的危险。吸入有毒。对呼吸道有刺激作用。长期暴露有损伤健康的危险。对水生物有毒。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n致癌性\n类别 1B\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH335\n可能造成呼吸道刺激\n\nH350\n可能致癌\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，恶心，头痛，气促，头晕。\n\n食入\n腹部疼痛,腹泻,呕吐,灼烧感。\n\n皮肤接触\n可能被吸收！发红，疼痛。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2515,145,3,'成分/组成信息','氯化苄\n\nCas No.\n100-44-7\n\nEC No.\n202-853-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2516,145,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2517,145,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2518,145,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2519,145,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2520,145,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯化苄\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\nG2A\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2521,145,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-43\n\n初沸点和沸程(℃)\n179\n\n闪点(闭杯，℃)\n67\n\n蒸发速率\n无资料\n\n易燃性\n可燃\n\n爆炸上限 /下限[%(v/v)]\n上限：14；下限：1.1\n\n蒸气压\n120Pa（20℃ ）\n\n蒸气密度(空气=1)\n4.4\n\n相对密度(水=1)\n1.1\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.3\n\n自燃温度(℃)\n585\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2522,145,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2523,145,11,'毒理学信息','急性毒性\n\n氯化苄\n100-44-7\n\nLD\n50\n(经口)\n1231mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯化苄\n100-44-7\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化苄\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2524,145,12,'生态学信息','急性水生毒性\n\n氯化苄\n100-44-7\n\n鱼类\nLC\n50\n：5mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2525,145,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2526,145,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1738\n\n联合国正确运输名称\n苄基氯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2527,145,15,'法规信息','国际化学品名录\n\n氯化苄\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化苄\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2528,145,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2529,146,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化汞\n\n产品英文名称\nmercuric chloride|mercury perchloride|mercury dichloride|mercurybichloride|corrosive sublimate\n\n别名\n氯化高汞|二氯化汞|升汞\n\nCAS NO.\n7487-94-7\n\nEC NO.\n231-299-8\n\n分子式\nHgCl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2530,146,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。可能有发生不可逆性作用的危险。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n生殖细胞致突变性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH341\n怀疑可造成遗传性缺陷\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。气促。\n\n食入\n胃痉挛。腹部疼痛。灼烧感。金属味道。腹泻。恶心。咽喉疼痛。呕吐。休克或虚脱。\n\n皮肤接触\n可能被吸收！发红。疼痛。水疱。皮肤烧伤。\n\n眼睛\n疼痛。发红。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2531,146,3,'成分/组成信息','氯化汞\n\nCas No.\n7487-94-7\n\nEC No.\n-\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2532,146,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。用水冲服活性炭浆。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2533,146,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2534,146,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2535,146,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2536,146,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯化汞\nGBZ 2.1-2007\n\nPC-TWA\n0.025 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n氯化汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2537,146,9,'理化特性','外观与性状\n白色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n2~3.2（0.2M）\n\n熔点/凝固点(℃)\n276\n\n初沸点和沸程(℃)\n302\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n5.44（25℃）\n\n溶解性(mg/L)\n550g/L（100℃）\n\n辛醇 /水分配系数\n0.1\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2538,146,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2539,146,11,'毒理学信息','急性毒性\n\n氯化汞\n7487-94-7\n\nLD\n50\n(经口)\n1mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯化汞\n7487-94-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化汞\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2540,146,12,'生态学信息','急性水生毒性\n\n氯化汞\n7487-94-7\n\n鱼类\nLC\n50\n：0.214mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.01mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.14mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2541,146,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2542,146,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1624\n\n联合国正确运输名称\n氯化汞\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:34','2025-10-21 07:50:34'),(2543,146,15,'法规信息','国际化学品名录\n\n氯化汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2544,146,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:34','2025-10-21 07:50:34'),(2545,147,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化氢[无水]\n\n产品英文名称\nhydrogen chloride,anhydrous\n\n别名\n-\n\nCAS NO.\n7647-01-0\n\nEC NO.\n231-595-7\n\n分子式\nHCl\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2546,147,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n腐蚀作用，灼烧感，咳嗽，呼吸困难，气促，咽喉痛。症状可能推迟显现。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。腐蚀作用，严重皮肤烧伤，疼痛。\n\n眼睛\n腐蚀作用，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2547,147,3,'成分/组成信息','氯化氢\n\nCas No.\n7647-01-0\n\nEC No.\n231-595-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2548,147,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2549,147,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、干粉。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2550,147,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2551,147,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2552,147,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯化氢\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2553,147,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-144\n\n初沸点和沸程(℃)\n-85\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2554,147,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2555,147,11,'毒理学信息','急性毒性\n\n氯化氢\n7647-01-0\n\nLD\n50\n(经口)\n900mg/kg(兔子)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯化氢\n7647-01-0\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化氢\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2556,147,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2557,147,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2558,147,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1050\n\n联合国正确运输名称\n无水氯化氢\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2559,147,15,'法规信息','国际化学品名录\n\n氯化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2560,147,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2561,148,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化锌\n\n产品英文名称\nzinc chloride\n\n别名\n-\n\nCAS NO.\n7646-85-7\n\nEC NO.\n231-592-0\n\n分子式\nZnCl2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2562,148,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛，灼烧感，呼吸困难，气促。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，咽喉疼痛，恶心，呕吐，休克或虚脱。\n\n皮肤接触\n皮肤烧伤，疼痛，发红。\n\n眼睛\n疼痛，发红，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2563,148,3,'成分/组成信息','氯化锌\n\nCas No.\n7646-85-7\n\nEC No.\n231-592-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2564,148,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂清洗皮肤，给予医疗护理。\n\n食入\n不要催吐。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2565,148,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2566,148,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2567,148,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2568,148,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯化锌\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2569,148,9,'理化特性','外观与性状\n白色固体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n5（100g/L，20℃）\n\n熔点/凝固点(℃)\n290\n\n初沸点和沸程(℃)\n732\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.9\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2570,148,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与有机过氧化物接触，会迅速燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n有机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2571,148,11,'毒理学信息','急性毒性\n\n氯化锌\n7646-85-7\n\nLD\n50\n(经口)\n350mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯化锌\n7646-85-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化锌\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2572,148,12,'生态学信息','急性水生毒性\n\n氯化锌\n7646-85-7\n\n鱼类\nLC\n50\n：3.36mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.97mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.05mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氯化锌：水/土壤-高 空气-高\n\n生物富集或生物积累性\n氯化锌：生物富集性-高（BCF=16000）\n\n土壤中的迁移性\n氯化锌：土壤迁移性-低（koc=23.74）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2573,148,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2574,148,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2331\n\n联合国正确运输名称\n无水氯化锌\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2575,148,15,'法规信息','国际化学品名录\n\n氯化锌\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化锌\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2576,148,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2577,149,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯化亚砜\n\n产品英文名称\nthionyl dichloride|thionyl chloride|sulfurous oxychloride|sulphinyl chloride\n\n别名\n亚硫酰二氯|二氯氧化硫|亚硫酰氯\n\nCAS NO.\n7719-09-7\n\nEC NO.\n231-748-8\n\n分子式\nCl2OS\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2578,149,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感,气促,呼吸困难,症状可能推迟显现。\n\n食入\n灼烧感，腹部疼痛，休克或虚脱。\n\n皮肤接触\n疼痛，发红，严重皮肤烧伤。\n\n眼睛\n疼痛，发红，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2579,149,3,'成分/组成信息','氯化亚砜\n\nCas No.\n7719-09-7\n\nEC No.\n231-748-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2580,149,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口。不要催吐，给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位。必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2581,149,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、干粉。\n\n不适合的灭火介质\n水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2582,149,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2583,149,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于75%。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2584,149,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2585,149,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n-104.5\n\n初沸点和沸程(℃)\n76\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n16kPa（25℃）\n\n蒸气密度(空气=1)\n4.1\n\n相对密度(水=1)\n1.64\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2586,149,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属接触会引起燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属、活泼金属、易燃有机物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2587,149,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氯化亚砜\n7719-09-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯化亚砜\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2588,149,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2589,149,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2590,149,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1836\n\n联合国正确运输名称\n亚硫酰氯\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2591,149,15,'法规信息','国际化学品名录\n\n氯化亚砜\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯化亚砜\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2592,149,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2593,150,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯磺酸\n\n产品英文名称\nchlorosulphonic acid|chlorosulfuric acid|sulfuric chlorohydrin\n\n别名\n氯化硫酸|氯硫酸\n\nCAS NO.\n7790-94-5\n\nEC NO.\n232-234-6\n\n分子式\nClHO3S\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2594,150,2,'危险性概述','紧急情况概述\n\n液体。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。对水生物有毒。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感，气促，呼吸困难。症状可能推迟显现。。\n\n食入\n灼烧感，腹部疼痛，恶心，休克或虚脱。\n\n皮肤接触\n疼痛，发红，严重皮肤烧伤。\n\n眼睛\n疼痛，发红，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2595,150,3,'成分/组成信息','氯磺酸\n\nCas No.\n7790-94-5\n\nEC No.\n232-234-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2596,150,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐。大量饮水，给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2597,150,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2598,150,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2599,150,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于75%。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2600,150,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2601,150,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n＜1（20℃）\n\n熔点/凝固点(℃)\n-80\n\n初沸点和沸程(℃)\n151~152（100kPa）\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n133Pa（20℃）\n\n蒸气密度(空气=1)\n4.02\n\n相对密度(水=1)\n1.75\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞151\n\n黏度\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2602,150,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属单质或有机物接触发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属单质、有机物和纤维类物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2603,150,11,'毒理学信息','急性毒性\n\n氯磺酸\n7790-94-5\n\nLD\n50\n(经口)\n50mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯磺酸\n7790-94-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯磺酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2604,150,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2605,150,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2606,150,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1754\n\n联合国正确运输名称\n氯磺酸(不含三氧化硫)\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2607,150,15,'法规信息','国际化学品名录\n\n氯磺酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯磺酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2608,150,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2609,13,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯甲烷\n\n产品英文名称\nchloromethane|R40|methyl chloride\n\n别名\nR40|甲基氯|一氯甲烷\n\nCAS NO.\n74-87-3\n\nEC NO.\n200-817-4\n\n分子式\nCH3Cl\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2610,13,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n蹒跚步态,头晕,头痛，恶心,呕吐,惊厥，神志不清。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n可能被吸收！与液体接触：冻伤。\n\n眼睛\n（见皮肤）。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2611,13,3,'成分/组成信息','氯甲烷\n\nCas No.\n74-87-3\n\nEC No.\n200-817-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2612,13,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2613,13,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2614,13,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2615,13,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2616,13,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯甲烷\nGBZ 2.1-2007\n\nPC-TWA\n60 mg/m3\n\nPC-STEL\n120 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2617,13,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-97.6\n\n初沸点和沸程(℃)\n-24.2\n\n闪点(闭杯，℃)\n-46\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：17.4；下限：8.1\n\n蒸气压\n506kPa\n\n蒸气密度(空气=1)\n1.8\n\n相对密度(水=1)\n0.92\n\n溶解性(mg/L)\n5g/L（20℃）\n\n辛醇 /水分配系数\n0.91\n\n自燃温度(℃)\n632\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2618,13,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2619,13,11,'毒理学信息','急性毒性\n\n氯甲烷\n74-87-3\n\nLD\n50\n(经口)\n1800mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n1800mg/kg(大鼠)\n\n致癌性\n\n氯甲烷\n74-87-3\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2620,13,12,'生态学信息','急性水生毒性\n\n氯甲烷\n74-87-3\n\n鱼类\nLC\n50\n：410mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2621,13,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2622,13,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1063\n\n联合国正确运输名称\n甲基氯\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:35','2025-10-21 07:50:35'),(2623,13,15,'法规信息','国际化学品名录\n\n氯甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2624,13,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:35','2025-10-21 07:50:35'),(2625,151,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯酸钠\n\n产品英文名称\nsodium chlorate\n\n别名\n-\n\nCAS NO.\n7775-09-9\n\nEC NO.\n231-887-4\n\n分子式\nNaClO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2626,151,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触容易引起火灾。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH271\n可能引起燃烧或爆炸；强氧化剂\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP283\n穿防火/阻燃服装。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触容易引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,嘴唇发青或手指发青,皮肤发青,意识模糊,惊厥,头晕，头痛,恶心,神志不清。\n\n食入\n腹部疼痛,腹泻,气促，呕吐(另见吸入)。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2627,151,3,'成分/组成信息','氯酸钠\n\nCas No.\n7775-09-9\n\nEC No.\n231-887-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2628,151,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2629,151,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2630,151,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2631,151,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2632,151,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2633,151,9,'理化特性','外观与性状\n白色或淡黄色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n248\n\n初沸点和沸程(℃)\n300\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.5（15℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n255\n\n黏度\n不适用',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2634,151,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物当受热、撞击或摩擦时会引发爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、金属氨基化物、氨、铵盐、胺、酰胺、醇、酚、羧酸、羧酸酯、腈类、硫酸、浓硝酸和磷酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2635,151,11,'毒理学信息','急性毒性\n\n氯酸钠\n7775-09-9\n\nLD\n50\n(经口)\n1200mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1200mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯酸钠\n7775-09-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯酸钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2636,151,12,'生态学信息','急性水生毒性\n\n氯酸钠\n7775-09-9\n\n鱼类\nLC\n50\n：2340mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2637,151,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2638,151,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1495\n\n联合国正确运输名称\n氯酸钠\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2639,151,15,'法规信息','国际化学品名录\n\n氯酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2640,151,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2641,152,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯乙酸\n\n产品英文名称\nchloroacetic acid|monochloroacetic acid\n\n别名\n氯醋酸|一氯醋酸\n\nCAS NO.\n79-11-8\n\nEC NO.\n201-178-4\n\n分子式\nC2H3ClO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2642,152,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,咽喉痛,呼吸困难,呕吐,惊厥,神志不清。症状可能推迟显现。。\n\n食入\n腹部疼痛,灼烧感,休克或虚脱,惊厥,神志不清。\n\n皮肤接触\n可能被吸收!发红,疼痛,皮肤烧伤。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2643,152,3,'成分/组成信息','氯乙酸\n\nCas No.\n79-11-8\n\nEC No.\n201-178-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2644,152,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2645,152,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、泡沫、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2646,152,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2647,152,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2648,152,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯乙酸\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2649,152,9,'理化特性','外观与性状\n无色或白色结晶\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n＜1（20℃，800g/L）\n\n熔点/凝固点(℃)\n50\n\n初沸点和沸程(℃)\n189\n\n闪点(闭杯，℃)\n126\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：8\n\n蒸气压\n8.68Pa\n\n蒸气密度(空气=1)\n3.26\n\n相对密度(水=1)\n1.58\n\n溶解性(mg/L)\n4210g/L（20℃）\n\n辛醇 /水分配系数\n0.34\n\n自燃温度(℃)\n470\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2650,152,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2651,152,11,'毒理学信息','急性毒性\n\n氯乙酸\n79-11-8\n\nLD\n50\n(经口)\n650mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯乙酸\n79-11-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯乙酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2652,152,12,'生态学信息','急性水生毒性\n\n氯乙酸\n79-11-8\n\n鱼类\nLC\n50\n：72mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：77mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.16mg/L (72h)(藻类)\n\n慢性水生毒性\n\n氯乙酸\n79-11-8\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：0.033mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2653,152,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2654,152,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1751\n\n联合国正确运输名称\n固态氯乙酸\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2655,152,15,'法规信息','国际化学品名录\n\n氯乙酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯乙酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2656,152,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2657,153,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯乙酸钠\n\n产品英文名称\nsodium chloroacetate|sodium salt of chloroacetic acid\n\n别名\n-\n\nCAS NO.\n3926-62-3\n\nEC NO.\n223-498-3\n\n分子式\nC2H2ClNaO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2658,153,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。对皮肤有刺激性。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH315\n造成皮肤刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。\n\n食入\n腹部疼痛。恶心。呕吐。惊厥。（另见吸入）。\n\n皮肤接触\n皮肤直接接触可造成皮肤刺激。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2659,153,3,'成分/组成信息','氯乙酸钠\n\nCas No.\n3926-62-3\n\nEC No.\n223-498-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2660,153,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。\n\n食入\n给予医疗护理。漱口。不要催吐。大量饮水。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2661,153,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2662,153,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2663,153,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2664,153,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2665,153,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n4.5~9.0（20℃，50g/L）\n\n熔点/凝固点(℃)\n150~200（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-3.47\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n150~200\n\n黏度\n不适用',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2666,153,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2667,153,11,'毒理学信息','急性毒性\n\n氯乙酸钠\n3926-62-3\n\nLD\n50\n(经口)\n95mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯乙酸钠\n3926-62-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯乙酸钠\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2668,153,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2669,153,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2670,153,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2659\n\n联合国正确运输名称\n氯乙酸钠\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2671,153,15,'法规信息','国际化学品名录\n\n氯乙酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯乙酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2672,153,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2673,154,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氯乙酰氯\n\n产品英文名称\nchloroacetyl chloride\n\n别名\n氯化氯乙酰\n\nCAS NO.\n79-04-9\n\nEC NO.\n201-171-6\n\n分子式\nC2H2Cl2O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2674,154,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽,呼吸困难,灼烧感,嘴唇或指甲发青,气促,咽喉疼痛。症状可能推迟显现。\n\n食入\n灼烧感，腹部疼痛，腹泻，休克或虚脱。\n\n皮肤接触\n可能被吸收！发红，疼痛，严重皮肤烧伤，起疱。\n\n眼睛\n疼痛，发红，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2675,154,3,'成分/组成信息','氯乙酰氯\n\nCas No.\n79-04-9\n\nEC No.\n201-171-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2676,154,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱掉污染的衣服,用大量水冲洗皮肤或淋浴,给予医疗护理。\n\n食入\n漱口，不要催吐，不要饮用任何东西，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2677,154,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2678,154,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2679,154,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2680,154,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氯乙酰氯\nGBZ 2.1-2007\n\nPC-TWA\n0.2 mg/m3\n\nPC-STEL\n0.6 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2681,154,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-21.8\n\n初沸点和沸程(℃)\n106\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n2.5kPa（20℃）\n\n蒸气密度(空气=1)\n3.9\n\n相对密度(水=1)\n1.418\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n1.4\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2682,154,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2683,154,11,'毒理学信息','急性毒性\n\n氯乙酰氯\n79-04-9\n\nLD\n50\n(经口)\n208mg/kg(大鼠)\n\nLD\n50\n(经皮)\n208mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氯乙酰氯\n79-04-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氯乙酰氯\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2684,154,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2685,154,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2686,154,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1752\n\n联合国正确运输名称\n氯乙酰氯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2687,154,15,'法规信息','国际化学品名录\n\n氯乙酰氯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氯乙酰氯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2688,154,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2689,155,1,'化学品及企业标识','产品标识\n\n产品中文名称\n马来酸酐\n\n产品英文名称\nmaleic anhydride|butenedioic anhydride\n\n别名\n马来酐|失水苹果酸酐|顺丁烯二酸酐\n\nCAS NO.\n108-31-6\n\nEC NO.\n203-571-6\n\n分子式\nC4H2O3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2690,155,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。有引起过敏、哮喘病症状或呼吸困难的风险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n呼吸道致敏物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感。咳嗽。咽喉痛。呼吸短促。喘息。\n\n食入\n恶心。腹部疼痛。灼烧感。呕吐。腹泻。\n\n皮肤接触\n皮肤干燥。发红。疼痛。。\n\n眼睛\n发红。疼痛。烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2691,155,3,'成分/组成信息','马来酸酐\n\nCas No.\n108-31-6\n\nEC No.\n203-571-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2692,155,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2693,155,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2694,155,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2695,155,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2696,155,8,'接触控制/个体防护','控制参数->职业接触限值\n\n马来酸酐\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2697,155,9,'理化特性','外观与性状\n无色或白色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n53\n\n初沸点和沸程(℃)\n202\n\n闪点(闭杯，℃)\n102\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：7.1；下限：1.4\n\n蒸气压\n25Pa\n\n蒸气密度(空气=1)\n3.4\n\n相对密度(水=1)\n1.43（15℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n477\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2698,155,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与碱金属、碱土金属、氨、铵离子、一甲胺、二甲胺、三乙胺、低级脂肪胺、吡啶或喹啉发生放热分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n碱金属、碱土金属、氨、铵离子、一甲胺、二甲胺、三乙胺、低级脂肪胺、吡啶或喹啉、醇类和氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2699,155,11,'毒理学信息','急性毒性\n\n马来酸酐\n108-31-6\n\nLD\n50\n(经口)\n400mg/kg(大鼠)\n\nLD\n50\n(经皮)\n400mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n马来酸酐\n108-31-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n马来酸酐\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2700,155,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2701,155,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2702,155,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2215\n\n联合国正确运输名称\n马来酸酐\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2703,155,15,'法规信息','国际化学品名录\n\n马来酸酐\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n马来酸酐\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2704,155,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2705,156,1,'化学品及企业标识','产品标识\n\n产品中文名称\n马钱子碱\n\n产品英文名称\nstrychnine\n\n别名\n-\n\nCAS NO.\n57-24-9\n\nEC NO.\n200-319-7\n\n分子式\nC21H22N2O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2706,156,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n（见食入）\n\n食入\n惊厥，肌肉僵硬，休克或虚脱。\n\n皮肤接触\n皮肤接触可产生严重毒害作用，吸收后可产生全身影响，并可致命。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2707,156,3,'成分/组成信息','马钱子碱\n\nCas No.\n57-24-9\n\nEC No.\n200-319-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2708,156,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤，给予医疗护理。\n\n食入\n漱口，给予医疗护理。让患者完全不受打扰。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2709,156,5,'消防措施','灭火介质\n\n适合的灭火介质\n水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2710,156,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2711,156,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2712,156,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2713,156,9,'理化特性','外观与性状\n白色晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n9.5（饱和溶液）\n\n熔点/凝固点(℃)\n275~285\n\n初沸点和沸程(℃)\n270（6.7 hPa）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.36\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.68\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2714,156,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2715,156,11,'毒理学信息','急性毒性\n\n马钱子碱\n57-24-9\n\nLD\n50\n(经口)\n16mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n马钱子碱\n57-24-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n马钱子碱\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2716,156,12,'生态学信息','急性水生毒性\n\n马钱子碱\n57-24-9\n\n鱼类\nLC\n50\n：0.91mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：10mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n马钱子碱：水/土壤-低(半衰期=56天) 空气-低(半衰期=0.08天)\n\n生物富集或生物积累性\n马钱子碱：生物富集性-低（LogKOW=1.93）\n\n土壤中的迁移性\n马钱子碱：土壤迁移性-低（koc=6422）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2717,156,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2718,156,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1692\n\n联合国正确运输名称\n马钱子碱\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:36','2025-10-21 07:50:36'),(2719,156,15,'法规信息','国际化学品名录\n\n马钱子碱\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n马钱子碱\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2720,156,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:36','2025-10-21 07:50:36'),(2721,157,1,'化学品及企业标识','产品标识\n\n产品中文名称\n煤焦沥青\n\n产品英文名称\npitch,coal tar,high-temp|tar asphal\n\n别名\n焦油沥青|煤沥青|煤膏\n\nCAS NO.\n65996-93-2\n\nEC NO.\n266-028-2\n\n分子式\nC15H28O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2722,157,2,'危险性概述','紧急情况概述\n\n固体。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\n生殖毒性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n喷嚏。咳嗽。见长期或反复接触的影响。\n\n食入\n见长期或反复接触的影响。\n\n皮肤接触\n可能被吸收！发红。灼烧感。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2723,157,3,'成分/组成信息','煤焦沥青\n\nCas No.\n65996-93-2\n\nEC No.\n266-028-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2724,157,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2725,157,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2726,157,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2727,157,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2728,157,8,'接触控制/个体防护','控制参数->职业接触限值\n\n煤焦沥青\nGBZ 2.1-2007\n\nPC-TWA\n0.2 mg/m3\n\nPC-STEL\n-\n\n备注\nG1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2729,157,9,'理化特性','外观与性状\n黑色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n30~180\n\n初沸点和沸程(℃)\n≥250\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n≤0.01kPa\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n微溶于水\n\n辛醇 /水分配系数\n6.04\n\n自燃温度(℃)\n≥500\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2730,157,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2731,157,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n煤焦沥青\n65996-93-2\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n煤焦沥青\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2732,157,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n煤焦沥青：水/土壤-高(半衰期=720天) 空气-低(半衰期=20.88天)\n\n生物富集或生物积累性\n煤焦沥青：生物富集性-低（BCF=13）\n\n土壤中的迁移性\n煤焦沥青：土壤迁移性-低（koc=165.5）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2733,157,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2734,157,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2735,157,15,'法规信息','国际化学品名录\n\n煤焦沥青\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n煤焦沥青\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2736,157,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2737,158,1,'化学品及企业标识','产品标识\n\n产品中文名称\n煤油\n\n产品英文名称\nlamp oil|kerosine|straight run kerosine\n\n别名\n火油|直馏煤油\n\nCAS NO.\n8008-20-6\n\nEC NO.\n232-366-4\n\n分子式\nC15H32\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2738,158,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n吸入危害\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n意识模糊，咳嗽，眩晕，头痛，咽喉痛，神志不清。\n\n食入\n腹泻，恶心，呕吐。\n\n皮肤接触\n皮肤干燥，粗糙。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2739,158,3,'成分/组成信息','煤油\n\nCas No.\n8008-20-6\n\nEC No.\n232-366-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2740,158,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，冲洗，然后用水和肥皂洗皮肤，给予医疗护理。\n\n食入\n不要催吐，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2741,158,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2742,158,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2743,158,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2744,158,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2745,158,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-20\n\n初沸点和沸程(℃)\n150~300\n\n闪点(闭杯，℃)\n37~65\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：5；下限：0.7\n\n蒸气压\n无资料\n\n蒸气密度(空气=1)\n4.5\n\n相对密度(水=1)\n0.8\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n220\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2746,158,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2747,158,11,'毒理学信息','急性毒性\n\n煤油\n8008-20-6\n\nLD\n50\n(经口)\n2835mg/kg(兔子)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n煤油\n8008-20-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n煤油\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2748,158,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2749,158,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2750,158,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1223\n\n联合国正确运输名称\n煤油\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2751,158,15,'法规信息','国际化学品名录\n\n煤油\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n煤油\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2752,158,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2753,159,1,'化学品及企业标识','产品标识\n\n产品中文名称\n钠\n\n产品英文名称\nsodium\n\n别名\n金属钠\n\nCAS NO.\n7440-23-5\n\nEC NO.\n231-132-9\n\n分子式\nNa\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2754,159,2,'危险性概述','紧急情况概述\n\n固体。会跟水激烈反应, 生成高度易燃的气体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH260\n遇水放出可自燃的易燃气体\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。\n\n食入\n灼烧感。休克或虚脱。\n\n皮肤接触\n疼痛。水疱。严重皮肤烧伤。\n\n眼睛\n严重深度烧伤。视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2755,159,3,'成分/组成信息','钠\n\nCas No.\n7440-23-5\n\nEC No.\n231-132-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2756,159,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气,休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2757,159,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						火焰被扑灭后可能复燃。\n2\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n3\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n4\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2758,159,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2759,159,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2760,159,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2761,159,9,'理化特性','外观与性状\n银白色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n14\n\n熔点/凝固点(℃)\n97.4\n\n初沸点和沸程(℃)\n880\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n0.97\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n120~125\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2762,159,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n在空气中会被迅速被氧化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、二氧化碳、卤化碳、卤素、卤间化合物、金属卤化物、非金属氧化物、酸、汞和联氨。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2763,159,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n钠\n7440-23-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2764,159,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2765,159,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2766,159,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1428\n\n联合国正确运输名称\n钠\n\n运输主要危险类别\n4.3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2767,159,15,'法规信息','国际化学品名录\n\n钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2768,159,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2769,160,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氖[液化的]\n\n产品英文名称\nNeon, liquefied\n\n别名\n-\n\nCAS NO.\n7440-01-9\n\nEC NO.\n231-110-9\n\n分子式\nNe\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2770,160,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n液化气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压液化气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕，迟钝，头痛。窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2771,160,3,'成分/组成信息','氖气\n\nCas No.\n7440-01-9\n\nEC No.\n231-110-9\n\n含量范围（质量分数，%）\n99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2772,160,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。如果感觉不舒服，需就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2773,160,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2774,160,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2775,160,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2776,160,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2777,160,9,'理化特性','外观与性状\n液化气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-248.7\n\n初沸点和沸程(℃)\n-246.1\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2778,160,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2779,160,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氖气\n7440-01-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氖气\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2780,160,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2781,160,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2782,160,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1913\n\n联合国正确运输名称\n冷冻液态氖\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2783,160,15,'法规信息','国际化学品名录\n\n氖气\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氖气\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2784,160,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2785,161,1,'化学品及企业标识','产品标识\n\n产品中文名称\n哌啶\n\n产品英文名称\npiperidine|hexahydropyridine|pentamethyleneimine\n\n别名\n六氢吡啶|氮己环\n\nCAS NO.\n110-89-4\n\nEC NO.\n203-813-0\n\n分子式\nC5H11N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2786,161,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,呼吸困难,气促,咽喉痛,症状可能推迟显现。\n\n食入\n腹部疼痛。灼烧感。呼吸困难。休克或虚脱。\n\n皮肤接触\n可能被吸收！发红。皮肤烧伤。疼痛。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2787,161,3,'成分/组成信息','哌啶\n\nCas No.\n110-89-4\n\nEC No.\n203-813-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2788,161,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2789,161,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2790,161,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2791,161,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2792,161,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2793,161,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n12.6（20℃，100g/L）\n\n熔点/凝固点(℃)\n-7\n\n初沸点和沸程(℃)\n106\n\n闪点(闭杯，℃)\n16\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.7；下限：1.15\n\n蒸气压\n5.3kPa（29.2℃ ）\n\n蒸气密度(空气=1)\n3.0\n\n相对密度(水=1)\n0.86\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.84\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2794,161,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与强酸、强碱、强氧化剂或强还原剂接触可能发生反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n强酸、强碱、强氧化剂和强还原剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2795,161,11,'毒理学信息','急性毒性\n\n哌啶\n110-89-4\n\nLD\n50\n(经口)\n400mg/kg(大鼠)\n\nLD\n50\n(经皮)\n400mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n哌啶\n110-89-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n哌啶\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2796,161,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2797,161,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2798,161,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2401\n\n联合国正确运输名称\n哌啶\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2799,161,15,'法规信息','国际化学品名录\n\n哌啶\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n哌啶\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2800,161,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2801,162,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硼氢化铝\n\n产品英文名称\naluminium borohydride|aluminium tetrahydroborate\n\n别名\n氢硼化铝\n\nCAS NO.\n16962-07-5\n\nEC NO.\n-\n\n分子式\nAlB3H12\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2802,162,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易自身燃烧,有引发火灾的危险。会跟水激烈反应, 生成高度易燃的气体。\n\nGHS危险性类别\n\n自燃固体\n类别 1\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH250\n暴露在空气中会自燃\n\nH260\n遇水放出可自燃的易燃气体\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP222\n不得与空气接触。\n\nP223\n不得与水接触。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP422\n内装物存放在适当的液体或惰性气体中。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n即使数量很少，在与空气接触五分钟内即可自燃。会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2803,162,3,'成分/组成信息','硼氢化铝\n\nCas No.\n16962-07-5\n\nEC No.\n-\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2804,162,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2805,162,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉，干砂或石灰。\n\n不适合的灭火介质\n水、二氧化碳和泡沫。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n7\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n8\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n9\r\n						.\r\n						加热时，容器可能爆炸。\n10\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2806,162,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2807,162,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2808,162,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2809,162,9,'理化特性','外观与性状\n固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n44.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2810,162,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n暴露于空气中可迅速燃烧，特别是潮湿的或富含二氧化碳的空气。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素、卤素含氧酸盐、炔烃、硝基烷烃、醚、金属氧化物、二氧化锰、过氧化氢、二甲亚砜、羧酸酯、氟代烯烃、氟代羧酸及其衍生物、酰胺和无机酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2811,162,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n硼氢化铝\n16962-07-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硼氢化铝\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2812,162,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2813,162,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2814,162,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2870\n\n联合国正确运输名称\n氢硼化铝\n\n运输主要危险类别\n4.2\n\n运输次要危险类别\n4.3\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}]','2025-10-21 07:50:37','2025-10-21 07:50:37'),(2815,162,15,'法规信息','国际化学品名录\n\n硼氢化铝\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n未列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n未列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n硼氢化铝\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2816,162,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:37','2025-10-21 07:50:37'),(2817,163,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硼氢化钠\n\n产品英文名称\nsodium borohydride|sodium tetrahydroborate\n\n别名\n氢硼化钠\n\nCAS NO.\n16940-66-2\n\nEC NO.\n241-004-4\n\n分子式\nNaBH4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2818,163,2,'危险性概述','紧急情况概述\n\n固体。会跟水激烈反应, 生成高度易燃的气体。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1C\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH260\n遇水放出可自燃的易燃气体\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咳嗽。咽喉痛。呼吸困难。呼吸短促。\n\n食入\n咽喉和胸腔灼烧感。腹部疼痛。呕吐。休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2819,163,3,'成分/组成信息','硼氢化钠\n\nCas No.\n16940-66-2\n\nEC No.\n241-004-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2820,163,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗（如可能易行，摘除隐形眼镜）。立即给予医疗护理。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n漱口。饮用1杯或2杯水。不要催吐。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2821,163,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						火焰被扑灭后可能复燃。\n2\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n3\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n4\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2822,163,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2823,163,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2824,163,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2825,163,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n11（10g/L，20℃）\n\n熔点/凝固点(℃)\n379（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：3.02\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.07（20℃）\n\n溶解性(mg/L)\n550g/L（25℃，缓慢分解）\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n220\n\n分解温度(℃)\n379（计算值）\n\n黏度\n不适用',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2826,163,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n暴露于空气中可迅速燃烧，特别是潮湿的或富含二氧化碳的空气。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素、卤素含氧酸盐、炔烃、硝基烷烃、醚、金属氧化物、二氧化锰、过氧化氢、二甲亚砜、羧酸酯、氟代烯烃、氟代羧酸及其衍生物、酰胺和无机酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2827,163,11,'毒理学信息','急性毒性\n\n硼氢化钠\n16940-66-2\n\nLD\n50\n(经口)\n162mg/kg(大鼠)\n\nLD\n50\n(经皮)\n162mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硼氢化钠\n16940-66-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硼氢化钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1C)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2828,163,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2829,163,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2830,163,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1426\n\n联合国正确运输名称\n氢硼化钠\n\n运输主要危险类别\n4.3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2831,163,15,'法规信息','国际化学品名录\n\n硼氢化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硼氢化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2832,163,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2833,164,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硼酸\n\n产品英文名称\nboric acid\n\n别名\n-\n\nCAS NO.\n10043-35-3\n\nEC NO.\n233-139-2\n\n分子式\nH3BO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2834,164,2,'危险性概述','紧急情况概述\n\n固体。\n\nGHS危险性类别\n\n生殖毒性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH360\n可能对生育能力或胎儿造成伤害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉疼痛。\n\n食入\n腹部疼痛，惊厥，腹泻，恶心，呕吐，皮疹。\n\n皮肤接触\n可能被吸收！发红，可能通过受伤皮肤吸收！\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2835,164,3,'成分/组成信息','硼酸\n\nCas No.\n10043-35-3\n\nEC No.\n233-139-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2836,164,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，冲洗，然后用水和肥皂洗皮肤，给予医疗护理。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2837,164,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2838,164,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2839,164,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2840,164,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2841,164,9,'理化特性','外观与性状\n无色或白色结晶固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n5.2（20℃）\n\n熔点/凝固点(℃)\n171（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.4\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.757\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n171\n\n黏度\n不适用',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2842,164,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2843,164,11,'毒理学信息','急性毒性\n\n硼酸\n10043-35-3\n\nLD\n50\n(经口)\n2660mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硼酸\n10043-35-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硼酸\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2844,164,12,'生态学信息','急性水生毒性\n\n硼酸\n10043-35-3\n\n鱼类\nLC\n50\n：487mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：226mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：290mg/L (72h)(藻类)\n\n慢性水生毒性\n\n硼酸\n10043-35-3\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：82mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n硼酸：水/土壤-低 空气-低\n\n生物富集或生物积累性\n硼酸：生物富集性-低（BCF=0）\n\n土壤中的迁移性\n硼酸：土壤迁移性-低（koc=35.04）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2845,164,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2846,164,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2847,164,15,'法规信息','国际化学品名录\n\n硼酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硼酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2848,164,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2849,165,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硼酸三甲酯\n\n产品英文名称\ntrimethyl borate|methyl borate\n\n别名\n三甲氧基硼烷\n\nCAS NO.\n121-43-7\n\nEC NO.\n204-468-9\n\n分子式\nC3H9BO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2850,165,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n灼烧感。腹部疼痛。\n\n皮肤接触\n发红。灼烧感。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2851,165,3,'成分/组成信息','硼酸三甲酯\n\nCas No.\n121-43-7\n\nEC No.\n204-468-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2852,165,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2853,165,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2854,165,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2855,165,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2856,165,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2857,165,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-29\n\n初沸点和沸程(℃)\n68\n\n闪点(闭杯，℃)\n27\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n18kPa（25℃）\n\n蒸气密度(空气=1)\n3.6\n\n相对密度(水=1)\n0.915\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n-1.9\n\n自燃温度(℃)\n305\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2858,165,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2859,165,11,'毒理学信息','急性毒性\n\n硼酸三甲酯\n121-43-7\n\nLD\n50\n(经口)\n6140mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硼酸三甲酯\n121-43-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硼酸三甲酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2860,165,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2861,165,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2862,165,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2416\n\n联合国正确运输名称\n硼酸三甲酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2863,165,15,'法规信息','国际化学品名录\n\n硼酸三甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硼酸三甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2864,165,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2865,166,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氢\n\n产品英文名称\nhydrogen\n\n别名\n氢气\n\nCAS NO.\n1333-74-0\n\nEC NO.\n215-605-7\n\n分子式\nH2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2866,166,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n严重冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2867,166,3,'成分/组成信息','氢\n\nCas No.\n1333-74-0\n\nEC No.\n215-605-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2868,166,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2869,166,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2870,166,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2871,166,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2872,166,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2873,166,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-259.14\n\n初沸点和沸程(℃)\n-253\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：76；下限：4\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n0.07\n\n相对密度(水=1)\n0.07\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n500~571\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2874,166,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属乙炔化合物的混合物在加热时，发生燃烧或白炽化。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属乙炔化合物、卤素及卤间化合物、卤素的氧化物、硝酸、氧化氮、硝酸盐、亚硝酸盐、卤素含氧酸盐、铬酸盐、高锰酸盐、无机过氧化物、金属氧化物和过氧甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2875,166,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氢\n1333-74-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氢\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2876,166,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2877,166,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2878,166,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1049\n\n联合国正确运输名称\n压缩氢\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2879,166,15,'法规信息','国际化学品名录\n\n氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2880,166,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2881,167,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氢溴酸\n\n产品英文名称\nhydrobromic acid\n\n别名\n溴化氢溶液\n\nCAS NO.\n10035-10-6\n\nEC NO.\n233-113-0\n\n分子式\nHBr\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2882,167,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,咽喉痛，呼吸困难，气促。症状可能推迟显现。。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n与液体接触：冻伤。发红，疼痛，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2883,167,3,'成分/组成信息','氢溴酸\n\nCas No.\n10035-10-6\n\nEC No.\n233-113-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2884,167,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n冻伤时,用大量水冲洗,不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2885,167,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2886,167,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2887,167,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2888,167,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氢溴酸\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2889,167,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-88.5\n\n初沸点和沸程(℃)\n-67\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n2445kPa（20℃）\n\n蒸气密度(空气=1)\n2.8\n\n相对密度(水=1)\n1.49（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2890,167,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2891,167,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氢溴酸\n10035-10-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氢溴酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2892,167,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2893,167,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2894,167,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1788\n\n联合国正确运输名称\n氢溴酸\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:38','2025-10-21 07:50:38'),(2895,167,15,'法规信息','国际化学品名录\n\n氢溴酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氢溴酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2896,167,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:38','2025-10-21 07:50:38'),(2897,168,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氢氧化钾\n\n产品英文名称\npotassium hydroxide|caustic potash|caustic potassium\n\n别名\n苛性钾\n\nCAS NO.\n1310-58-3\n\nEC NO.\n215-181-3\n\n分子式\nKOH\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2898,168,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。呼吸短促。\n\n食入\n腹部疼痛。口腔和咽喉烧伤。咽喉和胸腔有灼烧感。恶心。呕吐。休克或虚脱。\n\n皮肤接触\n发红。疼痛。严重的皮肤烧伤。水疱。\n\n眼睛\n发红。疼痛。视力模糊。严重烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2899,168,3,'成分/组成信息','氢氧化钾\n\nCas No.\n1310-58-3\n\nEC No.\n215-181-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2900,168,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴至少15分钟。立即给予医疗护理。\n\n食入\n漱口。不要催吐。在食入后几分钟内，可饮用1小杯水。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2901,168,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2902,168,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2903,168,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2904,168,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氢氧化钾\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2905,168,9,'理化特性','外观与性状\n白色片状固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n13.5\n\n熔点/凝固点(℃)\n380\n\n初沸点和沸程(℃)\n1324\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.04（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2906,168,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与酸类、酚类、醇类接触可发生剧烈反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n酸类、酚类、醇类和硝基取代烃。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2907,168,11,'毒理学信息','急性毒性\n\n氢氧化钾\n1310-58-3\n\nLD\n50\n(经口)\n273mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氢氧化钾\n1310-58-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氢氧化钾\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2908,168,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2909,168,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2910,168,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1813\n\n联合国正确运输名称\n固态氢氧化钾\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2911,168,15,'法规信息','国际化学品名录\n\n氢氧化钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氢氧化钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2912,168,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2913,169,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氢氧化钠\n\n产品英文名称\nsodium hydroxide|caustic soda|sodium hydrate\n\n别名\n苛性钠|烧碱\n\nCAS NO.\n1310-73-2\n\nEC NO.\n215-185-5\n\n分子式\nNaOH\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2914,169,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。灼烧感。呼吸短促。\n\n食入\n腹部疼痛。口腔和咽喉烧伤。咽喉和胸腔有灼烧感。恶心。呕吐。休克或虚脱。\n\n皮肤接触\n发红。疼痛。严重的皮肤烧伤。水疱。\n\n眼睛\n发红。疼痛。视力模糊。严重烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2915,169,3,'成分/组成信息','氢氧化钠\n\nCas No.\n1310-73-2\n\nEC No.\n215-185-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2916,169,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴至少15分钟。立即给予医疗护理。\n\n食入\n漱口。不要催吐。在食入后几分钟内，可饮用1小杯水。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2917,169,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2918,169,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2919,169,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2920,169,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氢氧化钠\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2921,169,9,'理化特性','外观与性状\n白色固体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n14（50g/L，20℃）\n\n熔点/凝固点(℃)\n318\n\n初沸点和沸程(℃)\n1388\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.12（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2922,169,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与酸类、酚类、醇类接触可发生剧烈反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n酸类、酚类、醇类和硝基取代烃。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2923,169,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氢氧化钠\n1310-73-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氢氧化钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2924,169,12,'生态学信息','急性水生毒性\n\n氢氧化钠\n1310-73-2\n\n鱼类\nLC\n50\n：196mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：40.4mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2925,169,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2926,169,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1823\n\n联合国正确运输名称\n固态氢氧化钠\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2927,169,15,'法规信息','国际化学品名录\n\n氢氧化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氢氧化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2928,169,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2929,170,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化钙\n\n产品英文名称\ncalcium cyanide|calcyanide\n\n别名\n-\n\nCAS NO.\n592-01-8\n\nEC NO.\n209-740-0\n\n分子式\nC2CaN2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2930,170,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n胸闷,意识模糊,惊厥,咳嗽,头晕,头痛,呼吸困难,恶心,气促,神志不清,呕吐,虚弱,皮肤发红。\n\n食入\n灼烧感。另见吸入。\n\n皮肤接触\n可能被吸收！发红，疼痛。另见吸入。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2931,170,3,'成分/组成信息','氰化钙\n\nCas No.\n592-01-8\n\nEC No.\n209-740-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2932,170,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。给予医疗护理。急救时戴防护手套。\n\n食入\n漱口，催吐（仅对清醒病人！），给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2933,170,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2934,170,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2935,170,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2936,170,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2937,170,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n350（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.8\n\n溶解性(mg/L)\n可溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n350\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2938,170,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2939,170,11,'毒理学信息','急性毒性\n\n氰化钙\n592-01-8\n\nLD\n50\n(经口)\n39mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化钙\n592-01-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化钙\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2940,170,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2941,170,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2942,170,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1575\n\n联合国正确运输名称\n氰化钙\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2943,170,15,'法规信息','国际化学品名录\n\n氰化钙\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n未列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化钙\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2944,170,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2945,171,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化汞\n\n产品英文名称\nmercury(Ⅱ)cyanide|mercury dicyanide\n\n别名\n氰化高汞|二氰化汞\n\nCAS NO.\n592-04-1\n\nEC NO.\n209-741-6\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2946,171,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触可能会引起敏化作用。对眼睛有刺激性。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2B\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH317\n可能造成皮肤过敏反应\n\nH320\n造成眼刺激\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可导致严重的毒性反应。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。\n\n眼睛\n本品对眼睛有轻微刺激。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2947,171,3,'成分/组成信息','氰化汞\n\nCas No.\n592-04-1\n\nEC No.\n209-741-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2948,171,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2949,171,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2950,171,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2951,171,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2952,171,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n氰化汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2953,171,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n320（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.996\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n320\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2954,171,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2955,171,11,'毒理学信息','急性毒性\n\n氰化汞\n592-04-1\n\nLD\n50\n(经口)\n26mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化汞\n592-04-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化汞\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成眼刺激(类别 2B)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2956,171,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2957,171,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2958,171,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1636\n\n联合国正确运输名称\n氰化汞\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2959,171,15,'法规信息','国际化学品名录\n\n氰化汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n未列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2960,171,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2961,172,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化钾\n\n产品英文名称\npotassuim cyanide\n\n别名\n山奈钾\n\nCAS NO.\n151-50-8\n\nEC NO.\n205-792-3\n\n分子式\nKCN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2962,172,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对眼睛有严重刺激性。短期暴露有损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH319\n造成严重眼刺激\n\nH371\n可能损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,头痛,意识模糊,虚弱,气促,惊厥,神志不清。\n\n食入\n灼烧感。恶心。呕吐。腹泻。（另见吸入）。\n\n皮肤接触\n可能被吸收!发红,疼痛(另见吸入)。\n\n眼睛\n发红,疼痛(另见吸入)。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2963,172,3,'成分/组成信息','氰化钾\n\nCas No.\n151-50-8\n\nEC No.\n205-792-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2964,172,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,用大量水冲洗皮肤或淋浴,给予医疗护理。\n\n食入\n催吐(仅对清醒病人!)。催吐时戴防护手套。禁止口对口进行人工呼吸。由经过培训的人员给予吸氧。给予医疗护理。\n\n吸入\n新鲜空气,休息,禁止口对口进行人工呼吸,由经过培训的人员给予吸氧,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2965,172,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2966,172,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2967,172,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2968,172,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2969,172,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n634\n\n初沸点和沸程(℃)\n1625\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.52（16℃）\n\n溶解性(mg/L)\n可溶于水\n\n辛醇 /水分配系数\n0.44\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2970,172,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与乙炔、丙酮的混合物产生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝酸盐、亚硝酸盐、卤素的含氧酸盐、铬酸盐、镁、无机酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2971,172,11,'毒理学信息','急性毒性\n\n氰化钾\n151-50-8\n\nLD\n50\n(经口)\n5mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化钾\n151-50-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2972,172,12,'生态学信息','急性水生毒性\n\n氰化钾\n151-50-8\n\n鱼类\nLC\n50\n：0.068mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2973,172,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2974,172,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1680\n\n联合国正确运输名称\n氰化钾，固态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2975,172,15,'法规信息','国际化学品名录\n\n氰化钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2976,172,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2977,173,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化钠\n\n产品英文名称\nsodium cyanide\n\n别名\n山奈\n\nCAS NO.\n143-33-9\n\nEC NO.\n205-599-4\n\n分子式\nNaCN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2978,173,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH319\n造成严重眼刺激\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,头痛,意识模糊,虚弱,气促,惊厥,神志不清。\n\n食入\n灼烧感。恶心。呕吐。腹泻。（另见吸入）。\n\n皮肤接触\n可能被吸收！发红。疼痛。另见吸入。\n\n眼睛\n发红。疼痛。（另见吸入）。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2979,173,3,'成分/组成信息','氰化钠\n\nCas No.\n143-33-9\n\nEC No.\n205-599-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2980,173,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,用大量水冲洗皮肤或淋浴,给予医疗护理\n\n食入\n催吐(仅对清醒病人!)。催吐时戴防护手套。禁止口对口进行人工呼吸。由经过培训的人员给予吸氧。给予医疗护理。\n\n吸入\n新鲜空气，休息。禁止口对口进行人工呼吸。由经过培训的人员给予吸氧。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2981,173,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2982,173,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2983,173,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2984,173,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2985,173,9,'理化特性','外观与性状\n白色结晶颗粒或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n563.7\n\n初沸点和沸程(℃)\n1496\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.6\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2986,173,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与乙炔、丙酮的混合物产生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝酸盐、亚硝酸盐、卤素的含氧酸盐、铬酸盐、镁、无机酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2987,173,11,'毒理学信息','急性毒性\n\n氰化钠\n143-33-9\n\nLD\n50\n(经口)\n6mg/kg(大鼠)\n\nLD\n50\n(经皮)\n6mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化钠\n143-33-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2988,173,12,'生态学信息','急性水生毒性\n\n氰化钠\n143-33-9\n\n鱼类\nLC\n50\n：0.125mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2989,173,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2990,173,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1689\n\n联合国正确运输名称\n氰化钠，固态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:39','2025-10-21 07:50:39'),(2991,173,15,'法规信息','国际化学品名录\n\n氰化钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2992,173,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:39','2025-10-21 07:50:39'),(2993,174,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化氢\n\n产品英文名称\nhydrogen cyanide|hydrocyanic acid|hydrocyanic acid,anhydrous\n\n别名\n无水氢氰酸\n\nCAS NO.\n74-90-8\n\nEC NO.\n200-821-6\n\n分子式\nCHN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(2994,174,2,'危险性概述','紧急情况概述\n\n液体。极端易燃，有爆炸危险。吸入有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH224\n极易燃液体和蒸气\n\nH330\n吸入致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃液体，有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n意识模糊。倦睡。头痛。恶心。惊厥。气促。神志不清。死亡。\n\n食入\n灼烧感。（另见吸入）。\n\n皮肤接触\n可能被吸收！（另见吸入）。\n\n眼睛\n蒸气将被吸收！发红。（见吸入）。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(2995,174,3,'成分/组成信息','氰化氢\n\nCas No.\n74-90-8\n\nEC No.\n200-821-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(2996,174,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。给予医疗护理。急救时戴防护手套。\n\n食入\n漱口。不要催吐。禁止口对口进行人工呼吸。由经过培训的人员给予吸氧。给予医疗护理。。\n\n吸入\n新鲜空气,休息。半直立体位。禁止口对口进行人工呼吸。由经过培训的人员给予吸氧。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(2997,174,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(2998,174,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(2999,174,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3000,174,8,'接触控制/个体防护','控制参数->职业接触限值\n\n氰化氢\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3001,174,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-13\n\n初沸点和沸程(℃)\n26\n\n闪点(闭杯，℃)\n-18\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：40；下限：5.6\n\n蒸气压\n82.6kPa（20℃）\n\n蒸气密度(空气=1)\n0.94\n\n相对密度(水=1)\n0.688（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.25\n\n自燃温度(℃)\n538\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3002,174,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与碱、金属、氧化剂、金属氧化物和金属硝酸盐接触会着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、碱、氧化剂、金属氧化物和金属硝酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3003,174,11,'毒理学信息','急性毒性\n\n氰化氢\n74-90-8\n\nLD\n50\n(经口)\n3.7mg/kg(小鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化氢\n74-90-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化氢\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3004,174,12,'生态学信息','急性水生毒性\n\n氰化氢\n74-90-8\n\n鱼类\nLC\n50\n：0.0925mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3005,174,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3006,174,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1051\n\n联合国正确运输名称\n氰化氢，稳定的，含水少于3%\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n3\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3007,174,15,'法规信息','国际化学品名录\n\n氰化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3008,174,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3009,175,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化锌\n\n产品英文名称\nzinc cyanide\n\n别名\n-\n\nCAS NO.\n557-21-1\n\nEC NO.\n209-162-9\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3010,175,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3011,175,3,'成分/组成信息','氰化锌\n\nCas No.\n557-21-1\n\nEC No.\n209-162-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3012,175,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3013,175,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3014,175,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3015,175,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3016,175,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3017,175,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n800\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.85\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3018,175,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与乙炔、丙酮的混合物产生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n硝酸盐、亚硝酸盐、卤素的含氧酸盐、铬酸盐、镁、无机酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3019,175,11,'毒理学信息','急性毒性\n\n氰化锌\n557-21-1\n\nLD\n50\n(经口)\n54mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化锌\n557-21-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化锌\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3020,175,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3021,175,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3022,175,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1713\n\n联合国正确运输名称\n氰化锌\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3023,175,15,'法规信息','国际化学品名录\n\n氰化锌\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化锌\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3024,175,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3025,176,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化溴\n\n产品英文名称\ncyanogen bromide|bromine cyanide\n\n别名\n溴化氰\n\nCAS NO.\n506-68-3\n\nEC NO.\n208-051-2\n\n分子式\nCBrN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3026,176,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感，惊厥，头晕，头痛，气促，呼吸困难，恶心，神志不清，呕吐。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n可能被吸收！发红，疼痛，水疱。（另见吸入）。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3027,176,3,'成分/组成信息','氰化溴\n\nCas No.\n506-68-3\n\nEC No.\n208-051-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3028,176,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n给予医疗护理。漱口，催吐（仅对清醒病人！）。\n\n吸入\n新鲜空气，休息。半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3029,176,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3030,176,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3031,176,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3032,176,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3033,176,9,'理化特性','外观与性状\n白色结晶固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n52\n\n初沸点和沸程(℃)\n61~62\n\n闪点(闭杯，℃)\n65\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n16.2kPa\n\n蒸气密度(空气=1)\n3.6\n\n相对密度(水=1)\n2.015\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3034,176,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3035,176,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氰化溴\n506-68-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化溴\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3036,176,12,'生态学信息','急性水生毒性\n\n氰化溴\n506-68-3\n\n鱼类\nLC\n50\n：0.355mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3037,176,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3038,176,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1889\n\n联合国正确运输名称\n溴化氰\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3039,176,15,'法规信息','国际化学品名录\n\n氰化溴\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化溴\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3040,176,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3041,177,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化亚铜\n\n产品英文名称\ncuprous cyanide\n\n别名\n-\n\nCAS NO.\n544-92-3\n\nEC NO.\n208-883-6\n\n分子式\nCuCN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3042,177,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。跟皮肤接触可能会引起敏化作用。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤致敏物\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH317\n可能造成皮肤过敏反应\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3043,177,3,'成分/组成信息','氰化亚铜\n\nCas No.\n544-92-3\n\nEC No.\n208-883-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3044,177,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3045,177,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3046,177,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3047,177,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3048,177,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3049,177,9,'理化特性','外观与性状\n黄色至绿色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n475\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.92\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3050,177,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3051,177,11,'毒理学信息','急性毒性\n\n氰化亚铜\n544-92-3\n\nLD\n50\n(经口)\n1265mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化亚铜\n544-92-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化亚铜\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3052,177,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3053,177,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3054,177,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1587\n\n联合国正确运输名称\n氰化铜\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3055,177,15,'法规信息','国际化学品名录\n\n氰化亚铜\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化亚铜\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3056,177,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3057,178,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化银\n\n产品英文名称\nsilver cyanide\n\n别名\n-\n\nCAS NO.\n506-64-9\n\nEC NO.\n208-048-6\n\n分子式\nAgCN\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3058,178,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。有严重损害眼睛的危险。长期暴露有损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH318\n造成严重眼损伤\n\nH373\n长期或反复接触可能损害器官\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能引起毒害作用。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3059,178,3,'成分/组成信息','氰化银\n\nCas No.\n506-64-9\n\nEC No.\n208-048-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3060,178,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3061,178,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3062,178,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3063,178,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3064,178,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3065,178,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n300\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.95\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n320\n\n黏度\n不适用',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3066,178,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3067,178,11,'毒理学信息','急性毒性\n\n氰化银\n506-64-9\n\nLD\n50\n(经口)\n123mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化银\n506-64-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化银\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3068,178,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3069,178,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3070,178,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1684\n\n联合国正确运输名称\n氰化银\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3071,178,15,'法规信息','国际化学品名录\n\n氰化银\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化银\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3072,178,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3073,179,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰化银钾\n\n产品英文名称\npotassium silver cyanide|potassium cyanoargenate\n\n别名\n银氰化钾\n\nCAS NO.\n506-61-6\n\nEC NO.\n208-047-0\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3074,179,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 1\n\n急性吸入毒性\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH330\n吸入致命\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n在正常生产处理过程中，吸入本品在正常操作过程中产生的粉尘或烟雾能导致严重的毒害作用，甚至可致命。\n\n食入\n意外食入本品可导致严重的毒性反应。\n\n皮肤接触\n皮肤接触可产生严重毒害作用，吸收后可产生全身影响，并可致命。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3075,179,3,'成分/组成信息','氰化银钾\n\nCas No.\n506-61-6\n\nEC No.\n208-047-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3076,179,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3077,179,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3078,179,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3079,179,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3080,179,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3081,179,9,'理化特性','外观与性状\n白色晶体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.45\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3082,179,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3083,179,11,'毒理学信息','急性毒性\n\n氰化银钾\n506-61-6\n\nLD\n50\n(经口)\n20.9mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氰化银钾\n506-61-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰化银钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3084,179,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3085,179,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3086,179,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1588\n\n联合国正确运输名称\n固态无机氰化物, 未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:40','2025-10-21 07:50:40'),(3087,179,15,'法规信息','国际化学品名录\n\n氰化银钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰化银钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3088,179,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:40','2025-10-21 07:50:40'),(3089,180,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氰基乙酸乙酯\n\n产品英文名称\nethyl cyanoacetate|ethyl cyanoethanoate|cyanoacetic acid ethyl ester\n\n别名\n氰基醋酸乙酯|乙基氰基乙酸酯\n\nCAS NO.\n105-56-6\n\nEC NO.\n203-309-0\n\n分子式\nC5H7NO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3090,180,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触可造成皮肤刺激。\n\n眼睛\n本品能造成严重眼刺激。眼睛直接接触可能会造成严重的炎症并伴随有疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3091,180,3,'成分/组成信息','氰基乙酸乙酯\n\nCas No.\n105-56-6\n\nEC No.\n203-309-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3092,180,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3093,180,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3094,180,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3095,180,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3096,180,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3097,180,9,'理化特性','外观与性状\n无色或黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-22\n\n初沸点和沸程(℃)\n206\n\n闪点(闭杯，℃)\n110\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（67.8℃）\n\n蒸气密度(空气=1)\n3.9\n\n相对密度(水=1)\n1.056（25℃）\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n555\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3098,180,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3099,180,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氰基乙酸乙酯\n105-56-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氰基乙酸乙酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3100,180,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n氰基乙酸乙酯：水/土壤-低 空气-低\n\n生物富集或生物积累性\n氰基乙酸乙酯：生物富集性-低（LogKOW=0.0162）\n\n土壤中的迁移性\n氰基乙酸乙酯：土壤迁移性-低（koc=4.141）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3101,180,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3102,180,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3103,180,15,'法规信息','国际化学品名录\n\n氰基乙酸乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氰基乙酸乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3104,180,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3105,181,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氟化氮\n\n产品英文名称\nnitrogen trifluoride\n\n别名\n-\n\nCAS NO.\n7783-54-2\n\nEC NO.\n232-007-1\n\n分子式\nF3N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3106,181,2,'危险性概述','紧急情况概述\n\n气体。跟可燃物质接触可能会引起火灾。高压，遇热有爆炸危险。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n氧化性气体\n类别 1\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH270\n可能导致或加剧燃烧；氧化剂\n\nH280\n内装高压气体；遇热可能爆炸\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP244\n阀门或紧固装置不得带有油脂或油剂。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP370+P376\n火灾时：如能保证安全，设法堵塞泄漏。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3107,181,3,'成分/组成信息','三氟化氮\n\nCas No.\n7783-54-2\n\nEC No.\n232-007-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3108,181,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3109,181,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						不燃烧，但会增强火势。\n4\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n5\r\n						.\r\n						因释放氧气有助燃效果。\n6\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n7\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n8\r\n						.\r\n						加热时，容器可能爆炸。\n9\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3110,181,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3111,181,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3112,181,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氟化氮\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n三氟化氮\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3113,181,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-208.5\n\n初沸点和沸程(℃)\n-129\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n＞101.35kPa\n\n蒸气密度(空气=1)\n2.46\n\n相对密度(水=1)\n1.885\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3114,181,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与空气或可燃性物质接触会爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n可燃性物质和有机易燃物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3115,181,11,'毒理学信息','急性毒性\n\n三氟化氮\n7783-54-2\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n三氟化氮\n7783-54-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氟化氮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3116,181,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n三氟化氮：水/土壤-低 空气-低\n\n生物富集或生物积累性\n三氟化氮：生物富集性-低（LogKOW=-1.603）\n\n土壤中的迁移性\n三氟化氮：土壤迁移性-低（koc=35.04）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3117,181,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3118,181,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2451\n\n联合国正确运输名称\n三氟化氮\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n5.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3119,181,15,'法规信息','国际化学品名录\n\n三氟化氮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n三氟化氮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3120,181,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3121,182,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氟化硼\n\n产品英文名称\nboron trifluoride|boron fluoride\n\n别名\n氟化硼\n\nCAS NO.\n7637-07-2\n\nEC NO.\n231-569-5\n\n分子式\nBF3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3122,182,2,'危险性概述','紧急情况概述\n\n液体。高压，遇热有爆炸危险。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，呼吸困难。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。灼烧感，疼痛。与液体接触会引起冻伤。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3123,182,3,'成分/组成信息','三氟化硼\n\nCas No.\n7637-07-2\n\nEC No.\n231-569-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3124,182,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。立即给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3125,182,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3126,182,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3127,182,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3128,182,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氟化硼\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n三氟化硼\nGBZ 2.1-2019\n\n生物检测指标\n尿中氟\n\n生物限值\n42 mmol/mol Cr（7 mg/g Cr）\n\n采样时间\n工作班后\n\n备注\n无\n\n生物检测指标\n尿中氟\n\n生物限值\n24 mmol/mol Cr（4 mg/g Cr）\n\n采样时间\n工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3129,182,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n无资料\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3130,182,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3131,182,11,'毒理学信息','急性毒性\n\n三氟化硼\n7637-07-2\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n三氟化硼\n7637-07-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氟化硼\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3132,182,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3133,182,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3134,182,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1008\n\n联合国正确运输名称\n三氟化硼\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3135,182,15,'法规信息','国际化学品名录\n\n三氟化硼\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氟化硼\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3136,182,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3137,183,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氟甲烷\n\n产品英文名称\ntrifluoromethane|freon 23|fluoroporm\n\n别名\nR23|氟仿\n\nCAS NO.\n75-46-7\n\nEC NO.\n200-872-4\n\n分子式\nCHF3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3138,183,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n意识模糊，瞌睡。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触时，可能冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3139,183,3,'成分/组成信息','三氟甲烷\n\nCas No.\n75-46-7\n\nEC No.\n200-872-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3140,183,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时：用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3141,183,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3142,183,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3143,183,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3144,183,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氟甲烷\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3145,183,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-155\n\n初沸点和沸程(℃)\n-84.4\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n4000kPa\n\n蒸气密度(空气=1)\n2.4\n\n相对密度(水=1)\n1.52\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n0.64\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3146,183,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3147,183,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n三氟甲烷\n75-46-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氟甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3148,183,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3149,183,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3150,183,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1984\n\n联合国正确运输名称\n三氟甲烷\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3151,183,15,'法规信息','国际化学品名录\n\n三氟甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氟甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3152,183,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3153,184,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氟氯乙烯[稳定的]\n\n产品英文名称\ntrifluorochloroethylene,stabilized|freon 1113|chlorotrifluoroethylene\n\n别名\nR1113|氯三氟乙烯\n\nCAS NO.\n79-38-9\n\nEC NO.\n201-201-8\n\n分子式\nC2ClF3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3154,184,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。吸入有毒。短期暴露有损伤健康的危险。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-一次接触\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH331\n吸入会中毒\n\nH371\n可能损害器官\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕，恶心。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3155,184,3,'成分/组成信息','三氟氯乙烯\n\nCas No.\n79-38-9\n\nEC No.\n201-201-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3156,184,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3157,184,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3158,184,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3159,184,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3160,184,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氟氯乙烯\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3161,184,9,'理化特性','外观与性状\n无色气体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-158\n\n初沸点和沸程(℃)\n-28\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：40.3；下限：24\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3162,184,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3163,184,11,'毒理学信息','急性毒性\n\n三氟氯乙烯\n79-38-9\n\nLD\n50\n(经口)\n268mg/kg(小鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n268mg/kg(小鼠)\n\n致癌性\n\n三氟氯乙烯\n79-38-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氟氯乙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3164,184,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3165,184,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3166,184,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1082\n\n联合国正确运输名称\n三氟氯乙烯，稳定的\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3167,184,15,'法规信息','国际化学品名录\n\n三氟氯乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氟氯乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3168,184,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3169,185,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三甲胺[无水]\n\n产品英文名称\ntri-methylamine,anhydrous\n\n别名\n-\n\nCAS NO.\n75-50-3\n\nEC NO.\n200-875-0\n\n分子式\nC3H9N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3170,185,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。对皮肤有刺激性。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH315\n造成皮肤刺激\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,头痛,咽喉痛,呼吸困难,气促,症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3171,185,3,'成分/组成信息','三甲胺\n\nCas No.\n75-50-3\n\nEC No.\n200-875-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3172,185,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3173,185,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3174,185,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3175,185,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3176,185,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3177,185,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-117\n\n初沸点和沸程(℃)\n3\n\n闪点(闭杯，℃)\n-6.7\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11.6；下限：2\n\n蒸气压\n187kPa\n\n蒸气密度(空气=1)\n2\n\n相对密度(水=1)\n0.636\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.2\n\n自燃温度(℃)\n190\n\n分解温度(℃)\n400（计算值）\n\n黏度\n不适用',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3178,185,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3179,185,11,'毒理学信息','急性毒性\n\n三甲胺\n75-50-3\n\nLD\n50\n(经口)\n500mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三甲胺\n75-50-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三甲胺\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3180,185,12,'生态学信息','急性水生毒性\n\n三甲胺\n75-50-3\n\n鱼类\nLC\n50\n：>100mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：28mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>100mg/L (72h)(藻类)\n\n慢性水生毒性\n\n三甲胺\n75-50-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：8.0mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：56mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3181,185,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3182,185,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1083\n\n联合国正确运输名称\n无水三甲胺\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:41','2025-10-21 07:50:41'),(3183,185,15,'法规信息','国际化学品名录\n\n三甲胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三甲胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3184,185,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:41','2025-10-21 07:50:41'),(3185,186,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯化磷\n\n产品英文名称\nphosphorus trichloride|phosphorus(Ⅲ)chloride|trichlorophosphine\n\n别名\n氯化磷,氯化亚磷\n\nCAS NO.\n7719-12-2\n\nEC NO.\n231-749-3\n\n分子式\nPCl3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3186,186,2,'危险性概述','紧急情况概述\n\n液体。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，气促，咽喉疼痛，呕吐，恶心，呼吸困难。症状可能推迟显现。。\n\n食入\n灼烧感，腹痛，休克或虚脱。（另见吸入）。\n\n皮肤接触\n发红，疼痛，水疱，皮肤烧伤。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤，视力丧失，流泪。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3187,186,3,'成分/组成信息','三氯化磷\n\nCas No.\n7719-12-2\n\nEC No.\n231-749-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3188,186,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3189,186,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、干砂、二氧化碳。\n\n不适合的灭火介质\n水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3190,186,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3191,186,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于75%。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3192,186,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氯化磷\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3193,186,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n-112\n\n初沸点和沸程(℃)\n76\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n13.3kPa（21℃）\n\n蒸气密度(空气=1)\n4.75\n\n相对密度(水=1)\n1.6\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3194,186,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3195,186,11,'毒理学信息','急性毒性\n\n三氯化磷\n7719-12-2\n\nLD\n50\n(经口)\n18mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n18mg/kg(大鼠)\n\n致癌性\n\n三氯化磷\n7719-12-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯化磷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3196,186,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3197,186,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3198,186,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1809\n\n联合国正确运输名称\n三氯化磷\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3199,186,15,'法规信息','国际化学品名录\n\n三氯化磷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯化磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3200,186,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3201,187,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯化硼\n\n产品英文名称\nboron trichloride\n\n别名\n-\n\nCAS NO.\n10294-34-5\n\nEC NO.\n233-658-4\n\n分子式\nBCl3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3202,187,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咽喉疼痛，灼烧感，咳嗽，呼吸困难，气促。症状可能推迟显现。。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n发红，皮肤烧伤，灼烧感，疼痛，水疱。与液体接触：冻伤。\n\n眼睛\n疼痛，发红，严重深度烧伤，视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3203,187,3,'成分/组成信息','三氯化硼\n\nCas No.\n10294-34-5\n\nEC No.\n233-658-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3204,187,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3205,187,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3206,187,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3207,187,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3208,187,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3209,187,9,'理化特性','外观与性状\n无色发烟液体或气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-107\n\n初沸点和沸程(℃)\n12.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3210,187,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3211,187,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n三氯化硼\n10294-34-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯化硼\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3212,187,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3213,187,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3214,187,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1741\n\n联合国正确运输名称\n三氯化硼\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n8\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3215,187,15,'法规信息','国际化学品名录\n\n三氯化硼\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯化硼\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3216,187,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3217,188,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯化铁溶液\n\n产品英文名称\nferric trichloride,solution|ferric chloride solution\n\n别名\n氯化铁溶液\n\nCAS NO.\n7705-08-0\n\nEC NO.\n231-729-4\n\n分子式\nFeCl3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3218,188,2,'危险性概述','紧急情况概述\n\n液体。有严重损害眼睛的危险。短期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH371\n可能损害器官\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n腹部疼痛。呕吐。腹泻。休克或虚脱。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3219,188,3,'成分/组成信息','三氯化铁\n\nCas No.\n7705-08-0\n\nEC No.\n231-729-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3220,188,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3221,188,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3222,188,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3223,188,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3224,188,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3225,188,9,'理化特性','外观与性状\n黑色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n1~2\n\n熔点/凝固点(℃)\n37\n\n初沸点和沸程(℃)\n315\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.13kPa（194℃）\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n2.9（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞200\n\n黏度\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3226,188,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属的混合物对机械振动非常敏感，会发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、硝酸酯、环氧化合物、烯烃和硝基化合物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3227,188,11,'毒理学信息','急性毒性\n\n三氯化铁\n7705-08-0\n\nLD\n50\n(经口)\n450mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三氯化铁\n7705-08-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯化铁\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3228,188,12,'生态学信息','急性水生毒性\n\n三氯化铁\n7705-08-0\n\n鱼类\nLC\n50\n：21mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3229,188,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3230,188,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2582\n\n联合国正确运输名称\n氯化铁溶液\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3231,188,15,'法规信息','国际化学品名录\n\n三氯化铁\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯化铁\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3232,188,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3233,189,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯甲烷\n\n产品英文名称\ntrichloromethane|chloroform\n\n别名\n氯仿\n\nCAS NO.\n67-66-3\n\nEC NO.\n200-663-8\n\n分子式\nCHCl3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3234,189,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。有轻微致癌性风险。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 3\n\n致癌性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH331\n吸入会中毒\n\nH351\n怀疑致癌\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，倦睡，头痛，恶心，神志不清。\n\n食入\n腹部疼痛，呕吐（另见吸入）。\n\n皮肤接触\n发红，疼痛，皮肤干燥。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3235,189,3,'成分/组成信息','三氯甲烷\n\nCas No.\n67-66-3\n\nEC No.\n200-663-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3236,189,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，大量饮水。休息，给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3237,189,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3238,189,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3239,189,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3240,189,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氯甲烷\nGBZ 2.1-2007\n\nPC-TWA\n20 mg/m3\n\nPC-STEL\n-\n\n备注\nG2B\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3241,189,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-64\n\n初沸点和沸程(℃)\n62\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n21.2kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.12\n\n相对密度(水=1)\n1.489（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.97\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3242,189,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3243,189,11,'毒理学信息','急性毒性\n\n三氯甲烷\n67-66-3\n\nLD\n50\n(经口)\n695mg/kg(大鼠)\n\nLD\n50\n(经皮)\n695mg/kg(大鼠)\n\nLD\n50\n(吸入)\n695mg/kg(大鼠)\n\n致癌性\n\n三氯甲烷\n67-66-3\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯甲烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3244,189,12,'生态学信息','急性水生毒性\n\n三氯甲烷\n67-66-3\n\n鱼类\nLC\n50\n：28mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3245,189,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3246,189,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1888\n\n联合国正确运输名称\n氯仿(三氯甲烷)\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3247,189,15,'法规信息','国际化学品名录\n\n三氯甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3248,189,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3249,190,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯氧磷\n\n产品英文名称\nphosphoryl trichloride|phosphorus oxytrichloride|phosphoryl chloride|phosphorus oxide trichloride|trichlorophosphorus oxide\n\n别名\n氧氯化磷|氯化磷酰|磷酰氯|三氯化磷酰|磷酰三氯\n\nCAS NO.\n10025-87-3\n\nEC NO.\n233-046-7\n\n分子式\nCl3OP\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3250,190,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。吸入有剧毒。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感，头晕,头痛,神志不清，恶心,呼吸困难,呕吐，虚弱,气促。症状可能推迟显现。。\n\n食入\n灼烧感,腹痛,休克或虚脱。(另见吸入)。\n\n皮肤接触\n发红，皮肤烧伤，疼痛，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤，视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3251,190,3,'成分/组成信息','三氯氧磷\n\nCas No.\n10025-87-3\n\nEC No.\n233-046-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3252,190,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，并给予医疗护理。\n\n食入\n漱口，不要催吐，并给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3253,190,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3254,190,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3255,190,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于75%。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3256,190,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氯氧磷\nGBZ 2.1-2007\n\nPC-TWA\n0.3 mg/m3\n\nPC-STEL\n0.6 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3257,190,9,'理化特性','外观与性状\n无色至淡黄色油性液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜7（酸性）\n\n熔点/凝固点(℃)\n1.25\n\n初沸点和沸程(℃)\n105.8\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n5.3kPa（27.3℃）\n\n蒸气密度(空气=1)\n5.3\n\n相对密度(水=1)\n1.645\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3258,190,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属接触会引起燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属、活泼金属、易燃有机物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3259,190,11,'毒理学信息','急性毒性\n\n三氯氧磷\n10025-87-3\n\nLD\n50\n(经口)\n36mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n36mg/kg(大鼠)\n\n致癌性\n\n三氯氧磷\n10025-87-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯氧磷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3260,190,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3261,190,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3262,190,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1810\n\n联合国正确运输名称\n三氯氧化磷(磷酰氯)\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n8\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:42','2025-10-21 07:50:42'),(3263,190,15,'法规信息','国际化学品名录\n\n三氯氧磷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯氧磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3264,190,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:42','2025-10-21 07:50:42'),(3265,191,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氯乙烯\n\n产品英文名称\ntrichloroethylene|trichloroethene\n\n别名\n-\n\nCAS NO.\n79-01-6\n\nEC NO.\n201-167-4\n\n分子式\nC2HCl3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3266,191,2,'危险性概述','紧急情况概述\n\n液体。对皮肤有刺激性。对眼睛有严重刺激性。气体可能会引起头晕或窒息。可能有发生不可逆性作用的危险。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 1B\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH341\n怀疑可造成遗传性缺陷\n\nH350\n可能致癌\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n头晕。倦睡。头痛。虚弱。恶心。神志不清。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n皮肤干燥。发红。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3267,191,3,'成分/组成信息','三氯乙烯\n\nCas No.\n79-01-6\n\nEC No.\n201-167-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3268,191,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。饮用1或2杯水。休息。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3269,191,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3270,191,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3271,191,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3272,191,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氯乙烯\nGBZ 2.1-2007\n\nPC-TWA\n30 mg/m3\n\nPC-STEL\n-\n\n备注\nG1，敏\n\n控制参数->生物限值\n\n三氯乙烯\nGBZ 2.1-2019\n\n生物检测指标\n尿中三氯乙酸\n\n生物限值\n0.3 mmol/L（50 mg/L）\n\n采样时间\n工作周末的班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3273,191,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-73\n\n初沸点和沸程(℃)\n87\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：10.5；下限：8\n\n蒸气压\n7.8kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.5\n\n相对密度(水=1)\n1.5\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.42\n\n自燃温度(℃)\n410\n\n分解温度(℃)\n≥110\n\n黏度\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3274,191,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3275,191,11,'毒理学信息','急性毒性\n\n三氯乙烯\n79-01-6\n\nLD\n50\n(经口)\n4920mg/kg(大鼠)\n\nLD\n50\n(经皮)\n4920mg/kg(大鼠)\n\nLD\n50\n(吸入)\n4920mg/kg(大鼠)\n\n致癌性\n\n三氯乙烯\n79-01-6\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氯乙烯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3276,191,12,'生态学信息','急性水生毒性\n\n三氯乙烯\n79-01-6\n\n鱼类\nLC\n50\n：38mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：11mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：77mg/L (72h)(藻类)\n\n慢性水生毒性\n\n三氯乙烯\n79-01-6\n\n鱼类\nNOEC：2.7mg/L(鱼)\n\n甲壳纲动物\nNOEC：2.1mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：45mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3277,191,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3278,191,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1710\n\n联合国正确运输名称\n三氯乙烯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3279,191,15,'法规信息','国际化学品名录\n\n三氯乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氯乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3280,191,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3281,192,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三溴化磷\n\n产品英文名称\nphosphorus tribromide\n\n别名\n-\n\nCAS NO.\n7789-60-8\n\nEC NO.\n232-178-2\n\n分子式\nBr3P\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3282,192,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3283,192,3,'成分/组成信息','三溴化磷\n\nCas No.\n7789-60-8\n\nEC No.\n232-178-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3284,192,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3285,192,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、干砂、二氧化碳。\n\n不适合的灭火介质\n水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3286,192,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3287,192,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3288,192,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3289,192,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-40\n\n初沸点和沸程(℃)\n175\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n0.65kPa（20℃）\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n2.85\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3290,192,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3291,192,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n三溴化磷\n7789-60-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三溴化磷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3292,192,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3293,192,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3294,192,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1808\n\n联合国正确运输名称\n三溴化磷\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3295,192,15,'法规信息','国际化学品名录\n\n三溴化磷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三溴化磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3296,192,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3297,193,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三亚乙基四胺\n\n产品英文名称\n3,6-diazaoctanethylenediamin|triethylenetetramine|bis(2-amino-ethyl)ethylene diamine\n\n别名\n二缩三乙二胺|三乙撑四胺\n\nCAS NO.\n112-24-3\n\nEC NO.\n203-950-6\n\n分子式\nC6H18N4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3298,193,2,'危险性概述','紧急情况概述\n\n液体。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。对水生环境可能会引起长期有害作用。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n对水生环境的危害-长期危害\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH412\n对水生生物有害并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛。咳嗽。灼烧感。呼吸困难。呼吸短促。\n\n食入\n口腔和咽喉烧伤。咽喉和胸腔有灼烧感。腹部疼痛。休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。水疱。\n\n眼睛\n发红。疼痛。视力丧失。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物有害并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3299,193,3,'成分/组成信息','三亚乙基四胺\n\nCas No.\n112-24-3\n\nEC No.\n203-950-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3300,193,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n先用大量水冲洗至少15分钟，然后脱去污染的衣服并再次冲洗。立即给予医疗护理。\n\n食入\n漱口。不要催吐。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3301,193,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3302,193,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3303,193,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3304,193,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3305,193,9,'理化特性','外观与性状\n淡黄色油性液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n10\n\n熔点/凝固点(℃)\n-35\n\n初沸点和沸程(℃)\n277\n\n闪点(闭杯，℃)\n135\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：6.5；下限：1.1\n\n蒸气压\n1.3Pa（20℃ ）\n\n蒸气密度(空气=1)\n5.04\n\n相对密度(水=1)\n0.98\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-1.4~-1.66\n\n自燃温度(℃)\n335\n\n分解温度(℃)\n277\n\n黏度\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3306,193,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3307,193,11,'毒理学信息','急性毒性\n\n三亚乙基四胺\n112-24-3\n\nLD\n50\n(经口)\n2500mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2500mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三亚乙基四胺\n112-24-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三亚乙基四胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3308,193,12,'生态学信息','急性水生毒性\n\n三亚乙基四胺\n112-24-3\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：3.7mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3309,193,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3310,193,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2259\n\n联合国正确运输名称\n三亚乙基四胺\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3311,193,15,'法规信息','国际化学品名录\n\n三亚乙基四胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三亚乙基四胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3312,193,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3313,194,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氧化二砷\n\n产品英文名称\ndiarsenic trioxide|arsenic trioxide|white arsenic|arsenous acid anhydride|arsenic sesquioxide\n\n别名\n白砒|砒霜|亚砷酸酐\n\nCAS NO.\n1327-53-3\n\nEC NO.\n215-481-4\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3314,194,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n致癌性\n类别 1A\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH350\n可能致癌\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,气促，喘息,头晕,头痛,虚弱,咽喉痛。症状可能推迟显现。。(见食入)。\n\n食入\n灼烧感，恶心，腹部疼痛，腹泻，呕吐，胃痉挛，肌肉震颤，休克，死亡。\n\n皮肤接触\n发红，疼痛，皮肤干燥，皮肤烧伤，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤，结膜炎。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3315,194,3,'成分/组成信息','三氧化二砷\n\nCas No.\n1327-53-3\n\nEC No.\n215-481-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3316,194,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂冲洗皮肤，给予医疗护理。\n\n食入\n漱口，催吐(仅对清醒病人！)，休息并给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3317,194,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3318,194,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3319,194,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3320,194,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氧化二砷\nGBZ 2.1-2007\n\nPC-TWA\n0.01 mg/m3\n\nPC-STEL\n0.02 mg/m3\n\n备注\nG1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3321,194,9,'理化特性','外观与性状\n白色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n275~313\n\n初沸点和沸程(℃)\n465\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.7~4.2\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3322,194,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3323,194,11,'毒理学信息','急性毒性\n\n三氧化二砷\n1327-53-3\n\nLD\n50\n(经口)\n14.6mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三氧化二砷\n1327-53-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氧化二砷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3324,194,12,'生态学信息','急性水生毒性\n\n三氧化二砷\n1327-53-3\n\n鱼类\nLC\n50\n：20.2mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3325,194,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3326,194,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1561\n\n联合国正确运输名称\n三氧化二砷\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3327,194,15,'法规信息','国际化学品名录\n\n三氧化二砷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氧化二砷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3328,194,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3329,195,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三氧化铬[无水]\n\n产品英文名称\nchromium(Ⅵ)trioxide|chromic anhydride\n\n别名\n铬酸酐\n\nCAS NO.\n1333-82-0\n\nEC NO.\n215-607-8\n\n分子式\nCrO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3330,195,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触容易引起火灾。吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有剧毒。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 1\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH271\n可能引起燃烧或爆炸；强氧化剂\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP283\n穿防火/阻燃服装。\n\nP284\n戴呼吸防护装置。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触容易引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽。呼吸困难。气促。咽喉痛。喘息。灼烧感。症状可能推迟显现。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。\n\n眼睛\n发红。疼痛。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3331,195,3,'成分/组成信息','三氧化铬\n\nCas No.\n1333-82-0\n\nEC No.\n215-607-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3332,195,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3333,195,5,'消防措施','灭火介质\n\n适合的灭火介质\n水。\n\n不适合的灭火介质\n干粉、二氧化碳或泡沫。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3334,195,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3335,195,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3336,195,8,'接触控制/个体防护','控制参数->职业接触限值\n\n三氧化铬\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n-\n\n备注\nG1；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3337,195,9,'理化特性','外观与性状\n暗红色晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜=2（强酸）（10%溶液）\n\n熔点/凝固点(℃)\n197\n\n初沸点和沸程(℃)\n250（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.7\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n250\n\n黏度\n不适用',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3338,195,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3339,195,11,'毒理学信息','急性毒性\n\n三氧化铬\n1333-82-0\n\nLD\n50\n(经口)\n80mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三氧化铬\n1333-82-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三氧化铬\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3340,195,12,'生态学信息','急性水生毒性\n\n三氧化铬\n1333-82-0\n\n鱼类\nLC\n50\n：49mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3341,195,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3342,195,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1463\n\n联合国正确运输名称\n无水三氧化铬\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n6.1+8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3343,195,15,'法规信息','国际化学品名录\n\n三氧化铬\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三氧化铬\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3344,195,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3345,196,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三乙胺\n\n产品英文名称\ntriethylamine\n\n别名\n-\n\nCAS NO.\n121-44-8\n\nEC NO.\n204-469-4\n\n分子式\nC6H15N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3346,196,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,气促,呼吸困难,头痛,头晕,虚弱,恶心,症状可能推迟显现。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。\n\n眼睛\n疼痛。发红。视力模糊。青眼晕。暂时失明。严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3347,196,3,'成分/组成信息','三乙胺\n\nCas No.\n121-44-8\n\nEC No.\n204-469-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3348,196,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3349,196,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3350,196,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3351,196,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3352,196,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3353,196,9,'理化特性','外观与性状\n无色至微黄色油状液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n12.7（15℃，100g/L）\n\n熔点/凝固点(℃)\n-115\n\n初沸点和沸程(℃)\n89\n\n闪点(闭杯，℃)\n-17\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8；下限：1.2\n\n蒸气压\n7.2kPa（20℃）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n0.7\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n1.45\n\n自燃温度(℃)\n230\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3354,196,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3355,196,11,'毒理学信息','急性毒性\n\n三乙胺\n121-44-8\n\nLD\n50\n(经口)\n460mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三乙胺\n121-44-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三乙胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3356,196,12,'生态学信息','急性水生毒性\n\n三乙胺\n121-44-8\n\n鱼类\nLC\n50\n：24mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：34mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：8.0mg/L (72h)(藻类)\n\n慢性水生毒性\n\n三乙胺\n121-44-8\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：11mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：1.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3357,196,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3358,196,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1296\n\n联合国正确运输名称\n三乙胺\n\n运输主要危险类别\n3\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:43','2025-10-21 07:50:43'),(3359,196,15,'法规信息','国际化学品名录\n\n三乙胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三乙胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3360,196,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:43','2025-10-21 07:50:43'),(3361,197,1,'化学品及企业标识','产品标识\n\n产品中文名称\n三正丁胺\n\n产品英文名称\ntributylamine\n\n别名\n三丁胺\n\nCAS NO.\n102-82-9\n\nEC NO.\n203-058-7\n\n分子式\nC12H27N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3362,197,2,'危险性概述','紧急情况概述\n\n液体。跟皮肤接触有剧毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有剧毒。对呼吸道有刺激作用。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH330\n吸入致命\n\nH335\n可能造成呼吸道刺激\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。在正常生产处理过程中，吸入本品的蒸气或气溶胶(雾、烟)可产生严重毒害作用，甚至可致命。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3363,197,3,'成分/组成信息','三正丁胺\n\nCas No.\n102-82-9\n\nEC No.\n203-058-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3364,197,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3365,197,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3366,197,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3367,197,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3368,197,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3369,197,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-70\n\n初沸点和沸程(℃)\n216~217\n\n闪点(闭杯，℃)\n63\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：6；下限：1.4\n\n蒸气压\n40～93Pa（20℃）\n\n蒸气密度(空气=1)\n6.4\n\n相对密度(水=1)\n0.78\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n1.52\n\n自燃温度(℃)\n210\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3370,197,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3371,197,11,'毒理学信息','急性毒性\n\n三正丁胺\n102-82-9\n\nLD\n50\n(经口)\n114mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n三正丁胺\n102-82-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n三正丁胺\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3372,197,12,'生态学信息','急性水生毒性\n\n三正丁胺\n102-82-9\n\n鱼类\n无资料\n\n甲壳纲动物\nEC\n50\n：8mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n三正丁胺：水/土壤-低 空气-低\n\n生物富集或生物积累性\n三正丁胺：生物富集性-中等（LogKOW=1.52）\n\n土壤中的迁移性\n三正丁胺：土壤迁移性-低（koc=4219）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3373,197,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3374,197,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2542\n\n联合国正确运输名称\n三丁胺\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3375,197,15,'法规信息','国际化学品名录\n\n三正丁胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n三正丁胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3376,197,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3377,198,1,'化学品及企业标识','产品标识\n\n产品中文名称\n砷化氢\n\n产品英文名称\narsenic hydride|arsenic trihydride|arsine\n\n别名\n砷化三氢|胂\n\nCAS NO.\n7784-42-1\n\nEC NO.\n232-066-3\n\n分子式\nAsH3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3378,198,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。吸入有剧毒。长期暴露有损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n急性吸入毒性\n类别 2\n\n致癌性\n类别 1A\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH330\n吸入致命\n\nH350\n可能致癌\n\nH373\n长期或反复接触可能损害器官\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n腹部疼痛,意识模糊,头晕,头痛,恶心,气促,呕吐,虚弱。症状可能推迟显现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n与液体接触：冻伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3379,198,3,'成分/组成信息','砷化氢\n\nCas No.\n7784-42-1\n\nEC No.\n232-066-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3380,198,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3381,198,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3382,198,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3383,198,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3384,198,8,'接触控制/个体防护','控制参数->职业接触限值\n\n砷化氢\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\nG1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3385,198,9,'理化特性','外观与性状\n无色气体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-116\n\n初沸点和沸程(℃)\n-62\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：78；下限：4.5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3386,198,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3387,198,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n砷化氢\n7784-42-1\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n砷化氢\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3388,198,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3389,198,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3390,198,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2188\n\n联合国正确运输名称\n胂\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3391,198,15,'法规信息','国际化学品名录\n\n砷化氢\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n砷化氢\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3392,198,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3393,199,1,'化学品及企业标识','产品标识\n\n产品中文名称\n石脑油\n\n产品英文名称\nnaphtha|low boiling point naphtha\n\n别名\n-\n\nCAS NO.\n8030-30-6\n\nEC NO.\n232-443-2\n\n分子式\nCnH2n+2(n=5~8)\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3394,199,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n生殖细胞致突变性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH340\n可能造成遗传性缺陷\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n在正常生产处理过程中，吞咽本品并进入呼吸道可能致命。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3395,199,3,'成分/组成信息','石脑油\n\nCas No.\n8030-30-6\n\nEC No.\n232-443-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3396,199,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3397,199,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3398,199,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3399,199,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3400,199,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3401,199,9,'理化特性','外观与性状\n微红的棕色非固定液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n＜-60\n\n初沸点和沸程(℃)\n180\n\n闪点(闭杯，℃)\n＜-40\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.6；下限：1.4\n\n蒸气压\n45kPa（38℃）\n\n蒸气密度(空气=1)\n3\n\n相对密度(水=1)\n0.62~0.88\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n280~470\n\n分解温度(℃)\n无资料\n\n黏度\n0.4~0.9（40℃）',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3402,199,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3403,199,11,'毒理学信息','急性毒性\n\n石脑油\n8030-30-6\n\nLD\n50\n(经口)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n石脑油\n8030-30-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n石脑油\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3404,199,12,'生态学信息','急性水生毒性\n\n石脑油\n8030-30-6\n\n鱼类\nLC\n50\n：9mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：3.7mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n石脑油：水/土壤-高(半衰期=360天) 空气-低(半衰期=1.83天)\n\n生物富集或生物积累性\n石脑油：生物富集性-中等（BCF=740）\n\n土壤中的迁移性\n石脑油：土壤迁移性-低（koc=517.8）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3405,199,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3406,199,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1993\n\n联合国正确运输名称\n易燃液体，未另作规定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3407,199,15,'法规信息','国际化学品名录\n\n石脑油\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n石脑油\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3408,199,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3409,200,1,'化学品及企业标识','产品标识\n\n产品中文名称\n石油醚\n\n产品英文名称\nligroine|low boiling point naphtha\n\n别名\n石油精\n\nCAS NO.\n8032-32-4\n\nEC NO.\n232-453-7\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3410,200,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n生殖细胞致突变性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH340\n可能造成遗传性缺陷\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n在正常生产处理过程中，吞咽本品并进入呼吸道可能致命。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3411,200,3,'成分/组成信息','石油醚\n\nCas No.\n8032-32-4\n\nEC No.\n232-453-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3412,200,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3413,200,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3414,200,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3415,200,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3416,200,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3417,200,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n25~80\n\n闪点(闭杯，℃)\n-18\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7；下限：1\n\n蒸气压\n400hPa（20℃）\n\n蒸气密度(空气=1)\n2.5\n\n相对密度(水=1)\n0.664（15℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n245\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3418,200,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3419,200,11,'毒理学信息','急性毒性\n\n石油醚\n8032-32-4\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n石油醚\n8032-32-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n石油醚\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3420,200,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n石油醚：水/土壤-低 空气-低\n\n生物富集或生物积累性\n石油醚：生物富集性-中等（LogKOW=3.9）\n\n土壤中的迁移性\n石油醚：土壤迁移性-低（koc=149）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3421,200,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3422,200,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1268\n\n联合国正确运输名称\n石油馏出物，未另作规定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3423,200,15,'法规信息','国际化学品名录\n\n石油醚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n石油醚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3424,200,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3425,201,1,'化学品及企业标识','产品标识\n\n产品中文名称\n石油气\n\n产品英文名称\noil gas|crude gas\n\n别名\n原油气\n\nCAS NO.\n68476-85-7\n\nEC NO.\n270-704-2\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3426,201,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n液化气体\n\n生殖细胞致突变性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH340\n可能造成遗传性缺陷\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压液化气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3427,201,3,'成分/组成信息','石油气\n\nCas No.\n68476-85-7\n\nEC No.\n270-704-2\n\n含量范围（质量分数，%）\n商业秘密',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3428,201,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3429,201,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3430,201,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3431,201,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3432,201,8,'接触控制/个体防护','控制参数->职业接触限值\n\n石油气\nGBZ 2.1-2007\n\nPC-TWA\n1000 mg/m3\n\nPC-STEL\n1500 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3433,201,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-188\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8.5~9.5；下限：1.5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3434,201,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3435,201,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n石油气\n68476-85-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n石油气\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3436,201,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n石油气：水/土壤-高 空气-高\n\n生物富集或生物积累性\n石油气：生物富集性-低（BCF=1.97）\n\n土壤中的迁移性\n石油气：土壤迁移性-低（koc=35.04）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3437,201,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3438,201,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1075\n\n联合国正确运输名称\n液化石油气\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3439,201,15,'法规信息','国际化学品名录\n\n石油气\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n石油气\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3440,201,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3441,202,1,'化学品及企业标识','产品标识\n\n产品中文名称\n四氟甲烷\n\n产品英文名称\ntetrafluoromethane|freon 14\n\n别名\nR14\n\nCAS NO.\n75-73-0\n\nEC NO.\n200-896-5\n\n分子式\nCF4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3442,202,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n意识模糊，头晕，头痛。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3443,202,3,'成分/组成信息','四氟甲烷\n\nCas No.\n75-73-0\n\nEC No.\n200-896-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3444,202,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3445,202,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3446,202,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3447,202,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3448,202,8,'接触控制/个体防护','控制参数->职业接触限值\n\n四氟甲烷\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3449,202,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-183.6\n\n初沸点和沸程(℃)\n-127.8\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n1100\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3450,202,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3451,202,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n四氟甲烷\n75-73-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n四氟甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3452,202,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3453,202,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3454,202,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1982\n\n联合国正确运输名称\n四氟甲烷\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:44','2025-10-21 07:50:44'),(3455,202,15,'法规信息','国际化学品名录\n\n四氟甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n四氟甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3456,202,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:44','2025-10-21 07:50:44'),(3457,203,1,'化学品及企业标识','产品标识\n\n产品中文名称\n四氯乙烯\n\n产品英文名称\ntetrachloroethylene|perchloroethylene\n\n别名\n全氯乙烯\n\nCAS NO.\n127-18-4\n\nEC NO.\n204-825-9\n\n分子式\nC2Cl4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3458,203,2,'危险性概述','紧急情况概述\n\n液体。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n致癌性\n类别 1B\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH350\n可能致癌\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，头痛，恶心，虚弱，神志不清。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3459,203,3,'成分/组成信息','四氯乙烯\n\nCas No.\n127-18-4\n\nEC No.\n204-825-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3460,203,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。大量饮水，休息。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3461,203,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3462,203,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3463,203,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45');
INSERT INTO `msds章节` VALUES (3464,203,8,'接触控制/个体防护','控制参数->职业接触限值\n\n四氯乙烯\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n-\n\n备注\nG2A\n\n控制参数->生物限值\n\n四氯乙烯\nGBZ 2.1-2019\n\n生物检测指标\n血中四氯乙烯\n\n生物限值\n0.2mg/L\n\n采样时间\n工作周末的班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3465,203,9,'理化特性','外观与性状\n无色液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-22\n\n初沸点和沸程(℃)\n121\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n1.9kPa（20℃ ）\n\n蒸气密度(空气=1)\n5.8\n\n相对密度(水=1)\n1.63（15℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n2.9\n\n自燃温度(℃)\n＞650\n\n分解温度(℃)\n≥140\n\n黏度\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3466,203,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3467,203,11,'毒理学信息','急性毒性\n\n四氯乙烯\n127-18-4\n\nLD\n50\n(经口)\n2629mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n2629mg/kg(大鼠)\n\n致癌性\n\n四氯乙烯\n127-18-4\n\nIARC\n类别2A\n\nNTP\n未列入\n\n其他信息\n\n组分\n四氯乙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3468,203,12,'生态学信息','急性水生毒性\n\n四氯乙烯\n127-18-4\n\n鱼类\nLC\n50\n：11.9mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.3mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：27mg/L (72h)(藻类)\n\n慢性水生毒性\n\n四氯乙烯\n127-18-4\n\n鱼类\nNOEC：1.9mg/L(鱼)\n\n甲壳纲动物\nNOEC：0.023mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：9.1mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n四氯乙烯：水/土壤-高(半衰期=720天) 空气-中等(半衰期=160.13天)\n\n生物富集或生物积累性\n四氯乙烯：生物富集性-低（BCF=77.1）\n\n土壤中的迁移性\n四氯乙烯：土壤迁移性-低（koc=106.8）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3469,203,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3470,203,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1897\n\n联合国正确运输名称\n四氯乙烯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3471,203,15,'法规信息','国际化学品名录\n\n四氯乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n四氯乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3472,203,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3473,204,1,'化学品及企业标识','产品标识\n\n产品中文名称\n四氧化三铅\n\n产品英文名称\nlead tetraoxide|lead oxide red|orange lead\n\n别名\n红丹|铅丹|铅橙\n\nCAS NO.\n1314-41-6\n\nEC NO.\n215-235-6\n\n分子式\nPb3O4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3474,204,2,'危险性概述','紧急情况概述\n\n固体。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n致癌性\n类别 1B\n\n生殖毒性\n类别 1A\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP391\n收集溢出物。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n腹部疼痛，恶心，呕吐。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3475,204,3,'成分/组成信息','四氧化三铅\n\nCas No.\n1314-41-6\n\nEC No.\n215-235-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3476,204,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3477,204,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3478,204,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3479,204,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3480,204,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n四氧化三铅\nGBZ 2.1-2019\n\n生物检测指标\n血中铅\n\n生物限值\n2.0 μmol/L（400 µg/L）\n\n采样时间\n接触三周后的任意时间\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3481,204,9,'理化特性','外观与性状\n橙红色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n500（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n9.1\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n500\n\n黏度\n不适用',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3482,204,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3483,204,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n四氧化三铅\n1314-41-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n四氧化三铅\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3484,204,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n四氧化三铅：生物富集性-低（BCF=237）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3485,204,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3486,204,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3077\n\n联合国正确运输名称\n对环境有害的固态物质，未另作规定的\n\n运输主要危险类别\n9\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n聚乙烯或聚丙烯容器等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/dd675fa0e546.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3487,204,15,'法规信息','国际化学品名录\n\n四氧化三铅\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n四氧化三铅\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3488,204,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3489,205,1,'化学品及企业标识','产品标识\n\n产品中文名称\n碳化钙\n\n产品英文名称\ncalcium carbide\n\n别名\n电石\n\nCAS NO.\n75-20-7\n\nEC NO.\n200-848-3\n\n分子式\nCaC2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3490,205,2,'危险性概述','紧急情况概述\n\n固体。会跟水激烈反应, 生成高度易燃的气体。\n\nGHS危险性类别\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH260\n遇水放出可自燃的易燃气体\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\n防范说明->事故响应\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n咳嗽，呼吸困难，气促，咽喉疼痛。\n\n食入\n呼吸困难，休克或虚脱。（另见吸入）。\n\n皮肤接触\n发红，皮肤烧伤，疼痛。\n\n眼睛\n发红，疼痛，灼烧感，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3491,205,3,'成分/组成信息','碳化钙\n\nCas No.\n75-20-7\n\nEC No.\n200-848-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3492,205,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n脱去污染的衣服,用大量水冲洗皮肤或沐浴。\n\n食入\n漱口,不要催吐,给予医疗护理\n\n吸入\n新鲜空气,休息,半直立体位,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3493,205,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						火焰被扑灭后可能复燃。\n2\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n3\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n4\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3494,205,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3495,205,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						在通风良好处进行操作。\n4\r\n						.\r\n						穿戴合适的个人防护用具。\n5\r\n						.\r\n						避免接触皮肤和进入眼睛。\n6\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3496,205,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3497,205,9,'理化特性','外观与性状\n深灰色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n2300\n\n初沸点和沸程(℃)\n2300\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.22\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n＞325（粉尘）\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3498,205,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与无机酸或醇接触会发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无机酸、非金属氧化物、共价卤化物、卤素、硝酸盐、无机过氧化物、金属氧化物、金属、非金属单质和醇。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3499,205,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n碳化钙\n75-20-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n碳化钙\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3500,205,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n碳化钙：水/土壤-低 空气-低\n\n生物富集或生物积累性\n碳化钙：生物富集性-低（LogKOW=0.37）\n\n土壤中的迁移性\n碳化钙：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3501,205,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3502,205,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1402\n\n联合国正确运输名称\n碳化钙\n\n运输主要危险类别\n4.3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3503,205,15,'法规信息','国际化学品名录\n\n碳化钙\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n碳化钙\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3504,205,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3505,206,1,'化学品及企业标识','产品标识\n\n产品中文名称\n碳酸二乙酯\n\n产品英文名称\ndiethyl carbonate\n\n别名\n碳酸乙酯\n\nCAS NO.\n105-58-8\n\nEC NO.\n203-311-1\n\n分子式\nC5H10O3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3506,206,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，恶心，咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3507,206,3,'成分/组成信息','碳酸二乙酯\n\nCas No.\n105-58-8\n\nEC No.\n203-311-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3508,206,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂清洗皮肤\n\n食入\n漱口，休息。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3509,206,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3510,206,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3511,206,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3512,206,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3513,206,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-43\n\n初沸点和沸程(℃)\n126\n\n闪点(闭杯，℃)\n25\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11；下限：1.4\n\n蒸气压\n1.1kPa（20℃）\n\n蒸气密度(空气=1)\n4.07\n\n相对密度(水=1)\n0.98\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n445\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3514,206,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3515,206,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n碳酸二乙酯\n105-58-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n碳酸二乙酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3516,206,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3517,206,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3518,206,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2366\n\n联合国正确运输名称\n碳酸二乙酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3519,206,15,'法规信息','国际化学品名录\n\n碳酸二乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n碳酸二乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3520,206,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3521,207,1,'化学品及企业标识','产品标识\n\n产品中文名称\n天然气[富含甲烷的]\n\n产品英文名称\nnatural gas,with a high methane content\n\n别名\n沼气\n\nCAS NO.\n8006-14-2\n\nEC NO.\n232-343-9\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3522,207,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3523,207,3,'成分/组成信息','天然气\n\nCas No.\n8006-14-2\n\nEC No.\n232-343-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3524,207,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3525,207,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3526,207,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3527,207,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3528,207,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3529,207,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-182\n\n初沸点和沸程(℃)\n-162\n\n闪点(闭杯，℃)\n-218\n\n蒸发速率\n不适用\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：15.0；下限：5.0\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n0.55\n\n相对密度(水=1)\n0.58~0.63\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n540\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3530,207,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3531,207,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n天然气\n8006-14-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n天然气\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3532,207,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n天然气：生物富集性-低（LogKOW=1.09）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3533,207,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3534,207,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1971\n\n联合国正确运输名称\n压缩甲烷\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:45','2025-10-21 07:50:45'),(3535,207,15,'法规信息','国际化学品名录\n\n天然气\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n未列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n天然气\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3536,207,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:45','2025-10-21 07:50:45'),(3537,208,1,'化学品及企业标识','产品标识\n\n产品中文名称\n五氧化二钒\n\n产品英文名称\ndivanadium pentaoxide|vanadium pentoxide|vanadic anhydride\n\n别名\n钒酸酐\n\nCAS NO.\n1314-62-1\n\nEC NO.\n215-239-8\n\n分子式\nV2O5\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3538,208,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。对呼吸道有刺激作用。可能有发生不可逆性作用的危险。有轻微致癌性风险。可能有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH335\n可能造成呼吸道刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH351\n怀疑致癌\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛，咳嗽，灼烧感，气促，呼吸困难，喘息。\n\n食入\n胃痉挛，腹泻，倦睡，恶心，神志不清，呕吐。\n\n皮肤接触\n发红，灼烧感，疼痛。\n\n眼睛\n疼痛，发红，结膜炎。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3539,208,3,'成分/组成信息','五氧化二钒\n\nCas No.\n1314-62-1\n\nEC No.\n215-239-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3540,208,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n催吐（仅对清醒病人！），大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3541,208,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3542,208,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3543,208,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3544,208,8,'接触控制/个体防护','控制参数->职业接触限值\n\n五氧化二钒\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n-\n\n备注\nG2B\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3545,208,9,'理化特性','外观与性状\n黄色至红棕色结晶或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n4（20℃，50g/L，悬浮液，计算值）\n\n熔点/凝固点(℃)\n690\n\n初沸点和沸程(℃)\n1750（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n3.357（18℃）\n\n溶解性(mg/L)\n微溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n1750\n\n黏度\n不适用',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3546,208,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3547,208,11,'毒理学信息','急性毒性\n\n五氧化二钒\n1314-62-1\n\nLD\n50\n(经口)\n10mg/kg(大鼠)\n\nLD\n50\n(经皮)\n10mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n五氧化二钒\n1314-62-1\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n五氧化二钒\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3548,208,12,'生态学信息','急性水生毒性\n\n五氧化二钒\n1314-62-1\n\n鱼类\nLC\n50\n：7.5mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：30mg/L (72h)(藻类)\n\n慢性水生毒性\n\n五氧化二钒\n1314-62-1\n\n鱼类\n无资料\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nNOEC：5.5mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n五氧化二钒：生物富集性-低（BCF=14）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3549,208,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3550,208,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2862\n\n联合国正确运输名称\n五氧化二钒，非熔凝状态\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3551,208,15,'法规信息','国际化学品名录\n\n五氧化二钒\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n五氧化二钒\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3552,208,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3553,209,1,'化学品及企业标识','产品标识\n\n产品中文名称\n五氧化二磷\n\n产品英文名称\nphosphorus pentoxide|phosphoric anhydride\n\n别名\n磷酸酐\n\nCAS NO.\n1314-56-3\n\nEC NO.\n215-236-1\n\n分子式\nP2O5\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3554,209,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。\n\n食入\n灼烧感，胃痉挛，腹泻，咽喉痛，呕吐。\n\n皮肤接触\n皮肤烧伤，疼痛，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3555,209,3,'成分/组成信息','五氧化二磷\n\nCas No.\n1314-56-3\n\nEC No.\n215-236-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3556,209,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤，给予医疗护理。急救时戴防护手套。\n\n食入\n不要催吐，休息，给予医疗护理。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3557,209,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、二氧化碳。\n\n不适合的灭火介质\n水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3558,209,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3559,209,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3560,209,8,'接触控制/个体防护','控制参数->职业接触限值\n\n五氧化二磷\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3561,209,9,'理化特性','外观与性状\n白色晶体或粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n1（20℃，5g/L）\n\n熔点/凝固点(℃)\n340\n\n初沸点和沸程(℃)\n300\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.4\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3562,209,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3563,209,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n五氧化二磷\n1314-56-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n五氧化二磷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3564,209,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3565,209,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3566,209,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1807\n\n联合国正确运输名称\n五氧化二磷\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3567,209,15,'法规信息','国际化学品名录\n\n五氧化二磷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n五氧化二磷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3568,209,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3569,210,1,'化学品及企业标识','产品标识\n\n产品中文名称\n五氧化二砷\n\n产品英文名称\ndiarsenic pentaoxide|arsenic anhydride|arsenic pentoxide|arsenic oxide|arsenic anhydride\n\n别名\n砷酸酐|五氧化砷|氧化砷\n\nCAS NO.\n1303-28-2\n\nEC NO.\n215-116-9\n\n分子式\nAs2O5\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3570,210,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。吸入有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性吸入毒性\n类别 3\n\n致癌性\n类别 1A\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH331\n吸入会中毒\n\nH350\n可能致癌\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,头晕,头痛,气促,虚弱,胸痛,症状可能推迟显现(见食入)。\n\n食入\n呕吐,腹部疼痛,腹泻,严重口渴,肌肉震颤，休克(见吸入)。\n\n皮肤接触\n发红，灼烧感，疼痛。\n\n眼睛\n发红,疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3571,210,3,'成分/组成信息','五氧化二砷\n\nCas No.\n1303-28-2\n\nEC No.\n215-116-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3572,210,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂冲洗皮肤，给予医疗护理。\n\n食入\n漱口。催吐(仅对清醒病人！)，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3573,210,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3574,210,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3575,210,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3576,210,8,'接触控制/个体防护','控制参数->职业接触限值\n\n五氧化二砷\nGBZ 2.1-2007\n\nPC-TWA\n0.01 mg/m3\n\nPC-STEL\n0.02 mg/m3\n\n备注\nG1\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3577,210,9,'理化特性','外观与性状\n白色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n315（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n4.3\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n315\n\n黏度\n不适用',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3578,210,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3579,210,11,'毒理学信息','急性毒性\n\n五氧化二砷\n1303-28-2\n\nLD\n50\n(经口)\n8mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n五氧化二砷\n1303-28-2\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n五氧化二砷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3580,210,12,'生态学信息','急性水生毒性\n\n五氧化二砷\n1303-28-2\n\n鱼类\nLC\n50\n：30.5mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3581,210,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3582,210,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1559\n\n联合国正确运输名称\n五氧化二砷\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3583,210,15,'法规信息','国际化学品名录\n\n五氧化二砷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n五氧化二砷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3584,210,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3585,211,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氙[压缩的]\n\n产品英文名称\nxenon,compressed\n\n别名\n-\n\nCAS NO.\n7440-63-3\n\nEC NO.\n231-172-7\n\n分子式\nXe\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3586,211,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕，迟钝，头痛。窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n与液体接触：冻伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3587,211,3,'成分/组成信息','氙\n\nCas No.\n7440-63-3\n\nEC No.\n231-172-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3588,211,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给予医疗护理。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。如果感觉不舒服，需就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3589,211,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3590,211,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3591,211,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3592,211,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3593,211,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-111.8\n\n初沸点和沸程(℃)\n-108.1\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n4.5\n\n相对密度(水=1)\n1.987\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.4\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3594,211,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3595,211,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氙\n7440-63-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氙\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3596,211,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3597,211,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3598,211,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2036\n\n联合国正确运输名称\n氙\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3599,211,15,'法规信息','国际化学品名录\n\n氙\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氙\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3600,211,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3601,212,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝化纤维素[干的或含水（或乙醇）＜25%]\n\n产品英文名称\nnitrocellulose,dry or wetted with less than 25% water(or alcohol),by mass\n\n别名\n硝化棉\n\nCAS NO.\n9004-70-0\n\nEC NO.\n618-392-2\n\n分子式\nUnspecified\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3602,212,2,'危险性概述','紧急情况概述\n\n固体。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。\n\nGHS危险性类别\n\n爆炸物\n类别 1.1项\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH201\n爆炸物，整体爆炸危险\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP230\n用专用稀释剂保持湿润。\n\nP240\n容器和接收设备接地/等势联接。\n\nP250\n不得研磨/冲击/摩擦。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP372\n火灾时可能爆炸。\n\nP373\n火接近到爆炸物时切勿救火。\n\nP370+P380\n火灾时撤离现场。\n\n防范说明->安全储存\n\nP401\n按照地方/区域/国家/国际规章贮存。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n通过打击、摩擦、火灾或其他着火源有极大爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/32cb3c3ce32f.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS01.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3603,212,3,'成分/组成信息','硝化纤维素\n\nCas No.\n9004-70-0\n\nEC No.\n-\n\n含量范围（质量分数，%）\n> 75',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3604,212,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3605,212,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3606,212,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3607,212,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3608,212,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3609,212,9,'理化特性','外观与性状\n白色纤维状固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n1.66\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n160~170\n\n分解温度(℃)\n170\n\n黏度\n不适用',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3610,212,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3611,212,11,'毒理学信息','急性毒性\n\n硝化纤维素\n9004-70-0\n\nLD\n50\n(经口)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝化纤维素\n9004-70-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝化纤维素\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3612,212,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3613,212,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3614,212,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n0340\n\n联合国正确运输名称\n硝化纤维素，干的\n\n运输主要危险类别\n1.1D\n\n运输次要危险类别\n无\n\n包装类别\n满足Ⅱ类包装要求\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e153b6ff8165.jpg\", \"type\": \"transport\", \"original_url\": \"images/d1.1.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3615,212,15,'法规信息','国际化学品名录\n\n硝化纤维素\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝化纤维素\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3616,212,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3617,213,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝基苯\n\n产品英文名称\nnitrobenzene\n\n别名\n-\n\nCAS NO.\n98-95-3\n\nEC NO.\n202-716-0\n\n分子式\nC6H5NO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3618,213,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。跟皮肤接触有毒。吸入有毒。有轻微致癌性风险。长期暴露有严重损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 3\n\n急性吸入毒性\n类别 3\n\n致癌性\n类别 2\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH311\n皮肤接触会中毒\n\nH331\n吸入会中毒\n\nH351\n怀疑致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n头痛,嘴唇发青或指甲发青,皮肤发青,头晕,恶心,虚弱,意识模糊,惊厥,神志不清。\n\n食入\n（另见吸入）。\n\n皮肤接触\n可能被吸收！（另见吸入）。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3619,213,3,'成分/组成信息','硝基苯\n\nCas No.\n98-95-3\n\nEC No.\n202-716-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3620,213,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗,然后用水和肥皂清洗皮肤。给予医疗护理。\n\n食入\n漱口。用水冲服活性炭浆。休息。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3621,213,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3622,213,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3623,213,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3624,213,8,'接触控制/个体防护','控制参数->职业接触限值\n\n硝基苯\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n皮，G2B\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3625,213,9,'理化特性','外观与性状\n无色至淡黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n8.1（20℃，1g/L，计算值）\n\n熔点/凝固点(℃)\n5\n\n初沸点和沸程(℃)\n211\n\n闪点(闭杯，℃)\n88\n\n蒸发速率\n无资料\n\n易燃性\n可燃\n\n爆炸上限 /下限[%(v/v)]\n上限：40；下限：1.8\n\n蒸气压\n20Pa（20℃）\n\n蒸气密度(空气=1)\n4.2\n\n相对密度(水=1)\n1.2\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n1.86\n\n自燃温度(℃)\n480\n\n分解温度(℃)\n＞350\n\n黏度\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3626,213,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氨、无机强碱、活泼金属、碱金属碳酸盐、金属氧化物、金属烷氧化物等接触发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氨、无机强碱、活泼金属、碱金属碳酸盐、金属氧化物、金属烷氧化物和硝酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3627,213,11,'毒理学信息','急性毒性\n\n硝基苯\n98-95-3\n\nLD\n50\n(经口)\n349mg/kg(大鼠)\n\nLD\n50\n(经皮)\n349mg/kg(大鼠)\n\nLD\n50\n(吸入)\n349mg/kg(大鼠)\n\n致癌性\n\n硝基苯\n98-95-3\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝基苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3628,213,12,'生态学信息','急性水生毒性\n\n硝基苯\n98-95-3\n\n鱼类\nLC\n50\n：102mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：34.8mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：23.8mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3629,213,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3630,213,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1662\n\n联合国正确运输名称\n硝基苯\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:46','2025-10-21 07:50:46'),(3631,213,15,'法规信息','国际化学品名录\n\n硝基苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝基苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3632,213,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:46','2025-10-21 07:50:46'),(3633,9,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸\n\n产品英文名称\nnitric acid\n\n别名\n-\n\nCAS NO.\n7697-37-2\n\nEC NO.\n231-714-2\n\n分子式\nHNO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3634,9,2,'危险性概述','紧急情况概述\n\n液体。跟可燃物质接触可能会引起火灾。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n氧化性液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可能加剧燃烧；氧化剂\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咳嗽,呼吸困难,呼吸短促,咽喉痛,症状可能推迟显现。\n\n食入\n咽喉疼痛。腹部疼痛。咽喉和胸腔灼烧感。休克或虚脱。呕吐。\n\n皮肤接触\n严重皮肤烧伤。疼痛。黄色斑渍。\n\n眼睛\n发红。疼痛。烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3635,9,3,'成分/组成信息','硝酸\n\nCas No.\n7697-37-2\n\nEC No.\n231-714-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3636,9,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗(如可能易行,摘除隐形眼镜)。立即给予医疗护理。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n不要催吐。饮用1杯或2杯水。休息。给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入蒸气。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3637,9,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3638,9,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n3\r\n						.\r\n						不要触摸或穿越泄漏物。\n4\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3639,9,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃（发烟硝酸储存温度不应高于25℃），相对湿度不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3640,9,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3641,9,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n＜1\n\n熔点/凝固点(℃)\n-41.6\n\n初沸点和沸程(℃)\n121\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n6.4kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.2\n\n相对密度(水=1)\n1.4\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.21\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3642,9,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3643,9,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n硝酸\n7697-37-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3644,9,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3645,9,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3646,9,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2031\n\n联合国正确运输名称\n硝酸，发红烟的除外，含硝酸大于70%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n5.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3647,9,15,'法规信息','国际化学品名录\n\n硝酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3648,9,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3649,214,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸汞\n\n产品英文名称\nmercuric nitrate\n\n别名\n硝酸高汞\n\nCAS NO.\n10045-94-0\n\nEC NO.\n233-152-3\n\n分子式\nHNO3.1/2Hg\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3650,214,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。可能有发生不可逆性作用的危险。可能有损伤胎儿或胚胎的危险。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 1\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n生殖细胞致突变性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH341\n怀疑可造成遗传性缺陷\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,灼烧感，头痛,呼吸困难,气促。\n\n食入\n灼烧感，腹部疼痛，腹泻，恶心，呕吐，金属味道。\n\n皮肤接触\n可能被吸收！发红，疼痛，皮肤烧伤，水疱。\n\n眼睛\n发红，疼痛，视力模糊，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3651,214,3,'成分/组成信息','硝酸汞\n\nCas No.\n10045-94-0\n\nEC No.\n233-152-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3652,214,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗，给予医疗护理。\n\n食入\n漱口，用水冲服活性炭浆，催吐（仅对清醒病人!),给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3653,214,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3654,214,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3655,214,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3656,214,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n硝酸汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3657,214,9,'理化特性','外观与性状\n无色或白色透明结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n79\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n4.4\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3658,214,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属粉末的混合物，在加热时剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属粉末、非金属单质粉末、硫化物、金属氨基化合物、金属乙炔化合物、酚类、金属氨基磺酸盐、金属氰化物、硫氰酸盐、磷化物、次磷酸盐、羧酸、羧酸酐、羧酸酯、乙醇、还原剂和过甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3659,214,11,'毒理学信息','急性毒性\n\n硝酸汞\n10045-94-0\n\nLD\n50\n(经口)\n26mg/kg(大鼠)\n\nLD\n50\n(经皮)\n26mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝酸汞\n10045-94-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸汞\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3660,214,12,'生态学信息','急性水生毒性\n\n硝酸汞\n10045-94-0\n\n鱼类\nLC\n50\n：0.172mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3661,214,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3662,214,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1625\n\n联合国正确运输名称\n硝酸汞\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3663,214,15,'法规信息','国际化学品名录\n\n硝酸汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3664,214,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3665,215,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸钾\n\n产品英文名称\npotassium nitrate\n\n别名\n-\n\nCAS NO.\n7757-79-1\n\nEC NO.\n231-818-8\n\n分子式\nKNO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3666,215,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。可能有损伤胎儿或胚胎的危险。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n腹部疼痛，嘴唇发青或指甲发青,皮肤发青,头晕,呼吸困难,意识模糊,惊厥,腹泻，头痛，恶心，神志不清。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3667,215,3,'成分/组成信息','硝酸钾\n\nCas No.\n7757-79-1\n\nEC No.\n231-818-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3668,215,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3669,215,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3670,215,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3671,215,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3672,215,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3673,215,9,'理化特性','外观与性状\n无色至白色晶体或粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n5.0~7.5（20℃，50g/L）\n\n熔点/凝固点(℃)\n333~334\n\n初沸点和沸程(℃)\n400（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.1\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n400\n\n黏度\n不适用',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3674,215,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属粉末的混合物，在加热时剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属粉末、非金属单质粉末、硫化物、金属氨基化合物、金属乙炔化合物、酚类、金属氨基磺酸盐、金属氰化物、硫氰酸盐、磷化物、次磷酸盐、羧酸、羧酸酐、羧酸酯、乙醇、还原剂和过甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3675,215,11,'毒理学信息','急性毒性\n\n硝酸钾\n7757-79-1\n\nLD\n50\n(经口)\n3750mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝酸钾\n7757-79-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸钾\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3676,215,12,'生态学信息','急性水生毒性\n\n硝酸钾\n7757-79-1\n\n鱼类\nLC\n50\n：190mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3677,215,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3678,215,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1486\n\n联合国正确运输名称\n硝酸钾\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3679,215,15,'法规信息','国际化学品名录\n\n硝酸钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3680,215,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3681,216,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸铑\n\n产品英文名称\nrhodium nitrate\n\n别名\n-\n\nCAS NO.\n10139-58-9\n\nEC NO.\n233-397-6\n\n分子式\nRh·(NO3)3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3682,216,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3683,216,3,'成分/组成信息','硝酸铑\n\nCas No.\n10139-58-9\n\nEC No.\n233-397-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3684,216,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3685,216,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3686,216,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3687,216,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3688,216,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3689,216,9,'理化特性','外观与性状\n红棕色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3690,216,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3691,216,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n硝酸铑\n10139-58-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸铑\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3692,216,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n硝酸铑：水/土壤-低 空气-低\n\n生物富集或生物积累性\n硝酸铑：生物富集性-低（LogKOW=0.209）\n\n土壤中的迁移性\n硝酸铑：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3693,216,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3694,216,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1477\n\n联合国正确运输名称\n无机硝酸盐，未另作规定的\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3695,216,15,'法规信息','国际化学品名录\n\n硝酸铑\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n未列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n硝酸铑\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3696,216,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3697,217,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸铝\n\n产品英文名称\naluminium nitrate\n\n别名\n-\n\nCAS NO.\n7784-27-2\n\nEC NO.\n236-751-8\n\n分子式\nAl(NO3)3·9(H2O)\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3698,217,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3699,217,3,'成分/组成信息','硝酸铝\n\nCas No.\n7784-27-2\n\nEC No.\n236-751-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3700,217,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3701,217,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3702,217,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3703,217,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3704,217,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3705,217,9,'理化特性','外观与性状\n无色结晶固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3706,217,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3707,217,11,'毒理学信息','急性毒性\n\n硝酸铝\n7784-27-2\n\nLD\n50\n(经口)\n3671mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝酸铝\n7784-27-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸铝\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3708,217,12,'生态学信息','急性水生毒性\n\n硝酸铝\n7784-27-2\n\n鱼类\nLC\n50\n：4.25mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3709,217,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3710,217,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1438\n\n联合国正确运输名称\n硝酸铝\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3711,217,15,'法规信息','国际化学品名录\n\n硝酸铝\n\n欧洲现有化学物质名录（EINECS）\n未列入\n\n美国 TSCA化学物质名录（TSCA）\n未列入\n\n加拿大国内化学物质名录（DSL）\n未列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸铝\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3712,217,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3713,218,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸钠\n\n产品英文名称\nsodium nitrate\n\n别名\n-\n\nCAS NO.\n7631-99-4\n\nEC NO.\n231-554-3\n\n分子式\nNaNO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3714,218,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。对眼睛有刺激性。可能有发生不可逆性作用的危险。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\n严重眼损伤/眼刺激\n类别 2B\n\n生殖细胞致突变性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH320\n造成眼刺激\n\nH341\n怀疑可造成遗传性缺陷\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n腹部疼痛，嘴唇发青或指甲发青，皮肤发青，惊厥，腹泻，头晕，头痛，呼吸困难，意识模糊，恶心，神志不清。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3715,218,3,'成分/组成信息','硝酸钠\n\nCas No.\n7631-99-4\n\nEC No.\n231-554-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3716,218,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3717,218,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3718,218,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3719,218,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3720,218,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3721,218,9,'理化特性','外观与性状\n无色结晶或粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n5.5~8.0（20℃，50g/L）\n\n熔点/凝固点(℃)\n308\n\n初沸点和沸程(℃)\n380（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.3\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n380\n\n黏度\n不适用',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3722,218,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属粉末的混合物，在加热时剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属粉末、非金属单质粉末、硫化物、金属氨基化合物、金属乙炔化合物、酚类、金属氨基磺酸盐、金属氰化物、硫氰酸盐、磷化物、次磷酸盐、羧酸、羧酸酐、羧酸酯、乙醇、还原剂和过甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3723,218,11,'毒理学信息','急性毒性\n\n硝酸钠\n7631-99-4\n\nLD\n50\n(经口)\n1267mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝酸钠\n7631-99-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成眼刺激(类别 2B)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3724,218,12,'生态学信息','急性水生毒性\n\n硝酸钠\n7631-99-4\n\n鱼类\nLC\n50\n：2190mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3725,218,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3726,218,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1498\n\n联合国正确运输名称\n硝酸钠\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:47','2025-10-21 07:50:47'),(3727,218,15,'法规信息','国际化学品名录\n\n硝酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3728,218,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:47','2025-10-21 07:50:47'),(3729,219,1,'化学品及企业标识','产品标识\n\n产品中文名称\n硝酸银\n\n产品英文名称\nsilver nitrate\n\n别名\n-\n\nCAS NO.\n7761-88-8\n\nEC NO.\n231-853-9\n\n分子式\nAgNO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3730,219,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n嘴唇或指甲发青,皮肤发青,灼烧感,意识模糊,惊厥,咳嗽,头昏,头痛,呼吸困难,恶心,气促,咽喉痛,神志不清,症状可能推迟显现。\n\n食入\n腹部疼痛,灼烧感,休克或虚脱(见吸入)。\n\n皮肤接触\n发红,皮肤烧伤,疼痛,水疱,另见吸入。\n\n眼睛\n发红,疼痛,视力丧失,严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3731,219,3,'成分/组成信息','硝酸银\n\nCas No.\n7761-88-8\n\nEC No.\n231-853-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3732,219,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗,然后脱去污染的衣服并再次冲洗,给予医疗护理。\n\n食入\n漱口,不要催吐,给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3733,219,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3734,219,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3735,219,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3736,219,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3737,219,9,'理化特性','外观与性状\n无色结晶\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n5.4~6.4（100g/L，20℃）\n\n熔点/凝固点(℃)\n212\n\n初沸点和沸程(℃)\n444（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n4.35（19℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n444\n\n黏度\n不适用',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3738,219,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属粉末的混合物，在加热时剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属粉末、非金属单质粉末、硫化物、金属氨基化合物、金属乙炔化合物、酚类、金属氨基磺酸盐、金属氰化物、硫氰酸盐、磷化物、次磷酸盐、羧酸、羧酸酐、羧酸酯、乙醇、还原剂和过甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3739,219,11,'毒理学信息','急性毒性\n\n硝酸银\n7761-88-8\n\nLD\n50\n(经口)\n1173mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n硝酸银\n7761-88-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n硝酸银\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3740,219,12,'生态学信息','急性水生毒性\n\n硝酸银\n7761-88-8\n\n鱼类\nLC\n50\n：0.0109mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.0029mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3741,219,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3742,219,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1493\n\n联合国正确运输名称\n硝酸银\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3743,219,15,'法规信息','国际化学品名录\n\n硝酸银\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n硝酸银\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3744,219,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3745,220,1,'化学品及企业标识','产品标识\n\n产品中文名称\n锌粉\n\n产品英文名称\nzinc powder\n\n别名\n-\n\nCAS NO.\n7440-66-6\n\nEC NO.\n231-175-3\n\n分子式\nZn\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3746,220,2,'危险性概述','紧急情况概述\n\n固体。在空气中容易发生自热反应,有引发火灾的危险。会跟水激烈反应, 生成高度易燃的气体。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n自热物质和混合物\n类别 1\n\n遇水放出易燃气体的物质和混合物\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH251\n自热；可能燃烧\n\nH260\n遇水放出可自燃的易燃气体\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP223\n不得与水接触。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP231+P232\n在惰性气体中操作和贮存。防潮。\n\nP235+P410\n保持低温。防日光照射。\n\n防范说明->事故响应\n\nP391\n收集溢出物。\n\nP335+P334\n掸掉皮肤上的细小颗粒。浸入冷水中/用湿绷带包扎。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP407\n垛/托盘之间应留有空隙。\n\nP413\n贮存散货质量大于……千克/……磅，温度不得超过\n……°C/……°F。\n\nP420\n远离其他材料存放。\n\nP402+P404\n存放于干燥处。存放在密闭的容器中。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n在空气中容易发生自热反应，有引发火灾的危险。会跟水激烈反应，生成可自燃的易燃气体。\n\n危害描述->健康危害\n\n吸入\n金属味和金属烟雾热。症状可能推迟显现。。\n\n食入\n腹部疼痛，恶心，呕吐。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3747,220,3,'成分/组成信息','锌粉\n\nCas No.\n7440-66-6\n\nEC No.\n231-175-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3748,220,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂洗皮肤。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						泄漏物质被水污染可能发生反应，产生气体，增加密闭的容器内的压力。\n2\r\n						.\r\n						仅在有排风的容器内收容泄漏物，而且必须安排尽快废弃处理。\n3\r\n						.\r\n						清除所有火源，增强通风。\n4\r\n						.\r\n						避免接触皮肤和眼睛。\n5\r\n						.\r\n						避免吸入粉尘。\n6\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3749,220,5,'消防措施','灭火介质\n\n适合的灭火介质\n金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。\n\n不适合的灭火介质\n禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						可燃，注意有粉尘爆炸的危险。\n3\r\n						.\r\n						物质接触空气可能自燃。\n4\r\n						.\r\n						火焰被扑灭后可能复燃。\n5\r\n						.\r\n						注意有自燃的危险。\n6\r\n						.\r\n						接触水可能发生强烈或爆炸性反应。\n7\r\n						.\r\n						物质接触空气，湿气或水可能燃烧。\n8\r\n						.\r\n						使用时可能产生易燃或易爆的蒸气-空气混合物。\n9\r\n						.\r\n						加热时，容器可能爆炸。\n10\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3750,220,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						严禁用水处理。隔离泄漏污染区，限制出入。\n2\r\n						.\r\n						不要在泄漏物上喷水或让水进入容器中。\n3\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n4\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n5\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3751,220,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						请于干燥的惰性气体氛围中操作，防潮。\n2\r\n						.\r\n						避免与湿气和水接触。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						请储存于干燥的惰性气体氛围中。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3752,220,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3753,220,9,'理化特性','外观与性状\n灰黑色粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n419\n\n初沸点和沸程(℃)\n907\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n7.14（25℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n460\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3754,220,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与卤素、卤间化合物及其他强氧化剂发生猛烈反应，或引起爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素、卤间化合物、强氧化剂、非金属、水和酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3755,220,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n锌粉\n7440-66-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n锌粉\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3756,220,12,'生态学信息','急性水生毒性\n\n锌粉\n7440-66-6\n\n鱼类\nLC\n50\n：2.01mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.33mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3757,220,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3758,220,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1436\n\n联合国正确运输名称\n锌粉尘\n\n运输主要危险类别\n4.3\n\n运输次要危险类别\n4.2\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运本品的车辆排气管须有阻火装置。装运本品的车辆排气管须有阻火装置。运输用车、船必须干燥，并有良好的防雨设施。运输用车、船必须干燥，并有良好的防雨设施。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。运输途中应防曝晒、雨淋，防高温。运输途中应防曝晒、雨淋，防高温。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/5e865cef5369.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/227c70cc314f.jpg\", \"type\": \"transport\", \"original_url\": \"images/d4.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3759,220,15,'法规信息','国际化学品名录\n\n锌粉\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n锌粉\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3760,220,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3761,221,1,'化学品及企业标识','产品标识\n\n产品中文名称\n溴化丙酰\n\n产品英文名称\npropionyl bromide|propanoyl bromide\n\n别名\n丙酰溴\n\nCAS NO.\n598-22-1\n\nEC NO.\n209-924-0\n\n分子式\nC3H5BrO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3762,221,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3763,221,3,'成分/组成信息','溴化丙酰\n\nCas No.\n598-22-1\n\nEC No.\n209-924-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3764,221,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3765,221,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3766,221,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3767,221,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3768,221,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3769,221,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n无资料\n\n初沸点和沸程(℃)\n103\n\n闪点(闭杯，℃)\n52.22\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n无资料\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n1.521\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3770,221,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3771,221,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n溴化丙酰\n598-22-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n溴化丙酰\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3772,221,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n溴化丙酰：水/土壤-高 空气-高\n\n生物富集或生物积累性\n溴化丙酰：生物富集性-低（LogKOW=0.1085）\n\n土壤中的迁移性\n溴化丙酰：土壤迁移性-低（koc=4.272）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3773,221,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3774,221,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1993\n\n联合国正确运输名称\n易燃液体，未另作规定的\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3775,221,15,'法规信息','国际化学品名录\n\n溴化丙酰\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n未列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n未列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n未列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n溴化丙酰\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3776,221,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3777,222,1,'化学品及企业标识','产品标识\n\n产品中文名称\n溴化汞\n\n产品英文名称\nmercury(Ⅱ)bromide|mercury dibromide\n\n别名\n二溴化汞|溴化高汞\n\nCAS NO.\n7789-47-1\n\nEC NO.\n232-169-3\n\n分子式\nBr2Hg\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3778,222,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可导致严重的毒性反应。\n\n皮肤接触\n皮肤直接接触可能导致皮肤过敏反应。皮肤直接接触可造成皮肤刺激。皮肤接触可产生严重毒害作用，吸收后可产生全身影响，并可致命。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3779,222,3,'成分/组成信息','溴化汞\n\nCas No.\n7789-47-1\n\nEC No.\n232-169-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3780,222,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3781,222,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3782,222,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3783,222,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3784,222,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n溴化汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3785,222,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n237\n\n初沸点和沸程(℃)\n322\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n12\n\n相对密度(水=1)\n6.05\n\n溶解性(mg/L)\n微溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3786,222,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属的混合物对机械振动非常敏感，会发生剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、硝酸酯、环氧化合物、烯烃和硝基化合物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3787,222,11,'毒理学信息','急性毒性\n\n溴化汞\n7789-47-1\n\nLD\n50\n(经口)\n40mg/kg(大鼠)\n\nLD\n50\n(经皮)\n40mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n溴化汞\n7789-47-1\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n溴化汞\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3788,222,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3789,222,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3790,222,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1634\n\n联合国正确运输名称\n溴化汞\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3791,222,15,'法规信息','国际化学品名录\n\n溴化汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n溴化汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3792,222,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3793,223,1,'化学品及企业标识','产品标识\n\n产品中文名称\n溴水[含溴≥3.5%]\n\n产品英文名称\nbromine solution,with more than 3.5% bromine\n\n别名\n-\n\nCAS NO.\n7726-95-6\n\nEC NO.\n231-778-1\n\n分子式\nBr2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3794,223,2,'危险性概述','紧急情况概述\n\n液体。有严重损害眼睛的危险。对水生物有毒。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤直接接触造成严重皮肤灼伤。\n\n眼睛\n眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3795,223,3,'成分/组成信息','溴\n\nCas No.\n7726-95-6\n\nEC No.\n231-778-1\n\n含量范围（质量分数，%）\n> 3.5',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3796,223,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3797,223,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、二氧化碳或耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3798,223,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3799,223,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3800,223,8,'接触控制/个体防护','控制参数->职业接触限值\n\n溴\nGBZ 2.1-2007\n\nPC-TWA\n0.6 mg/m3\n\nPC-STEL\n2 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3801,223,9,'理化特性','外观与性状\n黄色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-7.2\n\n初沸点和沸程(℃)\n58.8\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n23.3kPa（20℃ ）\n\n蒸气密度(空气=1)\n5.5\n\n相对密度(水=1)\n3.1\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n1.03\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3802,223,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与水接触立即分解，放出氧气。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n水、烷烃、炔烃、芳香烃、卤代烷烃、含氧有机化合物、金属、金属氢化物、非金属氢化物、非金属、金属乙炔化物、碳化物、叠氮化物、苛性碱、非金属氧化物和硫化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3803,223,11,'毒理学信息','急性毒性\n\n溴\n7726-95-6\n\nLD\n50\n(经口)\n2600mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n溴\n7726-95-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n溴\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3804,223,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3805,223,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3806,223,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1744\n\n联合国正确运输名称\n溴溶液\n\n运输主要危险类别\n8\n\n运输次要危险类别\n6.1\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3807,223,15,'法规信息','国际化学品名录\n\n溴\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n溴\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3808,223,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3809,224,1,'化学品及企业标识','产品标识\n\n产品中文名称\n亚磷酸三甲酯\n\n产品英文名称\ntrimethyl phosphite\n\n别名\n三甲氧基磷\n\nCAS NO.\n121-45-9\n\nEC NO.\n204-471-5\n\n分子式\nC3H9O3P\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3810,224,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n发红。疼痛。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3811,224,3,'成分/组成信息','亚磷酸三甲酯\n\nCas No.\n121-45-9\n\nEC No.\n204-471-5\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3812,224,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3813,224,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3814,224,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3815,224,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3816,224,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3817,224,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-78\n\n初沸点和沸程(℃)\n111.5\n\n闪点(闭杯，℃)\n23\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：61.2；下限：5.2\n\n蒸气压\n3.2kPa（25℃）\n\n蒸气密度(空气=1)\n4.3\n\n相对密度(水=1)\n1.1\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n250\n\n分解温度(℃)\n＞200\n\n黏度\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3818,224,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与强酸、强碱、强氧化剂或强还原剂接触可能发生反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n强酸、强碱、强氧化剂和强还原剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3819,224,11,'毒理学信息','急性毒性\n\n亚磷酸三甲酯\n121-45-9\n\nLD\n50\n(经口)\n1600mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1600mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n亚磷酸三甲酯\n121-45-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n亚磷酸三甲酯\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3820,224,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n亚磷酸三甲酯：水/土壤-高 空气-高\n\n生物富集或生物积累性\n亚磷酸三甲酯：生物富集性-低（LogKOW=-0.7291）\n\n土壤中的迁移性\n亚磷酸三甲酯：土壤迁移性-低（koc=252.8）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3821,224,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3822,224,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2329\n\n联合国正确运输名称\n亚磷酸三甲酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:48','2025-10-21 07:50:48'),(3823,224,15,'法规信息','国际化学品名录\n\n亚磷酸三甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n亚磷酸三甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3824,224,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:48','2025-10-21 07:50:48'),(3825,225,1,'化学品及企业标识','产品标识\n\n产品中文名称\n亚氯酸钠\n\n产品英文名称\nsodium chlorite\n\n别名\n-\n\nCAS NO.\n7758-19-2\n\nEC NO.\n231-836-6\n\n分子式\nNaClO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3826,225,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。吞食后有毒。跟皮肤接触有剧毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有剧毒。可能有发生不可逆性作用的危险。短期暴露有损伤健康的危险。长期暴露有损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n急性经口毒性\n类别 3\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n急性吸入毒性\n类别 2\n\n生殖细胞致突变性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH301\n吞咽会中毒\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH319\n造成严重眼刺激\n\nH330\n吸入致命\n\nH341\n怀疑可造成遗传性缺陷\n\nH371\n可能损害器官\n\nH373\n长期或反复接触可能损害器官\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n腹部疼痛，呕吐。\n\n皮肤接触\n发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3827,225,3,'成分/组成信息','亚氯酸钠\n\nCas No.\n7758-19-2\n\nEC No.\n231-836-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3828,225,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗。\n\n食入\n漱口，催吐（仅对清醒病人!),给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3829,225,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3830,225,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3831,225,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3832,225,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3833,225,9,'理化特性','外观与性状\n白色粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n10.0~11.0（20℃，100g/L）\n\n熔点/凝固点(℃)\n180~200（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n无资料\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.5\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n180~200\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3834,225,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物当受热、撞击或摩擦时会引发爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、金属氨基化物、氨、铵盐、胺、酰胺、醇、酚、羧酸、羧酸酯、腈类、硫酸、浓硝酸和磷酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3835,225,11,'毒理学信息','急性毒性\n\n亚氯酸钠\n7758-19-2\n\nLD\n50\n(经口)\n165mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n165mg/kg(大鼠)\n\n致癌性\n\n亚氯酸钠\n7758-19-2\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n亚氯酸钠\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3836,225,12,'生态学信息','急性水生毒性\n\n亚氯酸钠\n7758-19-2\n\n鱼类\nLC\n50\n：278mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.15mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：1.32mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3837,225,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3838,225,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1496\n\n联合国正确运输名称\n亚氯酸钠\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3839,225,15,'法规信息','国际化学品名录\n\n亚氯酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n亚氯酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3840,225,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3841,226,1,'化学品及企业标识','产品标识\n\n产品中文名称\n亚硒酸\n\n产品英文名称\nselenious acid\n\n别名\n-\n\nCAS NO.\n7783-00-8\n\nEC NO.\n231-974-7\n\n分子式\nH2SeO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3842,226,2,'危险性概述','紧急情况概述\n\n固体。吞食后有毒。有严重损害眼睛的危险。吸入有毒。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 3\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH331\n吸入会中毒\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，呼吸困难，咽喉痛，气促。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，咽喉疼痛，腹泻，恶心，呕吐，休克或虚脱。\n\n皮肤接触\n发红，疼痛，水疱，皮肤烧伤。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3843,226,3,'成分/组成信息','亚硒酸\n\nCas No.\n7783-00-8\n\nEC No.\n231-974-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3844,226,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3845,226,5,'消防措施','灭火介质\n\n适合的灭火介质\n干粉、耐醇泡沫。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3846,226,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3847,226,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3848,226,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3849,226,9,'理化特性','外观与性状\n白色固体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n1.5（20℃，50g/L）\n\n熔点/凝固点(℃)\n70（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n266Pa（15℃）\n\n蒸气密度(空气=1)\n＞1\n\n相对密度(水=1)\n3\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n70\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3850,226,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3851,226,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n亚硒酸\n7783-00-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n亚硒酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3852,226,12,'生态学信息','急性水生毒性\n\n亚硒酸\n7783-00-8\n\n鱼类\nLC\n50\n：6.61mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3853,226,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3854,226,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n2923\n\n联合国正确运输名称\n腐蚀性固体，毒性，未另作规定的\n\n运输主要危险类别\n8\n\n运输次要危险类别\n6.1\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3855,226,15,'法规信息','国际化学品名录\n\n亚硒酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n亚硒酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3856,226,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3857,227,1,'化学品及企业标识','产品标识\n\n产品中文名称\n亚硒酸钠\n\n产品英文名称\nsodium selenite|disodium selenite\n\n别名\n亚硒酸二钠\n\nCAS NO.\n10102-18-8\n\nEC NO.\n233-267-9\n\n分子式\nNa2SeO3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3858,227,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触可能会引起敏化作用。吸入有毒。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n皮肤致敏物\n类别 1\n\n急性吸入毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH317\n可能造成皮肤过敏反应\n\nH331\n吸入会中毒\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n胃痉挛，咳嗽，腹泻，头晕，头痛，脱发，呼吸困难，恶心，咽喉痛，呕吐。\n\n食入\n胃痉挛，呕吐。\n\n皮肤接触\n发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3859,227,3,'成分/组成信息','亚硒酸钠\n\nCas No.\n10102-18-8\n\nEC No.\n233-267-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3860,227,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，催吐（仅对清醒病人），给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3861,227,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3862,227,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3863,227,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3864,227,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3865,227,9,'理化特性','外观与性状\n白色结晶粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n9（50g/L）\n\n熔点/凝固点(℃)\n320（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n320\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3866,227,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3867,227,11,'毒理学信息','急性毒性\n\n亚硒酸钠\n10102-18-8\n\nLD\n50\n(经口)\n7mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n亚硒酸钠\n10102-18-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n亚硒酸钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3868,227,12,'生态学信息','急性水生毒性\n\n亚硒酸钠\n10102-18-8\n\n鱼类\nLC\n50\n：11.3mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1.5mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n亚硒酸钠：生物富集性-低（BCF=85）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3869,227,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3870,227,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3288\n\n联合国正确运输名称\n无机毒性固体，未另作规定的\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3871,227,15,'法规信息','国际化学品名录\n\n亚硒酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n亚硒酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3872,227,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3873,228,1,'化学品及企业标识','产品标识\n\n产品中文名称\n亚硝酸钠\n\n产品英文名称\nsodium nitrite\n\n别名\n-\n\nCAS NO.\n7632-00-0\n\nEC NO.\n231-555-9\n\n分子式\nNaNO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3874,228,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。吞食后有毒。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 3\n\n急性经口毒性\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH301\n吞咽会中毒\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n嘴唇发青或手指发青，皮肤发青，意识模糊，惊厥，头晕，头痛，恶心，神志不清。\n\n食入\n脉搏加快。（见吸入）。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3875,228,3,'成分/组成信息','亚硝酸钠\n\nCas No.\n7632-00-0\n\nEC No.\n231-555-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3876,228,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水，然后脱去污染的衣服并再次冲洗。\n\n食入\n催吐(仅对清醒病人!),大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3877,228,5,'消防措施','灭火介质\n\n适合的灭火介质\n水。\n\n不适合的灭火介质\n干粉、二氧化碳或泡沫。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3878,228,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3879,228,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于75%。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3880,228,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3881,228,9,'理化特性','外观与性状\n白色结晶或粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n9（100g/L，20℃）\n\n熔点/凝固点(℃)\n280\n\n初沸点和沸程(℃)\n320（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.2\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-3.7\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n＞320\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3882,228,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属粉末的混合物，在加热时剧烈爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属粉末、非金属单质粉末、硫化物、金属氨基化合物、金属乙炔化合物、酚类、金属氨基磺酸盐、金属氰化物、硫氰酸盐、磷化物、次磷酸盐、羧酸、羧酸酐、羧酸酯、乙醇、还原剂和过甲酸。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3883,228,11,'毒理学信息','急性毒性\n\n亚硝酸钠\n7632-00-0\n\nLD\n50\n(经口)\n180mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n亚硝酸钠\n7632-00-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n亚硝酸钠\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3884,228,12,'生态学信息','急性水生毒性\n\n亚硝酸钠\n7632-00-0\n\n鱼类\nLC\n50\n：0.675mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3885,228,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3886,228,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1500\n\n联合国正确运输名称\n亚硝酸钠\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n6.1\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3887,228,15,'法规信息','国际化学品名录\n\n亚硝酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n亚硝酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3888,228,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3889,229,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氩[压缩的]\n\n产品英文名称\nargon,compressed\n\n别名\n-\n\nCAS NO.\n7440-37-1\n\nEC NO.\n231-147-0\n\n分子式\nAr\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3890,229,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\n防范说明->事故响应\n\n防范说明->安全储存\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕。迟钝。头痛。窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3891,229,3,'成分/组成信息','氩\n\nCas No.\n7440-37-1\n\nEC No.\n231-147-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3892,229,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3893,229,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3894,229,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3895,229,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3896,229,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3897,229,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-189.2\n\n初沸点和沸程(℃)\n-185.9\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n67 mg/L（20℃）\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3898,229,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3899,229,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氩\n7440-37-1\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氩\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3900,229,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3901,229,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3902,229,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1006\n\n联合国正确运输名称\n压缩氩\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3903,229,15,'法规信息','国际化学品名录\n\n氩\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氩\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3904,229,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3905,230,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氧[液化的]\n\n产品英文名称\nOxygen, liquefied\n\n别名\n-\n\nCAS NO.\n7782-44-7\n\nEC NO.\n231-956-9\n\n分子式\nO2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3906,230,2,'危险性概述','紧急情况概述\n\n气体。跟可燃物质接触可能会引起火灾。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n氧化性气体\n类别 1\n\n加压气体\n液化气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH270\n可能导致或加剧燃烧；氧化剂\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP244\n阀门或紧固装置不得带有油脂或油剂。\n\n防范说明->事故响应\n\nP370+P376\n火灾时：如能保证安全，设法堵塞泄漏。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。高压液化气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，咽喉痛，视力障碍。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3907,230,3,'成分/组成信息','氧\n\nCas No.\n7782-44-7\n\nEC No.\n231-956-9\n\n含量范围（质量分数，%）\n99',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3908,230,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3909,230,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						不燃烧，但会增强火势。\n4\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n5\r\n						.\r\n						因释放氧气有助燃效果。\n6\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n7\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n8\r\n						.\r\n						加热时，容器可能爆炸。\n9\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3910,230,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3911,230,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3912,230,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3913,230,9,'理化特性','外观与性状\n液化气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-218.4\n\n初沸点和沸程(℃)\n-183\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n助燃\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n可溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3914,230,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与水接触会使其分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n乙炔、丙酮、乙醚、二硫化碳、二硼烷、四硼烷、五硼烷、三溴化磷和二甲氧基甲烷。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3915,230,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n氧\n7782-44-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n氧\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3916,230,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3917,230,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3918,230,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1073\n\n联合国正确运输名称\n冷冻液态氧\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n5.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:49','2025-10-21 07:50:49'),(3919,230,15,'法规信息','国际化学品名录\n\n氧\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氧\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3920,230,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:49','2025-10-21 07:50:49'),(3921,231,1,'化学品及企业标识','产品标识\n\n产品中文名称\n氧化汞\n\n产品英文名称\nmercury(Ⅱ)oxide|mercury monoxide\n\n别名\n一氧化汞|黄降汞|红降汞\n\nCAS NO.\n21908-53-2\n\nEC NO.\n244-654-7\n\n分子式\nHgO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3922,231,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有剧毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有刺激作用。短期暴露有严重损伤健康的危险。长期暴露有损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 2\n\n皮肤腐蚀/刺激\n类别 2\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH310\n皮肤接触致命\n\nH315\n造成皮肤刺激\n\nH317\n可能造成皮肤过敏反应\n\nH319\n造成严重眼刺激\n\nH335\n可能造成呼吸道刺激\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH370\n会损害器官\n\nH373\n长期或反复接触可能损害器官\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP262\n严防进入眼中、接触皮肤或衣服。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP302+P350\n如皮肤沾染：轻轻地用大量肥皂和水清洗。\n\nP302+P352\n如皮肤沾染：用大量肥皂和水清洗。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咳嗽。\n\n食入\n腹部疼痛，腹泻，恶心，呕吐。\n\n皮肤接触\n可能被吸收！发红。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3923,231,3,'成分/组成信息','氧化汞\n\nCas No.\n21908-53-2\n\nEC No.\n244-654-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3924,231,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3925,231,5,'消防措施','灭火介质\n\n适合的灭火介质\n矽土、水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3926,231,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3927,231,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3928,231,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n氧化汞\nGBZ 2.1-2019\n\n生物检测指标\n尿中总汞\n\n生物限值\n20 μmol/mol Cr（35 µg/g Cr）\n\n采样时间\n接触 6 个月后工作班前\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3929,231,9,'理化特性','外观与性状\n红色或黄色粉末\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n500（分解）\n\n初沸点和沸程(℃)\n&gt;35\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n11.1\n\n溶解性(mg/L)\n50（20℃）\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n500\n\n黏度\n不适用',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3930,231,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3931,231,11,'毒理学信息','急性毒性\n\n氧化汞\n21908-53-2\n\nLD\n50\n(经口)\n18mg/kg(大鼠)\n\nLD\n50\n(经皮)\n18mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n氧化汞\n21908-53-2\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n氧化汞\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3932,231,12,'生态学信息','急性水生毒性\n\n氧化汞\n21908-53-2\n\n鱼类\n无资料\n\n甲壳纲动物\nEC\n50\n：0.000004mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3933,231,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3934,231,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1641\n\n联合国正确运输名称\n氧化汞\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3935,231,15,'法规信息','国际化学品名录\n\n氧化汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n氧化汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3936,231,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3937,232,1,'化学品及企业标识','产品标识\n\n产品中文名称\n一氯二氟甲烷\n\n产品英文名称\nchloro-difluoromethane|freon 22|\n\n别名\nR22|二氟一氯甲烷|氯二氟甲烷\n\nCAS NO.\n75-45-6\n\nEC NO.\n200-871-9\n\n分子式\nCHClF2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3938,232,2,'危险性概述','紧急情况概述\n\n气体。高压，遇热有爆炸危险。对眼睛有刺激性。气体可能会引起头晕或窒息。对臭氧层有危害。\n\nGHS危险性类别\n\n加压气体\n压缩气体\n\n严重眼损伤/眼刺激\n类别 2B\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n生殖毒性\n类别 1B\n\n对臭氧层的危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH280\n内装高压气体；遇热可能爆炸\n\nH320\n造成眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH420\n破坏高层大气中的臭氧，危害公共健康和环境\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\nP502\n有关回收和循环使用的资料，请征询制造商/供应商。\n\n危害描述->物理和化学危险\n\n高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n心律失常。意识模糊，倦睡，神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3939,232,3,'成分/组成信息','一氯二氟甲烷\n\nCas No.\n75-45-6\n\nEC No.\n200-871-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3940,232,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3941,232,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						加热时，容器可能爆炸。\n4\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3942,232,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3943,232,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3944,232,8,'接触控制/个体防护','控制参数->职业接触限值\n\n一氯二氟甲烷\nGBZ 2.1-2007\n\nPC-TWA\n3500 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3945,232,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-146\n\n初沸点和沸程(℃)\n-41\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n908kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.0\n\n相对密度(水=1)\n1.49（-69℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.08\n\n自燃温度(℃)\n632\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3946,232,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3947,232,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n一氯二氟甲烷\n75-45-6\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n一氯二氟甲烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成眼刺激(类别 2B)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3948,232,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3949,232,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3950,232,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1018\n\n联合国正确运输名称\n二氟氯甲烷\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3951,232,15,'法规信息','国际化学品名录\n\n一氯二氟甲烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n一氯二氟甲烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3952,232,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3953,233,1,'化学品及企业标识','产品标识\n\n产品中文名称\n一氯化硫\n\n产品英文名称\ndisulphur dichloride|sulfur monochloride\n\n别名\n氯化硫\n\nCAS NO.\n10025-67-9\n\nEC NO.\n233-036-2\n\n分子式\nCl2S2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3954,233,2,'危险性概述','紧急情况概述\n\n液体。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。对水生物有剧毒, 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n对水生环境的危害-急性危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH400\n对水生生物毒性极大\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛，灼烧感，咳嗽，呼吸困难，气促。症状可能推迟显现。。\n\n食入\n腹部疼痛，灼烧感，休克或虚脱。\n\n皮肤接触\n发红，皮肤烧伤，疼痛，水疱。\n\n眼睛\n发红，疼痛，严重深度烧伤，视力丧失。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3955,233,3,'成分/组成信息','一氯化硫\n\nCas No.\n10025-67-9\n\nEC No.\n233-036-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3956,233,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗数分钟（如方便，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱掉污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3957,233,5,'消防措施','灭火介质\n\n适合的灭火介质\n干砂、二氧化碳、雾状水。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3958,233,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3959,233,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3960,233,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3961,233,9,'理化特性','外观与性状\n黄色至微红的液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-77\n\n初沸点和沸程(℃)\n138\n\n闪点(闭杯，℃)\n118.5\n\n蒸发速率\n无资料\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：32.5；下限：4.2\n\n蒸气压\n0.9kPa（20℃ ）\n\n蒸气密度(空气=1)\n4.7\n\n相对密度(水=1)\n1.6885（15℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n234\n\n分解温度(℃)\n300（计算值）\n\n黏度\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3962,233,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与镁、钠、钾、铜等金属或乙炔金属化合物接触发生着火或燃烧。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n镁、钠、钾、铜、氧化剂、乙炔金属化合物、醇类、烃类、氢气和水。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3963,233,11,'毒理学信息','急性毒性\n\n一氯化硫\n10025-67-9\n\nLD\n50\n(经口)\n132mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n132mg/kg(大鼠)\n\n致癌性\n\n一氯化硫\n10025-67-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n一氯化硫\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3964,233,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n一氯化硫：水/土壤-低 空气-低\n\n生物富集或生物积累性\n一氯化硫：生物富集性-低（LogKOW=0.229）\n\n土壤中的迁移性\n一氯化硫：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3965,233,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3966,233,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1828\n\n联合国正确运输名称\n氯化硫\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3967,233,15,'法规信息','国际化学品名录\n\n一氯化硫\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n一氯化硫\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3968,233,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3969,234,1,'化学品及企业标识','产品标识\n\n产品中文名称\n一氧化二氮[液化的]\n\n产品英文名称\nNitrogen oxide (N2O)\n\n别名\n-\n\nCAS NO.\n10024-97-2\n\nEC NO.\n233-032-0\n\n分子式\nN2O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3970,234,2,'危险性概述','紧急情况概述\n\n气体。跟可燃物质接触可能会引起火灾。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n氧化性气体\n类别 1\n\n加压气体\n液化气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n生殖毒性\n类别 1A\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH270\n可能导致或加剧燃烧；氧化剂\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP244\n阀门或紧固装置不得带有油脂或油剂。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P376\n火灾时：如能保证安全，设法堵塞泄漏。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。高压液化气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n欣快症。倦睡。神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3971,234,3,'成分/组成信息','一氧化二氮\n\nCas No.\n10024-97-2\n\nEC No.\n233-032-0\n\n含量范围（质量分数，%）\n99',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3972,234,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时，用大量水冲洗，不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3973,234,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						高浓度气体可导致没有预兆的窒息。\n2\r\n						.\r\n						与气体接触可能造成烧伤,严重伤害和/或冻伤。\n3\r\n						.\r\n						不燃烧，但会增强火势。\n4\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n5\r\n						.\r\n						因释放氧气有助燃效果。\n6\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n7\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n8\r\n						.\r\n						加热时，容器可能爆炸。\n9\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3974,234,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3975,234,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3976,234,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3977,234,9,'理化特性','外观与性状\n液化气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-90.8\n\n初沸点和沸程(℃)\n-88.5\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3978,234,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3979,234,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n一氧化二氮\n10024-97-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n一氧化二氮\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3980,234,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3981,234,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3982,234,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2201\n\n联合国正确运输名称\n冷冻液态氧化亚氮\n\n运输主要危险类别\n2.2\n\n运输次要危险类别\n5.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/e9aaeea54ca2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.2.jpg\"}, {\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3983,234,15,'法规信息','国际化学品名录\n\n一氧化二氮\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n一氧化二氮\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3984,234,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3985,235,1,'化学品及企业标识','产品标识\n\n产品中文名称\n一氧化铅\n\n产品英文名称\nlead monoxide|lead oxide|yellow lead\n\n别名\n氧化铅|黄丹\n\nCAS NO.\n1317-36-8\n\nEC NO.\n215-267-0\n\n分子式\nPbO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3986,235,2,'危险性概述','紧急情况概述\n\n固体。可能有发生不可逆性作用的危险。长期暴露有损伤健康的危险。\n\nGHS危险性类别\n\n生殖细胞致突变性\n类别 2\n\n致癌性\n类别 1B\n\n生殖毒性\n类别 1A\n\n特异性靶器官毒性-反复接触\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH341\n怀疑可造成遗传性缺陷\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH373\n长期或反复接触可能损害器官\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n见长期或反复接触的影响。\n\n食入\n腹部疼痛。恶心。呕吐。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3987,235,3,'成分/组成信息','一氧化铅\n\nCas No.\n1317-36-8\n\nEC No.\n215-267-0\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3988,235,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。\n\n食入\n漱口。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3989,235,5,'消防措施','灭火介质\n\n适合的灭火介质\n矽土、水。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						加热时，容器可能爆炸。\n2\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3990,235,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n2\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n3\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3991,235,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3992,235,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n一氧化铅\nGBZ 2.1-2019\n\n生物检测指标\n血中铅\n\n生物限值\n2.0 μmol/L（400 µg/L）\n\n采样时间\n接触三周后的任意时间\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3993,235,9,'理化特性','外观与性状\n黄色至淡红色结晶粉末\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n8~9（20℃，100g/L，悬浮液）\n\n熔点/凝固点(℃)\n888\n\n初沸点和沸程(℃)\n1470\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n9.5\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3994,235,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3995,235,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n一氧化铅\n1317-36-8\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n一氧化铅\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3996,235,12,'生态学信息','急性水生毒性\n\n一氧化铅\n1317-36-8\n\n鱼类\nLC\n50\n：3560mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n一氧化铅：生物富集性-低（BCF=43）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3997,235,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(3998,235,14,'运输信息','标签和标记\n\n运输标签\n不适用\n\n运输信息\n\nIMDG-CODE\n不被管制为危险品运输\n\n其他信息\n\n包装方法\n按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/8012ee763ddc.jpg\", \"type\": \"transport\", \"original_url\": \"images/weixin/hgweixin.jpg\"}]','2025-10-21 07:50:50','2025-10-21 07:50:50'),(3999,235,15,'法规信息','国际化学品名录\n\n一氧化铅\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n一氧化铅\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(4000,235,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:50','2025-10-21 07:50:50'),(4001,236,1,'化学品及企业标识','产品标识\n\n产品中文名称\n一氧化碳\n\n产品英文名称\ncarbon monoxide\n\n别名\n-\n\nCAS NO.\n630-08-0\n\nEC NO.\n211-128-3\n\n分子式\nCO\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4002,236,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。吸入有毒。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n急性吸入毒性\n类别 3\n\n生殖毒性\n类别 1A\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH331\n吸入会中毒\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头痛，意识模糊，头晕，恶心。虚弱，神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4003,236,3,'成分/组成信息','一氧化碳\n\nCas No.\n630-08-0\n\nEC No.\n211-128-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4004,236,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4005,236,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4006,236,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4007,236,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4008,236,8,'接触控制/个体防护','控制参数->职业接触限值\n\n一氧化碳\nGBZ 2.1-2007\n\nPC-TWA\n20 mg/m3\n\nPC-STEL\n30 mg/m3\n\n备注\n非高原\n\n控制参数->生物限值\n\n一氧化碳\nGBZ 2.1-2019\n\n生物检测指标\n血中碳氧血红蛋白\n\n生物限值\n5% HbCO\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4009,236,9,'理化特性','外观与性状\n无色气体\n\n气味\n无特殊气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-205\n\n初沸点和沸程(℃)\n-191\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：74.2；下限：12.5\n\n蒸气压\n＞101.08kPa\n\n蒸气密度(空气=1)\n0.97\n\n相对密度(水=1)\n0.00125\n\n溶解性(mg/L)\n与水部分混溶\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n605\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4010,236,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与活泼金属反应具有爆炸性或引起着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n活泼金属、醇、醛、二硫化碳、碳、硫、磷、硼、还原剂、金属乙炔化物和金属碳化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4011,236,11,'毒理学信息','急性毒性\n\n一氧化碳\n630-08-0\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n一氧化碳\n630-08-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n一氧化碳\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4012,236,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4013,236,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4014,236,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1016\n\n联合国正确运输名称\n压缩一氧化碳\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4015,236,15,'法规信息','国际化学品名录\n\n一氧化碳\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n一氧化碳\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4016,236,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4017,237,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙苯\n\n产品英文名称\nethylbenzene|phenylethane\n\n别名\n乙基苯\n\nCAS NO.\n100-41-4\n\nEC NO.\n202-849-4\n\n分子式\nC8H10\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4018,237,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  有轻微致癌性风险。长期暴露有损伤健康的危险。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n致癌性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH351\n怀疑致癌\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP314\n如感觉不适，须求医/就诊。\n\nP331\n不得诱导呕吐。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。头晕，倦睡，头痛。\n\n食入\n咽喉和胸腔有灼烧感。(另见吸入)。\n\n皮肤接触\n发红。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4019,237,3,'成分/组成信息','乙苯\n\nCas No.\n100-41-4\n\nEC No.\n202-849-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4020,237,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4021,237,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4022,237,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4023,237,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4024,237,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙苯\nGBZ 2.1-2007\n\nPC-TWA\n100 mg/m3\n\nPC-STEL\n150 mg/m3\n\n备注\nG2B\n\n控制参数->生物限值\n\n乙苯\nGBZ 2.1-2019\n\n生物检测指标\n尿中苯乙醇酸加苯乙醛酸\n\n生物限值\n0.8 g/g Cr\n\n采样时间\n工作班末\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4025,237,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-95\n\n初沸点和沸程(℃)\n136\n\n闪点(闭杯，℃)\n18\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：6.7；下限：1\n\n蒸气压\n0.9kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.7\n\n相对密度(水=1)\n0.867（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.1\n\n自燃温度(℃)\n432\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4026,237,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n可与卤化物发生活性反应。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤化物、氧化剂和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4027,237,11,'毒理学信息','急性毒性\n\n乙苯\n100-41-4\n\nLD\n50\n(经口)\n3500mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙苯\n100-41-4\n\nIARC\n类别2B\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙苯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4028,237,12,'生态学信息','急性水生毒性\n\n乙苯\n100-41-4\n\n鱼类\nLC\n50\n：80mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：4.75mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：3.6mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4029,237,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4030,237,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1175\n\n联合国正确运输名称\n乙苯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4031,237,15,'法规信息','国际化学品名录\n\n乙苯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙苯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4032,237,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4033,2,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙醇[无水]\n\n产品英文名称\nalcohol anhydrous|ethanol|ethyl alcohol\n\n别名\n无水酒精\n\nCAS NO.\n64-17-5\n\nEC NO.\n200-578-6\n\n分子式\nC2H6O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4034,2,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽,头痛,疲劳,倦睡。\n\n食入\n灼烧感,头痛,意识模糊,头晕,神志不清。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红，疼痛，灼烧感。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4035,2,3,'成分/组成信息','乙醇\n\nCas No.\n64-17-5\n\nEC No.\n200-578-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4036,2,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4037,2,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4038,2,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4039,2,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4040,2,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4041,2,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n7.0（20℃，10g/L）\n\n熔点/凝固点(℃)\n-117\n\n初沸点和沸程(℃)\n79\n\n闪点(闭杯，℃)\n13\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：19；下限：3.3\n\n蒸气压\n5.8kPa（20℃ ）\n\n蒸气密度(空气=1)\n1.6\n\n相对密度(水=1)\n0.79（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.32\n\n自燃温度(℃)\n363\n\n分解温度(℃)\n≥700\n\n黏度\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4042,2,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂反应剧烈，有引起燃烧爆炸的危险。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、碱金属、碱土金属和铝。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4043,2,11,'毒理学信息','急性毒性\n\n乙醇\n64-17-5\n\nLD\n50\n(经口)\n7060mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n7060mg/kg(大鼠)\n\n致癌性\n\n乙醇\n64-17-5\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙醇\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4044,2,12,'生态学信息','急性水生毒性\n\n乙醇\n64-17-5\n\n鱼类\nLC\n50\n：11000mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：9950mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n乙醇：水/土壤-低(半衰期=2.17天) 空气-低(半衰期=5.08天)\n\n生物富集或生物积累性\n乙醇：生物富集性-低（LogKOW=-0.31）\n\n土壤中的迁移性\n乙醇：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4045,2,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4046,2,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1170\n\n联合国正确运输名称\n乙醇(酒精)\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4047,2,15,'法规信息','国际化学品名录\n\n乙醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4048,2,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4049,238,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙二醇单甲醚\n\n产品英文名称\nethylene glycol monomethyl ether|2-methoxyethanol|methyl cellosolve\n\n别名\n2-甲氧基乙醇|甲基溶纤剂\n\nCAS NO.\n109-86-4\n\nEC NO.\n203-713-7\n\n分子式\nC3H8O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4050,238,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n生殖毒性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH360\n可能对生育能力或胎儿造成伤害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n意识模糊,咳嗽,咽喉痛,头晕,头痛,恶心,神志不清,呕吐,虚弱。\n\n食入\n腹部疼痛。腹泻。恶心。呕吐。（另见吸入）。\n\n皮肤接触\n可能被吸收！（另见吸入）。\n\n眼睛\n发红。疼痛。视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4051,238,3,'成分/组成信息','乙二醇单甲醚\n\nCas No.\n109-86-4\n\nEC No.\n203-713-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4052,238,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4053,238,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4054,238,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4055,238,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4056,238,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙二醇单甲醚\nGBZ 2.1-2007\n\nPC-TWA\n15 mg/m3\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4057,238,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-85\n\n初沸点和沸程(℃)\n125\n\n闪点(闭杯，℃)\n39\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：24.5；下限：2.3\n\n蒸气压\n0.83kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.6\n\n相对密度(水=1)\n0.96\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.503\n\n自燃温度(℃)\n285\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4058,238,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4059,238,11,'毒理学信息','急性毒性\n\n乙二醇单甲醚\n109-86-4\n\nLD\n50\n(经口)\n2370mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2370mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙二醇单甲醚\n109-86-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙二醇单甲醚\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4060,238,12,'生态学信息','急性水生毒性\n\n乙二醇单甲醚\n109-86-4\n\n鱼类\nLC\n50\n：>89mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：>85mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>100mg/L (72h)(藻类)\n\n慢性水生毒性\n\n乙二醇单甲醚\n109-86-4\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：>92mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：100mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4061,238,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4062,238,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1188\n\n联合国正确运输名称\n乙二醇一甲醚\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4063,238,15,'法规信息','国际化学品名录\n\n乙二醇单甲醚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙二醇单甲醚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4064,238,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4065,239,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙二醇乙醚\n\n产品英文名称\nethylene glycol monoethyl ether|2-ethoxyethanol|ethyl cellosolve\n\n别名\n2-乙氧基乙醇|乙基溶纤剂\n\nCAS NO.\n110-80-5\n\nEC NO.\n203-804-1\n\n分子式\nC4H10O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4066,239,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。吸入有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n急性吸入毒性\n类别 3\n\n生殖毒性\n类别 1B\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH331\n吸入会中毒\n\nH360\n可能对生育能力或胎儿造成伤害\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP261\n避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP311\n呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。倦睡。头痛。气促。咽喉痛。虚弱。神志不清。\n\n食入\n腹部疼痛。恶心。呕吐。（另见吸入）。\n\n皮肤接触\n可能被吸收！（另见吸入）。\n\n眼睛\n视力模糊。发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4067,239,3,'成分/组成信息','乙二醇乙醚\n\nCas No.\n110-80-5\n\nEC No.\n203-804-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4068,239,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。大量饮水。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4069,239,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4070,239,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4071,239,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4072,239,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙二醇乙醚\nGBZ 2.1-2007\n\nPC-TWA\n18 mg/m3\n\nPC-STEL\n36 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4073,239,9,'理化特性','外观与性状\n无色油状液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n7（中性）（20℃）\n\n熔点/凝固点(℃)\n-70\n\n初沸点和沸程(℃)\n135\n\n闪点(闭杯，℃)\n44\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：15.6；下限：1.7\n\n蒸气压\n0.5kPa（20℃）\n\n蒸气密度(空气=1)\n3.1\n\n相对密度(水=1)\n0.93\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.540\n\n自燃温度(℃)\n235\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4074,239,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4075,239,11,'毒理学信息','急性毒性\n\n乙二醇乙醚\n110-80-5\n\nLD\n50\n(经口)\n2125mg/kg(大鼠)\n\nLD\n50\n(经皮)\n2125mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙二醇乙醚\n110-80-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙二醇乙醚\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4076,239,12,'生态学信息','急性水生毒性\n\n乙二醇乙醚\n110-80-5\n\n鱼类\nLC\n50\n：>95mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1890mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>100mg/L (72h)(藻类)\n\n慢性水生毒性\n\n乙二醇乙醚\n110-80-5\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：>97mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：100mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4077,239,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4078,239,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1171\n\n联合国正确运输名称\n乙二醇一乙醚\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4079,239,15,'法规信息','国际化学品名录\n\n乙二醇乙醚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙二醇乙醚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4080,239,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4081,240,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙醚\n\n产品英文名称\nether|diethyl ether\n\n别名\n二乙基醚\n\nCAS NO.\n60-29-7\n\nEC NO.\n200-467-2\n\n分子式\n-\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4082,240,2,'危险性概述','紧急情况概述\n\n液体。极端易燃，有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 1\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH224\n极易燃液体和蒸气\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃液体，有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛，倦睡，呕吐，头痛，呼吸困难，神志不清。\n\n食入\n头晕，倦睡，呕吐。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4083,240,3,'成分/组成信息','乙醚\n\nCas No.\n60-29-7\n\nEC No.\n200-467-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4084,240,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴。\n\n食入\n漱口，不要催吐。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4085,240,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4086,240,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4087,240,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4088,240,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙醚\nGBZ 2.1-2007\n\nPC-TWA\n300 mg/m3\n\nPC-STEL\n500 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4089,240,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-116\n\n初沸点和沸程(℃)\n35\n\n闪点(闭杯，℃)\n-45\n\n蒸发速率\n无资料\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：48；下限：1.7\n\n蒸气压\n58.6kPa（20℃）\n\n蒸气密度(空气=1)\n2.6\n\n相对密度(水=1)\n0.7\n\n溶解性(mg/L)\n69g/L（20℃）\n\n辛醇 /水分配系数\n0.89\n\n自燃温度(℃)\n160~180\n\n分解温度(℃)\n550（计算值）\n\n黏度\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4090,240,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与卤素、卤间化合物接触会发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n卤素、卤间化合物、无机酸、硫、硫化物和过氧化钠。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4091,240,11,'毒理学信息','急性毒性\n\n乙醚\n60-29-7\n\nLD\n50\n(经口)\n1215mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙醚\n60-29-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙醚\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4092,240,12,'生态学信息','急性水生毒性\n\n乙醚\n60-29-7\n\n鱼类\nLC\n50\n：2560mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4093,240,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4094,240,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1155\n\n联合国正确运输名称\n二乙醚(乙醚)\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:51','2025-10-21 07:50:51'),(4095,240,15,'法规信息','国际化学品名录\n\n乙醚\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙醚\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4096,240,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:51','2025-10-21 07:50:51'),(4097,241,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙硼烷\n\n产品英文名称\ndiborane\n\n别名\n二硼烷\n\nCAS NO.\n19287-45-7\n\nEC NO.\n242-940-6\n\n分子式\nB2H6\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4098,241,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。有严重损害眼睛的危险。吸入有剧毒。短期暴露有严重损伤健康的危险。长期暴露有严重损伤健康的危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n皮肤腐蚀/刺激\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 1\n\n特异性靶器官毒性-一次接触\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH370\n会损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P311\n如接触到：呼叫解毒中心或医生。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n咳嗽,咽喉痛,恶心,呼吸困难,头晕,虚弱,头痛,发烧或体温升高,震颤,症状可能推迟出现。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n严重冻伤。\n\n眼睛\n严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4099,241,3,'成分/组成信息','乙硼烷\n\nCas No.\n19287-45-7\n\nEC No.\n242-940-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4100,241,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行摘除隐形眼镜),然后就医。\n\n皮肤接触\n冻伤时,用大量水冲洗,不要脱去衣服。给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4101,241,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂或二氧化碳；大火：喷洒水、水雾或普通泡沫。\n\n不适合的灭火介质\n不要在泄漏点或安全设备上用水直接喷洒 ，否则可能会导致结冰。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4102,241,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4103,241,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4104,241,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙硼烷\nGBZ 2.1-2007\n\nPC-TWA\n0.1 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4105,241,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-165\n\n初沸点和沸程(℃)\n-92\n\n闪点(闭杯，℃)\n-90\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：88；下限：0.8\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n0.96\n\n相对密度(水=1)\n0.21（15℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n40~50\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4106,241,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触会发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、金属和有机溶剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4107,241,11,'毒理学信息','急性毒性\n\n乙硼烷\n19287-45-7\n\nLD\n50\n(经口)\n无资料\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n\n致癌性\n\n乙硼烷\n19287-45-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙硼烷\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n会损害器官(类别 1)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4108,241,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4109,241,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4110,241,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1911\n\n联合国正确运输名称\n乙硼烷\n\n运输主要危险类别\n2.3\n\n运输次要危险类别\n2.1\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/6bf949ddcfdd.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.3.jpg\"}, {\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4111,241,15,'法规信息','国际化学品名录\n\n乙硼烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n未列入\n\n中国化学品管理名录\n\n乙硼烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4112,241,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4113,242,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙炔\n\n产品英文名称\nacetylene|carbide gas|ethyne\n\n别名\n电石气\n\nCAS NO.\n74-86-2\n\nEC NO.\n200-816-9\n\n分子式\nC2H2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4114,242,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。高压，遇热有爆炸危险。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n化学性质不稳定气体\nA类\n\n加压气体\n压缩气体\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH230\n无空气也可能迅速反应\n\nH280\n内装高压气体；遇热可能爆炸\n\n防范说明->预防措施\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\n防范说明->事故响应\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n头晕。迟钝。头痛。窒息。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4115,242,3,'成分/组成信息','乙炔\n\nCas No.\n74-86-2\n\nEC No.\n200-816-9\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4116,242,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4117,242,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4118,242,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4119,242,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4120,242,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4121,242,9,'理化特性','外观与性状\n无色气体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-81\n\n初沸点和沸程(℃)\n-85\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：100；下限：2.5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n305\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4122,242,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂接触或混合形成过氧化物及氮氧化物易发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、活性金属、重金属及重金属盐和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4123,242,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n乙炔\n74-86-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙炔\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4124,242,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n乙炔：水/土壤-低 空气-低\n\n生物富集或生物积累性\n乙炔：生物富集性-低（LogKOW=0.37）\n\n土壤中的迁移性\n乙炔：土壤迁移性-低（koc=14.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4125,242,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4126,242,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3374\n\n联合国正确运输名称\n乙炔，无溶剂\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4127,242,15,'法规信息','国际化学品名录\n\n乙炔\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙炔\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4128,242,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4129,243,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸[含量＞80%]\n\n产品英文名称\nacetic acid (more than 80%)\n\n别名\n醋酸\n\nCAS NO.\n64-19-7\n\nEC NO.\n200-580-7\n\n分子式\nC2H4O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4130,243,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咽喉痛。咳嗽。灼烧感。头痛，头晕。呼吸短促，呼吸困难。\n\n食入\n咽喉疼痛。有灼烧感。腹部疼痛。呕吐。休克或虚脱。\n\n皮肤接触\n疼痛。发红。皮肤烧伤。水疱。\n\n眼睛\n发红。疼痛。严重烧伤。视力丧失。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4131,243,3,'成分/组成信息','乙酸\n\nCas No.\n64-19-7\n\nEC No.\n200-580-7\n\n含量范围（质量分数，%）\n> 80',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4132,243,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水冲洗(如可能易行，摘除隐形眼镜)。立即给与医疗护理。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴至少15分钟。立即给予医疗护理。\n\n食入\n漱口。不要催吐。食入后几分钟内，可饮用1小杯水。立即给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。立即给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4133,243,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、二氧化碳、泡沫。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4134,243,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4135,243,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于32℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4136,243,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸\nGBZ 2.1-2007\n\nPC-TWA\n10 mg/m3\n\nPC-STEL\n20 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4137,243,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n2.9\n\n熔点/凝固点(℃)\n16.7\n\n初沸点和沸程(℃)\n118\n\n闪点(闭杯，℃)\n39\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：17；下限：6\n\n蒸气压\n1.5kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.1\n\n相对密度(水=1)\n1.05\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n-0.17\n\n自燃温度(℃)\n485\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4138,243,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n具有可燃性，其蒸气（或粉末）与空气接触可形成爆炸性混合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、糠醇、乙醛、硝酸、硝酸盐、亚硝酸盐、卤素的含氧酸盐和无机过氧化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4139,243,11,'毒理学信息','急性毒性\n\n乙酸\n64-19-7\n\nLD\n50\n(经口)\n3310mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙酸\n64-19-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4140,243,12,'生态学信息','急性水生毒性\n\n乙酸\n64-19-7\n\n鱼类\nLC\n50\n：88mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：65mg/L (48h)(甲壳纲)\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n乙酸：水/土壤-低 空气-低\n\n生物富集或生物积累性\n乙酸：生物富集性-低（LogKOW=-0.17）\n\n土壤中的迁移性\n乙酸：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4141,243,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4142,243,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n2789\n\n联合国正确运输名称\n乙酸溶液，按重量含酸大于80%\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4143,243,15,'法规信息','国际化学品名录\n\n乙酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4144,243,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4145,244,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸酐\n\n产品英文名称\nacetyl oxide|acetic anhydride\n\n别名\n醋酸酐\n\nCAS NO.\n108-24-7\n\nEC NO.\n203-564-8\n\n分子式\nC4H6O3\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4146,244,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。呼吸困难。呼吸短促。咽喉痛。\n\n食入\n腹部疼痛。灼烧感。休克或虚脱。\n\n皮肤接触\n发红。皮肤烧伤。疼痛。水疱。影响可能推迟显现。\n\n眼睛\n引起流泪。发红。疼痛。灼伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4147,244,3,'成分/组成信息','乙酸酐\n\nCas No.\n108-24-7\n\nEC No.\n203-564-8\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4148,244,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。给予医疗护理。\n\n食入\n漱口。不要催吐。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4149,244,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、二氧化碳、泡沫。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4150,244,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4151,244,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于32℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4152,244,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸酐\nGBZ 2.1-2007\n\nPC-TWA\n16 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4153,244,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n3（20℃，10g/L，计算值）\n\n熔点/凝固点(℃)\n-73\n\n初沸点和沸程(℃)\n139\n\n闪点(闭杯，℃)\n49\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：10.3；下限：2.7\n\n蒸气压\n0.5kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n1.083（20℃）\n\n溶解性(mg/L)\n无资料\n\n辛醇 /水分配系数\n-0.27\n\n自燃温度(℃)\n316\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4154,244,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与碱金属、碱土金属、氨、铵离子、一甲胺、二甲胺、三乙胺、低级脂肪胺、吡啶或喹啉发生放热分解。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n碱金属、碱土金属、氨、铵离子、一甲胺、二甲胺、三乙胺、低级脂肪胺、吡啶或喹啉、醇类和氧化剂。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4155,244,11,'毒理学信息','急性毒性\n\n乙酸酐\n108-24-7\n\nLD\n50\n(经口)\n1780mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n1780mg/kg(大鼠)\n\n致癌性\n\n乙酸酐\n108-24-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸酐\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4156,244,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4157,244,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4158,244,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1715\n\n联合国正确运输名称\n乙酸酐\n\n运输主要危险类别\n8\n\n运输次要危险类别\n3\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}, {\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4159,244,15,'法规信息','国际化学品名录\n\n乙酸酐\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸酐\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4160,244,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4161,245,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸汞\n\n产品英文名称\nmercury(Ⅱ)acetate\n\n别名\n乙酸高汞|醋酸汞\n\nCAS NO.\n1600-27-7\n\nEC NO.\n216-491-1\n\n分子式\nC4H6HgO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4162,245,2,'危险性概述','紧急情况概述\n\n固体。吞食后有剧毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。可能有发生不可逆性作用的危险。可能有损伤胎儿或胚胎的危险。短期暴露有损伤健康的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n急性经口毒性\n类别 2\n\n急性经皮肤毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n生殖细胞致突变性\n类别 2\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-一次接触\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH300\n吞咽致命\n\nH311\n皮肤接触会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH341\n怀疑可造成遗传性缺陷\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH371\n可能损害器官\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP322\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP361\n立即去除/脱掉所有沾染的衣服。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n咽喉痛，咳嗽，头痛，呼吸困难，气促。\n\n食入\n腹部疼痛，灼烧感，腹泻，呕吐，金属味道。\n\n皮肤接触\n可能被吸收！皮肤烧伤，疼痛。\n\n眼睛\n发红，疼痛，严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4163,245,3,'成分/组成信息','乙酸汞\n\nCas No.\n1600-27-7\n\nEC No.\n216-491-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4164,245,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，催吐（仅对清醒病人！），给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入粉尘。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4165,245,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4166,245,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4167,245,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于32℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4168,245,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸汞\nGBZ 2.1-2007\n\nPC-TWA\n0.01 mg/m3\n\nPC-STEL\n0.03 mg/m3\n\n备注\n皮，G2B（甲基汞）\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4169,245,9,'理化特性','外观与性状\n白色至近乎于白色结晶粉末\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n178（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n11\n\n相对密度(水=1)\n3.28\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n178\n\n黏度\n不适用',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4170,245,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4171,245,11,'毒理学信息','急性毒性\n\n乙酸汞\n1600-27-7\n\nLD\n50\n(经口)\n40.9mg/kg(大鼠)\n\nLD\n50\n(经皮)\n40.9mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙酸汞\n1600-27-7\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸汞\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n可能损害器官(类别 2)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n怀疑可造成遗传性缺陷(类别 2)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4172,245,12,'生态学信息','急性水生毒性\n\n乙酸汞\n1600-27-7\n\n鱼类\nLC\n50\n：0.12mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4173,245,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4174,245,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1629\n\n联合国正确运输名称\n乙酸汞(醋酸汞)\n\n运输主要危险类别\n6.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4175,245,15,'法规信息','国际化学品名录\n\n乙酸汞\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸汞\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4176,245,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4177,246,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸甲酯\n\n产品英文名称\nmethyl acetate|acetic acid methyl ester\n\n别名\n醋酸甲酯\n\nCAS NO.\n79-20-9\n\nEC NO.\n201-185-2\n\n分子式\nC3H6O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4178,246,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，倦睡，迟钝，头痛，咽喉疼痛，呼吸困难，神志不清。症状可能推迟显现。。\n\n食入\n腹部疼痛，迟钝，恶心，呕吐，虚弱。（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红，粗糙。\n\n眼睛\n发红，疼痛，视力模糊。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4179,246,3,'成分/组成信息','乙酸甲酯\n\nCas No.\n79-20-9\n\nEC No.\n201-185-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4180,246,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，大量饮水，给予医疗护理。\n\n吸入\n新鲜空气，休息，半直立体位，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4181,246,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4182,246,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4183,246,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4184,246,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸甲酯\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n500 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4185,246,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-98\n\n初沸点和沸程(℃)\n57\n\n闪点(闭杯，℃)\n-13\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：16；下限：3.1\n\n蒸气压\n21.7kPa（20℃）\n\n蒸气密度(空气=1)\n2.6\n\n相对密度(水=1)\n0.93\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.18\n\n自燃温度(℃)\n445\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4186,246,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属烷氧化物接触会发生着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、金属氢化物、无机过氧化物、硝酸盐和卤素的含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4187,246,11,'毒理学信息','急性毒性\n\n乙酸甲酯\n79-20-9\n\nLD\n50\n(经口)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n> 5000mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙酸甲酯\n79-20-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸甲酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4188,246,12,'生态学信息','急性水生毒性\n\n乙酸甲酯\n79-20-9\n\n鱼类\nLC\n50\n：399mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4189,246,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4190,246,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1231\n\n联合国正确运输名称\n乙酸甲酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:52','2025-10-21 07:50:52'),(4191,246,15,'法规信息','国际化学品名录\n\n乙酸甲酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸甲酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4192,246,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:52','2025-10-21 07:50:52'),(4193,6,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸乙酯\n\n产品英文名称\nethyl acetate|acetic acid ethyl ester\n\n别名\n醋酸乙酯\n\nCAS NO.\n141-78-6\n\nEC NO.\n205-500-4\n\n分子式\nC4H8O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4194,6,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，头晕，瞌睡，头痛，恶心，咽喉疼痛，神志不清，虚弱。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4195,6,3,'成分/组成信息','乙酸乙酯\n\nCas No.\n141-78-6\n\nEC No.\n205-500-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4196,6,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(若可能易行,摘除隐形眼镜)，然后就医。\n\n皮肤接触\n脱去污染的衣服,用大量水冲洗或淋浴,给予医疗护理。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4197,6,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4198,6,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4199,6,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4200,6,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸乙酯\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n300 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4201,6,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-84\n\n初沸点和沸程(℃)\n77\n\n闪点(闭杯，℃)\n-4\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11.5；下限：2.2\n\n蒸气压\n10kPa（20℃）\n\n蒸气密度(空气=1)\n3.0\n\n相对密度(水=1)\n0.9\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n0.73\n\n自燃温度(℃)\n427\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4202,6,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属烷氧化物接触会发生着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、金属氢化物、无机过氧化物、硝酸盐和卤素的含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4203,6,11,'毒理学信息','急性毒性\n\n乙酸乙酯\n141-78-6\n\nLD\n50\n(经口)\n5620mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙酸乙酯\n141-78-6\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸乙酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4204,6,12,'生态学信息','急性水生毒性\n\n乙酸乙酯\n141-78-6\n\n鱼类\nLC\n50\n：328mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\nErC\n50\n：2500mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4205,6,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4206,6,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1173\n\n联合国正确运输名称\n乙酸乙酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4207,6,15,'法规信息','国际化学品名录\n\n乙酸乙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸乙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4208,6,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4209,247,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸正丙酯\n\n产品英文名称\npropyl acetate\n\n别名\n醋酸正丙酯\n\nCAS NO.\n109-60-4\n\nEC NO.\n203-686-1\n\n分子式\nC5H10O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4210,247,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。对眼睛有严重刺激性。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n严重眼损伤/眼刺激\n类别 2A\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH319\n造成严重眼刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP337+P313\n如仍觉眼刺激：求医/就诊。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽，咽喉痛。\n\n食入\n意外食入本品可能对个体健康有害。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4211,247,3,'成分/组成信息','乙酸正丙酯\n\nCas No.\n109-60-4\n\nEC No.\n203-686-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4212,247,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗数分钟（若方便易行，取下隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，冲洗，然后用水和肥皂清洗皮肤。\n\n食入\n漱口，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4213,247,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4214,247,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4215,247,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4216,247,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸正丙酯\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n300 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4217,247,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-92\n\n初沸点和沸程(℃)\n101.6\n\n闪点(闭杯，℃)\n14\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：8；下限：2\n\n蒸气压\n3.3kPa（20℃ ）\n\n蒸气密度(空气=1)\n3.5\n\n相对密度(水=1)\n0.89（20℃）\n\n溶解性(mg/L)\n21.2 g/L（20℃ ）\n\n辛醇 /水分配系数\n1.24\n\n自燃温度(℃)\n450\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4218,247,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属烷氧化物接触会发生着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、金属氢化物、无机过氧化物、硝酸盐和卤素的含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4219,247,11,'毒理学信息','急性毒性\n\n乙酸正丙酯\n109-60-4\n\nLD\n50\n(经口)\n9370mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n乙酸正丙酯\n109-60-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸正丙酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n造成严重眼刺激(类别 2A)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4220,247,12,'生态学信息','急性水生毒性\n\n乙酸正丙酯\n109-60-4\n\n鱼类\nLC\n50\n：60mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4221,247,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4222,247,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1276\n\n联合国正确运输名称\n乙酸正丙酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4223,247,15,'法规信息','国际化学品名录\n\n乙酸正丙酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸正丙酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4224,247,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4225,248,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙酸正丁酯\n\n产品英文名称\nn-butyl acetate|acetic acid n-butyl ester\n\n别名\n醋酸正丁酯\n\nCAS NO.\n123-86-4\n\nEC NO.\n204-658-1\n\n分子式\nC6H12O2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4226,248,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n警告\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头晕。头痛。\n\n食入\n恶心。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4227,248,3,'成分/组成信息','乙酸正丁酯\n\nCas No.\n123-86-4\n\nEC No.\n204-658-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4228,248,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4229,248,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4230,248,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4231,248,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4232,248,8,'接触控制/个体防护','控制参数->职业接触限值\n\n乙酸正丁酯\nGBZ 2.1-2007\n\nPC-TWA\n200 mg/m3\n\nPC-STEL\n300 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4233,248,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-78\n\n初沸点和沸程(℃)\n126\n\n闪点(闭杯，℃)\n27\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.6；下限：1.2\n\n蒸气压\n1.2kPa（20℃）\n\n蒸气密度(空气=1)\n4.0\n\n相对密度(水=1)\n0.88（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n1.82\n\n自燃温度(℃)\n420\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4234,248,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属烷氧化物接触会发生着火。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属烷氧化物、金属氢化物、无机过氧化物、硝酸盐和卤素的含氧酸盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4235,248,11,'毒理学信息','急性毒性\n\n乙酸正丁酯\n123-86-4\n\nLD\n50\n(经口)\n10768mg/kg(大鼠)\n\nLD\n50\n(经皮)\n10768mg/kg(大鼠)\n\nLD\n50\n(吸入)\n10768mg/kg(大鼠)\n\n致癌性\n\n乙酸正丁酯\n123-86-4\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙酸正丁酯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4236,248,12,'生态学信息','急性水生毒性\n\n乙酸正丁酯\n123-86-4\n\n鱼类\nLC\n50\n：81mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4237,248,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4238,248,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1123\n\n联合国正确运输名称\n乙酸丁酯\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4239,248,15,'法规信息','国际化学品名录\n\n乙酸正丁酯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙酸正丁酯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4240,248,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4241,249,1,'化学品及企业标识','产品标识\n\n产品中文名称\n乙烯\n\n产品英文名称\nethylene\n\n别名\n-\n\nCAS NO.\n74-85-1\n\nEC NO.\n200-815-3\n\n分子式\nC2H4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4242,249,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n倦睡，神志不清。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4243,249,3,'成分/组成信息','乙烯\n\nCas No.\n74-85-1\n\nEC No.\n200-815-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4244,249,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n用大量水彻底冲洗至少15分钟。如有不适，就医。\n\n皮肤接触\n立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4245,249,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4246,249,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4247,249,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4248,249,8,'接触控制/个体防护','控制参数->职业接触限值\n\n职业接触限值\n无资料\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4249,249,9,'理化特性','外观与性状\n无色气体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-169.2\n\n初沸点和沸程(℃)\n-104\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：36；下限：2.7\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n490\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4250,249,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与二氧化氮、氧化氮、氨反应形成氮氧化物的加成产物易发生爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n二氧化氮、氧化氮、氨、氧化剂、卤代烃和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4251,249,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n乙烯\n74-85-1\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n乙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4252,249,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4253,249,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4254,249,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1962\n\n联合国正确运输名称\n乙烯\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4255,249,15,'法规信息','国际化学品名录\n\n乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4256,249,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4257,250,1,'化学品及企业标识','产品标识\n\n产品中文名称\n正丁胺\n\n产品英文名称\nbutylamine|1-aminobutane\n\n别名\n1-氨基丁烷\n\nCAS NO.\n109-73-9\n\nEC NO.\n203-699-2\n\n分子式\nC4H11N\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4258,250,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。对呼吸道有刺激作用。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n皮肤腐蚀/刺激\n类别 1A\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咽喉痛,咳嗽,灼烧感,头痛,头晕,脸红,呕吐，气促,呼吸困难。症状可能推迟显现。\n\n食入\n灼烧感,腹痛,腹泻，恶心,呕吐,休克或虚脱。\n\n皮肤接触\n可能被吸收!发红，皮肤烧伤，疼痛，水疱。\n\n眼睛\n疼痛，发红，严重深度烧伤，失明。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4259,250,3,'成分/组成信息','正丁胺\n\nCas No.\n109-73-9\n\nEC No.\n203-699-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4260,250,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气,半直立体位。必要时进行人工呼吸，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入蒸气。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4261,250,5,'消防措施','灭火介质\n\n适合的灭火介质\n小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。\n\n不适合的灭火介质\n避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4262,250,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n6\r\n						.\r\n						不要触摸或穿越泄漏物。\n7\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n8\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n9\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n10\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4263,250,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4264,250,8,'接触控制/个体防护','控制参数->职业接触限值\n\n正丁胺\nGBZ 2.1-2007\n\nPC-TWA\n-\n\nPC-STEL\n-\n\n备注\n皮\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4265,250,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n12.6（20℃，100g/L）\n\n熔点/凝固点(℃)\n-50\n\n初沸点和沸程(℃)\n78\n\n闪点(闭杯，℃)\n-12\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：9.8；下限：1.7\n\n蒸气压\n10.9kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.5\n\n相对密度(水=1)\n0.74\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.86\n\n自燃温度(℃)\n312\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4266,250,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与氧化剂，酸酐,金属，金属氧化物/高锰酸钾,金属盐,硝基化合物接触发生燃烧或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化剂、卤素、酸酐、酸、金属、金属氧化物、高锰酸钾、硝基化合物和金属盐。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4267,250,11,'毒理学信息','急性毒性\n\n正丁胺\n109-73-9\n\nLD\n50\n(经口)\n366mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n正丁胺\n109-73-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n正丁胺\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1A)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4268,250,12,'生态学信息','急性水生毒性\n\n正丁胺\n109-73-9\n\n鱼类\nLC\n50\n：150mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4269,250,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4270,250,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1125\n\n联合国正确运输名称\n正丁胺\n\n运输主要危险类别\n3\n\n运输次要危险类别\n8\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:53','2025-10-21 07:50:53'),(4271,250,15,'法规信息','国际化学品名录\n\n正丁胺\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n正丁胺\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4272,250,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:53','2025-10-21 07:50:53'),(4273,251,1,'化学品及企业标识','产品标识\n\n产品中文名称\n正丁醇\n\n产品英文名称\nn-butanol|butan-1-ol\n\n别名\n-\n\nCAS NO.\n71-36-3\n\nEC NO.\n200-751-6\n\n分子式\nC4H10O\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4274,251,2,'危险性概述','紧急情况概述\n\n液体。易燃,其蒸气与空气混合，能形成爆炸性混合物。对皮肤有刺激性。有严重损害眼睛的危险。对呼吸道有刺激作用。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃液体\n类别 3\n\n皮肤腐蚀/刺激\n类别 2\n\n严重眼损伤/眼刺激\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH226\n易燃液体和蒸气\n\nH315\n造成皮肤刺激\n\nH318\n造成严重眼损伤\n\nH335\n可能造成呼吸道刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n咳嗽。咽喉痛。头痛。头晕。倦睡。\n\n食入\n腹部疼痛。倦睡。头晕。恶心。腹泻。呕吐。\n\n皮肤接触\n发红。疼痛。皮肤干燥。\n\n眼睛\n发红。疼痛。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4275,251,3,'成分/组成信息','正丁醇\n\nCas No.\n71-36-3\n\nEC No.\n200-751-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4276,251,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服。用大量水冲洗皮肤或淋浴。\n\n食入\n漱口。大量饮水。不要催吐。给予医疗护理。\n\n吸入\n新鲜空气，休息。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4277,251,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4278,251,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4279,251,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4280,251,8,'接触控制/个体防护','控制参数->职业接触限值\n\n正丁醇\nGBZ 2.1-2007\n\nPC-TWA\n100 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4281,251,9,'理化特性','外观与性状\n无色透明液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n7（20℃，70g/L）\n\n熔点/凝固点(℃)\n-90\n\n初沸点和沸程(℃)\n117\n\n闪点(闭杯，℃)\n29\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：11.3；下限：1.4\n\n蒸气压\n0.58kPa（20℃ ）\n\n蒸气密度(空气=1)\n2.6\n\n相对密度(水=1)\n0.81（20℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n0.9\n\n自燃温度(℃)\n345\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4282,251,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n无资料\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n无资料\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4283,251,11,'毒理学信息','急性毒性\n\n正丁醇\n71-36-3\n\nLD\n50\n(经口)\n790mg/kg(大鼠)\n\nLD\n50\n(经皮)\n790mg/kg(大鼠)\n\nLD\n50\n(吸入)\n790mg/kg(大鼠)\n\n致癌性\n\n正丁醇\n71-36-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n正丁醇\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4284,251,12,'生态学信息','急性水生毒性\n\n正丁醇\n71-36-3\n\n鱼类\nLC\n50\n：1910mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：1980mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：>1000mg/L (72h)(藻类)\n\n慢性水生毒性\n\n正丁醇\n71-36-3\n\n鱼类\n无资料\n\n甲壳纲动物\nNOEC：4.1mg/L(甲壳纲)\n\n藻类/水生植物\nNOEC：180mg/L(藻类)\n\n其他信息\n\n持久性和降解性\n正丁醇：水/土壤-低(半衰期=54天) 空气-低(半衰期=3.65天)\n\n生物富集或生物积累性\n正丁醇：生物富集性-低（BCF=64）\n\n土壤中的迁移性\n正丁醇：土壤迁移性-中等（koc=2.443）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4285,251,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4286,251,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1120\n\n联合国正确运输名称\n丁醇\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4287,251,15,'法规信息','国际化学品名录\n\n正丁醇\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n正丁醇\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4288,251,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4289,252,1,'化学品及企业标识','产品标识\n\n产品中文名称\n正己烷\n\n产品英文名称\nn-hexane|hexane\n\n别名\n己烷\n\nCAS NO.\n110-54-3\n\nEC NO.\n203-777-6\n\n分子式\nC6H14\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4290,252,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  对皮肤有刺激性。气体可能会引起头晕或窒息。可能有损伤胎儿或胚胎的危险。长期暴露有损伤健康的危险。对水生物有毒。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n皮肤腐蚀/刺激\n类别 2\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n生殖毒性\n类别 2\n\n特异性靶器官毒性-反复接触\n类别 2\n\n对水生环境的危害-急性危害\n类别 2\n\n对水生环境的危害-长期危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH315\n造成皮肤刺激\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH361\n怀疑对生育能力或胎儿造成伤害\n\nH373\n长期或反复接触可能损害器官\n\nH401\n对水生生物有毒\n\nH411\n对水生生物有毒并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP321\n具体治疗（见本标签上的……）。\n\nP331\n不得诱导呕吐。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP332+P313\n如发生皮肤刺激：求医/就诊。\n\nP362+P364\n脱掉所有沾染的衣服，清洗后方可重新使用。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕，倦睡，迟钝，头痛，恶心，虚弱，神志不清。\n\n食入\n腹部疼痛。（另见吸入）。\n\n皮肤接触\n皮肤干燥，发红，疼痛。\n\n眼睛\n发红，疼痛。\n\n危害描述->环境危害\n\n本品对水生生物有毒并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4291,252,3,'成分/组成信息','正己烷\n\nCas No.\n110-54-3\n\nEC No.\n203-777-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4292,252,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤，给予医疗护理。\n\n食入\n漱口，不要催吐，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4293,252,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4294,252,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4295,252,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4296,252,8,'接触控制/个体防护','控制参数->职业接触限值\n\n正己烷\nGBZ 2.1-2007\n\nPC-TWA\n100 mg/m3\n\nPC-STEL\n180 mg/m3\n\n备注\n皮\n\n控制参数->生物限值\n\n正己烷\nGBZ 2.1-2019\n\n生物检测指标\n尿中 2,5-己二酮\n\n生物限值\n35.0 μmol/L（4.0 mg/L）\n\n采样时间\n工作班后\n\n备注\n无\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4297,252,9,'理化特性','外观与性状\n无色液体\n\n气味\n有刺激性气味\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-95\n\n初沸点和沸程(℃)\n69\n\n闪点(闭杯，℃)\n-22\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.5；下限：1.1\n\n蒸气压\n17（20℃）\n\n蒸气密度(空气=1)\n3.0\n\n相对密度(水=1)\n0.6603（20℃）\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.9\n\n自燃温度(℃)\n225\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4298,252,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4299,252,11,'毒理学信息','急性毒性\n\n正己烷\n110-54-3\n\nLD\n50\n(经口)\n25000mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n25000mg/kg(大鼠)\n\n致癌性\n\n正己烷\n110-54-3\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n正己烷\n\n皮肤腐蚀/刺激\n造成皮肤刺激(类别 2)\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n怀疑对生育能力或胎儿造成伤害(类别 2)\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触可能损害器官(类别 2)\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4300,252,12,'生态学信息','急性水生毒性\n\n正己烷\n110-54-3\n\n鱼类\nLC\n50\n：57.8mg/L (96h)(鱼)\n\n甲壳纲动物\n无资料\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n正己烷：水/土壤-低 空气-低\n\n生物富集或生物积累性\n正己烷：生物富集性-中等（LogKOW=3.9）\n\n土壤中的迁移性\n正己烷：土壤迁移性-低（koc=149）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4301,252,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4302,252,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1208\n\n联合国正确运输名称\n己烷\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4303,252,15,'法规信息','国际化学品名录\n\n正己烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n正己烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4304,252,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4305,253,1,'化学品及企业标识','产品标识\n\n产品中文名称\n正磷酸\n\n产品英文名称\nphosphoric acid|orthophosphoric acid\n\n别名\n磷酸\n\nCAS NO.\n7664-38-2\n\nEC NO.\n231-633-2\n\n分子式\nH3PO4\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4306,253,2,'危险性概述','紧急情况概述\n\n固体。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。\n\nGHS危险性类别\n\n皮肤腐蚀/刺激\n类别 1B\n\n严重眼损伤/眼刺激\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH318\n造成严重眼损伤\n\n防范说明->预防措施\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP321\n具体治疗（见本标签上的……）。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n无资料\n\n危害描述->健康危害\n\n吸入\n灼烧感，咳嗽，气促，咽喉痛。\n\n食入\n腹部疼痛，灼烧感，休克或虚脱。\n\n皮肤接触\n发红，疼痛，皮肤烧伤，水疱。\n\n眼睛\n疼痛，发红，严重深度烧伤。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4307,253,3,'成分/组成信息','正磷酸\n\nCas No.\n7664-38-2\n\nEC No.\n231-633-2\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4308,253,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n脱去污染的衣服，用大量水冲洗皮肤或淋浴，给予医疗护理。\n\n食入\n漱口，大量饮水，不要催吐，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						存储和使用区域应当有贮留池以便在排放和处理前调整pH值，并稀释泄漏液。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4309,253,5,'消防措施','灭火介质\n\n适合的灭火介质\n雾状水、砂土、二氧化碳。\n\n不适合的灭火介质\n高压水。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						遇火会产生刺激性、毒性或腐蚀性的气体。\n2\r\n						.\r\n						加热时，容器可能爆炸。\n3\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4310,253,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n5\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n6\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4311,253,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃，相对湿度不应高于80%。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4312,253,8,'接触控制/个体防护','控制参数->职业接触限值\n\n正磷酸\nGBZ 2.1-2007\n\nPC-TWA\n1 mg/m3\n\nPC-STEL\n3 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4313,253,9,'理化特性','外观与性状\n无色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n42\n\n初沸点和沸程(℃)\n213（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n4Pa（20℃）\n\n蒸气密度(空气=1)\n无资料\n\n相对密度(水=1)\n无资料\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n213（解放水）\n\n黏度\n不适用',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4314,253,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与非金属单质或有机物接触发生着火或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n非金属单质、有机物和纤维类物质。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4315,253,11,'毒理学信息','急性毒性\n\n正磷酸\n7664-38-2\n\nLD\n50\n(经口)\n1530mg/kg(大鼠)\n\nLD\n50\n(经皮)\n1530mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n正磷酸\n7664-38-2\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n正磷酸\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4316,253,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n正磷酸：水/土壤-高 空气-高\n\n生物富集或生物积累性\n正磷酸：生物富集性-低（LogKOW=-0.7699）\n\n土壤中的迁移性\n正磷酸：土壤迁移性-高（koc=1）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4317,253,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4318,253,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n3453\n\n联合国正确运输名称\n固态磷酸\n\n运输主要危险类别\n8\n\n运输次要危险类别\n无\n\n包装类别\nⅢ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f78f50b5e1d2.jpg\", \"type\": \"transport\", \"original_url\": \"images/d8.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4319,253,15,'法规信息','国际化学品名录\n\n正磷酸\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n正磷酸\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4320,253,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4321,254,1,'化学品及企业标识','产品标识\n\n产品中文名称\n正戊烷\n\n产品英文名称\npentane\n\n别名\n戊烷\n\nCAS NO.\n109-66-0\n\nEC NO.\n203-692-4\n\n分子式\nC5H12\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4322,254,2,'危险性概述','紧急情况概述\n\n液体。高度易燃,其蒸气与空气混合，能形成爆炸性混合物。如果被吞食，可能会造成严重肺部损伤。  气体可能会引起头晕或窒息。对水生物有毒。\n\nGHS危险性类别\n\n易燃液体\n类别 2\n\n吸入危害\n类别 1\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\n对水生环境的危害-急性危害\n类别 2\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH225\n高度易燃液体和蒸气\n\nH304\n吞咽及进入呼吸道可能致命\n\nH336\n可能造成昏昏欲睡或眩晕\n\nH401\n对水生生物有毒\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP233\n保持容器密闭。\n\nP240\n容器和接收设备接地/等势联接。\n\nP241\n使用防爆的电气/通风/照明等设备。\n\nP242\n只能使用不产生火花的工具。\n\nP243\n采取防止静电放电的措施。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP331\n不得诱导呕吐。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP403+P235\n存放在通风良好的地方。保持低温。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。\n\n危害描述->健康危害\n\n吸入\n头晕,倦睡,头痛,恶心,神志不清,呕吐。\n\n食入\n（另见吸入）。\n\n皮肤接触\n皮肤干燥。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n本品对水生生物有毒。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4323,254,3,'成分/组成信息','正戊烷\n\nCas No.\n109-66-0\n\nEC No.\n203-692-4\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4324,254,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜),然后就医。\n\n皮肤接触\n脱去污染的衣服,冲洗,然后用水和肥皂清洗皮肤。\n\n食入\n漱口，不要催吐，休息，给予医疗护理。\n\n吸入\n新鲜空气，休息，给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4325,254,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						可与空气形成爆炸性混合物 。\n2\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n3\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n4\r\n						.\r\n						液体和蒸气易燃。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4326,254,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4327,254,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4328,254,8,'接触控制/个体防护','控制参数->职业接触限值\n\n正戊烷\nGBZ 2.1-2007\n\nPC-TWA\n500 mg/m3\n\nPC-STEL\n1000 mg/m3\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4329,254,9,'理化特性','外观与性状\n无色液体\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n无资料\n\n熔点/凝固点(℃)\n-129\n\n初沸点和沸程(℃)\n36\n\n闪点(闭杯，℃)\n-49\n\n蒸发速率\n无资料\n\n易燃性\n易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：7.8；下限：1.5\n\n蒸气压\n53.3kPa（18.5℃）\n\n蒸气密度(空气=1)\n2.5\n\n相对密度(水=1)\n0.63\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n3.39\n\n自燃温度(℃)\n309\n\n分解温度(℃)\n无资料\n\n黏度\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4330,254,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n遇明火易燃或爆炸。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n氧化性物质和卤素。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4331,254,11,'毒理学信息','急性毒性\n\n正戊烷\n109-66-0\n\nLD\n50\n(经口)\n400mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n400mg/kg(大鼠)\n\n致癌性\n\n正戊烷\n109-66-0\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n正戊烷\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n吞咽及进入呼吸道可能致命(类别 1)\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4332,254,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4333,254,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4334,254,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1265\n\n联合国正确运输名称\n戊烷，液体\n\n运输主要危险类别\n3\n\n运输次要危险类别\n无\n\n包装类别\nⅠ\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n开口钢桶。安瓿瓶外普通木箱。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。运输途中应防曝晒、雨淋，防高温。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品及食品添加剂等混装混运。严禁用木船、水泥船散装运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/18e4bdc012b5.jpg\", \"type\": \"transport\", \"original_url\": \"images/d3.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4335,254,15,'法规信息','国际化学品名录\n\n正戊烷\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n正戊烷\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4336,254,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4337,255,1,'化学品及企业标识','产品标识\n\n产品中文名称\n重铬酸铵\n\n产品英文名称\nammonium dichromate|ammonium bichromate\n\n别名\n红矾铵\n\nCAS NO.\n7789-09-5\n\nEC NO.\n232-143-1\n\n分子式\nCr2H8N2O7\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4338,255,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有剧毒。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咽喉痛。咳嗽。喘息。呼吸困难。\n\n食入\n恶心。呕吐。腹部疼痛。灼烧感。腹泻。休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4339,255,3,'成分/组成信息','重铬酸铵\n\nCas No.\n7789-09-5\n\nEC No.\n232-143-1\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4340,255,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4341,255,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						加热时，容器可能爆炸。\n7\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4342,255,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n2\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n3\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n4\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4343,255,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4344,255,8,'接触控制/个体防护','控制参数->职业接触限值\n\n重铬酸铵\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n-\n\n备注\nG1；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4345,255,9,'理化特性','外观与性状\n桔黄色单斜结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n3.9\n\n熔点/凝固点(℃)\n180（分解）\n\n初沸点和沸程(℃)\n无资料\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.15\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n225\n\n分解温度(℃)\n190\n\n黏度\n不适用',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4346,255,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物是烟火物质。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、非金属单质、醇、羧酸、羧酸酐、酮、炔烃和金属氨基化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4347,255,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n重铬酸铵\n7789-09-5\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n重铬酸铵\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4348,255,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4349,255,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4350,255,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n1439\n\n联合国正确运输名称\n重铬酸铵\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n无\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。按照生产商推荐的方法进行包装。\n\n运输注意事项\n严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4351,255,15,'法规信息','国际化学品名录\n\n重铬酸铵\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n未列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n重铬酸铵\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4352,255,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4353,256,1,'化学品及企业标识','产品标识\n\n产品中文名称\n重铬酸钾\n\n产品英文名称\npotassium dichromate|red potassium chromate\n\n别名\n红矾钾\n\nCAS NO.\n7778-50-9\n\nEC NO.\n231-906-6\n\n分子式\nK2Cr2O7\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4354,256,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有剧毒。有引起过敏、哮喘病症状或呼吸困难的风险。对呼吸道有刺激作用。有发生不可逆性作用的危险。有致癌性。有损伤胎儿或胚胎的危险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n呼吸道致敏物\n类别 1\n\n特异性靶器官毒性-一次接触：呼吸道刺激\n类别 3\n\n生殖细胞致突变性\n类别 1\n\n致癌性\n类别 1\n\n生殖毒性\n类别 1\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH335\n可能造成呼吸道刺激\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n灼烧感。咽喉痛。咳嗽。喘息。呼吸困难。\n\n食入\n恶心。呕吐。腹部疼痛。灼烧感。腹泻。休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4355,256,3,'成分/组成信息','重铬酸钾\n\nCas No.\n7778-50-9\n\nEC No.\n231-906-6\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4356,256,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气，休息。半直立体位。必要时进行人工呼吸。给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4357,256,5,'消防措施','灭火介质\n\n适合的灭火介质\n水。\n\n不适合的灭火介质\n干粉、二氧化碳或泡沫。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4358,256,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4359,256,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4360,256,8,'接触控制/个体防护','控制参数->职业接触限值\n\n重铬酸钾\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n-\n\n备注\nG1；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4361,256,9,'理化特性','外观与性状\n橙红色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n4（5%溶液）\n\n熔点/凝固点(℃)\n398\n\n初沸点和沸程(℃)\n500（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.68（25℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n500\n\n黏度\n不适用',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4362,256,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物是烟火物质。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、非金属单质、醇、羧酸、羧酸酐、酮、炔烃和金属氨基化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4363,256,11,'毒理学信息','急性毒性\n\n重铬酸钾\n7778-50-9\n\nLD\n50\n(经口)\n25mg/kg(大鼠)\n\nLD\n50\n(经皮)\n25mg/kg(大鼠)\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n重铬酸钾\n7778-50-9\n\nIARC\n类别1\n\nNTP\n未列入\n\n其他信息\n\n组分\n重铬酸钾\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n可能对生育能力或胎儿造成伤害(类别 1)\n\n特异性靶器官系统毒性-单次接触\n可能造成呼吸道刺激(类别 3)\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n可能造成遗传性缺陷(类别 1)\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4364,256,12,'生态学信息','急性水生毒性\n\n重铬酸钾\n7778-50-9\n\n鱼类\nLC\n50\n：51.1mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.12mg/L (48h)(甲壳纲)\n\n藻类/水生植物\nErC\n50\n：0.6mg/L (96h)(藻类)\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n重铬酸钾：水/土壤-高 空气-高\n\n生物富集或生物积累性\n重铬酸钾：生物富集性-低（LogKOW=2.6724）\n\n土壤中的迁移性\n重铬酸钾：土壤迁移性-低（koc=393.3）\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4365,256,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4366,256,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3087\n\n联合国正确运输名称\n氧化性固体，毒性，未另作规定的\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n6.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:54','2025-10-21 07:50:54'),(4367,256,15,'法规信息','国际化学品名录\n\n重铬酸钾\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n重铬酸钾\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4368,256,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:54','2025-10-21 07:50:54'),(4369,257,1,'化学品及企业标识','产品标识\n\n产品中文名称\n重铬酸钠\n\n产品英文名称\nsodium dichromate\n\n别名\n红矾钠\n\nCAS NO.\n10588-01-9\n\nEC NO.\n234-190-3\n\n分子式\nNa2Cr2O7\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4370,257,2,'危险性概述','紧急情况概述\n\n固体。跟可燃物质接触可能会引起火灾。吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入有剧毒。有引起过敏、哮喘病症状或呼吸困难的风险。长期暴露有严重损伤健康的危险。对水生物有剧毒, 使用适当的容器, 以预防污染环境。对水生环境可能会引起长期有害作用。 使用适当的容器, 以预防污染环境。\n\nGHS危险性类别\n\n氧化性固体\n类别 2\n\n急性经口毒性\n类别 3\n\n皮肤腐蚀/刺激\n类别 1B\n\n皮肤致敏物\n类别 1\n\n严重眼损伤/眼刺激\n类别 1\n\n急性吸入毒性\n类别 2\n\n呼吸道致敏物\n类别 1\n\n生殖细胞致突变性\n类别 1B\n\n致癌性\n类别 1A\n\n生殖毒性\n类别 1B\n\n特异性靶器官毒性-反复接触\n类别 1\n\n对水生环境的危害-急性危害\n类别 1\n\n对水生环境的危害-长期危害\n类别 1\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH272\n可加剧燃烧；氧化剂\n\nH301\n吞咽会中毒\n\nH314\n造成严重皮肤灼伤和眼损伤\n\nH317\n可能造成皮肤过敏反应\n\nH318\n造成严重眼损伤\n\nH330\n吸入致命\n\nH334\n吸入可能导致过敏或哮喘病症状或呼吸困难\n\nH340\n可能造成遗传性缺陷\n\nH350\n可能致癌\n\nH360\n可能对生育能力或胎儿造成伤害\n\nH372\n长期或反复接触会对器官造成损害\n\nH400\n对水生生物毒性极大\n\nH410\n对水生生物毒性极大并具有长期持续影响\n\n防范说明->预防措施\n\nP201\n在使用前获取特别指示。\n\nP202\n在明白所有安全防范措施之前请勿搬动。\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP220\n避开/贮存处远离服装/可燃材料。\n\nP221\n采取一切防范措施，避免与可燃物混合。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP264\n作业后彻底清洗脸部及手部。\n\nP270\n使用本产品时不要进食、饮水或吸烟。\n\nP271\n只能在室外或通风良好之处使用。\n\nP272\n受沾染的工作服不得带出工作场地。\n\nP273\n避免释放到环境中。\n\nP280\n戴防护手套/穿防护服/戴防护眼罩/戴防护面具。\n\nP284\n戴呼吸防护装置。\n\nP285\n如通风不足，须戴呼吸防护装置。\n\n防范说明->事故响应\n\nP310\n立即呼叫解毒中心或医生。\n\nP314\n如感觉不适，须求医/就诊。\n\nP320\n紧急具体治疗（见本标签上的……）。\n\nP321\n具体治疗（见本标签上的……）。\n\nP330\n漱口。\n\nP363\n沾染的衣服清洗后方可重新使用。\n\nP391\n收集溢出物。\n\nP301+P310\n如误吞咽：立即呼叫解毒中心/医生。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP304+P341\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\nP306+P360\n如沾染衣服：立即用水充分冲洗沾染的衣服和皮肤，\n然后脱掉衣服。\n\nP308+P313\n如接触到或有疑虑：求医/就诊。\n\nP333+P313\n如发生皮肤刺激或皮疹：求医/就诊。\n\nP342+P311\n如有呼吸系统病症：呼叫解毒中心或医生。\n\nP370+P378\n火灾时：使用本报告第五部分提及的合适的灭火介质灭火。\n\nP301+P330+P331\n如误吞咽：漱口。不要诱导呕吐。\n\nP303+P361+P353\n如皮肤(或头发)沾染：立即去除/脱掉所有沾染的衣服。用水清洗皮肤/淋浴。\n\nP305+P351+P338\n如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。\n\nP371+P380+P375\n如发生大火和大量泄漏：撤离现场。因有爆炸危险，须远距离灭火。\n\n防范说明->安全储存\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n跟可燃物质接触可能会引起火灾。\n\n危害描述->健康危害\n\n吸入\n灼烧感,咽喉痛,咳嗽,喘息,呼吸困难。\n\n食入\n恶心,呕吐,腹部疼痛,灼烧感,腹泻,休克或虚脱。\n\n皮肤接触\n发红。疼痛。皮肤烧伤。\n\n眼睛\n发红。疼痛。视力模糊。严重深度烧伤。\n\n危害描述->环境危害\n\n本品对水生生物毒性极大并具有长期持续影响。请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/3ab2eda0daf2.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS03.jpg\"}, {\"alt\": \"\", \"url\": \"images/07213ad88aa7.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS06.jpg\"}, {\"alt\": \"\", \"url\": \"images/0c579322dad4.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS05.jpg\"}, {\"alt\": \"\", \"url\": \"images/e46d76ca7a1c.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS08.jpg\"}, {\"alt\": \"\", \"url\": \"images/2d3078b9cf5e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS09.jpg\"}]','2025-10-21 07:50:55','2025-10-21 07:50:55'),(4371,257,3,'成分/组成信息','重铬酸钠\n\nCas No.\n10588-01-9\n\nEC No.\n234-190-3\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4372,257,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n先用大量水冲洗几分钟(如可能易行,摘除隐形眼镜),然后就医。\n\n皮肤接触\n先用大量水冲洗，然后脱去污染的衣服并再次冲洗。给予医疗护理。\n\n食入\n漱口。饮用1或2杯水。给予医疗护理。\n\n吸入\n新鲜空气,休息,半直立体位,必要时进行人工呼吸,给予医疗护理。\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						避免接触任何有机物，包括燃料、溶剂、锯屑、纸张、衣料或其它禁忌物质，这些物质都可以引起点燃。\n2\r\n						.\r\n						清除所有火源，增强通风。\n3\r\n						.\r\n						避免接触皮肤和眼睛。\n4\r\n						.\r\n						避免吸入粉尘。\n5\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4373,257,5,'消防措施','灭火介质\n\n适合的灭火介质\n水。\n\n不适合的灭火介质\n干粉、二氧化碳或泡沫。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						不燃烧，但会增强火势。\n2\r\n						.\r\n						与木材、纸张、油类或金属粉末等可燃物质接触，能引起自燃或剧烈分解。\n3\r\n						.\r\n						因释放氧气有助燃效果。\n4\r\n						.\r\n						物质含有氧化剂/有机过氧化物，可通过供氧使火势加强并让火焰自身维持。\n5\r\n						.\r\n						灭火行动对已发生的火灾可能无效。\n6\r\n						.\r\n						燃烧时可能会释放毒性烟雾。\n7\r\n						.\r\n						加热时，容器可能爆炸。\n8\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4374,257,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。\n2\r\n						.\r\n						不要触摸或穿越泄漏物。\n3\r\n						.\r\n						不要触摸破损的容器或泄漏物质除非穿着合适的防护服。\n4\r\n						.\r\n						确保可燃物（木头、纸、油等）远离泄漏物。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4375,257,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						在通风良好处进行操作。\n2\r\n						.\r\n						穿戴合适的个人防护用具。\n3\r\n						.\r\n						避免接触皮肤和进入眼睛。\n4\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度一般不应高于30℃，相对湿度一般不应高于80%。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4376,257,8,'接触控制/个体防护','控制参数->职业接触限值\n\n重铬酸钠\nGBZ 2.1-2007\n\nPC-TWA\n0.05 mg/m3\n\nPC-STEL\n-\n\n备注\nG1；敏\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4377,257,9,'理化特性','外观与性状\n红色至桔红色结晶\n\n气味\n无资料\n\n气味临界值\n无资料\n\npH 值\n4\n\n熔点/凝固点(℃)\n357\n\n初沸点和沸程(℃)\n400（分解）\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n无资料\n\n爆炸上限 /下限[%(v/v)]\n上限：无资料；下限：无资料\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n2.52（13℃）\n\n溶解性(mg/L)\n与水混溶\n\n辛醇 /水分配系数\n无资料\n\n自燃温度(℃)\n无资料\n\n分解温度(℃)\n400（计算值）\n\n黏度\n不适用',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4378,257,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属粉末的混合物是烟火物质。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属粉末、非金属单质、醇、羧酸、羧酸酐、酮、炔烃和金属氨基化物。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4379,257,11,'毒理学信息','急性毒性\n\n重铬酸钠\n10588-01-9\n\nLD\n50\n(经口)\n50mg/kg(大鼠)\n\nLD\n50\n(经皮)\n无资料\n\nLD\n50\n(吸入)\n无资料\n\n致癌性\n\n重铬酸钠\n10588-01-9\n\nIARC\n未列入\n\nNTP\n未列入\n\n其他信息\n\n组分\n重铬酸钠\n\n皮肤腐蚀/刺激\n造成严重皮肤灼伤和眼损伤(类别 1B)\n\n严重眼损伤/刺激\n造成严重眼损伤(类别 1)\n\n皮肤致敏\n可能造成皮肤过敏反应(类别 1)\n\n呼吸致敏\n吸入可能导致过敏或哮喘病症状或呼吸困难(类别 1)\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-反复接触\n长期或反复接触会对器官造成损害(类别 1)\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4380,257,12,'生态学信息','急性水生毒性\n\n重铬酸钠\n10588-01-9\n\n鱼类\nLC\n50\n：43.3mg/L (96h)(鱼)\n\n甲壳纲动物\nEC\n50\n：0.12mg/L (48h)()\n\n藻类/水生植物\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n重铬酸钠：生物富集性-低（BCF=36）\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4381,257,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4382,257,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n\n运输信息\n\n联合国危险货物编号\n3087\n\n联合国正确运输名称\n氧化性固体，毒性，未另作规定的\n\n运输主要危险类别\n5.1\n\n运输次要危险类别\n6.1\n\n包装类别\nⅡ\n\n海洋污染物(是/否)\n是\n\n其他信息\n\n包装方法\n螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱等。螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱等。塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶、塑料袋外塑料桶。按照生产商推荐的方法进行包装。\n\n运输注意事项\n运输途中应防曝晒、雨淋，防高温。严禁与酸类、碱类、氧化剂、食品及食品添加剂混运。严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/f1c0b932d2af.jpg\", \"type\": \"transport\", \"original_url\": \"images/d5.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/139f1abc2164.jpg\", \"type\": \"transport\", \"original_url\": \"images/d6.1.jpg\"}, {\"alt\": \"\", \"url\": \"images/ec94e73b5763.jpg\", \"type\": \"transport\", \"original_url\": \"images/d9_s.jpg\"}]','2025-10-21 07:50:55','2025-10-21 07:50:55'),(4383,257,15,'法规信息','国际化学品名录\n\n重铬酸钠\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n重铬酸钠\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4384,257,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-21 07:50:55','2025-10-21 07:50:55'),(4385,14,1,'化学品及企业标识','产品标识\n\n产品中文名称\n1,1-二氟乙烯\n\n产品英文名称\n1,1-difluoroethylene|freon 1132a|vinylidene fluoride\n\n别名\nR1132a|偏氟乙烯\n\nCAS NO.\n75-38-7\n\nEC NO.\n200-867-7\n\n分子式\nC2H2F2\n\n产品推荐和限制用途\n\n产品的推荐用途\n请咨询生产商。\n\n产品的限制用途\n请咨询生产商。\n\n安全数据单提供者信息\n\n企业名称\n常州合规思远产品安全技术服务有限公司\n\n企业地址\n常州市新北区太湖东路9号4幢1205室\n\n邮编\n213022\n\n传真\n0519-85150306\n\n联系电话\n0519-85150306\n\n电子邮件地址\nmsds@hgmsds.com\n\n企业应急电话\n0532-83889090',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4386,14,2,'危险性概述','紧急情况概述\n\n气体。极端易燃,有爆炸危险。高压，遇热有爆炸危险。气体可能会引起头晕或窒息。\n\nGHS危险性类别\n\n易燃气体\n类别 1\n\n加压气体\n压缩气体\n\n特异性靶器官毒性-一次接触：麻醉效应\n类别 3\n\nGHS标签要素\n\n象形图\n\n信号词\n危险\n\n危险性说明\n\nH220\n极易燃气体\n\nH280\n内装高压气体；遇热可能爆炸\n\nH336\n可能造成昏昏欲睡或眩晕\n\n防范说明->预防措施\n\nP210\n远离热源/火花/明火/热表面。禁止吸烟。\n\nP260\n不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。\n\nP271\n只能在室外或通风良好之处使用。\n\n防范说明->事故响应\n\nP312\n如感觉不适，呼叫解毒中心或医生。\n\nP377\n漏气着火：切勿灭火，除非漏气能够安全地制止。\n\nP381\n除去一切点火源，如果这么做没有危险。\n\nP304+P340\n如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势。\n\n防范说明->安全储存\n\nP403\n存放在通风良好的地方。\n\nP405\n存放处须加锁。\n\nP403+P233\n存放在通风良好的地方。保持容器密闭。\n\nP410+P403\n防日晒。存放在通风良好处。\n\n防范说明->废弃处置\n\nP501\n按照地方/区域/国家/国际规章处置内装物/容器。\n\n危害描述->物理和化学危险\n\n极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。\n\n危害描述->健康危害\n\n吸入\n吸入本品可能引起瞌睡和头昏眼花，可能伴随嗜睡、警惕性下降、反射作用消失、失去协调性并感到眩晕。\n\n食入\n由于本品的物理状态，在商业/工业场合中，认为本品不太可能进入体内。\n\n皮肤接触\n与液体接触：冻伤。\n\n眼睛\n眼睛直接接触本品可导致暂时不适。\n\n危害描述->环境危害\n\n请参阅SDS第十二部分。','[{\"alt\": \"\", \"url\": \"images/937c3187ee3b.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS02.jpg\"}, {\"alt\": \"\", \"url\": \"images/287cb31d33b3.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS04.jpg\"}, {\"alt\": \"\", \"url\": \"images/064882ab2b2e.jpg\", \"type\": \"ghs\", \"original_url\": \"images/GHS07.jpg\"}]','2025-10-31 12:05:41','2025-10-31 12:05:41'),(4387,14,3,'成分/组成信息','1,1-二氟乙烯\n\nCas No.\n75-38-7\n\nEC No.\n200-867-7\n\n含量范围（质量分数，%）\n>= 99',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4388,14,4,'急救措施','急救措施描述\n\n一般性建议\n急救措施通常是需要的，请将本SDS出示给到达现场的医生。\n\n眼睛接触\n首先用大量水冲洗几分钟（如可能易行，摘除隐形眼镜），然后就医。\n\n皮肤接触\n冻伤时用大量水冲洗，不要脱衣服，给予医疗护理。\n\n食入\n禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。\n\n吸入\n新鲜空气，休息\n\n急救人员的防护\n确保医护人员了解产品的危害特性，并采取自身防护措施，以保护自己和防止污染传播。\n\n对保护施救者的忠告\n\n1\r\n						.\r\n						清除所有火源，增强通风。\n2\r\n						.\r\n						避免接触皮肤和眼睛。\n3\r\n						.\r\n						避免吸入蒸气。\n4\r\n						.\r\n						使用防护装备,包括呼吸面具。\n\n对医生的特别提示\n\n1\r\n						.\r\n						根据出现的症状进行针对性处理。\n2\r\n						.\r\n						注意症状可能会出现延迟。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4389,14,5,'消防措施','灭火介质\n\n适合的灭火介质\n使用适合火灾类型的合适的灭火剂。\n\n不适合的灭火介质\n无特别说明。\n\n源于此物质或混合物的特别危害\n\n1\r\n						.\r\n						易燃：易被热源、火花或火焰点燃。\n2\r\n						.\r\n						可与空气形成爆炸性混合物。\n3\r\n						.\r\n						暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。\n4\r\n						.\r\n						蒸气可能会移动到着火源并回闪。\n5\r\n						.\r\n						加热时，容器可能爆炸。\n6\r\n						.\r\n						受热或接触火焰可能会产生膨胀或爆炸性分解。\n\n灭火注意事项及防护措施\n\n1\r\n						.\r\n						灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。\n2\r\n						.\r\n						在安全距离处、有充足防护的情况下灭火。\n3\r\n						.\r\n						防止消防水污染地表和地下水系统。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4390,14,6,'泄漏应急处理','作业人员防护措施，防护设备和紧急处理程序\n\n1\r\n						.\r\n						避免吸入蒸气、接触皮肤和眼睛。\n2\r\n						.\r\n						谨防蒸气积累达到可爆炸的浓度。\n3\r\n						.\r\n						蒸气能在低洼处积聚。\n4\r\n						.\r\n						建议应急人员戴正压自给式呼吸器，穿防毒、防静电服，戴化学防渗透手套。\n5\r\n						.\r\n						保证充分的通风。清除所有点火源。采取防静电措施。\n6\r\n						.\r\n						迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。\n7\r\n						.\r\n						使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。\n\n环境保护措施\n\n1\r\n						.\r\n						在确保安全的情况下，采取措施防止进一步的泄漏或溢出。\n2\r\n						.\r\n						避免排放到周围环境中。\n\n泄漏化学品的收容、清除方法及所使用的处置材料\n\n1\r\n						.\r\n						少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。\n2\r\n						.\r\n						附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。\n3\r\n						.\r\n						清除所有点火源，并采用防火花工具和防暴设备。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4391,14,7,'操作处置与储存','操作注意事项\n\n1\r\n						.\r\n						避免吸入蒸气。\n2\r\n						.\r\n						只能使用不产生火花的工具。\n3\r\n						.\r\n						为防止静电释放引起的蒸气着火，设备上所有金属部件都要接地。\n4\r\n						.\r\n						使用防爆设备。\n5\r\n						.\r\n						在通风良好处进行操作。\n6\r\n						.\r\n						穿戴合适的个人防护用具。\n7\r\n						.\r\n						避免接触皮肤和进入眼睛。\n8\r\n						.\r\n						远离热源、火花、明火和热表面。\n\n储存注意事项\n\n1\r\n						.\r\n						保持容器密闭。\n2\r\n						.\r\n						储存在干燥、阴凉和通风处。\n3\r\n						.\r\n						远离热源、火花、明火和热表面。\n4\r\n						.\r\n						存储于远离不相容材料和食品容器的地方。\n5\r\n						.\r\n						储存温度不应高于30℃。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4392,14,8,'接触控制/个体防护','控制参数->职业接触限值\n\n1,1-二氟乙烯\nGBZ 2.1-2007\n\nPC-TWA\n2 mg/m3\n\nPC-STEL\n-\n\n备注\n-\n\n控制参数->生物限值\n\n生物限值\n无资料\n\n控制参数->监测方法\n\n1\r\n						.\r\n						EN 14042  工作场所空气  用于评估暴露于化学或生物试剂的程序指南。\n2\r\n						.\r\n						GBZ/T 160.1~GBZ/T 160.81-2004工作场所空气有毒物质测定（系列标准）。\n\n工程控制\n\n1\r\n						.\r\n						保持充分的通风，特别在封闭区内。\n2\r\n						.\r\n						确保在工作场所附近有洗眼和淋浴设施。\n3\r\n						.\r\n						使用防爆电器、通风、照明等设备。\n4\r\n						.\r\n						设置应急撤离通道和必要的泄险区。\n\n个人防护装备\n\n眼睛防护\n佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。\n\n手部防护\n戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161.1标准测试的防护手套。\n\n呼吸系统防护\n如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具（US）或AXBEK型（EN 14387）防毒面具筒。\n\n皮肤和身体防护\n穿阻燃防静电防护服和抗静电的防护靴。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4393,14,9,'理化特性','外观与性状\n无色气体\n\n气味\n轻微气味\n\n气味临界值\n无资料\n\npH 值\n不适用\n\n熔点/凝固点(℃)\n-144\n\n初沸点和沸程(℃)\n-83\n\n闪点(闭杯，℃)\n不适用\n\n蒸发速率\n不适用\n\n易燃性\n极易燃\n\n爆炸上限 /下限[%(v/v)]\n上限：21.3；下限：5.5\n\n蒸气压\n不适用\n\n蒸气密度(空气=1)\n不适用\n\n相对密度(水=1)\n不适用\n\n溶解性(mg/L)\n不溶于水\n\n辛醇 /水分配系数\n不适用\n\n自燃温度(℃)\n640\n\n分解温度(℃)\n无资料\n\n黏度\n不适用',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4394,14,10,'稳定性和反应性','稳定性和反应性\n\n反应性\n与不相容物质接触可发生分解或其它化学反应。\n\n化学稳定性\n在正确的使用和存储条件下是稳定的。\n\n危险反应的可能性\n与金属反应形成有机金属化合物。\n\n避免接触的条件\n不相容物质，热、火焰和火花。\n\n禁配物\n金属、氧化剂和碱。\n\n危险的分解产物\n在正常的储存和使用条件下，不会产生危险的分解产物。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4395,14,11,'毒理学信息','急性毒性\n\n急性毒性\n无资料\n\n致癌性\n\n1,1-二氟乙烯\n75-38-7\n\nIARC\n类别3\n\nNTP\n未列入\n\n其他信息\n\n组分\n1,1-二氟乙烯\n\n皮肤腐蚀/刺激\n根据现有资料，不符合分类标准\n\n严重眼损伤/刺激\n根据现有资料，不符合分类标准\n\n皮肤致敏\n根据现有资料，不符合分类标准\n\n呼吸致敏\n根据现有资料，不符合分类标准\n\n生殖毒性\n根据现有资料，不符合分类标准\n\n特异性靶器官系统毒性-单次接触\n可能造成昏昏欲睡或眩晕(类别 3)\n\n特异性靶器官系统毒性-反复接触\n根据现有资料，不符合分类标准\n\n吸入危害\n根据现有资料，不符合分类标准\n\n生殖细胞致突变性\n根据现有资料，不符合分类标准\n\n生殖毒性附加危害\n根据现有资料，不符合分类标准',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4396,14,12,'生态学信息','急性水生毒性\n\n急性水生毒性\n无资料\n\n慢性水生毒性\n\n慢性水生毒性\n无资料\n\n其他信息\n\n持久性和降解性\n无资料\n\n生物富集或生物积累性\n无资料\n\n土壤中的迁移性\n无资料\n\nPBT和vPvB的结果评价\n无资料',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4397,14,13,'废弃处置','废弃处置\n\n废弃化学品\n处置之前应参阅国家和地方有关法规。建议用焚烧法处置。\n\n污染包装物\n包装物清空后仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。\n\n废弃注意事项\n请参阅13.1和13.2。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4398,14,14,'运输信息','标签和标记\n\n运输标签\n\n海洋污染物\n无\n\n运输信息\n\n联合国危险货物编号\n1959\n\n联合国正确运输名称\n1,1-二氟乙烯\n\n运输主要危险类别\n2.1\n\n运输次要危险类别\n无\n\n包装类别\n不适用\n\n海洋污染物(是/否)\n否\n\n其他信息\n\n包装方法\n采用钢质气瓶等压力容器包装。按照生产商推荐的方法进行包装。\n\n运输注意事项\n装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。严禁与氧化剂、卤素等混装混运。高度不得超过车辆的防护栏板，并用三角木垫卡牢，防止滚动。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。采用钢瓶运输时必须戴好钢瓶上的安全帽。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输工具上应根据相关运输要求张贴危险标志、公告。','[{\"alt\": \"\", \"url\": \"images/013c0cdda673.jpg\", \"type\": \"transport\", \"original_url\": \"images/d2.1.jpg\"}]','2025-10-31 12:05:41','2025-10-31 12:05:41'),(4399,14,15,'法规信息','国际化学品名录\n\n1,1-二氟乙烯\n\n欧洲现有化学物质名录（EINECS）\n列入\n\n美国 TSCA化学物质名录（TSCA）\n列入\n\n加拿大国内化学物质名录（DSL）\n列入\n\n中国现有化学物质名录（IECSC）\n列入\n\n新西兰现有暂用的化学物质名录（NZIoC）\n未列入\n\n菲律宾化学品和化学物质名录（PICCS）\n列入\n\n韩国现有化学物质名录（KECI）\n列入\n\n澳大利亚现有化学品物质名录（AIIC）\n列入\n\n中国化学品管理名录\n\n1,1-二氟乙烯\n\n《危险化学品目录（2015年版）》，安监总局2015年第5号公告\n列入\n\n《重点环境管理危险化学品目录》，环保部办公厅2014年第33号文\n未列入\n\n《中国严格限制进出口的有毒化学品目录》，环保部2013年第85号公告\n未列入\n\n《药用类麻醉药品和精神药品目录》，国家药监局2025年第55号公告\n未列入\n\n《重点监管的危险化学品名录（第1和第2批）》，安监总局2011年第95号和2013年第12号通知\n未列入\n\n《中国进出口受控消耗臭氧层物质名录（第1到6批）》，环保部2000年至2012系列公告\n未列入\n\n《易制爆危险化学品名录（2011年版）》，公安部2011年11月25日公告\n未列入\n\n《高毒物品目录》，卫生部2003年第142号通知\n未列入',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41'),(4400,14,16,'其他信息','修改说明\n\n本SDS按照《化学品安全技术说明书 内容和项目顺序》（GB/T16483-2008）和《化学品安全技术说明书编写指南》（GB/T 17519-2013）等标准修订。其中，化学品GHS分类结果依据《危险化学品目录（2015版）实施指南（试行）》及《化学品分类和标签规范》（GB 30000.2-2013~GB 30000.29-2013）系列标准。\n\n免责声明\n\n本安全技术说明书格式符合我国GB/T16483和GB/T17519要求，数据来源于国际权威数据库和企业提交的数据，其它的信息是基于公司目前所掌握的知识。我们尽量保证其中所有信息的正确性，但由于信息来源的多样性以及本公司所掌握知识的局限性，本文件仅供使用者参考。安全技术说明书的使用者应根据使用目的，对相关信息的合理性做出判断。我们对该产品操作、存储、使用或处置等环节产生的任何损害，不承担任何责任。',NULL,'2025-10-31 12:05:41','2025-10-31 12:05:41');
