--
-- Table structure for table `化学品`
--

DROP TABLE IF EXISTS `化学品`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `化学品` (
  `编号` bigint NOT NULL AUTO_INCREMENT COMMENT '化学品ID',
  `CAS号` varchar(32) DEFAULT NULL COMMENT 'CAS号，如 50-00-0',
  `中文名` varchar(256) NOT NULL COMMENT '中文名称',
  `英文名` varchar(256) DEFAULT NULL COMMENT '英文名称',
  `分子式` varchar(64) DEFAULT NULL COMMENT '分子式',
  `EC编号` varchar(64) DEFAULT NULL COMMENT 'EC编号',
  `创建时间` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `更新时间` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`编号`),
  UNIQUE KEY `CAS号` (`CAS号`),
  KEY `索引_CAS号` (`CAS号`),
  KEY `索引_中文名` (`中文名`(191)),
  KEY `索引_英文名` (`英文名`(191)),
  FULLTEXT KEY `全文索引_名称` (`中文名`,`英文名`) COMMENT '名称全文索引'
) ENGINE=InnoDB AUTO_INCREMENT=260 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='化学品主表';
/*!40101 SET character_set_client = @saved_cs_client */;

