DROP TABLE IF EXISTS `化学品别名`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `化学品别名` (
  `编号` bigint NOT NULL AUTO_INCREMENT COMMENT '别名ID',
  `化学品编号` bigint NOT NULL COMMENT '化学品ID',
  `别名` varchar(256) NOT NULL COMMENT '别名/同义词',
  `创建时间` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`编号`),
  KEY `索引_化学品` (`化学品编号`),
  FULLTEXT KEY `全文索引_别名` (`别名`) COMMENT '别名全文索引',
  CONSTRAINT `外键_别名_化学品` FOREIGN KEY (`化学品编号`) REFERENCES `化学品` (`编号`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=405 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='化学品别名表';
